function loadThemePreference() {
  try {
    return localStorage.getItem(THEME_STORAGE_KEY) === "light" ? "light" : "dark";
  } catch {
    return "dark";
  }
}

function loadExecutionParallelWorkers() {
  try {
    const stored = localStorage.getItem(EXECUTION_PARALLEL_WORKERS_STORAGE_KEY);
    if (stored === null) return null;
    const value = Number.parseInt(stored, 10);
    return Number.isInteger(value) && value >= 1 ? value : null;
  } catch {
    return null;
  }
}

function loadExecutionBoolean(key) {
  try {
    const value = localStorage.getItem(key);
    if (value === "true") return true;
    if (value === "false") return false;
  } catch {
    // Execution preference persistence is optional.
  }
  return null;
}

function loadExecutionText(key) {
  try {
    const value = localStorage.getItem(key);
    return value === null ? null : String(value).trim();
  } catch {
    return null;
  }
}

const initialTheme = loadThemePreference();
const initialExecutionParallelWorkers = loadExecutionParallelWorkers();
const initialExecutionStrictLint = loadExecutionBoolean(EXECUTION_STRICT_LINT_STORAGE_KEY);
const initialExecutionBackend = loadExecutionText(EXECUTION_BACKEND_STORAGE_KEY);
const initialExecutionImplementation = loadExecutionText(EXECUTION_IMPLEMENTATION_STORAGE_KEY);
const initialExecutionUsePlanCache = loadExecutionBoolean(EXECUTION_PLAN_CACHE_STORAGE_KEY);
document.documentElement.dataset.theme = initialTheme;

