function applyExecutionControlsContract(rawContract) {
  const raw = rawContract && typeof rawContract === "object" ? rawContract : {};
  const rawWorkers = raw.parallel_workers && typeof raw.parallel_workers === "object"
    ? raw.parallel_workers
    : {};
  const minimum = Number.isInteger(rawWorkers.minimum) ? rawWorkers.minimum : 1;
  const maximum = Number.isInteger(rawWorkers.maximum) && rawWorkers.maximum >= minimum
    ? rawWorkers.maximum
    : minimum;
  const defaultWorkers = Number.isInteger(rawWorkers.default)
    && rawWorkers.default >= minimum
    && rawWorkers.default <= maximum
    ? rawWorkers.default
    : minimum;
  executionControlsContract = {
    strict_lint: {
      default: typeof ((raw.strict_lint || {}).default) === "boolean"
        ? raw.strict_lint.default
        : false,
    },
    backend: { default: (raw.backend || {}).default ?? null },
    implementation: { default: (raw.implementation || {}).default ?? null },
    parallel_workers: {
      minimum,
      maximum,
      default: defaultWorkers,
    },
    use_plan_cache: {
      default: typeof ((raw.use_plan_cache || {}).default) === "boolean"
        ? raw.use_plan_cache.default
        : true,
    },
  };
  if (typeof state.executionStrictLint !== "boolean") {
    state.executionStrictLint = executionControlsContract.strict_lint.default;
  }
  if (state.executionBackend === null) {
    state.executionBackend = executionControlsContract.backend.default || "";
  }
  if (state.executionImplementation === null) {
    state.executionImplementation = executionControlsContract.implementation.default || "";
  }
  if (typeof state.executionUsePlanCache !== "boolean") {
    state.executionUsePlanCache = executionControlsContract.use_plan_cache.default;
  }
  if (
    !Number.isInteger(state.executionParallelWorkers)
    || state.executionParallelWorkers < minimum
    || state.executionParallelWorkers > maximum
  ) {
    state.executionParallelWorkers = defaultWorkers;
  }
}

function executionParallelWorkerOptions() {
  const workers = executionControlsContract.parallel_workers;
  return Array.from(
    { length: workers.maximum - workers.minimum + 1 },
    (_, index) => workers.minimum + index
  );
}

function executionRequestOptions() {
  const workerOptions = executionParallelWorkerOptions();
  return {
    strict_lint: Boolean(state.executionStrictLint),
    backend: String(state.executionBackend || "").trim() || null,
    implementation: String(state.executionImplementation || "").trim() || null,
    parallel_workers: workerOptions.includes(state.executionParallelWorkers)
      ? state.executionParallelWorkers
      : executionControlsContract.parallel_workers.default,
    use_plan_cache: Boolean(state.executionUsePlanCache),
  };
}

function persistExecutionPreference(key, value) {
  try {
    localStorage.setItem(key, String(value));
  } catch {
    // Execution preference persistence is optional.
  }
}

