function textSampleCountLabel(sampleIds) {
  const ids = parseTextSampleIds(sampleIds);
  if (!ids.length) return "default samples";
  return `${ids.length} text${ids.length === 1 ? "" : "s"}`;
}

function researchSummarySection(recipe, options = {}) {
  const summary = researchSummaryForRecipe(recipe);
  const validation = researchCatalogValidation(summary);
  const datasetName = (validation.dataset && validation.dataset.name) || summary.dataset.name || summary.dataset.id || "dataset inferred";
  const taskName = (validation.task && validation.task.name) || summary.task.name || summary.task.id || "purpose inferred";
  const statusLabel = validation.errors.length
    ? "catalog error"
    : validation.warnings.length
      ? "catalog warning"
      : state.researchCatalog
        ? "catalog valid"
        : "catalog loading";
  const statusClass = validation.errors.length ? "danger" : validation.warnings.length ? "warning" : "success";
  const metrics = researchMetricRows(summary, validation.task);
  const issueText = [...validation.errors, ...validation.warnings].join(" ");
  const grouped = Boolean(options.group);
  return `
    <section class="${grouped ? "config-facet-group" : "config-section"} research-section">
      <div class="config-section-header">
        <div>
          <${grouped ? "h3" : "h2"}>Research</${grouped ? "h3" : "h2"}>
          <span>${escapeHtml(taskName)}</span>
        </div>
      </div>
      <div class="research-summary-grid">
        <span class="inline-badge ${escapeAttr(statusClass)}">${escapeHtml(statusLabel)}</span>
        <span class="inline-badge" title="${escapeAttr(datasetName)}">data ${escapeHtml(summary.dataset.id || "unknown")}</span>
        <span class="inline-badge">purpose ${escapeHtml(summary.task.id || "unknown")}</span>
        <span class="inline-badge">${escapeHtml(summary.dataset.modality || summary.task.modality || "modality unknown")}</span>
      </div>
      <div class="research-metric-list" aria-label="Catalog metrics">
        ${metrics.length ? metrics.map(researchMetricPill).join("") : '<span class="field-hint">No catalog metrics inferred for this recipe yet.</span>'}
      </div>
      ${issueText ? `<div class="field-hint research-issues">${escapeHtml(issueText)}</div>` : ""}
    </section>
  `;
}

function researchSummaryForRecipe(recipe) {
  const steps = (recipe && recipe.steps) || [];
  const dataStep = stepById(steps, "data") ||
    steps.find((step) => String(step.op || "").startsWith("source.")) ||
    steps.find((step) => step.op === "wireless.miso_ofdm_csi") ||
    {};
  const dataset = researchDatasetForStep(dataStep);
  const task = recipePurposeIdentity(recipe);
  const metrics = Array.from(new Set([
    ...recipeDeclaredResearchMetricIds(recipe),
    ...researchMetricsForTask(task.id, steps),
  ]));
  return { dataset, task, metrics };
}

function recipeDeclaredResearchMetricIds(recipe) {
  const metadata = recipe && recipe.metadata && typeof recipe.metadata === "object" ? recipe.metadata : {};
  const research = metadata.research && typeof metadata.research === "object" ? metadata.research : {};
  const task = research.task && typeof research.task === "object" ? research.task : {};
  const declared = [
    ...(Array.isArray(research.metrics) ? research.metrics : []),
    ...(Array.isArray(task.metrics) ? task.metrics : []),
    ...(Array.isArray(metadata.metric_specs) ? metadata.metric_specs : []),
  ];
  return Array.from(new Set(declared.map((metric) => (
    typeof metric === "string" ? metric : String((metric && metric.id) || "")
  )).filter(Boolean)));
}

function researchDatasetForStep(step) {
  const op = step && step.op;
  const params = (step && step.params) || {};
  if (op === "wireless.miso_ofdm_csi") {
    return {
      id: "sionna_correlated_miso_ofdm_csi",
      name: "Seeded correlated MISO-OFDM CSI",
      modality: "wireless",
      source_op: op,
    };
  }
  if (op === "source.image_dataset") {
    return {
      id: String(params.dataset || "kodak"),
      name: String(params.dataset || "kodak"),
      modality: "image",
      source_op: op,
    };
  }
  if (op === "source.local_npz_images") {
    return {
      id: "local_npz_images",
      name: "Local NPZ image batch",
      modality: "image",
      source_op: op,
    };
  }
  if (op === "source.text_dataset") {
    return {
      id: String(params.dataset || "semantic_text_smoke"),
      name: textDatasetLabel(params.dataset || "semantic_text_smoke"),
      modality: "text",
      source_op: op,
    };
  }
  if (op === "source.task_labels_smoke") {
    return {
      id: String(params.dataset || "task_smoke"),
      name: "Task-oriented smoke set",
      modality: "generic",
      source_op: op,
    };
  }
  if (op === "source.coco128_detection") {
    return {
      id: "coco128_detection",
      name: "COCO128 object detection",
      modality: "image",
      source_op: op,
    };
  }
  if (op === "source.coco8_segmentation") {
    return {
      id: "coco8_segmentation",
      name: "COCO8 segmentation",
      modality: "image",
      source_op: op,
    };
  }
  if (op === "source.retrieval_smoke") {
    return {
      id: String(params.dataset || "retrieval_smoke"),
      name: "Image-text retrieval smoke set",
      modality: "multimodal",
      source_op: op,
    };
  }
  if (op === "source.flickr8k_retrieval") {
    return {
      id: "flickr8k",
      name: "Flickr8k image-caption retrieval",
      modality: "multimodal",
      source_op: op,
    };
  }
  if (op === "source.semantic_artifacts_smoke") {
    return {
      id: String(params.dataset || "semantic_artifact_smoke"),
      name: "Semantic artifact smoke set",
      modality: "multimodal",
      source_op: op,
    };
  }
  if (op === "source.vqa_smoke") {
    return {
      id: String(params.dataset || "coco_vqa_smoke"),
      name: "COCO/VQA-style smoke set",
      modality: "multimodal",
      source_op: op,
    };
  }
  if (op === "source.vqa_manifest") {
    return {
      id: String(params.manifest_path || "local_vqa_manifest"),
      name: "Local VQA manifest",
      modality: "multimodal",
      source_op: op,
    };
  }
  if (op === "source.vqa_small_hf") {
    return {
      id: "vqa_small",
      name: "VQA small sample",
      modality: "multimodal",
      source_op: op,
    };
  }
  return { id: "", name: "", modality: "", source_op: op || "" };
}

