function researchTaskForSteps(steps) {
  const ops = new Set((steps || []).map((step) => step.op));
  if (ops.has("metrics.csi_feedback")) {
    return {
      id: "csi_compression_feedback",
      name: "Learned CSI compression and feedback",
      kind: "channel_state_feedback",
      modality: "wireless",
    };
  }
  if (ops.has("metrics.classification")) {
    return {
      id: "classification",
      name: "Classification",
      kind: "task_success",
      modality: "generic",
    };
  }
  if (ops.has("metrics.vqa")) {
    return {
      id: "visual_question_answering",
      name: "Visual question answering",
      kind: "task_success",
      modality: "multimodal",
    };
  }
  if (ops.has("metrics.detection")) {
    return {
      id: "object_detection",
      name: "Object detection",
      kind: "task_success",
      modality: "image",
    };
  }
  if (ops.has("metrics.segmentation")) {
    return {
      id: "segmentation",
      name: "Segmentation",
      kind: "task_success",
      modality: "image",
    };
  }
  if (ops.has("metrics.captioning")) {
    return {
      id: "image_captioning",
      name: "Image captioning",
      kind: "task_success",
      modality: "multimodal",
    };
  }
  if (ops.has("metrics.retrieval")) {
    return {
      id: "image_text_retrieval",
      name: "Image-text retrieval",
      kind: "task_success",
      modality: "multimodal",
    };
  }
  if (ops.has("metrics.embedding_similarity") || ops.has("foundation.diffusion_state_to_image")) {
    return {
      id: "image_generation",
      name: "Caption-to-image generation",
      kind: "generative_reconstruction",
      modality: "multimodal",
    };
  }
  if (ops.has("metrics.image_reconstruction")) {
    return {
      id: "image_reconstruction",
      name: "Image reconstruction",
      kind: "reconstruction",
      modality: "image",
    };
  }
  if (ops.has("metrics.text_semantic_similarity")) {
    return {
      id: "text_semantic_similarity",
      name: "Text semantic reconstruction",
      kind: "semantic_reconstruction",
      modality: "text",
    };
  }
  if (
    ops.has("source.resource_allocation_scenario") ||
    ops.has("metrics.resource_allocation") ||
    ops.has("metrics.ofdm_power_allocation") ||
    (steps || []).some((step) => (
      step.op === "model.symbol_power_allocator" &&
      step.params &&
      step.params.granularity === "per_subcarrier"
    ))
  ) {
    return {
      id: "resource_allocation",
      name: "Resource allocation",
      kind: "policy_optimization",
      modality: "wireless",
    };
  }
  if (ops.has("metrics.bit_error_rate")) {
    return {
      id: "bit_transport",
      name: "Bit transport integrity",
      kind: "transport_integrity",
      modality: "bits",
    };
  }
  return { id: "", name: "", kind: "", modality: "" };
}

function researchMetricsForTask(taskId, steps) {
  const taskDef = researchCatalogEntry("tasks", taskId);
  if (taskDef && Array.isArray(taskDef.metrics)) {
    const metrics = [...taskDef.metrics];
    const ops = new Set((steps || []).map((step) => step.op));
    if (ops.has("metrics.semantic_state_faithfulness")) {
      [
        "faithfulness.concept_f1",
        "faithfulness.fact_f1",
        "faithfulness.unsupported_assertion_rate",
        "faithfulness.kb_fact_precision",
      ].forEach((metric) => {
        if (!metrics.includes(metric)) metrics.push(metric);
      });
    }
    return metrics;
  }
  const ops = new Set((steps || []).map((step) => step.op));
  if (ops.has("metrics.csi_feedback")) {
    return [
      "csi_feedback.nmse_db",
      "csi_feedback.phase_invariant_cosine",
      "csi_feedback.achieved_spectral_efficiency_bps_hz",
      "csi_feedback.spectral_efficiency_retention",
    ];
  }
  if (ops.has("metrics.image_reconstruction")) return ["quality.psnr_db", "quality.mse", "quality.mae"];
  if (ops.has("metrics.text_semantic_similarity")) return ["semantic.lexical_similarity", "text.unigram_bleu_proxy", "text.edit_similarity", "text.exact_match"];
  if (ops.has("metrics.bit_error_rate")) return ["channel.ber"];
  return [];
}

function researchMetricRows(summary, taskDef) {
  const ids = summary.metrics || [];
  return ids.map((id) => {
    const def = researchCatalogEntry("metrics", id);
    return {
      id,
      name: (def && def.name) || id,
      unit: (def && def.unit) || "",
      status: (def && def.status) || (def ? "supported" : "unknown"),
      required: taskDef && Array.isArray(taskDef.metrics) ? taskDef.metrics.includes(id) : true,
    };
  });
}

function researchMetricPill(metric) {
  const className = metric.status === "supported" ? "success" : metric.status === "planned" ? "warning" : "";
  const unit = metric.unit ? ` (${metric.unit})` : "";
  return `<span class="research-metric-pill ${escapeAttr(className)}" title="${escapeAttr(metric.name + unit)}">${escapeHtml(metric.id)}</span>`;
}

function researchCatalogValidation(summary) {
  const errors = [];
  const warnings = [];
  const dataset = researchCatalogEntry("datasets", summary.dataset.id);
  const task = researchCatalogEntry("tasks", summary.task.id);
  if (!state.researchCatalog) warnings.push("Research catalog is still loading.");
  if (summary.dataset.id && !dataset) warnings.push(`Dataset ${summary.dataset.id} is not in the research catalog.`);
  if (summary.task.id && !task) warnings.push(`Purpose ${summary.task.id} is not in the research catalog.`);
  if (dataset && summary.dataset.modality && dataset.modality !== summary.dataset.modality) {
    errors.push(`Dataset ${summary.dataset.id} is cataloged as ${dataset.modality}, but this recipe inferred ${summary.dataset.modality}.`);
  }
  if (task && summary.task.modality && task.modality !== summary.task.modality) {
    errors.push(`Purpose ${summary.task.id} is cataloged as ${task.modality}, but this recipe inferred ${summary.task.modality}.`);
  }
  if (dataset && task && dataset.modality !== task.modality && task.modality !== "multimodal") {
    errors.push(`Dataset ${dataset.id} modality ${dataset.modality} does not match purpose ${task.id} modality ${task.modality}.`);
  }
  const allowedMetrics = new Set([...(task && task.metrics ? task.metrics : []), ...(task && task.optional_metrics ? task.optional_metrics : [])]);
  (summary.metrics || []).forEach((metricId) => {
    const metric = researchCatalogEntry("metrics", metricId);
    if (!metric) {
      warnings.push(`Metric ${metricId} is not in the research catalog.`);
    } else if (metric.status && metric.status !== "supported") {
      warnings.push(`Metric ${metricId} is cataloged as ${metric.status}.`);
    }
    if (task && allowedMetrics.size && !allowedMetrics.has(metricId)) {
      warnings.push(`Metric ${metricId} is not listed for purpose ${task.id}.`);
    }
  });
  return { errors, warnings, dataset, task };
}

function researchCatalogEntry(kind, id) {
  if (!id || !state.researchCatalog) return null;
  const entries = Array.isArray(state.researchCatalog[kind]) ? state.researchCatalog[kind] : [];
  return entries.find((item) => item && item.id === id) || null;
}

function externalRepresentationField(current) {
  const value = current || "bits";
  const options = Object.entries(EXTERNAL_REPRESENTATIONS)
    .map(([id, representation]) => `<option value="${escapeAttr(id)}"${id === value ? " selected" : ""}>${escapeHtml(representation.label)}</option>`)
    .join("");
  return `
    <label class="compact-field">
      <span class="sr-only">External output type</span>
      <select data-config="external.representation">${options}</select>
    </label>
  `;
}

function externalCodecHint(profile) {
  if (!profile || !profile.id.startsWith("external")) return "";
  return `
    <div class="field-hint">
      This is a custom adapter slot. It runs your Python encoder/decoder callables and is not a built-in runnable codec.
    </div>
  `;
}

async function selectRecipe(recipe) {
  if (!recipe) return;
  snapshotRenderedRecipeConfiguratorBlockIds(state.selectedRecipe, state.editRecipe);
  state.selectedRecipe = recipe;
  state.selectedRecipeKey = recipe.key;
  state.editRecipe = recipe.recipe || null;
  state.editRecipeKey = recipe.recipe ? recipe.key : null;
  state.selectedNodeId = null;
  state.selectedEdgeKey = null;
  state.pendingGraphLink = null;
  state.positions = {};
  renderRecipes();
  renderRecipeControls();
  await loadSelectedRecipePayload();
  if (state.activeView === "results") {
    await loadAllRecipeResults(false);
  }
  if (state.activeView === "training") {
    refreshTrainingInspection(true);
  }
}

async function loadSelectedRecipePayload() {
  if (!state.selectedRecipe) {
    state.editRecipe = null;
    state.editRecipeKey = null;
    state.graph = null;
    els.graphSurface.innerHTML = '<div class="graph-empty">No recipe</div>';
    setRecipeHeader("Recipe", 0, 0, "no recipe");
    if (els.recipeTabbar) els.recipeTabbar.hidden = state.activeView === "results";
    renderRecipeControls();
    setBusy(state.busy);
    return;
  }
  const loadingRecipe = state.selectedRecipe;
  const loadingKey = loadingRecipe.key;
  if (!loadingRecipe.recipe) {
    if (!loadingRecipe.path) {
      throw new Error("recipe tab has no payload");
    }
    const payload = await api(`/api/recipe?path=${encodeURIComponent(loadingRecipe.path)}`);
    if (!state.selectedRecipe || state.selectedRecipe.key !== loadingKey) return;
    loadingRecipe.recipe = structuredCloneFallback(payload.recipe);
  }
  if (!state.selectedRecipe || state.selectedRecipe.key !== loadingKey) return;
  state.editRecipe = state.selectedRecipe.recipe;
  state.editRecipeKey = loadingKey;
  if (!findStep(state.selectedNodeId)) {
    state.selectedNodeId = null;
  }
  rebuildExperimentGraph(true);
}

function rebuildExperimentGraph(render = true) {
  if (!state.editRecipe) return;
  if (state.selectedRecipe && state.editRecipeKey === state.selectedRecipe.key) {
    state.selectedRecipe.recipe = state.editRecipe;
    state.selectedRecipe.name = state.editRecipe.name || state.selectedRecipe.name;
    state.selectedRecipe.step_count = (state.editRecipe.steps || []).length;
  }
  state.graph = graphFromRecipePayload(state.editRecipe);
  setRecipeHeader(
    recipeDisplayName(state.selectedRecipe) || state.editRecipe.name || "recipe",
    state.graph.nodes.length,
    state.graph.edges.length,
    "editable experiment"
  );
  if (render) renderGraph(state.graph);
  if (state.activeView === "training") {
    setTrainingRecipeHeader();
    renderTrainingView();
    refreshTrainingInspection(false);
  }
  renderRecipes();
  renderRecipeControls();
  setBusy(state.busy);
}

async function duplicateSelectedRecipe(sourceRecipe = state.selectedRecipe) {
  if (!sourceRecipe) return;
  if (!sourceRecipe.recipe) {
    if (!sourceRecipe.path) return;
    const payload = await api(`/api/recipe?path=${encodeURIComponent(sourceRecipe.path)}`);
    sourceRecipe.recipe = structuredCloneFallback(payload.recipe);
  }
  const recipe = structuredCloneFallback(sourceRecipe.recipe);
  stripRecipeWorkingStateMetadata(recipe);
  recipe.name = nextDuplicateRecipeName(recipe.name || sourceRecipe.name || "recipe");
  recipe.metadata = {
    ...(recipe.metadata || {}),
    duplicated_from: sourceRecipe.templatePath || sourceRecipe.path || sourceRecipe.name,
  };
  const copy = {
    key: `working:${Date.now()}:${Math.random().toString(36).slice(2)}`,
    color: nextRecipeColor(),
    tabLabel: `Recipe ${state.recipes.length + 1}`,
    name: recipe.name,
    path: "",
    description: sourceRecipe.description || "",
    step_count: (recipe.steps || []).length,
    metadata: recipe.metadata,
    source: "working",
    templatePath: sourceRecipe.templatePath || "",
    templateId: sourceRecipe.templateId || "",
    editorPreference: sourceRecipe.editorPreference || "graph",
    configuratorView: defaultRecipeConfiguratorView(recipe),
    configuratorOpenStepIds: [],
    preserveTopology: sourceRecipe.preserveTopology !== false,
    workingCopy: true,
    duplicatedFrom: sourceRecipe.key || sourceRecipe.name || "",
    lastRunId: null,
    resultDirty: false,
    transientStatus: null,
    recipe,
  };
  state.recipes.push(copy);
  await selectRecipe(copy);
  setActiveView("graph");
  notify(`duplicated ${recipe.name}`);
}

function currentRecipeJsonText() {
  const recipe = state.editRecipe || (state.selectedRecipe && state.selectedRecipe.recipe);
  if (!recipe) return "";
  const executableRecipe = structuredCloneFallback(recipe);
  stripRecipeWorkingStateMetadata(executableRecipe);
  return JSON.stringify(executableRecipe, null, 2);
}

function rawRecipeEditorStatus(message = "", kind = "") {
  const status = els.settingsBody.querySelector("[data-raw-recipe-status]");
  if (!status) return;
  status.textContent = message;
  status.hidden = !message;
  status.className = `raw-recipe-editor-status${kind ? ` ${kind}` : ""}`;
}

function openRawRecipeEditor() {
  const text = currentRecipeJsonText();
  if (!text) {
    notify("no recipe to edit");
    return;
  }
  if (state.rawRecipeEditorSession && state.rawRecipeEditorSession.controller) {
    state.rawRecipeEditorSession.controller.abort();
  }
  const generation = state.rawRecipeEditorGeneration + 1;
  state.rawRecipeEditorGeneration = generation;
  state.rawRecipeEditorSession = {
    generation,
    recipe: state.editRecipe,
    envelope: recipeConfiguratorEnvelope(state.editRecipe),
    selectedRecipeKey: state.selectedRecipeKey,
    controller: null,
    pending: false,
  };
  state.settingsSection = "raw-recipe";
  els.settingsTitle.textContent = "Raw Recipe JSON";
  els.settingsSubtitle.textContent = "Current working copy only";
  els.settingsBody.innerHTML = `
    <div class="raw-recipe-editor">
      <label>
        <span class="sr-only">Raw recipe JSON</span>
        <textarea data-raw-recipe-text spellcheck="false" autocapitalize="off" autocomplete="off" aria-describedby="rawRecipeEditorHint"></textarea>
      </label>
      <div id="rawRecipeEditorHint" class="field-hint">Apply validates the complete recipe before replacing this tab's working copy. Catalog templates and files on disk are never modified.</div>
      <div class="raw-recipe-editor-status" data-raw-recipe-status role="alert" hidden></div>
      <div class="raw-recipe-editor-actions">
        <button type="button" class="secondary" data-raw-recipe-copy>Copy</button>
        <button type="button" class="secondary" data-raw-recipe-paste>Paste</button>
        <button type="button" class="secondary" data-raw-recipe-cancel>Cancel</button>
        <button type="button" class="primary" data-raw-recipe-apply>Apply to working copy</button>
      </div>
    </div>
  `;
  const copyButton = els.settingsBody.querySelector("[data-raw-recipe-copy]");
  const pasteButton = els.settingsBody.querySelector("[data-raw-recipe-paste]");
  const cancelButton = els.settingsBody.querySelector("[data-raw-recipe-cancel]");
  const applyButton = els.settingsBody.querySelector("[data-raw-recipe-apply]");
  if (copyButton) copyButton.addEventListener("click", copyRawRecipeText);
  if (pasteButton) pasteButton.addEventListener("click", pasteRawRecipeText);
  if (cancelButton) cancelButton.addEventListener("click", closeSettingsDialog);
  if (applyButton) applyButton.addEventListener("click", applyRawRecipeText);
  els.settingsOverlay.hidden = false;
  const textarea = els.settingsBody.querySelector("[data-raw-recipe-text]");
  if (textarea) {
    textarea.value = text;
    textarea.addEventListener("keydown", (event) => {
      if ((event.ctrlKey || event.metaKey) && event.key === "Enter") {
        event.preventDefault();
        applyRawRecipeText();
      }
    });
    if (typeof textarea.focus === "function") textarea.focus();
    if (typeof textarea.setSelectionRange === "function") textarea.setSelectionRange(0, 0);
    textarea.scrollTop = 0;
    textarea.scrollLeft = 0;
  }
}

function rawRecipeEditorSessionIsCurrent(session) {
  if (!session || session !== state.rawRecipeEditorSession) return false;
  if (session.generation !== state.rawRecipeEditorGeneration) return false;
  if (state.settingsSection !== "raw-recipe") return false;
  if (state.editRecipe !== session.recipe) return false;
  if (state.selectedRecipeKey !== session.selectedRecipeKey) return false;
  if (session.envelope && state.selectedRecipe !== session.envelope) return false;
  return true;
}

async function copyRawRecipeText() {
  const textarea = els.settingsBody.querySelector("[data-raw-recipe-text]");
  if (!textarea) return;
  const text = textarea.value;
  try {
    if (navigator.clipboard && navigator.clipboard.writeText) {
      await navigator.clipboard.writeText(text);
    } else {
      fallbackCopyText(text);
    }
    rawRecipeEditorStatus("Recipe JSON copied.", "success");
  } catch (_error) {
    fallbackCopyText(text);
    rawRecipeEditorStatus("Recipe JSON copied.", "success");
  }
}

async function pasteRawRecipeText() {
  const textarea = els.settingsBody.querySelector("[data-raw-recipe-text]");
  if (!textarea) return;
  try {
    if (!navigator.clipboard || !navigator.clipboard.readText) {
      textarea.focus();
      rawRecipeEditorStatus("Clipboard access is unavailable here. Paste directly into the editor.", "warning");
      return;
    }
    textarea.value = await navigator.clipboard.readText();
    textarea.focus();
    rawRecipeEditorStatus("Clipboard content pasted. Review it before applying.", "success");
  } catch (error) {
    textarea.focus();
    rawRecipeEditorStatus(`Clipboard access failed: ${error.message || String(error)}. Paste directly into the editor.`, "error");
  }
}

async function applyRawRecipeText() {
  const textarea = els.settingsBody.querySelector("[data-raw-recipe-text]");
  const applyButton = els.settingsBody.querySelector("[data-raw-recipe-apply]");
  const session = state.rawRecipeEditorSession;
  if (!textarea || !state.editRecipe || !rawRecipeEditorSessionIsCurrent(session)) return;
  if (session.pending) return;
  let authoredRecipe;
  try {
    authoredRecipe = strictJsonParse(textarea.value);
  } catch (error) {
    rawRecipeEditorStatus(`Invalid JSON: ${error.message || String(error)}`, "error");
    return;
  }
  if (!authoredRecipe || typeof authoredRecipe !== "object" || Array.isArray(authoredRecipe)) {
    rawRecipeEditorStatus("The recipe must be a JSON object.", "error");
    return;
  }
  const numberProblem = recipeJsonNumberProblem(authoredRecipe);
  if (numberProblem) {
    rawRecipeEditorStatus(`Invalid recipe value: ${numberProblem}.`, "error");
    return;
  }
  if (applyButton) {
    applyButton.disabled = true;
    applyButton.setAttribute("aria-busy", "true");
  }
  rawRecipeEditorStatus("Validating recipe…");
  session.pending = true;
  const controller = typeof AbortController === "function" ? new AbortController() : null;
  session.controller = controller;
  try {
    const payload = await api("/api/recipe/validate", {
      method: "POST",
      body: JSON.stringify({ recipe: authoredRecipe }),
      ...(controller ? { signal: controller.signal } : {}),
    });
    if (!rawRecipeEditorSessionIsCurrent(session)) return;
    const validatedRecipe = structuredCloneFallback(payload.recipe);
    const working = session.envelope;
    if (working) {
      working.preserveTopology = true;
      working.workingCopy = true;
      working.configuratorView = defaultRecipeConfiguratorView(validatedRecipe);
      working.configuratorOpenStepIds = [];
    }
    state.selectedNodeId = null;
    state.selectedEdgeKey = null;
    state.pendingGraphLink = null;
    state.positions = {};
    applyBuiltRecipe(validatedRecipe, true);
    els.settingsOverlay.hidden = true;
    state.settingsSection = null;
    state.rawRecipeEditorSession = null;
    notify("recipe JSON applied to this working copy");
  } catch (error) {
    if (error && error.name === "AbortError") return;
    if (!rawRecipeEditorSessionIsCurrent(session)) return;
    rawRecipeEditorStatus(error.message || String(error), "error");
  } finally {
    if (session.controller === controller) session.controller = null;
    session.pending = false;
    if (applyButton) {
      applyButton.disabled = false;
      applyButton.removeAttribute("aria-busy");
    }
  }
}

function fallbackCopyText(text) {
  const textarea = document.createElement("textarea");
  textarea.value = text;
  textarea.setAttribute("readonly", "");
  textarea.style.position = "fixed";
  textarea.style.left = "-10000px";
  textarea.style.top = "0";
  document.body.appendChild(textarea);
  textarea.select();
  document.execCommand("copy");
  textarea.remove();
}

function setRecipeHeader(name, nodes, edges, mode) {
  hideResultsHeaderControls();
  els.recipeTitle.textContent = name;
  els.recipeMeta.textContent = `${nodes} nodes - ${edges} edges - ${mode}`;
  renderRecipeSuiteTag(currentRecipeSuiteInfo());
  renderExecutionProfileTag(state.editRecipe);
  renderGraphHeaderControls(state.activeView === "graph" || state.activeView === "training");
}

function setTrainingRecipeHeader() {
  hideResultsHeaderControls();
  els.recipeTitle.textContent = recipeDisplayName(state.selectedRecipe) || (state.editRecipe && state.editRecipe.name) || "recipe";
  els.recipeMeta.textContent = "";
  renderRecipeSuiteTag(currentRecipeSuiteInfo());
  renderExecutionProfileTag(state.editRecipe);
  renderGraphHeaderControls(true);
}

function renderGraphHeaderControls(show = state.activeView === "graph") {
  if (!els.graphHeaderControls) return;
  if (!show) {
    els.graphHeaderControls.hidden = true;
    els.graphHeaderControls.innerHTML = "";
    return;
  }
  const mode = GRAPH_RUNNER_MODES[state.graphRunnerMode] ? state.graphRunnerMode : "benchmark_run";
  const info = GRAPH_RUNNER_MODES[mode];
  const workerOptions = executionParallelWorkerOptions();
  const parallelWorkers = workerOptions.includes(state.executionParallelWorkers)
    ? state.executionParallelWorkers
    : executionControlsContract.parallel_workers.default;
  els.graphHeaderControls.hidden = false;
  els.graphHeaderControls.innerHTML = `
    <label class="graph-runner-select">
      <span>Workflow view</span>
      <select data-graph-runner-mode title="${escapeAttr(`Display only: ${info.description} This does not change the recipe or how Run All executes.`)}">
        ${Object.entries(GRAPH_RUNNER_MODES).map(([runner, payload]) => `
          <option value="${escapeAttr(runner)}"${runner === mode ? " selected" : ""}>${escapeHtml(payload.label)}</option>
        `).join("")}
      </select>
    </label>
    <label class="graph-runner-select" data-ui-tooltip="Run All processes recipe tabs and matrix variants sequentially. Values above one parallelize only dependency-independent DAG branches inside each recipe; dependent blocks still wait. Use Sequential for latency comparisons because concurrent branches can contend for CPU, GPU, memory, and I/O.">
      <span>Execution</span>
      <select data-execution-parallel-workers aria-label="Execution workers">
        ${workerOptions.map((workers) => `
          <option value="${workers}"${workers === parallelWorkers ? " selected" : ""}>${workers === 1 ? "Sequential" : `Parallel · ${workers}`}</option>
        `).join("")}
      </select>
    </label>
    <label class="graph-runner-select">
      <span>Backend</span>
      <input type="text" data-execution-backend value="${escapeAttr(state.executionBackend || "")}" placeholder="Automatic" aria-label="Required execution backend" />
    </label>
    <label class="graph-runner-select">
      <span>Implementation</span>
      <input type="text" data-execution-implementation value="${escapeAttr(state.executionImplementation || "")}" placeholder="Automatic" aria-label="Required execution implementation" />
    </label>
    <label class="graph-runner-select" data-ui-tooltip="Reject the run before dispatch unless every recipe passes strict shared-platform lint.">
      <span>Strict lint</span>
      <input type="checkbox" data-execution-strict-lint${state.executionStrictLint ? " checked" : ""} />
    </label>
    <label class="graph-runner-select" data-ui-tooltip="Reuse a content-bound execution plan when available. Turn this off to force a fresh plan.">
      <span>Plan cache</span>
      <input type="checkbox" data-execution-use-plan-cache${state.executionUsePlanCache ? " checked" : ""} />
    </label>
  `;
  const select = els.graphHeaderControls.querySelector("[data-graph-runner-mode]");
  if (select) select.addEventListener("change", (event) => {
    const next = event.currentTarget.value;
    state.graphRunnerMode = GRAPH_RUNNER_MODES[next] ? next : "benchmark_run";
    renderGraphHeaderControls(true);
    if (state.graph) renderGraph(state.graph);
  });
  const executionSelect = els.graphHeaderControls.querySelector("[data-execution-parallel-workers]");
  if (executionSelect) executionSelect.addEventListener("change", (event) => {
    const requested = Number.parseInt(event.currentTarget.value || "", 10);
    state.executionParallelWorkers = workerOptions.includes(requested)
      ? requested
      : executionControlsContract.parallel_workers.default;
    persistExecutionPreference(
      EXECUTION_PARALLEL_WORKERS_STORAGE_KEY,
      state.executionParallelWorkers
    );
    renderGraphHeaderControls(true);
  });
  const backendInput = els.graphHeaderControls.querySelector("[data-execution-backend]");
  if (backendInput) backendInput.addEventListener("change", (event) => {
    state.executionBackend = String(event.currentTarget.value || "").trim();
    persistExecutionPreference(EXECUTION_BACKEND_STORAGE_KEY, state.executionBackend);
  });
  const implementationInput = els.graphHeaderControls.querySelector("[data-execution-implementation]");
  if (implementationInput) implementationInput.addEventListener("change", (event) => {
    state.executionImplementation = String(event.currentTarget.value || "").trim();
    persistExecutionPreference(
      EXECUTION_IMPLEMENTATION_STORAGE_KEY,
      state.executionImplementation
    );
  });
  const strictLintInput = els.graphHeaderControls.querySelector("[data-execution-strict-lint]");
  if (strictLintInput) strictLintInput.addEventListener("change", (event) => {
    state.executionStrictLint = Boolean(event.currentTarget.checked);
    persistExecutionPreference(
      EXECUTION_STRICT_LINT_STORAGE_KEY,
      state.executionStrictLint
    );
  });
  const planCacheInput = els.graphHeaderControls.querySelector("[data-execution-use-plan-cache]");
  if (planCacheInput) planCacheInput.addEventListener("change", (event) => {
    state.executionUsePlanCache = Boolean(event.currentTarget.checked);
    persistExecutionPreference(
      EXECUTION_PLAN_CACHE_STORAGE_KEY,
      state.executionUsePlanCache
    );
  });
}

function graphChannelModeInfo(graph) {
  const nodes = graph && Array.isArray(graph.nodes) ? graph.nodes : [];
  if (nodes.some((node) => node.op === "channel.identity_symbol_link" && String(((node.params || {}).label) || "").includes("bit_perfect_bypass"))) {
    return {
      label: "bit-perfect bypass",
      tone: "digital",
      tooltip: "Disabled channel keeps the transport skeleton visible with null modulation, disabled TX power, identity symbol link, and null demodulation.",
    };
  }
  if (nodes.some((node) => node.op === "channel.identity_symbol_link")) {
    return {
      label: "identity PHY",
      tone: "differentiable",
      tooltip: "Disabled channel uses a continuous identity PHY: symbols pass through unchanged and gradients can flow through the identity block.",
    };
  }
  if (nodes.some((node) => node.op === "channel.identity_link")) {
    return {
      label: "bit-perfect bypass",
      tone: "digital",
      tooltip: "Disabled channel uses a bit-perfect bypass: bits pass through unchanged, but the discrete bitstream is a gradient stop.",
    };
  }
  if (nodes.some((node) => node.op === "wireless.channel" || node.op === "wireless.digital_link")) {
    return {
      label: "physical channel",
      tone: "active",
      tooltip: "The recipe includes an active physical/channel model rather than a disabled-channel bypass.",
    };
  }
  return null;
}

function renderGraph(graph) {
  if (!graph || !graph.nodes) {
    els.graphSurface.innerHTML = '<div class="graph-empty">No recipe graph</div>';
    bindGraphVisualizationSaveButton();
    return;
  }
  if (state.selectedEdgeKey && !graph.edges.some((edge) => graphEdgeKey(edge) === state.selectedEdgeKey)) {
    state.selectedEdgeKey = null;
  }
  const editorToolbar = graphEditorToolbarMarkup(graph);
  if (!graph.nodes.length) {
    els.graphSurface.innerHTML = `${editorToolbar}<div class="graph-empty graph-editor-empty">No blocks in this working recipe. Add a block to begin.</div>`;
    bindGraphEditorControls();
    bindGraphVisualizationSaveButton();
    return;
  }
  ensureNodePositions(graph);
  const size = graphCanvasSize(graph);
  const zoom = graphZoom();
  const width = Math.round(size.width * zoom);
  const height = Math.round(size.height * zoom);
  const edgeMarkup = graph.edges.map((edge, index) => edgeMarkupFor(edge, index)).join("");
  const nodeMarkup = graph.nodes
    .map((node, index) => {
      const pos = state.positions[node.id];
      const family = node.op.split(".")[0];
      const selected = state.selectedNodeId === node.id ? " selected" : "";
      const status = nodeStatus(node, index, graph);
      const progress = nodeProgress(node, graph, status);
      const flow = nodeFlowLabel(node, graph);
      const entropyInfo = nodeEntropyInfo(node);
      const role = canonicalBlockDisplayName(node);
      const detail = nodeDetailLabel(node, entropyInfo);
      const diffInfo = nodeDifferentiabilityInfo(node);
      const runnerInfo = nodeRunnerSupportInfo(node);
      const backendInfo = nodeBackendInfo(node, state.graphRunnerMode);
      const equivalenceInfo = nodeEquivalenceInfo(node);
      const tooltip = nodeTooltip(node, flow, entropyInfo, detail, diffInfo, runnerInfo, backendInfo, equivalenceInfo);
      const accessibleLabel = graphNodeAccessibleLabel(node, role, status, index, graph.nodes.length);
      return `
        <g class="node ${family} status-${escapeAttr(status.kind)}${selected}" data-node="${escapeAttr(node.id)}" data-graph-control transform="translate(${pos.x}, ${pos.y})" role="button" tabindex="-1" aria-pressed="${selected ? "true" : "false"}" aria-label="${escapeAttr(accessibleLabel)}" data-ui-tooltip="${escapeAttr(tooltip)}">
          <rect width="${NODE_W}" height="${NODE_H}"></rect>
          ${graphNodePortsMarkup(node)}
          ${nodeContractBadges(backendInfo, diffInfo, equivalenceInfo)}
          ${nodeStatusIcon(status.kind, status.label)}
          <text class="node-title" x="10" y="17">${escapeHtml(trim(role, 24))}</text>
          <text class="node-detail" x="10" y="36">${escapeHtml(trim(detail, 30))}</text>
          <text class="node-flow" x="10" y="54">${escapeHtml(trim(flow, 32))}</text>
          ${nodeProgressBar(progress)}
        </g>
      `;
    })
    .join("");

  els.graphSurface.innerHTML = `
    ${editorToolbar}
    <svg id="recipeSvg" width="${width}" height="${height}" viewBox="0 0 ${size.width} ${size.height}" role="group" tabindex="0" aria-label="${escapeAttr(graphCompositeAccessibleLabel(graph))}" aria-keyshortcuts="ArrowLeft ArrowRight ArrowUp ArrowDown Home End Enter Escape" style="--recipe-color: ${escapeAttr(recipeColor(state.selectedRecipe))}">
      <defs>
        <marker id="arrow" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="6" markerHeight="6" orient="auto-start-reverse">
          <path d="M 0 0 L 10 5 L 0 10 z" fill="#87928b"></path>
        </marker>
      </defs>
      <g id="edgeLayer">${edgeMarkup}${pendingGraphLinkMarkup()}</g>
      <g id="nodeLayer">${nodeMarkup}</g>
    </svg>
  `;
  bindGraphVisualizationSaveButton();
  bindGraphEditorControls();
  bindGraphPortControls();
  bindGraphCompositeNavigation();
  els.graphSurface.querySelectorAll("[data-node]").forEach((nodeEl) => {
    nodeEl.addEventListener("pointerdown", (event) => startNodeDrag(event, nodeEl.getAttribute("data-node")));
    nodeEl.addEventListener("click", (event) => {
      event.stopPropagation();
      selectNode(nodeEl.getAttribute("data-node"));
    });
    nodeEl.addEventListener("keydown", (event) => {
      activateGraphControlOnKeyboard(event, () => selectNode(nodeEl.getAttribute("data-node")));
    });
  });
  const svg = document.getElementById("recipeSvg");
  if (svg) {
    svg.addEventListener("click", () => {
      state.selectedNodeId = null;
      state.selectedEdgeKey = null;
      state.pendingGraphLink = null;
      renderGraph(state.graph);
      syncRecipeConfiguratorBlockSelection("");
    });
  }
  els.graphSurface.querySelectorAll("[data-select-edge]").forEach((edge) => {
    const select = (event) => {
      event.stopPropagation();
      const index = Number(edge.getAttribute("data-edit-edge"));
      const selectedEdge = state.graph && state.graph.edges ? state.graph.edges[index] : null;
      if (selectedEdge) selectGraphEdge(selectedEdge);
    };
    edge.addEventListener("click", select);
    edge.addEventListener("keydown", (event) => activateGraphControlOnKeyboard(event, () => select(event)));
  });
}

function graphCompositeAccessibleLabel(graph) {
  const nodes = graph && Array.isArray(graph.nodes) ? graph.nodes.length : 0;
  const edges = graph && Array.isArray(graph.edges) ? graph.edges.length : 0;
  return `Recipe graph, ${nodes} block${nodes === 1 ? "" : "s"} and ${edges} connection${edges === 1 ? "" : "s"}. Use arrow keys to inspect controls, Alt plus wheel to zoom, or Tab to skip the graph.`;
}

function graphNodeAccessibleLabel(node, role, status, index, total) {
  const block = role || canonicalBlockDisplayName(node) || "Block";
  const id = String((node && node.id) || "");
  const stateLabel = String((status && status.label) || "");
  return `Block ${index + 1} of ${total}: ${block}${id ? `, ${id}` : ""}${stateLabel ? `. ${stateLabel}` : ""}.`;
}

function bindGraphCompositeNavigation() {
  const svg = document.getElementById("recipeSvg");
  if (!svg) return;
  svg.addEventListener("keydown", (event) => {
    const controls = graphCompositeControls(svg);
    if (!controls.length) return;
    if (event.key === "Escape" && event.target !== svg) {
      event.preventDefault();
      event.stopPropagation();
      svg.focus();
      return;
    }
    if (event.target === svg && ["Enter", " "].includes(event.key)) {
      event.preventDefault();
      event.stopPropagation();
      controls[0].focus();
      return;
    }
    const navigationKeys = ["ArrowLeft", "ArrowRight", "ArrowUp", "ArrowDown", "Home", "End"];
    if (!navigationKeys.includes(event.key)) return;
    event.preventDefault();
    event.stopPropagation();
    const current = controls.indexOf(event.target);
    let next = current;
    if (event.key === "Home") next = 0;
    else if (event.key === "End") next = controls.length - 1;
    else if (event.key === "ArrowRight" || event.key === "ArrowDown") next = current < 0 ? 0 : (current + 1) % controls.length;
    else next = current < 0 ? controls.length - 1 : (current - 1 + controls.length) % controls.length;
    controls[next].focus();
  });
}

function graphCompositeControls(svg) {
  if (!svg) return [];
  return [
    ...svg.querySelectorAll("[data-node][data-graph-control]"),
    ...svg.querySelectorAll("[data-node-output][data-graph-control]"),
    ...svg.querySelectorAll("[data-node-input][data-graph-control]"),
    ...svg.querySelectorAll("[data-select-edge][data-graph-control]"),
  ];
}

function activateGraphControlOnKeyboard(event, action) {
  if (!["Enter", " "].includes(event.key)) return;
  event.preventDefault();
  event.stopPropagation();
  action();
}

function graphEditorToolbarMarkup(graph) {
  const issues = graphRecipeConfigurationIssues(state.editRecipe);
  const statusClass = issues.length ? "invalid" : "valid";
  const statusLabel = issues.length ? `${issues.length} issue${issues.length === 1 ? "" : "s"}` : "Valid topology";
  const statusTooltip = issues.length
    ? `${statusLabel}: ${issues[0]}`
    : "Valid topology. All operation inputs are connected with compatible artifact types.";
  return `
    <div class="graph-editor-toolbar" data-graph-editor-toolbar role="toolbar" aria-label="Graph editing">
      <button type="button" class="icon-button graph-editor-icon-button graph-validation-state ${statusClass}" data-graph-show-issues aria-label="${escapeAttr(statusLabel)}" data-ui-tooltip="${escapeAttr(statusTooltip)}">${topologyStatusIconMarkup(!issues.length)}</button>
      <button type="button" class="icon-button graph-editor-icon-button graph-add-block-button" data-graph-add-block aria-label="Add block" data-ui-tooltip="Add block"${state.busy ? " disabled" : ""}>${addBlockIconMarkup()}</button>
      <button type="button" class="icon-button destructive-icon-button graph-editor-icon-button" data-graph-remove-selected aria-label="Remove selected block or link" data-ui-tooltip="Remove selected block or link"${(state.selectedNodeId || state.selectedEdgeKey) && !state.busy ? "" : " disabled"}>${deleteIconMarkup()}</button>
    </div>
  `;
}

function addBlockIconMarkup() {
  return `<svg class="action-icon-glyph" viewBox="0 0 24 24" aria-hidden="true"><path d="M12 5v14M5 12h14"></path></svg>`;
}

function deleteIconMarkup() {
  return `<svg class="action-icon-glyph" viewBox="0 0 24 24" aria-hidden="true"><path d="M4 7h16M9 7V4h6v3M7 7l1 13h8l1-13M10 11v5M14 11v5"></path></svg>`;
}

function topologyStatusIconMarkup(valid) {
  const symbol = valid
    ? '<path d="m7.5 12.3 3 3 6-7"></path>'
    : '<path d="M12 7.5v5.5M12 16.5h.01"></path>';
  return `<svg class="action-icon-glyph topology-status-glyph" viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="12" r="9"></circle>${symbol}</svg>`;
}

function bindGraphEditorControls() {
  els.graphSurface.querySelectorAll("[data-graph-add-block]").forEach((button) => button.addEventListener("click", openGraphAddBlockDialog));
  els.graphSurface.querySelectorAll("[data-graph-remove-selected]").forEach((button) => {
    button.addEventListener("click", removeCurrentGraphSelection);
  });
  els.graphSurface.querySelectorAll("[data-graph-show-issues]").forEach((button) => {
    button.addEventListener("click", () => {
      const issues = graphRecipeConfigurationIssues(state.editRecipe);
      notify(issues.length ? issues[0] : "recipe topology is valid");
    });
  });
}

function openGraphAddBlockDialog() {
  if (!state.editRecipe || state.busy) return;
  renderGraphAddBlockDialog("", "");
}

function openGraphReplaceBlockDialog(stepId) {
  if (!state.editRecipe || state.busy || !findStep(stepId)) return;
  renderGraphReplaceBlockDialog(stepId, "", "");
}

function renderGraphReplaceBlockDialog(stepId, query = "", selectedOperationId = "") {
  const step = findStep(stepId);
  if (!step) return;
  state.settingsSection = "graph-replace-block";
  const normalizedQuery = String(query || "").trim().toLowerCase();
  const operations = (state.operations || []).filter((operation) => {
    if (!normalizedQuery) return true;
    return `${operation.id} ${operation.name || ""}`.toLowerCase().includes(normalizedQuery);
  });
  const selectable = operations.filter(operationAvailable);
  const selectedId = selectable.some((operation) => operation.id === selectedOperationId)
    ? selectedOperationId
    : selectable.find((operation) => operation.id !== step.op)?.id || step.op;
  const selectedOperation = operationById(selectedId);
  const replacing = Boolean(selectedOperation && selectedOperation.id !== step.op);
  els.settingsTitle.textContent = `Replace ${step.id}`;
  els.settingsSubtitle.textContent = "Explicit graph-contract change";
  els.settingsBody.innerHTML = `
    <div class="graph-operation-picker">
      <div class="config-warning compact"><strong>Current operation</strong><code>${escapeHtml(step.op)}</code><span>Replacement keeps the block ID and description. Compatible inputs and same-name parameters are retained; incompatible edges and matrix bindings are removed.</span></div>
      <label>
        <span>Search operations</span>
        <input data-replace-operation-search value="${escapeAttr(query)}" placeholder="Search by operation name or ID" autofocus />
      </label>
      <label>
        <span>New operation</span>
        <select size="12" data-replace-operation-select>
          ${graphOperationOptions(operations, selectedId)}
        </select>
      </label>
      <div class="graph-operation-preview">
        ${selectedOperation ? graphOperationPreviewMarkup(selectedOperation) : '<div class="field-hint">No available operations match this search.</div>'}
      </div>
      <div class="recipe-library-dialog-actions">
        <button type="button" class="primary" data-confirm-replace-graph-block${replacing ? "" : " disabled"}>Replace operation</button>
      </div>
    </div>
  `;
  const search = els.settingsBody.querySelector("[data-replace-operation-search]");
  const select = els.settingsBody.querySelector("[data-replace-operation-select]");
  if (search) search.addEventListener("input", () => {
    renderGraphReplaceBlockDialog(stepId, search.value, "");
    const nextSearch = els.settingsBody.querySelector("[data-replace-operation-search]");
    if (nextSearch) {
      nextSearch.focus();
      nextSearch.setSelectionRange(nextSearch.value.length, nextSearch.value.length);
    }
  });
  if (select) select.addEventListener("change", () => renderGraphReplaceBlockDialog(stepId, query, select.value));
  const replaceButton = els.settingsBody.querySelector("[data-confirm-replace-graph-block]");
  if (replaceButton) replaceButton.addEventListener("click", () => replaceRecipeOperation(stepId, selectedId));
  els.settingsOverlay.hidden = false;
}

function renderGraphAddBlockDialog(query = "", selectedOperationId = "") {
  state.settingsSection = "graph-add-block";
  const normalizedQuery = String(query || "").trim().toLowerCase();
  const operations = (state.operations || []).filter((operation) => {
    if (!normalizedQuery) return true;
    return `${operation.id} ${operation.name || ""}`.toLowerCase().includes(normalizedQuery);
  });
  const selectable = operations.filter(operationAvailable);
  const selectedId = selectable.some((operation) => operation.id === selectedOperationId)
    ? selectedOperationId
    : selectable[0]
      ? selectable[0].id
      : "";
  const selectedOperation = operationById(selectedId);
  els.settingsTitle.textContent = "Add Pipeline Block";
  els.settingsSubtitle.textContent = `${selectable.length} available operation${selectable.length === 1 ? "" : "s"}`;
  els.settingsBody.innerHTML = `
    <div class="graph-operation-picker">
      <label>
        <span>Search operations</span>
        <input data-graph-operation-search value="${escapeAttr(query)}" placeholder="Search by operation name or ID" autofocus />
      </label>
      <label>
        <span>Operation</span>
        <select size="12" data-graph-operation-select>
          ${graphOperationOptions(operations, selectedId)}
        </select>
      </label>
      <div class="graph-operation-preview">
        ${selectedOperation ? graphOperationPreviewMarkup(selectedOperation) : '<div class="field-hint">No available operations match this search.</div>'}
      </div>
      <div class="recipe-library-dialog-actions">
        <button type="button" class="primary" data-confirm-add-graph-block${selectedOperation ? "" : " disabled"}>Add block</button>
      </div>
    </div>
  `;
  const search = els.settingsBody.querySelector("[data-graph-operation-search]");
  const select = els.settingsBody.querySelector("[data-graph-operation-select]");
  if (search) search.addEventListener("input", () => {
    renderGraphAddBlockDialog(search.value, "");
    const nextSearch = els.settingsBody.querySelector("[data-graph-operation-search]");
    if (nextSearch) {
      nextSearch.focus();
      nextSearch.setSelectionRange(nextSearch.value.length, nextSearch.value.length);
    }
  });
  if (select) select.addEventListener("change", () => renderGraphAddBlockDialog(query, select.value));
  const addButton = els.settingsBody.querySelector("[data-confirm-add-graph-block]");
  if (addButton) addButton.addEventListener("click", () => addRecipeOperation(selectedId));
  els.settingsOverlay.hidden = false;
}

function graphOperationOptions(operations, selectedId) {
  const families = new Map();
  (operations || []).forEach((operation) => {
    const family = String(operation.id || "operation").split(".")[0];
    if (!families.has(family)) families.set(family, []);
    families.get(family).push(operation);
  });
  return Array.from(families.entries())
    .sort(([left], [right]) => left.localeCompare(right))
    .map(([family, items]) => `
      <optgroup label="${escapeAttr(titleCaseShort(family))}">
        ${items.sort((left, right) => left.id.localeCompare(right.id)).map((operation) => {
          const available = operationAvailable(operation);
          return `<option value="${escapeAttr(operation.id)}"${operation.id === selectedId ? " selected" : ""}${available ? "" : " disabled"}>${escapeHtml(operation.name || operation.id)} - ${escapeHtml(operation.id)}</option>`;
        }).join("")}
      </optgroup>
    `).join("");
}

function graphOperationPreviewMarkup(operation) {
  const inputs = Object.entries(operationInputKinds(operation));
  const outputs = Object.entries(operation.output_kinds || {});
  const params = Object.keys(((operation.params_schema || {}).properties) || {});
  return `
    <strong>${escapeHtml(operation.name || operation.id)}</strong>
    <code>${escapeHtml(operation.id)}</code>
    <div class="graph-operation-contract-row"><span>Inputs</span><b>${escapeHtml(inputs.length ? inputs.map(([name]) => name).join(", ") : "none")}</b></div>
    <div class="graph-operation-contract-row"><span>Outputs</span><b>${escapeHtml(outputs.length ? outputs.map(([name]) => name).join(", ") : "none")}</b></div>
    <div class="graph-operation-contract-row"><span>Parameters</span><b>${escapeHtml(params.length ? params.join(", ") : "none")}</b></div>
  `;
}

function uniqueStepIdForOperation(operationId) {
  const base = slugName(String(operationId || "operation").split(".").pop());
  const used = new Set((state.editRecipe && state.editRecipe.steps || []).map((step) => step.id));
  if (!used.has(base)) return base;
  let index = 2;
  while (used.has(`${base}_${index}`)) index += 1;
  return `${base}_${index}`;
}

function addRecipeOperation(operationId) {
  const operation = operationById(operationId);
  if (!state.editRecipe || !operation || !operationAvailable(operation)) return;
  const stepId = uniqueStepIdForOperation(operationId);
  const step = {
    id: stepId,
    op: operationId,
    inputs: {},
    params: structuredCloneFallback(defaultParamsFor(operation)),
  };
  if (!Array.isArray(state.editRecipe.steps)) state.editRecipe.steps = [];
  state.editRecipe.steps.push(step);
  state.positions[stepId] = visibleGraphInsertionPosition();
  state.selectedNodeId = stepId;
  storeRecipeConfiguratorView("blocks");
  state.selectedEdgeKey = null;
  commitRecipeTopologyEdit(true);
  closeSettingsDialog();
  syncRecipeConfiguratorBlockSelection(stepId, { scroll: true });
  notify(`added ${stepId}`);
}

function recipeReferenceIsCompatible(targetStep, inputName, reference) {
  const sourceId = String(reference || "").split(".")[0];
  const outputName = String(reference || "").slice(sourceId.length + 1);
  const sourceStep = findStep(sourceId);
  const sourceOperation = sourceStep && operationById(sourceStep.op);
  const targetOperation = targetStep && operationById(targetStep.op);
  const outputKind = sourceOperation && (sourceOperation.output_kinds || {})[outputName];
  const acceptedKinds = targetOperation && operationInputKinds(targetOperation)[inputName];
  return Boolean(outputKind && Array.isArray(acceptedKinds) && (!acceptedKinds.length || acceptedKinds.includes(outputKind)));
}

function recipeSweepTargetsAreValid(recipe, path) {
  const targets = sweepTargetsForPath(recipe, path);
  return Boolean(targets.length && targets.every(({ stepId, param }) => {
    const step = stepById((recipe && recipe.steps) || [], stepId);
    return recipeStepAcceptsParameter(step, param);
  }));
}

function removeRecipeVariantsTargetingStep(recipe, stepId) {
  const canonical = canonicalRecipeMatrix(recipe);
  if (canonical !== null) {
    const before = recipeMatrixBindings(recipe, canonical).length;
    removeRecipeMatrixStep(recipe, stepId);
    const afterMatrix = canonicalRecipeMatrix(recipe);
    return Math.max(0, before - (afterMatrix ? recipeMatrixBindings(recipe, afterMatrix).length : 0));
  }
  const specs = recipeSweepSpecs(recipe);
  const retained = {};
  let removed = 0;
  Object.entries(specs).forEach(([path, spec]) => {
    if (sweepTargetsForPath(recipe, path).some((target) => target.stepId === stepId)) removed += 1;
    else retained[path] = spec;
  });
  writeRecipeSweepMatrixFromPathSpecs(recipe, retained);
  return removed;
}

function reconcileRecipeVariantReferences(recipe) {
  const canonical = canonicalRecipeMatrix(recipe);
  if (canonical !== null) {
    const before = recipeMatrixBindings(recipe, canonical).length;
    commitCanonicalMatrixMutation(recipe, structuredCloneFallback(canonical));
    const afterMatrix = canonicalRecipeMatrix(recipe);
    return Math.max(0, before - (afterMatrix ? recipeMatrixBindings(recipe, afterMatrix).length : 0));
  }
  const metadata = recipe && recipe.metadata && typeof recipe.metadata === "object" ? recipe.metadata : {};
  const hasLegacy = ["sweep", "sweeps", "ui_sweeps"].some((key) => Object.prototype.hasOwnProperty.call(metadata, key));
  if (!hasLegacy) return 0;
  const specs = recipeSweepSpecs(recipe);
  const retained = {};
  let removed = 0;
  Object.entries(specs).forEach(([path, spec]) => {
    if (recipeSweepTargetsAreValid(recipe, path)) retained[path] = spec;
    else removed += 1;
  });
  writeRecipeSweepMatrixFromPathSpecs(recipe, retained);
  delete recipe.metadata.sweep;
  return removed;
}

function recipeCaptureSweepTargetSteps(recipe, path) {
  const text = String(path || "");
  const separator = text.indexOf(".");
  if (separator < 1 || separator >= text.length - 1) return [];
  const stepId = text.slice(0, separator);
  const param = text.slice(separator + 1);
  const steps = (recipe && recipe.steps) || [];
  const isEffectiveTarget = (step) => {
    if (!recipeStepAcceptsParameter(step, param)) return false;
    const operation = operationById(step.op) || {};
    const properties = (((operation.params_schema || {}).properties) || {});
    return !properties[param] || schemaParameterIsEffective(properties[param], step, properties);
  };
  const direct = stepById(steps, stepId);
  if (direct) return isEffectiveTarget(direct) ? [direct] : [];
  if (stepId !== "channel") return [];
  return steps.filter((step) => (
    (String(step.op || "").startsWith("wireless.") || step.id === "wireless_channel" || Object.prototype.hasOwnProperty.call(step.params || {}, param)) &&
    isEffectiveTarget(step)
  ));
}

function recipeCaptureSweepTargetIsValid(recipe, path) {
  return recipeCaptureSweepTargetSteps(recipe, path).length > 0;
}

function removeRecipeDatasetCaptureSweepsTargetingStep(recipe, stepId, referenceRecipe = recipe) {
  const capture = recipe && recipe.dataset_capture;
  if (!capture || capture.sweep === undefined) return 0;
  let removed = 0;
  const filterAssignment = (assignment) => {
    if (!assignment || typeof assignment !== "object" || Array.isArray(assignment)) return null;
    const retained = {};
    Object.entries(assignment).forEach(([path, value]) => {
      if (recipeCaptureSweepTargetSteps(referenceRecipe, path).some((step) => step.id === stepId)) removed += 1;
      else retained[path] = value;
    });
    return Object.keys(retained).length ? retained : null;
  };
  if (Array.isArray(capture.sweep)) {
    const retained = capture.sweep.map(filterAssignment).filter(Boolean);
    if (retained.length) capture.sweep = retained;
    else delete capture.sweep;
  } else if (capture.sweep && typeof capture.sweep === "object") {
    const retained = filterAssignment(capture.sweep);
    if (retained) capture.sweep = retained;
    else delete capture.sweep;
  }
  return removed;
}

function reconcileRecipeDatasetCaptureReferences(recipe) {
  const capture = recipe && recipe.dataset_capture;
  if (!capture || typeof capture !== "object" || Array.isArray(capture)) return 0;
  let removed = 0;
  if (Array.isArray(capture.taps)) {
    const validReferences = new Set(availableCaptureTapOptions(recipe).map((item) => item.ref));
    const taps = capture.taps.filter((tap) => tap && validReferences.has(String(tap.from || "")));
    removed += capture.taps.length - taps.length;
    capture.taps = taps;
  }
  const filterSweepAssignment = (assignment, grid = false) => {
    if (!assignment || typeof assignment !== "object" || Array.isArray(assignment)) return null;
    const retained = {};
    Object.entries(assignment).forEach(([path, value]) => {
      const problem = !recipeCaptureSweepTargetIsValid(recipe, path)
        ? `unknown target ${path}`
        : grid
          ? recipeCaptureSweepGridProblem(recipe, path, value)
          : recipeCaptureSweepValueProblem(recipe, path, value);
      if (problem) removed += 1;
      else setOwnJsonProperty(retained, path, value);
    });
    return Object.keys(retained).length ? retained : null;
  };
  if (canonicalRecipeMatrix(recipe) !== null && capture.sweep !== undefined) {
    removed += Array.isArray(capture.sweep)
      ? capture.sweep.reduce((count, assignment) => count + Object.keys(assignment || {}).length, 0)
      : Object.keys(capture.sweep || {}).length;
    delete capture.sweep;
  } else if (Array.isArray(capture.sweep)) {
    const retained = capture.sweep.map(filterSweepAssignment).filter(Boolean);
    if (retained.length) capture.sweep = retained;
    else delete capture.sweep;
  } else if (capture.sweep && typeof capture.sweep === "object") {
    const retained = filterSweepAssignment(capture.sweep, true);
    if (retained) capture.sweep = retained;
    else delete capture.sweep;
  }
  if (capture.sweep !== undefined && recipeCaptureSweepPlanProblem(recipe, capture.sweep)) {
    removed += Array.isArray(capture.sweep)
      ? capture.sweep.reduce((count, assignment) => count + Object.keys(assignment || {}).length, 0)
      : Object.keys(capture.sweep || {}).length;
    delete capture.sweep;
  }
  return removed;
}

function removeTrainedArtifactBindingForStep(recipe, stepId) {
  const metadata = recipe && recipe.metadata;
  const bindings = metadata && metadata.trained_artifact_bindings;
  const current = bindings && bindings[stepId];
  if (!current) return 0;
  const group = String(current.binding_group || "");
  let removed = 0;
  Object.entries(bindings).forEach(([boundStepId, binding]) => {
    if (boundStepId === stepId || (group && binding && binding.id === current.id && String(binding.binding_group || "") === group)) {
      delete bindings[boundStepId];
      removed += 1;
    }
  });
  if (!Object.keys(bindings).length) delete metadata.trained_artifact_bindings;
  return removed;
}

function reconcileRecipeTrainedArtifactBindings(recipe, previousRecipe = null) {
  const metadata = recipe && recipe.metadata;
  const bindings = metadata && metadata.trained_artifact_bindings;
  if (!bindings || typeof bindings !== "object" || Array.isArray(bindings)) return 0;
  const previousSteps = new Map((((previousRecipe && previousRecipe.steps) || [])).map((step) => [String(step.id), step]));
  const invalid = new Set();
  Object.entries(bindings).forEach(([stepId, stored]) => {
    const step = stepById((recipe && recipe.steps) || [], stepId);
    const previousStep = previousSteps.get(stepId);
    if (!step || (previousStep && previousStep.op !== step.op) || !stored || typeof stored !== "object") {
      invalid.add(stepId);
      return;
    }
    const artifacts = (state.trainedArtifacts || []).filter((artifact) => String(artifact.id || "") === String(stored.id || ""));
    if (!artifacts.length) return;
    const stillMatches = compatibleTrainedArtifactChoices(step, recipe).some((choice) => {
      if (String(choice.artifact.id || "") !== String(stored.id || "")) return false;
      if (stored.manifest_path && String(choice.artifact.manifest_path || "") !== String(stored.manifest_path)) return false;
      const sha = choice.artifact.artifact && choice.artifact.artifact.sha256;
      if (stored.sha256 && String(sha || "") !== String(stored.sha256)) return false;
      if (stored.binding_group && String(choice.binding.binding_group || "") !== String(stored.binding_group)) return false;
      if (stored.role && String(choice.binding.role || "") !== String(stored.role)) return false;
      return choice.ready && Object.entries(choice.binding.params || {}).every(
        ([name, value]) => Object.prototype.hasOwnProperty.call(step.params || {}, name) && schemaValuesEqual(step.params[name], value)
      );
    });
    if (!stillMatches) invalid.add(stepId);
  });
  let removed = 0;
  Array.from(invalid).forEach((stepId) => {
    if (metadata.trained_artifact_bindings && metadata.trained_artifact_bindings[stepId]) {
      removed += removeTrainedArtifactBindingForStep(recipe, stepId);
    }
  });
  return removed;
}

function reconcileRecipeTopologyReferences(recipe, previousRecipe = null) {
  const variants = reconcileRecipeVariantReferences(recipe);
  const capture = reconcileRecipeDatasetCaptureReferences(recipe);
  const artifacts = reconcileRecipeTrainedArtifactBindings(recipe, previousRecipe);
  return { variants, capture, artifacts, total: variants + capture + artifacts };
}

function replaceRecipeOperation(stepId, operationId) {
  const step = findStep(stepId);
  const operation = operationById(operationId);
  if (!step || !operation || step.op === operationId || !operationAvailable(operation)) return;
  const previousRecipe = structuredCloneFallback(state.editRecipe);
  const previousParams = { ...(step.params || {}) };
  const previousInputs = { ...(step.inputs || {}) };
  const parameterSchema = operation.params_schema || {};
  const properties = parameterSchema.properties || {};
  const additional = parameterSchema.additionalProperties;
  const nextParams = structuredCloneFallback(defaultParamsFor(operation));
  let droppedParams = 0;
  Object.entries(previousParams).forEach(([name, value]) => {
    const schema = Object.prototype.hasOwnProperty.call(properties, name)
      ? properties[name]
      : additional === true
        ? {}
        : additional && typeof additional === "object"
          ? additional
          : null;
    if (!schema || schemaValueProblem(value, schema)) {
      droppedParams += 1;
      return;
    }
    setOwnJsonProperty(nextParams, name, structuredCloneFallback(value));
  });
  step.op = operationId;
  step.params = nextParams;
  step.inputs = {};
  Object.keys(operationInputKinds(operation)).forEach((inputName) => {
    const reference = previousInputs[inputName];
    if (reference && recipeReferenceIsCompatible(step, inputName, reference)) step.inputs[inputName] = reference;
  });
  let disconnected = Object.keys(previousInputs).length - Object.keys(step.inputs).length;
  const outputs = operation.output_kinds || {};
  (state.editRecipe.steps || []).forEach((target) => {
    if (target.id === stepId) return;
    Object.entries(target.inputs || {}).forEach(([inputName, reference]) => {
      if (!String(reference).startsWith(`${stepId}.`)) return;
      const outputName = String(reference).slice(stepId.length + 1);
      if (!Object.prototype.hasOwnProperty.call(outputs, outputName) || !recipeReferenceIsCompatible(target, inputName, reference)) {
        delete target.inputs[inputName];
        disconnected += 1;
      }
    });
  });
  const removedVariants = removeRecipeVariantsTargetingStep(state.editRecipe, stepId);
  const removedArtifacts = removeTrainedArtifactBindingForStep(state.editRecipe, stepId);
  const removedCaptureSweeps = removeRecipeDatasetCaptureSweepsTargetingStep(state.editRecipe, stepId, previousRecipe);
  const reconciled = reconcileRecipeTopologyReferences(state.editRecipe, previousRecipe);
  state.selectedNodeId = stepId;
  state.selectedEdgeKey = null;
  state.pendingGraphLink = null;
  commitRecipeTopologyEdit(true);
  closeSettingsDialog();
  syncRecipeConfiguratorBlockSelection(stepId, { scroll: true });
  const pruned = removedVariants + removedArtifacts + removedCaptureSweeps + reconciled.total;
  notify(`replaced ${stepId} with ${operationId}${disconnected ? `; disconnected ${disconnected} incompatible edge${disconnected === 1 ? "" : "s"}` : ""}${droppedParams ? `; reset ${droppedParams} incompatible parameter${droppedParams === 1 ? "" : "s"}` : ""}${pruned ? `; pruned ${pruned} stale recipe reference${pruned === 1 ? "" : "s"}` : ""}`);
}

function visibleGraphInsertionPosition() {
  const surface = els.graphSurface;
  const zoom = graphZoom();
  const centerX = (surface.scrollLeft + surface.clientWidth / 2) / zoom - NODE_W / 2;
  const centerY = (surface.scrollTop + surface.clientHeight / 2) / zoom - NODE_H / 2;
  return { x: Math.max(12, centerX), y: Math.max(56, centerY) };
}

function ensureNodePositions(graph) {
  graph.nodes.forEach((node, index) => {
    if (state.positions[node.id]) return;
    const family = node.op.split(".")[0];
    const y = family === "metrics" ? 276 : 72 + (index % 2) * 32;
    state.positions[node.id] = { x: 48 + index * 208, y };
  });
}

function graphBounds(graph) {
  let maxX = 0;
  let maxY = 0;
  graph.nodes.forEach((node) => {
    const pos = state.positions[node.id] || { x: 0, y: 0 };
    maxX = Math.max(maxX, pos.x + NODE_W);
    maxY = Math.max(maxY, pos.y + NODE_H);
  });
  return { maxX, maxY };
}

function graphCanvasSize(graph) {
  const bounds = graphBounds(graph || { nodes: [] });
  return {
    width: Math.max(920, bounds.maxX + 320),
    height: Math.max(620, bounds.maxY + 260),
  };
}

function graphZoom() {
  return Math.max(GRAPH_ZOOM_MIN, Math.min(GRAPH_ZOOM_MAX, Number(state.graphZoom) || 1));
}

function applyGraphCanvasSize() {
  const svg = document.getElementById("recipeSvg");
  if (!svg || !state.graph) return;
  const size = graphCanvasSize(state.graph);
  const zoom = graphZoom();
  svg.setAttribute("viewBox", `0 0 ${size.width} ${size.height}`);
  svg.setAttribute("width", String(Math.round(size.width * zoom)));
  svg.setAttribute("height", String(Math.round(size.height * zoom)));
}

function edgeMarkupFor(edge, index) {
  const endpoints = graphEdgeEndpoints(edge);
  if (!endpoints) return "";
  const path = graphConnectionPath(endpoints.x1, endpoints.y1, endpoints.x2, endpoints.y2);
  const label = edgeLabelPosition(endpoints);
  const selected = graphEdgeKey(edge) === state.selectedEdgeKey;
  const accessibleLabel = `Connection ${index + 1}: ${edge.from_step}.${edge.from_output} to ${edge.to_step}.${edge.to_input}. ${edgeDataLabel(edge)}`;
  return `
    <path class="edge-hit-area" data-edge-hit="${index}" data-select-edge="${index}" data-edit-edge="${index}" data-graph-control d="${path}" role="button" tabindex="-1" aria-pressed="${selected ? "true" : "false"}" aria-label="${escapeAttr(accessibleLabel)}" />
    <path class="edge${selected ? " selected" : ""}" data-edge="${index}" d="${path}" marker-end="url(#arrow)" />
    <text class="edge-label" data-edge-label="${index}" x="${label.x}" y="${label.y}">${escapeHtml(edgeDataLabel(edge))}</text>
  `;
}

function graphConnectionPath(x1, y1, x2, y2) {
  const mid = x1 + Math.max(28, (x2 - x1) / 2);
  return `M ${x1} ${y1} C ${mid} ${y1}, ${mid} ${y2}, ${x2} ${y2}`;
}

function edgeLabelPosition(endpoints) {
  return { x: (endpoints.x1 + endpoints.x2) / 2, y: (endpoints.y1 + endpoints.y2) / 2 - 10 };
}

function graphEdgeKey(edge) {
  return edge ? `${edge.to_step}.${edge.to_input}` : "";
}

function graphPortY(index, count) {
  if (count <= 1) return NODE_H / 2;
  const minY = 24;
  const maxY = NODE_H - 30;
  return minY + (index / (count - 1)) * (maxY - minY);
}

function graphEdgeEndpoints(edge) {
  const source = state.positions[edge.from_step];
  const target = state.positions[edge.to_step];
  if (!source || !target || !state.graph) return null;
  const sourceNode = (state.graph.nodes || []).find((node) => node.id === edge.from_step);
  const targetNode = (state.graph.nodes || []).find((node) => node.id === edge.to_step);
  const outputNames = Object.keys((sourceNode && sourceNode.outputs) || {});
  const inputNames = Object.keys((targetNode && targetNode.inputs) || {});
  const outputIndex = Math.max(0, outputNames.indexOf(edge.from_output));
  const inputIndex = Math.max(0, inputNames.indexOf(edge.to_input));
  return {
    x1: source.x + NODE_W,
    y1: source.y + graphPortY(outputIndex, Math.max(1, outputNames.length)),
    x2: target.x,
    y2: target.y + graphPortY(inputIndex, Math.max(1, inputNames.length)),
  };
}

function graphNodePortsMarkup(node) {
  const inputs = Object.entries(node.inputs || {});
  const outputs = Object.entries(node.outputs || {});
  const inputMarkup = inputs.map(([name, acceptedKinds], index) => {
    const current = String(((findStep(node.id) || {}).inputs || {})[name] || "");
    const compatibility = pendingLinkCompatibility(node.id, name, acceptedKinds);
    const classes = ["node-port", "node-input-port"];
    if (current) classes.push("connected");
    if (compatibility) classes.push(compatibility);
    return `
      <circle class="${classes.join(" ")}" cx="0" cy="${graphPortY(index, inputs.length)}" r="6"
        data-node-input="${escapeAttr(node.id)}" data-port-name="${escapeAttr(name)}" data-graph-control
        role="button" tabindex="-1" aria-label="${escapeAttr(`Input ${name} on ${canonicalBlockDisplayName(node)}${current ? `, connected from ${current}` : ", unconnected"}.`)}"
        data-ui-tooltip="${escapeAttr(`${node.id}.${name} input${current ? ` - ${current}` : ""}\nAccepts: ${(acceptedKinds || []).join(", ") || "any artifact"}`)}">
      </circle>
    `;
  }).join("");
  const outputMarkup = outputs.map(([name, kind], index) => `
    <circle class="node-port node-output-port${state.pendingGraphLink && state.pendingGraphLink.sourceStep === node.id && state.pendingGraphLink.sourceOutput === name ? " active" : ""}"
      cx="${NODE_W}" cy="${graphPortY(index, outputs.length)}" r="6"
      data-node-output="${escapeAttr(node.id)}" data-port-name="${escapeAttr(name)}" data-port-kind="${escapeAttr(kind)}" data-graph-control
      role="button" tabindex="-1" aria-label="${escapeAttr(`Output ${name} on ${canonicalBlockDisplayName(node)}.`)}" data-ui-tooltip="${escapeAttr(`${node.id}.${name} output\n${kind}`)}">
    </circle>
  `).join("");
  return `<g class="node-ports">${inputMarkup}${outputMarkup}</g>`;
}

function pendingLinkCompatibility(targetStepId, inputName, acceptedKinds) {
  const pending = state.pendingGraphLink;
  if (!pending) return "";
  const acceptsKind = !acceptedKinds.length || acceptedKinds.includes(pending.kind);
  const cyclic = connectionWouldCreateCycle(pending.sourceStep, targetStepId, inputName);
  return acceptsKind && !cyclic ? "compatible" : "incompatible";
}

function pendingGraphLinkMarkup() {
  const pending = state.pendingGraphLink;
  if (!pending) return "";
  const source = state.positions[pending.sourceStep];
  const sourceNode = state.graph && state.graph.nodes.find((node) => node.id === pending.sourceStep);
  if (!source || !sourceNode) return "";
  const outputNames = Object.keys(sourceNode.outputs || {});
  const outputIndex = Math.max(0, outputNames.indexOf(pending.sourceOutput));
  const x1 = source.x + NODE_W;
  const y1 = source.y + graphPortY(outputIndex, Math.max(1, outputNames.length));
  const pointer = pending.pointer || { x: x1 + 96, y: y1 };
  return `<path id="pendingGraphEdge" class="edge pending" d="${graphConnectionPath(x1, y1, pointer.x, pointer.y)}" marker-end="url(#arrow)" />`;
}

function bindGraphPortControls() {
  els.graphSurface.querySelectorAll("[data-node-output]").forEach((port) => {
    port.addEventListener("pointerdown", (event) => event.stopPropagation());
    const activate = (event) => {
      event.preventDefault();
      event.stopPropagation();
      startPendingGraphLink(
        port.getAttribute("data-node-output"),
        port.getAttribute("data-port-name"),
        port.getAttribute("data-port-kind")
      );
    };
    port.addEventListener("click", activate);
    port.addEventListener("keydown", (event) => activateGraphControlOnKeyboard(event, () => activate(event)));
  });
  els.graphSurface.querySelectorAll("[data-node-input]").forEach((port) => {
    port.addEventListener("pointerdown", (event) => event.stopPropagation());
    const activate = (event) => {
      event.preventDefault();
      event.stopPropagation();
      completePendingGraphLink(port.getAttribute("data-node-input"), port.getAttribute("data-port-name"));
    };
    port.addEventListener("click", activate);
    port.addEventListener("keydown", (event) => activateGraphControlOnKeyboard(event, () => activate(event)));
  });
}

function startPendingGraphLink(sourceStep, sourceOutput, kind) {
  if (state.busy || state.graphInteractionMode !== "edit") return;
  state.selectedNodeId = null;
  state.selectedEdgeKey = null;
  state.pendingGraphLink = { sourceStep, sourceOutput, kind, pointer: null };
  renderGraph(state.graph);
  renderRecipeControls();
}

function completePendingGraphLink(targetStep, targetInput) {
  const pending = state.pendingGraphLink;
  if (!pending) {
    const target = findStep(targetStep);
    const reference = target && target.inputs ? target.inputs[targetInput] : "";
    const edge = state.graph && state.graph.edges.find((item) => graphEdgeKey(item) === `${targetStep}.${targetInput}`);
    if (reference && edge) selectGraphEdge(edge);
    else selectNode(targetStep);
    return;
  }
  try {
    setRecipeInputConnection(targetStep, targetInput, `${pending.sourceStep}.${pending.sourceOutput}`);
    state.pendingGraphLink = null;
    state.selectedNodeId = null;
    state.selectedEdgeKey = `${targetStep}.${targetInput}`;
    commitRecipeTopologyEdit(true);
    notify(`connected ${pending.sourceStep}.${pending.sourceOutput} to ${targetStep}.${targetInput}`);
  } catch (error) {
    notify(error.message || String(error));
  }
}

function cancelPendingGraphLink() {
  if (!state.pendingGraphLink) return;
  state.pendingGraphLink = null;
  if (state.graph) renderGraph(state.graph);
}

function updatePendingGraphLinkPointer(event) {
  if (!state.pendingGraphLink) return;
  const svg = document.getElementById("recipeSvg");
  const path = document.getElementById("pendingGraphEdge");
  if (!svg || !path) return;
  const rect = svg.getBoundingClientRect();
  const viewBox = svg.viewBox && svg.viewBox.baseVal;
  if (!rect.width || !rect.height || !viewBox) return;
  const x = viewBox.x + ((event.clientX - rect.left) / rect.width) * viewBox.width;
  const y = viewBox.y + ((event.clientY - rect.top) / rect.height) * viewBox.height;
  state.pendingGraphLink.pointer = { x, y };
  const source = state.positions[state.pendingGraphLink.sourceStep];
  const sourceNode = state.graph && state.graph.nodes.find((node) => node.id === state.pendingGraphLink.sourceStep);
  if (!source || !sourceNode) return;
  const outputNames = Object.keys(sourceNode.outputs || {});
  const index = Math.max(0, outputNames.indexOf(state.pendingGraphLink.sourceOutput));
  const x1 = source.x + NODE_W;
  const y1 = source.y + graphPortY(index, Math.max(1, outputNames.length));
  path.setAttribute("d", graphConnectionPath(x1, y1, x, y));
}

function updateGraphGeometry() {
  if (!state.graph) return;
  applyGraphCanvasSize();
  state.graph.nodes.forEach((node) => {
    const pos = state.positions[node.id];
    const el = els.graphSurface.querySelector(`[data-node="${cssEscape(node.id)}"]`);
    if (el && pos) el.setAttribute("transform", `translate(${pos.x}, ${pos.y})`);
  });
  state.graph.edges.forEach((edge, index) => {
    const endpoints = graphEdgeEndpoints(edge);
    if (!endpoints) return;
    const path = els.graphSurface.querySelector(`[data-edge="${index}"]`);
    const hitPath = els.graphSurface.querySelector(`[data-edge-hit="${index}"]`);
    const label = els.graphSurface.querySelector(`[data-edge-label="${index}"]`);
    const pathData = graphConnectionPath(endpoints.x1, endpoints.y1, endpoints.x2, endpoints.y2);
    if (path) path.setAttribute("d", pathData);
    if (hitPath) hitPath.setAttribute("d", pathData);
    if (label) {
      const labelPos = edgeLabelPosition(endpoints);
      label.setAttribute("x", String(labelPos.x));
      label.setAttribute("y", String(labelPos.y));
    }
  });
  const pending = state.pendingGraphLink;
  if (pending && pending.pointer) {
    const pendingPath = document.getElementById("pendingGraphEdge");
    const source = state.positions[pending.sourceStep];
    const sourceNode = state.graph.nodes.find((node) => node.id === pending.sourceStep);
    if (pendingPath && source && sourceNode) {
      const names = Object.keys(sourceNode.outputs || {});
      const index = Math.max(0, names.indexOf(pending.sourceOutput));
      pendingPath.setAttribute("d", graphConnectionPath(
        source.x + NODE_W,
        source.y + graphPortY(index, Math.max(1, names.length)),
        pending.pointer.x,
        pending.pointer.y
      ));
    }
  }
}

function nodeProgress(node, graph, status) {
  const job = jobForRecipe(state.selectedRecipe);
  const payloadProgress = progressForStep(job, node.id);
  if (payloadProgress) return payloadProgress;
  const progress = job ? stepProgressFromEvents(job.events || {}, node.id) : null;
  if (progress) return progress;
  const summary = latestSummaryForRecipe(state.selectedRecipe);
  if (!job && !summary) return null;
  if (status.kind === "done") return { percent: 100, label: "100%" };
  if (status.kind === "running") return { percent: 0, label: "running" };
  if (status.kind === "failed" || status.kind === "stopped") {
    const completed = completedStepsFromJob(job);
    return { percent: completed.has(node.id) ? 100 : 0, label: status.label.toLowerCase() };
  }
  return job ? { percent: 0, label: "0%" } : null;
}

function progressForStep(job, stepId) {
  const raw = job && job.progress && job.progress.steps && job.progress.steps[stepId];
  if (!raw || typeof raw !== "object") return null;
  const percent = progressPercentValue(raw);
  return {
    percent: percent === null ? 0 : percent,
    label: progressLabel(raw, percent),
  };
}

function progressPercentValue(progress) {
  if (!progress || typeof progress !== "object") return null;
  if (typeof progress.percent === "number" && Number.isFinite(progress.percent)) return clampPercent(progress.percent);
  if (
    typeof progress.completed === "number" &&
    typeof progress.total === "number" &&
    Number.isFinite(progress.completed) &&
    Number.isFinite(progress.total) &&
    progress.total > 0
  ) {
    return clampPercent((progress.completed / progress.total) * 100);
  }
  return null;
}

function progressLabel(progress, percent) {
  const pieces = [];
  if (progress.status) pieces.push(String(progress.status));
  if (progress.phase) pieces.push(String(progress.phase));
  if (percent !== null) pieces.push(`${Math.round(percent)}%`);
  return pieces.join(" - ") || "";
}

function clampPercent(value) {
  if (!Number.isFinite(value)) return 0;
  return Math.max(0, Math.min(100, value));
}

function clampUnit(value) {
  if (!Number.isFinite(value)) return 0;
  return Math.max(-1, Math.min(1, value));
}

function nodeProgressBar(progress) {
  if (!progress) return "";
  const percent = clampPercent(Number(progress.percent || 0));
  const fillWidth = (NODE_W - 20) * percent / 100;
  const label = progress.label || `${Math.round(percent)}%`;
  return `
    <g class="node-progress" transform="translate(10, ${NODE_H - 35})" role="img" aria-label="${escapeAttr(label)}" data-ui-tooltip="${escapeAttr(label)}">
      <rect class="node-progress-track" width="${NODE_W - 20}" height="4" rx="2"></rect>
      <rect class="node-progress-fill" width="${fillWidth}" height="4" rx="2"></rect>
      <text class="node-progress-label" x="${NODE_W - 24}" y="-3">${escapeHtml(`${Math.round(percent)}%`)}</text>
    </g>
  `;
}

function stepProgressFromEvents(events, stepId) {
  const live = stepStateFromEvents(events || []);
  if (live.completed.has(stepId)) return { percent: 100, label: "100%" };
  if (live.activeStep === stepId) return { percent: 0, label: "running" };
  if (live.started.has(stepId)) return { percent: 0, label: "started" };
  return null;
}

function completedStepsFromJob(job) {
  return stepStateFromEvents((job && job.events) || []).completed;
}

function nodeRoleLabel(node) {
  const id = String((node && node.id) || "");
  const op = String((node && node.op) || "");
  if (id === "data" || op.startsWith("source.")) return "Data";
  if (op === "model.modulation_classifier_adapter") return "Classifier";
  if (id === "knowledge_base") return "Knowledge base";
  if (id === "semantic_encoder") return "Semantic encoder";
  if (id === "semantic_ground" || id === "noisy_semantic_ground" || id === "receiver_semantic_ground") return "Semantic grounding";
  if (id === "sender_representation_noise" || id === "receiver_representation_noise") return "Representation noise";
  if (isPayloadCoderOperation(op)) return op.includes("decode") || op.includes("bits_to_") ? "Payload decoder" : "Payload encoder";
  if (id === "sender" || id === "image_encoder" || id === "text_encoder" || op.endsWith("_encode")) return "Encoder";
  if (id === "payload_encoder" || id === "payload_packer" || op.includes("_to_bits") || op.endsWith("payload_encode")) return "Payload encoder";
  if (id === "payload_decoder" || id === "payload_unpacker" || op.includes("bits_to_") || op.endsWith("payload_decode")) return "Payload decoder";
  if (id === "payload_bit_boundary") return "Payload boundary";
  if (id === "tx_bit_boundary" || id === "tx_symbol_boundary") return "Tx boundary";
  if (op === "channel.symbol_power_identity" || op === "channel.symbol_power_normalize" || op === "model.symbol_power_allocator") return "TX power";
  if (id === "rx_bit_boundary" || id === "rx_symbol_boundary") return "Rx boundary";
  if (id === "channel_bit_count_match" || id === "symbol_count_match") return "Channel check";
  if (id === "channel_encoder") return "Channel code";
  if (id === "channel_decoder") return "Channel decoder";
  if (op === "modulation.identity_modulate") return "Null modulator";
  if (id === "modulator") return "Modulator";
  if (op === "channel.identity_link") return "Bit link bypass";
  if (op === "channel.identity_symbol_link") return "Identity PHY channel";
  if (id === "wireless_channel" || op === "wireless.channel" || op === "wireless.digital_link") return "Physical channel";
  if (op === "demodulation.identity_demodulate") return "Null demodulator";
  if (id === "demodulator") return "Demodulator";
  if (id === "receiver" || op.endsWith("_decode")) return "Decoder";
  if (id === "receiver_repair") return "Receiver repair";
  if (id === "evaluation" || id === "faithfulness" || op.startsWith("metrics.")) return "Metrics";
  if (id === "codec_export") return "Runtime export";
  return humanizeIdentifier(id || op);
}

function canonicalBlockDisplayName(block) {
  return nodeRoleLabel(block) || "Block";
}

function nodeDetailLabel(node, entropyInfo) {
  const op = String((node && node.op) || "");
  const params = (node && node.params) || {};
  if (op === "source.image_dataset") return imageDatasetDetail(params);
  if (op === "source.kodak_files") return "Kodak file list";
  if (op === "source.text_dataset") return textDatasetDetail(params);
  if (op === "source.vqa_smoke" || op === "source.vqa_manifest" || op === "source.vqa_small_hf") return vqaDatasetDetail(op, params);
  if (op === "source.coco128_detection") return datasetLimitDetail("COCO128 detection", params);
  if (op === "source.coco8_segmentation") return datasetLimitDetail("COCO8 segmentation", params);
  if (op === "source.flickr8k_retrieval") return datasetLimitDetail("Flickr8k retrieval", params);
  if (op === "source.retrieval_smoke") return datasetLimitDetail("Retrieval smoke", params);
  if (op === "source.semantic_artifacts_smoke") return "Semantic artifact smoke";
  if (op === "source.task_labels_smoke") return datasetLimitDetail("Classification smoke", params);
  if (op === "channel.bit_boundary") return bitBoundaryDetail(params);
  if (op === "channel.symbol_boundary") return symbolBoundaryDetail(params);
  if (op === "channel.symbol_power_identity") return "Power pass-through";
  if (op === "channel.symbol_power_normalize") return `Fixed ${formatMetricNumber(numberOr(params.target_power, 1), 3)}`;
  if (op === "model.symbol_power_allocator") return `${txPowerGranularityLabel(params.granularity)} - ${txPowerBudgetModeLabel(params.budget_mode)} - ${formatMetricNumber(numberOr(params.target_power, 1), 3)}`;
  if (op === "channel.identity_encoder" || op === "channel.identity_decoder") return "No channel code";
  if (op === "channel.repetition_encoder") return `Repetition code x${integerOr(params.factor, 3)}`;
  if (op === "channel.repetition_decoder") return integerOr(params.factor, 0) > 0 ? `Repetition decode x${integerOr(params.factor, 1)}` : "Repetition decode";
  if (op === "channel.identity_link") return "Bit-perfect bypass";
  if (op === "channel.identity_symbol_link") return "Continuous identity channel";
  if (op === "wireless.channel" || op === "wireless.digital_link") return wirelessDetail(params);
  if (op === "modulation.identity_modulate") return "Bits/logits as 0/1 symbols";
  if (op === "modulation.digital_modulate") return `${String(params.modulation || "qpsk").toUpperCase()} symbols`;
  if (op === "demodulation.identity_demodulate") return "Identity symbols to bits/logits";
  if (op === "demodulation.digital_demodulate") return `${String(params.modulation || "qpsk").toUpperCase()} hard decisions`;
  if (op === "channel.bit_count_match") return "Tx/Rx bit count check";
  if (op === "channel.symbol_count_match") return "Tx/Rx symbol count check";
  if (isPayloadCoderOperation(op)) return payloadCoderDetail(node, entropyInfo);
  if (op.startsWith("model.") || op.startsWith("foundation.")) return modelOrFoundationDetail(node, entropyInfo);
  if (op.startsWith("noise.")) return noiseDetail(params);
  if (op.startsWith("metrics.")) return metricDetail(op);
  return cleanOperationLabel((node && node.name) || op);
}

function imageDatasetDetail(params) {
  const dataset = titleCaseShort(params.dataset || "dataset");
  const ids = listParam(params.image_ids || params.sample_ids);
  const count = ids.length || (String(params.dataset || "").toLowerCase() === "kodak" ? 24 : 0);
  const crop = integerOr(params.crop_size, 0);
  const idText = ids.length && ids.length <= 3 ? ids.join(",") : count ? `${count} images` : "images";
  return `${dataset} - ${idText}${crop > 0 ? ` - crop ${crop}` : ""}`;
}

function textDatasetDetail(params) {
  const dataset = params.dataset === "semantic_text_smoke" ? "Text smoke" : titleCaseShort(params.dataset || "text");
  const ids = listParam(params.sample_ids);
  return `${dataset}${ids.length ? ` - ${ids.length} samples` : ""}`;
}

function vqaDatasetDetail(op, params) {
  if (op === "source.vqa_manifest") return `VQA manifest - ${shortPathLabel(params.manifest_path || "local")}`;
  if (op === "source.vqa_small_hf") return datasetLimitDetail("VQA small", params);
  return datasetLimitDetail("VQA smoke", params);
}

function datasetLimitDetail(label, params) {
  const limit = integerOr(params.limit, 0);
  const sampleIds = listParam(params.sample_ids);
  const count = sampleIds.length || limit;
  return count > 0 ? `${label} - ${count} samples` : label;
}

function bitBoundaryDetail(params) {
  const role = String(params.role || params.label || "").toLowerCase();
  if (role.includes("payload")) return "Canonical payload bits";
  if (role.includes("modulator") || role.includes("tx")) return "Canonical transmitted bits";
  if (role.includes("rx") || role.includes("output")) return "Canonical received bits";
  return "Canonical bits";
}

function symbolBoundaryDetail(params) {
  const role = String(params.role || params.label || "").toLowerCase();
  if (role.includes("tx") || role.includes("modulator")) return "Canonical tx symbols";
  if (role.includes("rx") || role.includes("output")) return "Canonical rx symbols";
  return "Canonical complex symbols";
}

function wirelessDetail(params) {
  const channel = channelModeLabel(params.channel || params.mode || "awgn");
  const snr = params.snr_db !== undefined && params.snr_db !== null && String(params.snr_db) !== "" ? ` - ${formatValue(Number(params.snr_db))} dB` : "";
  const backend = params.wireless_backend && params.wireless_backend !== "auto" ? ` - ${params.wireless_backend}` : "";
  return `${channel}${snr}${backend}`;
}

function noiseDetail(params) {
  const mode = String(params.mode || "none");
  if (mode === "none") return "No source semantic perturbation";
  const probability = params.probability !== undefined ? ` p=${formatValue(Number(params.probability))}` : "";
  return `${humanizeIdentifier(mode)}${probability}`;
}

function metricDetail(op) {
  const labels = {
    "metrics.image_reconstruction": "Image quality metrics",
    "metrics.bit_error_rate": "Bit error rate",
    "metrics.text_semantic_similarity": "Text lexical similarity metrics",
    "metrics.semantic_state_faithfulness": "Semantic faithfulness",
    "metrics.classification": "Classification metrics",
    "metrics.vqa": "VQA single-reference exact match",
    "metrics.detection": "Detection metrics",
    "metrics.segmentation": "Segmentation metrics",
    "metrics.retrieval": "Retrieval metrics",
    "metrics.embedding_similarity": "Embedding similarity",
    "metrics.captioning": "Caption metrics",
    "metrics.external_classification": "External classification metric",
  };
  return labels[op] || cleanOperationLabel(op);
}

function isPayloadCoderOperation(op) {
  return [
    "channel.payload_passthrough_encoder",
    "channel.payload_passthrough_decoder",
    "channel.indices_to_bits",
    "channel.bits_to_indices",
    "channel.latents_to_bits",
    "channel.bits_to_latents",
    "model.compressai_entropy_encode",
    "model.compressai_entropy_decode",
    "model.compressai_onnx_entropy_encode",
    "model.compressai_onnx_entropy_decode",
    "model.compressai_onnx_cpp_entropy_encode",
    "model.compressai_onnx_cpp_entropy_decode",
    "model.compressai_openvino_entropy_encode",
    "model.compressai_openvino_entropy_decode",
    "model.compressai_aoti_entropy_encode",
    "model.compressai_aoti_entropy_decode",
    "model.eflic_indices_to_bits",
    "model.eflic_bits_to_indices",
    "model.text_utf8_encode",
    "model.text_utf8_decode",
    "foundation.semantic_state_payload_encode",
    "foundation.semantic_state_payload_decode",
    "foundation.vqa_payload_encode",
    "foundation.vqa_payload_decode",
  ].includes(op);
}

function payloadCoderDetail(node, entropyInfo) {
  const op = String(node.op || "");
  const runtimeLabel = runtimePayloadCoderLabel(node);
  if (runtimeLabel) return runtimeLabel;
  if (op.includes("compressai") && op.includes("entropy")) return "Native entropy coder";
  if (op === "channel.payload_passthrough_encoder" || op === "channel.payload_passthrough_decoder") return "Payload bits passthrough";
  if (op === "channel.indices_to_bits" || op === "channel.bits_to_indices") return "Fixed index bit-packing";
  if (op === "channel.latents_to_bits" || op === "channel.bits_to_latents") {
    const dtype = node.params && node.params.dtype ? String(node.params.dtype) : "float32";
    return `Raw latent bit-packing (${dtype})`;
  }
  if (op === "model.eflic_indices_to_bits" || op === "model.eflic_bits_to_indices") return "EF-LIC fixed index packing";
  if (op === "model.text_utf8_encode" || op === "model.text_utf8_decode") return "JSON UTF-8 payload";
  if (op === "foundation.semantic_state_payload_encode" || op === "foundation.semantic_state_payload_decode") return "SemanticState JSON payload";
  if (op === "foundation.vqa_payload_encode" || op === "foundation.vqa_payload_decode") return "VQA semantic packet";
  if (entropyInfo) {
    const coder = firstTruthy([entropyInfo.coder, entropyInfo.algorithm, entropyInfo.entropy_coder]);
    if (coder) return `Native ${coder}`;
  }
  return cleanOperationLabel(node.name || op);
}

function runtimePayloadCoderLabel(node) {
  const metadata = nodeRuntimeMetadata(node);
  const explicit = firstTruthy([
    metadata.payload_coder_label,
    metadata.payload_codec,
    metadata.payload_format,
  ]);
  if (explicit) return cleanPayloadLabel(explicit);
  if (metadata.payload_passthrough) return "Payload bits passthrough";
  if (metadata.entropy_coded === true) {
    const coder = firstTruthy([metadata.entropy_coder, metadata.entropy_algorithm]);
    return coder ? `Native entropy coder - ${coder}` : "Native entropy coder";
  }
  if (metadata.entropy_coded === false && (metadata.payload_format || metadata.packer)) {
    return cleanPayloadLabel(metadata.payload_format || metadata.packer);
  }
  return "";
}

function modelOrFoundationDetail(node, entropyInfo) {
  const op = String(node.op || "");
  const params = node.params || {};
  if (op === "foundation.knowledge_base") return params.kb_id ? `KB ${params.kb_id}` : "Knowledge base";
  if (op === "foundation.text_semantic_state_encode") return `Rule extractor - max ${integerOr(params.max_concepts, 16)} concepts`;
  if (op === "foundation.semantic_state_ground") return "Ground against knowledge base";
  if (op === "foundation.semantic_state_to_text") return textGeneratorLabel(params.generator || "local_template");
  if (op === "foundation.text_mask_repair") return textGeneratorLabel(params.generator || "masked_lm");
  if (op === "foundation.vqa_transformers_answer") return `VQA model - ${shortModelId(params.model_id || "dandelin/vilt")}`;
  if (op === "foundation.clip_image_embed" || op === "foundation.clip_text_embed") return `CLIP - ${shortModelId(params.model_id || params.backend || "clip")}`;
  if (op === "foundation.clip_retrieval_rank") return "CLIP retrieval ranking";
  if (op === "foundation.diffusion_state_to_image") return `Diffusion - ${shortModelId(params.model_id || "diffusers")}`;
  if (op === "foundation.yolo_detect") return `YOLO detect - ${shortModelId(params.model_id || params.model || "yolo")}`;
  if (op === "foundation.yolo_segment") return `YOLO segment - ${shortModelId(params.model_id || params.model || "yolo")}`;
  if (op === "model.text_bart_jscc_encode" || op === "model.text_bart_jscc_decode") return `BART JSCC-lite - ${shortModelId(params.model_id || "bart")}`;
  if (op === "model.text_utf8_encode" || op === "model.text_utf8_decode") return "Raw text JSON UTF-8";
  if (op === "model.jpeg_encode" || op === "model.jpeg_decode") return `JPEG q${integerOr(params.quality, 75)}`;
  const profile = codecProfileForOperation(op);
  if (profile) return codecOperationDetail(profile, op, params, entropyInfo);
  return cleanOperationLabel(node.name || op);
}

function codecOperationDetail(profile, op, params, entropyInfo) {
  if (profile.id === "compressai") {
    const modelId = firstListValue(params.model || params.model_name || "bmshj2018_hyperprior");
    const modelInfo = compressAiModelInfo(modelId);
    const modelLabel = modelInfo ? modelInfo.shortLabel || modelInfo.label : modelId;
    const rate = params.vbr_scale_index !== undefined && compressAiModelIsVbr(modelId)
      ? `vbr ${params.vbr_scale_index}`
      : params.quality !== undefined
        ? `q${params.quality}`
        : "";
    return ["CompressAI", modelLabel, rate].filter(Boolean).join(" - ");
  }
  if (profile.id === "eflic") {
    const forceInd = params.force_ind !== undefined ? `rate ${params.force_ind}` : "";
    return ["EF-LIC", forceInd].filter(Boolean).join(" - ");
  }
  if (profile.id === "jpeg") return `JPEG q${integerOr(params.quality, 75)}`;
  if (profile.id && ["evc", "tcm", "hpcm"].includes(profile.id)) {
    return upstreamCodecDetail(profile, params);
  }
  if (profile.id === "diffusers_autoencoderkl") return `AutoencoderKL - ${shortModelId(params.model_id || "diffusers")}`;
  if (profile.id === "diffusers_vqmodel") return `VQModel - ${shortModelId(params.model_id || "diffusers")}`;
  if (profile.external) return "Custom external codec";
  if (entropyInfo) {
    const coder = firstTruthy([entropyInfo.coder, entropyInfo.algorithm]);
    if (coder) return `${profile.label} - ${coder}`;
  }
  return profile.label || cleanOperationLabel(op);
}

function upstreamCodecDetail(profile, params) {
  const presetId = params.checkpoint_preset;
  const preset = (profile.checkpointPresets || []).find((item) => item.id === presetId);
  const presetLabel = preset ? preset.label : "";
  const model = params.model_name ? String(params.model_name).replace(/_/g, " ") : "";
  return [profile.label, presetLabel || model].filter(Boolean).join(" - ");
}

function codecProfileForOperation(op) {
  for (const profile of CODEC_PROFILES) {
    if (operationBelongsToProfile(op, profile)) return profile;
    for (const adapter of Object.values(profile.runtimeAdapters || {})) {
      if (operationBelongsToProfile(op, adapter)) return { ...profile, ...adapter, label: profile.label };
    }
  }
  return null;
}

function operationBelongsToProfile(op, profile) {
  return [
    profile.encoder,
    profile.decoder,
    profile.packer,
    profile.unpacker,
    profile.settingsEncoder,
    profile.conversion && profile.conversion.op,
  ].filter(Boolean).includes(op);
}

function nodeFlowLabel(node, graph) {
  const inputs = (graph.edges || [])
    .filter((edge) => edge.to_step === node.id)
    .map((edge) => edgeDataLabel(edge));
  const outputs = Object.entries(node.outputs || {}).map(([name, kind]) =>
    dataTypeLabel(kind, outputArtifactForNode(node.id, name), name)
  );
  const inputLabel = compactDataLabels(inputs.length ? inputs : operationInputLabels(node));
  const outputLabel = compactDataLabels(outputs.length ? outputs : ["none"]);
  return `${inputLabel} -> ${outputLabel}`;
}

function nodeMetaLabel(node, entropyInfo) {
  if (!entropyInfo) return "";
  const coder = firstTruthy([entropyInfo.coder, entropyInfo.algorithm, entropyInfo.entropy_coder]);
  if (!coder) return "";
  const language = shortEntropyLanguage(firstTruthy([entropyInfo.language, entropyInfo.entropy_language]));
  return `entropy: ${coder}${language ? ` - ${language}` : ""}`;
}

function nodeTooltip(node, flow, entropyInfo, detail = "", diffInfo = null, runnerInfo = null, backendInfo = null, equivalenceInfo = null) {
  const lines = [node.id, detail, node.op, flow];
  if (backendInfo) {
    const runnerLabel = GRAPH_RUNNER_MODES[state.graphRunnerMode] ? GRAPH_RUNNER_MODES[state.graphRunnerMode].label : "Runner";
    lines.push(`${runnerLabel}: ${backendInfo.tooltip}`);
  }
  if (diffInfo) {
    lines.push(`Differentiability: ${diffInfo.tooltip}`);
  }
  if (equivalenceInfo) {
    lines.push(`Equivalence: ${equivalenceInfo.tooltip}`);
  }
  if (runnerInfo) {
    lines.push(`Runners: ${runnerInfo.tooltip}`);
  }
  if (entropyInfo) {
    const coder = firstTruthy([entropyInfo.coder, entropyInfo.entropy_coder]);
    const algorithm = firstTruthy([entropyInfo.algorithm, entropyInfo.entropy_algorithm]);
    const implementation = firstTruthy([entropyInfo.implementation, entropyInfo.entropy_implementation]);
    const language = firstTruthy([entropyInfo.language, entropyInfo.entropy_language]);
    const note = firstTruthy([entropyInfo.note, entropyInfo.entropy_note]);
    if (coder) lines.push(`Entropy coder: ${coder}`);
    if (algorithm && algorithm !== coder) lines.push(`Algorithm: ${algorithm}`);
    if (implementation) lines.push(`Implementation: ${implementation}`);
    if (language) lines.push(`Language/runtime: ${language}`);
    if (note) lines.push(note);
  }
  return lines.filter(Boolean).join("\n");
}

function nodeRuntimeMetadata(node) {
  const step = latestStepSummaryForNode(node && node.id);
  const sources = [];
  if (step && step.metadata) sources.push(step.metadata);
  if (step && step.outputs) {
    Object.values(step.outputs || {}).forEach((artifact) => {
      if (artifact && artifact.metadata) sources.push(artifact.metadata);
    });
  }
  return sources.reduce((merged, source) => ({ ...merged, ...source }), {});
}

function listParam(value) {
  if (Array.isArray(value)) return value.map(String).map((item) => item.trim()).filter(Boolean);
  return String(value === undefined || value === null ? "" : value)
    .split(",")
    .map((item) => item.trim())
    .filter(Boolean);
}

function firstListValue(value) {
  const values = listParam(value);
  return values.length ? values[0] : String(value || "");
}

function titleCaseShort(value) {
  const text = humanizeIdentifier(value);
  return text ? text.charAt(0).toUpperCase() + text.slice(1) : "";
}

function humanizeIdentifier(value) {
  return String(value || "")
    .replace(/^.*\./, "")
    .replace(/[_-]+/g, " ")
    .replace(/\s+/g, " ")
    .trim();
}

function cleanOperationLabel(value) {
  const text = humanizeIdentifier(value);
  if (!text) return "operation";
  return text
    .replace(/\bpayload bits\b/gi, "payload bits")
    .replace(/\bnumpy\b/gi, "NumPy")
    .replace(/\bjson\b/gi, "JSON")
    .replace(/\butf8\b/gi, "UTF-8")
    .replace(/\bonnx\b/gi, "ONNX");
}

function cleanPayloadLabel(value) {
  const text = String(value || "");
  const preferred = {
    json_utf8: "JSON UTF-8",
    text_utf8_json: "Text JSON UTF-8",
    semantic_state_json_utf8: "SemanticState JSON UTF-8",
    "eflic.fixed_length_indices": "EF-LIC fixed index packing",
    "noema.safe_data_json_base64.v1": "Noema safe data envelope",
    latents_to_bits: "Raw latent bit-packing",
    indices_to_bits: "Fixed index bit-packing",
    passthrough: "Payload bits passthrough",
  };
  if (preferred[text]) return preferred[text];
  return cleanOperationLabel(text);
}

function textGeneratorLabel(generator) {
  const item = TEXT_GENERATOR_MODES.find((mode) => mode.id === generator);
  return item ? item.label : cleanOperationLabel(generator || "show received text");
}

function shortModelId(value) {
  const text = String(value || "").trim();
  if (!text) return "";
  const parts = text.split("/");
  return parts.length > 1 ? parts.slice(-2).join("/") : text;
}

function shortPathLabel(value) {
  const text = String(value || "").trim();
  if (!text) return "";
  const parts = text.split(/[\\/]+/).filter(Boolean);
  return parts.length ? parts[parts.length - 1] : text;
}

function nodeEntropyInfo(node) {
  const runtimeInfo = runtimeEntropyInfo(node);
  if (runtimeInfo) return runtimeInfo;
  return normalizeEntropyInfo(node.entropyInfo);
}

function runtimeEntropyInfo(node) {
  const step = latestStepSummaryForNode(node.id);
  if (!step) return null;
  const sources = [];
  if (step.metadata) sources.push(step.metadata);
  Object.values(step.outputs || {}).forEach((artifact) => {
    if (artifact && artifact.metadata) sources.push(artifact.metadata);
  });
  for (const source of sources) {
    const info = normalizeEntropyInfo(source);
    if (info) return info;
  }
  return null;
}

function normalizeEntropyInfo(source) {
  if (!source || typeof source !== "object") return null;
  const coder = firstTruthy([source.coder, source.entropy_coder]);
  const algorithm = firstTruthy([source.algorithm, source.entropy_algorithm]);
  const implementation = firstTruthy([source.implementation, source.entropy_implementation, source.backend, source.entropy_backend]);
  const language = firstTruthy([source.language, source.entropy_language]);
  const note = firstTruthy([source.note, source.entropy_note]);
  if (!coder && !algorithm && !implementation && !language && !note) return null;
  return { coder, algorithm, implementation, language, note };
}

function shortEntropyLanguage(language) {
  const value = String(language || "");
  if (!value) return "";
  if (value.includes("ONNX Runtime")) return "ONNX+C++";
  if (value.includes("C++")) return "C++/PyTorch";
  if (value.includes("C/Python")) return "C/Python";
  return value;
}

function operationInputLabels(node) {
  return Object.entries(node.inputs || {}).map(([_name, kinds]) => {
    const kind = Array.isArray(kinds) ? kinds[0] : kinds;
    return dataTypeLabel(kind, null, "");
  });
}

function edgeDataLabel(edge) {
  const sourceNode = state.graph && (state.graph.nodes || []).find((node) => node.id === edge.from_step);
  const kind = sourceNode && sourceNode.outputs ? sourceNode.outputs[edge.from_output] : "";
  return dataTypeLabel(kind, outputArtifactForNode(edge.from_step, edge.from_output), edge.from_output);
}

function outputArtifactForNode(stepId, outputName) {
  const step = latestStepSummaryForNode(stepId);
  return step && step.outputs ? step.outputs[outputName] || null : null;
}

function latestStepSummaryForNode(stepId) {
  const summary = latestSummaryForRecipe(state.selectedRecipe);
  return summary && (summary.steps || []).find((item) => item.id === stepId) || null;
}

function dataTypeLabel(kind, artifact, fallbackName) {
  const semantic = semanticDataLabel((artifact && artifact.kind) || kind || fallbackName);
  const dtype = artifactDtype(artifact, fallbackName);
  if (semantic === "bits") {
    return bitDataLabel((artifact && artifact.metadata) || {}, dtype);
  }
  return dtype ? `${semantic} (${dtype})` : semantic;
}

function bitDataLabel(metadata, dtype) {
  const storageDtype = dtype || "uint8";
  if (metadata && (metadata.adapter_bit_storage === "packed_bytes" || metadata.source_bit_storage === "packed_bytes")) {
    return `bits unpacked (${storageDtype}, from bytes)`;
  }
  if (metadata && (metadata.channel_bit_array === "unpacked_uint8" || metadata.bit_count || metadata.payload_bit_count)) {
    return `bits unpacked (${storageDtype}, 1 bit/elem)`;
  }
  if (metadata && metadata.byte_count && metadata.payload_format) {
    return `bits unpacked (${storageDtype}, bytes->bits)`;
  }
  return dtype ? `bits (${dtype})` : "bits";
}

function semanticDataLabel(kind) {
  const value = String(kind || "");
  if (value.includes("image")) return "image";
  if (value.includes("text")) return "text";
  if (value.includes("indices")) return "indices";
  if (value.includes("latents")) return "latent";
  if (value.includes("symbols")) return "symbols";
  if (value.includes("bits")) return "bits";
  if (value.includes("report")) return "report";
  return value.replace(/^.*\./, "") || "data";
}

function artifactDtype(artifact, arrayName) {
  const metadata = (artifact && artifact.metadata) || {};
  if (metadata.dtype) return String(metadata.dtype);
  if (metadata.tensor_dtype) return String(metadata.tensor_dtype);
  const arrays = metadata.arrays || {};
  if (arrayName && arrays[arrayName] && arrays[arrayName].dtype) return String(arrays[arrayName].dtype);
  const first = Object.values(arrays)[0];
  return first && first.dtype ? String(first.dtype) : "";
}

function compactDataLabels(labels) {
  const unique = [];
  (labels || []).forEach((label) => {
    if (label && !unique.includes(label)) unique.push(label);
  });
  if (!unique.length) return "none";
  if (unique.length <= 2) return unique.join(" + ");
  return `${unique.slice(0, 2).join(" + ")} +${unique.length - 2}`;
}

function graphDragMovedPastClickThreshold(drag, event = null) {
  if (!drag) return false;
  if (drag.moved) return true;
  if (!event || !Number.isFinite(event.clientX) || !Number.isFinite(event.clientY)) return false;
  const dx = event.clientX - drag.startX;
  const dy = event.clientY - drag.startY;
  return dx * dx + dy * dy >= GRAPH_DRAG_CLICK_THRESHOLD_PX * GRAPH_DRAG_CLICK_THRESHOLD_PX;
}

function clearPendingGraphClickSuppression(token = pendingGraphClickSuppression) {
  if (!token || pendingGraphClickSuppression !== token) return;
  pendingGraphClickSuppression = null;
  if (pendingGraphClickSuppressionTimer !== null) clearTimeout(pendingGraphClickSuppressionTimer);
  pendingGraphClickSuppressionTimer = null;
}

function armGraphClickSuppression() {
  clearPendingGraphClickSuppression();
  const token = {};
  pendingGraphClickSuppression = token;
  pendingGraphClickSuppressionTimer = setTimeout(() => clearPendingGraphClickSuppression(token), 0);
}

function consumeSuppressedGraphClick(event) {
  if (!pendingGraphClickSuppression) return false;
  clearPendingGraphClickSuppression();
  if (event && typeof event.preventDefault === "function") event.preventDefault();
  if (event && typeof event.stopPropagation === "function") event.stopPropagation();
  if (event && typeof event.stopImmediatePropagation === "function") event.stopImmediatePropagation();
  return true;
}

function startNodeDrag(event, nodeId) {
  if (!nodeId || event.button !== 0) return;
  event.preventDefault();
  event.stopPropagation();
  const pos = state.positions[nodeId];
  state.drag = {
    kind: "node",
    nodeId,
    startX: event.clientX,
    startY: event.clientY,
    originX: pos.x,
    originY: pos.y,
    zoom: graphZoom(),
    moved: false,
  };
}

function startGraphPan(event) {
  if (
    event.button !== 0 ||
    event.target.closest("[data-node]") ||
    event.target.closest("button, input, select, textarea, [data-graph-editor-toolbar], [data-select-edge]")
  ) return;
  event.preventDefault();
  state.drag = {
    kind: "pan",
    startX: event.clientX,
    startY: event.clientY,
    scrollLeft: els.graphSurface.scrollLeft,
    scrollTop: els.graphSurface.scrollTop,
    moved: false,
  };
  els.graphSurface.classList.add("panning");
}

function onGraphWheel(event) {
  if (!state.graph || !visualizationWheelZoomRequested(event)) return;
  event.preventDefault();
  const surface = els.graphSurface;
  const rect = surface.getBoundingClientRect();
  const oldZoom = graphZoom();
  const delta = event.deltaY > 0 ? -1 : 1;
  const factor = delta > 0 ? 1.1 : 1 / 1.1;
  const nextZoom = Math.max(GRAPH_ZOOM_MIN, Math.min(GRAPH_ZOOM_MAX, oldZoom * factor));
  if (Math.abs(nextZoom - oldZoom) < 0.001) return;
  const anchorX = event.clientX - rect.left + surface.scrollLeft;
  const anchorY = event.clientY - rect.top + surface.scrollTop;
  const graphX = anchorX / oldZoom;
  const graphY = anchorY / oldZoom;
  state.graphZoom = nextZoom;
  applyGraphCanvasSize();
  surface.scrollLeft = graphX * nextZoom - (event.clientX - rect.left);
  surface.scrollTop = graphY * nextZoom - (event.clientY - rect.top);
}

function onPointerMove(event) {
  updatePendingGraphLinkPointer(event);
  if (!state.drag) return;
  const dx = event.clientX - state.drag.startX;
  const dy = event.clientY - state.drag.startY;
  if (
    (state.drag.kind === "node" || state.drag.kind === "pan") &&
    dx * dx + dy * dy >= GRAPH_DRAG_CLICK_THRESHOLD_PX * GRAPH_DRAG_CLICK_THRESHOLD_PX
  ) {
    state.drag.moved = true;
  }
  if (state.drag.kind === "pan") {
    els.graphSurface.scrollLeft = state.drag.scrollLeft - dx;
    els.graphSurface.scrollTop = state.drag.scrollTop - dy;
    return;
  }
  if (state.drag.kind === "compare-divider") {
    setCompareSplitFromClientX(state.drag.slider, event.clientX);
    return;
  }
  if (state.drag.kind === "compare-pan") {
    const zoom = Math.max(1, Number(state.resultImageZoom) || 1);
    if (zoom <= 1.005) return;
    const max = comparePanMax(state.drag.slider, zoom);
    state.resultImagePan = {
      x: clampUnit((state.drag.startPanX || 0) + (max.x ? dx / max.x : 0)),
      y: clampUnit((state.drag.startPanY || 0) + (max.y ? dy / max.y : 0)),
    };
    applyResultImageTransform();
    return;
  }
  if (state.drag.kind === "rd-pan") {
    event.preventDefault();
    const spec = state.drag.spec;
    const svgDx = state.drag.screenWidth ? (dx / state.drag.screenWidth) * spec.width : 0;
    const svgDy = state.drag.screenHeight ? (dy / state.drag.screenHeight) * spec.height : 0;
    const xRatio = svgDx / spec.plotWidth;
    const yRatio = svgDy / spec.plotHeight;
    state.rdView = {
      xMetric: spec.xMetric,
      yMetric: spec.yMetric,
      xStat: spec.xStat,
      yStat: spec.yStat,
      xLog: spec.xLog,
      yLog: spec.yLog,
      xDomain: panDomain(spec.xDomain, xRatio, spec.xLog, -1),
      yDomain: panDomain(spec.yDomain, yRatio, spec.yLog, 1),
    };
    renderResultsDashboard(state.resultRows || []);
    const chart = els.resultsComparison.querySelector("[data-rd-chart]");
    if (chart) {
      chart.classList.add("panning");
      state.drag.chart = chart;
    }
    return;
  }
  if (state.drag.kind === "model-time-pan") {
    event.preventDefault();
    const spec = state.drag.spec;
    const svgDx = state.drag.screenWidth ? (dx / state.drag.screenWidth) * spec.width : 0;
    const svgDy = state.drag.screenHeight ? (dy / state.drag.screenHeight) * spec.height : 0;
    const xRatio = svgDx / spec.plotWidth;
    const yRatio = svgDy / spec.plotHeight;
    state.modelTimeView = {
      xMetric: spec.xMetric,
      yMetric: spec.yMetric,
      xStat: spec.xStat,
      yStat: spec.yStat,
      xLog: spec.xLog,
      yLog: spec.yLog,
      xDomain: panDomain(spec.xDomain, xRatio, spec.xLog, -1),
      yDomain: panDomain(spec.yDomain, yRatio, spec.yLog, 1),
    };
    renderResultsDashboard(state.resultRows || []);
    const chart = els.resultsComparison.querySelector("[data-model-time-chart]");
    if (chart) {
      chart.classList.add("panning");
      state.drag.chart = chart;
    }
    return;
  }
  if (state.drag.kind === "domain-chart-pan") {
    event.preventDefault();
    const spec = state.drag.spec;
    const svgDx = state.drag.screenWidth ? (dx / state.drag.screenWidth) * spec.width : 0;
    const svgDy = state.drag.screenHeight ? (dy / state.drag.screenHeight) * spec.height : 0;
    const xRatio = svgDx / spec.plotWidth;
    const yRatio = svgDy / spec.plotHeight;
    setDomainChartView(
      state.drag.chart,
      spec,
      panDomain(spec.xDomain, xRatio, spec.xLog, -1),
      panDomain(spec.yDomain, yRatio, spec.yLog, 1),
      validDomain(spec.y2Domain) ? panDomain(spec.y2Domain, yRatio, spec.y2Log, 1) : null,
    );
    renderResultsDashboard(state.resultRows || []);
    const charts = els.resultsComparison.querySelectorAll("[data-domain-chart]");
    const chart = Array.from(charts).find((item) => domainChartViewKey(item) === state.drag.viewKey);
    if (chart) {
      chart.classList.add("panning");
      state.drag.chart = chart;
    }
    return;
  }
  const dragZoom = Math.max(GRAPH_ZOOM_MIN, Number(state.drag.zoom) || graphZoom());
  state.positions[state.drag.nodeId] = {
    x: Math.max(12, state.drag.originX + dx / dragZoom),
    y: Math.max(12, state.drag.originY + dy / dragZoom),
  };
  updateGraphGeometry();
}

function onPointerUp(event) {
  const completedDrag = state.drag;
  if (
    completedDrag &&
    (completedDrag.kind === "node" || completedDrag.kind === "pan") &&
    graphDragMovedPastClickThreshold(completedDrag, event)
  ) {
    armGraphClickSuppression();
  }
  els.graphSurface.classList.remove("panning");
  els.resultsComparison.querySelectorAll(".image-compare-slider.panning, .compare-divider.dragging").forEach((element) => {
    element.classList.remove("panning", "dragging");
  });
  els.resultsComparison.querySelectorAll(".rd-chart.panning").forEach((element) => {
    element.classList.remove("panning");
  });
  state.drag = null;
}

function selectNode(nodeId, rerender = true) {
  state.selectedNodeId = nodeId;
  storeRecipeConfiguratorView("blocks");
  state.selectedEdgeKey = null;
  state.pendingGraphLink = null;
  if (rerender) renderGraph(state.graph);
  const synchronized = syncRecipeConfiguratorBlockSelection(nodeId, { scroll: rerender });
  if (!synchronized) {
    renderRecipeControls();
    syncRecipeConfiguratorBlockSelection(nodeId, { scroll: rerender });
  }
}

function selectGraphEdge(edge, rerender = true) {
  if (!edge) return;
  state.selectedNodeId = null;
  state.pendingGraphLink = null;
  state.selectedEdgeKey = graphEdgeKey(edge);
  if (rerender) renderGraph(state.graph);
  syncRecipeConfiguratorBlockSelection("");
}

function removeCurrentGraphSelection() {
  if (state.busy) return;
  if (state.selectedEdgeKey) {
    const edge = state.graph && state.graph.edges.find((item) => graphEdgeKey(item) === state.selectedEdgeKey);
    if (!edge) return;
    const label = `${edge.from_step}.${edge.from_output} to ${edge.to_step}.${edge.to_input}`;
    setRecipeInputConnection(edge.to_step, edge.to_input, "");
    state.selectedEdgeKey = null;
    state.pendingGraphLink = null;
    commitRecipeTopologyEdit(true);
    notify(`removed link ${label}`);
    return;
  }
  if (state.selectedNodeId) removeRecipeStep(state.selectedNodeId);
}

function removeCurrentGraphSelectionFromKeyboard(event) {
  if (
    state.activeView !== "graph" ||
    state.busy ||
    !els.settingsOverlay.hidden ||
    !els.logOverlay.hidden ||
    (!state.selectedNodeId && !state.selectedEdgeKey)
  ) return;
  const target = event.target;
  if (target && ((typeof target.matches === "function" && target.matches("input, textarea, select")) || target.isContentEditable)) return;
  event.preventDefault();
  removeCurrentGraphSelection();
}

function recipeStatus(recipe) {
  if (state.runningRecipeKey === recipe.key || recipe.transientStatus === "running") {
    return { kind: "running", label: "Running" };
  }
  if (recipe.transientStatus === "stopped") return { kind: "stopped", label: "Stopped" };
  if (recipe.transientStatus === "failed") return { kind: "failed", label: "Failed" };
  const run = runForRecipe(recipe);
  if (run) return statusFromRun(run.status);
  if (recipeHasWarnings(recipe.recipe)) return { kind: "warning", label: "Warning" };
  return { kind: "queued", label: "Queued" };
}

function nodeStatus(node, index, graph) {
  const warning = node.status && node.status !== "implemented";
  const job = jobForRecipe(state.selectedRecipe);
  const jobStatus = nodeStatusFromJob(node, graph, job, warning);
  if (jobStatus) {
    return jobStatus;
  }
  if (state.selectedRecipe && state.selectedRecipe.transientStatus === "failed") {
    return index === 0
      ? { kind: "failed", label: "Failed" }
      : warning
        ? { kind: "warning", label: "Warning" }
        : { kind: "queued", label: "Queued" };
  }
  if (state.selectedRecipe && state.selectedRecipe.transientStatus === "stopped") {
    return index === 0
      ? { kind: "stopped", label: "Stopped" }
      : warning
        ? { kind: "warning", label: "Warning" }
        : { kind: "queued", label: "Queued" };
  }

  const summary = latestSummaryForRecipe(state.selectedRecipe);
  if (!summary) {
    return warning ? { kind: "warning", label: "Warning" } : { kind: "queued", label: "Queued" };
  }

  const completed = new Set((summary.steps || []).filter((step) => step.status === "completed").map((step) => step.id));
  if (completed.has(node.id)) return { kind: "done", label: "Done" };

  if (["failed", "resource_exhausted", "timed_out"].includes(summary.status)) {
    const failedNode = firstUncompletedNode(graph, completed);
    if (failedNode && failedNode.id === node.id) return { kind: "failed", label: "Failed" };
    return warning ? { kind: "warning", label: "Warning" } : { kind: "queued", label: "Queued" };
  }

  if (summary.status === "canceled") {
    const stoppedNode = firstUncompletedNode(graph, completed);
    if (stoppedNode && stoppedNode.id === node.id) return { kind: "stopped", label: "Stopped" };
    return warning ? { kind: "warning", label: "Warning" } : { kind: "queued", label: "Queued" };
  }

  if (summary.status === "running") {
    const runningNode = firstUncompletedNode(graph, completed);
    if (runningNode && runningNode.id === node.id) return { kind: "running", label: "Running" };
    return warning ? { kind: "warning", label: "Warning" } : { kind: "queued", label: "Queued" };
  }

  return warning ? { kind: "warning", label: "Warning" } : { kind: "queued", label: "Queued" };
}

function firstUncompletedNode(graph, completed) {
  return (graph.nodes || []).find((node) => !completed.has(node.id)) || null;
}

function jobForRecipe(recipe) {
  return recipe ? state.runJobs[recipe.key] || null : null;
}

function nodeStatusFromJob(node, graph, job, warning) {
  if (!job || !Array.isArray(job.events) || !job.events.length) return null;
  const live = stepStateFromEvents(job.events);
  if (live.completed.has(node.id)) return { kind: "done", label: "Done" };

  if (["failed", "resource_exhausted", "timed_out"].includes(job.status)) {
    const failedStep = live.activeStep || firstUncompletedNode(graph, live.completed);
    if (failedStep && failedStep.id === node.id) return { kind: "failed", label: "Failed" };
    if (failedStep === node.id) return { kind: "failed", label: "Failed" };
    return warning ? { kind: "warning", label: "Warning" } : { kind: "queued", label: "Queued" };
  }

  if (job.status === "canceled") {
    const stoppedStep = live.activeStep || firstUncompletedNode(graph, live.completed);
    if (stoppedStep && stoppedStep.id === node.id) return { kind: "stopped", label: "Stopped" };
    if (stoppedStep === node.id) return { kind: "stopped", label: "Stopped" };
    return warning ? { kind: "warning", label: "Warning" } : { kind: "queued", label: "Queued" };
  }

  if (!isTerminalJobStatus(job.status)) {
    if (live.activeStep === node.id) return { kind: "running", label: "Running" };
    if (!live.activeStep && live.started.size) {
      const runningNode = firstUncompletedNode(graph, live.completed);
      if (runningNode && runningNode.id === node.id) return { kind: "running", label: "Running" };
    }
  }

  return warning ? { kind: "warning", label: "Warning" } : { kind: "queued", label: "Queued" };
}

function stepStateFromEvents(events) {
  const started = new Set();
  const completed = new Set();
  let activeStep = null;
  (events || []).forEach((event) => {
    const stepId = event && event.step_id;
    if (!stepId) return;
    if (event.kind === "step_started") {
      started.add(stepId);
      activeStep = stepId;
    } else if (event.kind === "step_completed") {
      completed.add(stepId);
      if (activeStep === stepId) activeStep = null;
    }
  });
  return { started, completed, activeStep };
}

function latestSummaryForRecipe(recipe) {
  if (!recipe) return null;
  const run = runForRecipe(recipe);
  return run && state.runSummaries[run.run_id] ? state.runSummaries[run.run_id] : null;
}

function statusFromRun(status) {
  if (status === "completed") return { kind: "done", label: "Done" };
  if (status === "failed") return { kind: "failed", label: "Failed" };
  if (status === "resource_exhausted") return { kind: "failed", label: "Memory limit" };
  if (status === "timed_out") return { kind: "failed", label: "Timed out" };
  if (status === "canceled") return { kind: "stopped", label: "Stopped" };
  if (status === "running") return { kind: "running", label: "Running" };
  return { kind: "queued", label: "Queued" };
}

function recipeHasWarnings(recipe) {
  return recipeConfigurationIssues(recipe).length > 0;
}

function statusIcon(kind, label, extraClass = "") {
  if (kind === "queued") return "";
  return `<span class="status-icon status-${escapeAttr(kind)} ${escapeAttr(extraClass)}" role="img" aria-label="${escapeAttr(label)}" title="${escapeAttr(label)}"></span>`;
}

function nodeStatusIcon(kind, label) {
  if (kind === "queued") return "";
  return `
    <foreignObject class="node-status-fo" x="${NODE_W - 28}" y="3" width="22" height="22">
      <div xmlns="http://www.w3.org/1999/xhtml" class="node-status-html">
        ${statusIcon(kind, label, "node-block-status-icon")}
      </div>
    </foreignObject>
  `;
}

function nodeDifferentiabilityInfo(node) {
  const spec = node && node.differentiability ? node.differentiability : null;
  if (!spec || typeof spec !== "object") return null;
  const capabilities = node && node.training_capabilities && typeof node.training_capabilities === "object"
    ? node.training_capabilities
    : {};
  const framework = String(spec.framework || "numpy");
  const gradient = String(spec.gradient || "none");
  const fineTuning = Boolean(capabilities.built_in_fine_tuning);
  const replacementReady = Boolean(capabilities.portable_replacement);
  const exportable = Boolean(spec.exportable);
  const reason = String(spec.reason || "").trim();
  const tone = gradient === "full" ? "full" : gradient === "surrogate" ? "surrogate" : gradient === "stop" ? "stop" : "none";
  const label = gradient === "full" ? "full" : gradient === "surrogate" ? "surrogate" : gradient === "stop" ? "stop" : "none";
  const pieces = [
    framework,
    `gradient ${gradient}`,
    fineTuning ? "built-in fine-tuning supported" : "no built-in fine-tuning",
    replacementReady ? "portable replacement supported" : "no portable replacement ABI",
    exportable ? "exportable as unchanged support" : "not exportable as unchanged support",
  ];
  if (reason) pieces.push(reason);
  return { framework, gradient, fineTuning, replacementReady, exportable, reason, tone, label, tooltip: pieces.join("; ") };
}

function nodeDifferentiabilityBadge(diffInfo, statusKind) {
  if (!diffInfo) return "";
  const x = statusKind === "queued" ? NODE_W - 60 : NODE_W - 82;
  return `
    <foreignObject class="node-diff-fo" x="${x}" y="3" width="50" height="22">
      <div xmlns="http://www.w3.org/1999/xhtml" class="node-diff-badge node-diff-${escapeAttr(diffInfo.tone)}" title="${escapeAttr(diffInfo.tooltip)}">
        ${escapeHtml(diffInfo.label)}
      </div>
    </foreignObject>
  `;
}

function nodeContractBadges(backendInfo, diffInfo, equivalenceInfo) {
  const gradientInfo = diffInfo || { label: "none", tone: "none", tooltip: "gradient none" };
  const backend = backendInfo || { label: "n/a", tone: "off", tooltip: "No runner materialization metadata." };
  const equivalence = equivalenceInfo || { label: "behavioral", tone: "behavioral", tooltip: "No equivalence metadata declared." };
  return `
    <foreignObject class="node-contract-fo" x="10" y="${NODE_H - 24}" width="${NODE_W - 20}" height="20">
      <div xmlns="http://www.w3.org/1999/xhtml" class="node-contract-row">
        <span class="node-mini-badge node-backend-${escapeAttr(backend.tone)}" title="${escapeAttr(backend.tooltip)}">${escapeHtml(backend.label)}</span>
        <span class="node-mini-badge node-gradient-${escapeAttr(gradientInfo.tone)}" title="${escapeAttr(gradientInfo.tooltip)}">${escapeHtml(gradientInfo.label)}</span>
        <span class="node-mini-badge node-equivalence-${escapeAttr(equivalence.tone)}" title="${escapeAttr(equivalence.tooltip)}">${escapeHtml(equivalence.label)}</span>
      </div>
    </foreignObject>
  `;
}

function nodeBackendInfo(node, runnerMode) {
  const runner = GRAPH_RUNNER_MODES[runnerMode] ? runnerMode : "benchmark";
  const support = node && node.runner_support && node.runner_support[runner] ? node.runner_support[runner] : null;
  const implemented = support && Array.isArray(support.implemented_materializations) ? support.implemented_materializations : [];
  if (!support || !support.supported || !implemented.length) {
    return {
      label: graphRunnerMissingLabel(runner),
      tone: "off",
      tooltip: support && support.reason ? support.reason : `No ${runner.replace("_", " ")} materialization is available.`,
    };
  }
  const labels = [];
  implemented.forEach((item) => {
    const label = backendDisplayLabel(item.backend);
    if (label && !labels.includes(label)) labels.push(label);
  });
  const label = labels.length <= 2 ? labels.join("/") : `${labels[0]}+${labels.length - 1}`;
  const primary = backendTone(implemented[0] && implemented[0].backend);
  const implementations = implemented.map((item) => `${backendDisplayLabel(item.backend)}:${item.implementation || "default"}`).join(", ");
  return {
    label: label || "backend",
    tone: primary,
    tooltip: `${GRAPH_RUNNER_MODES[runner].label} backend materialization: ${implementations}`,
  };
}

function graphRunnerMissingLabel(runner) {
  if (runner === "benchmark_run") return "No benchmark run";
  if (runner === "dataset_capture") return "No dataset capture";
  if (runner === "differentiable_export") return "No differentiable export";
  return "No backend";
}

function backendDisplayLabel(value) {
  const backend = String(value || "").toLowerCase();
  if (backend === "numpy") return "NumPy";
  if (backend === "torch") return "Torch";
  if (backend === "sionna") return "Sionna";
  if (backend === "external") return "External";
  if (backend === "onnxruntime") return "ONNX";
  if (backend === "openvino") return "OpenVINO";
  if (backend === "cpp") return "C++";
  if (backend === "tensorflow") return "TensorFlow";
  if (backend === "python") return "Python";
  if (backend === "blackbox") return "Blackbox";
  return backend ? humanizeIdentifier(backend) : "Backend";
}

function backendTone(value) {
  const backend = String(value || "").toLowerCase();
  if (["numpy", "torch", "sionna", "external", "onnxruntime", "openvino", "cpp", "tensorflow", "python", "blackbox"].includes(backend)) return backend;
  return "generic";
}

function nodeEquivalenceInfo(node) {
  const spec = node && node.equivalence && typeof node.equivalence === "object" ? node.equivalence : {};
  const type = String(spec.type || "behavioral").toLowerCase();
  const label = type === "numerical" ? "numerical" : type === "statistical" ? "statistical" : type === "exact" ? "exact" : "behavioral";
  const parts = [`equivalence ${label}`];
  if (spec.tolerance !== undefined) parts.push(`tolerance ${JSON.stringify(spec.tolerance)}`);
  if (spec.reason) parts.push(String(spec.reason));
  return { label, tone: label, tooltip: parts.join("; ") };
}

function nodeRunnerSupportInfo(node) {
  const support = node && node.runner_support && typeof node.runner_support === "object" ? node.runner_support : null;
  if (!support) return null;
  const order = ["benchmark_run", "dataset_capture", "differentiable_export"];
  const labels = { benchmark_run: "benchmark run", dataset_capture: "dataset capture", differentiable_export: "differentiable export" };
  const shortLabels = { benchmark_run: "BR", dataset_capture: "DC", differentiable_export: "DE" };
  const parts = [];
  const failures = [];
  order.forEach((runner) => {
    const item = support[runner] || {};
    const ok = Boolean(item.supported);
    parts.push(`${labels[runner]} ${ok ? "yes" : "no"}`);
    if (!ok) failures.push(`${labels[runner]}: ${item.reason || "unsupported"}`);
  });
  return {
    label: order.map((runner) => `${shortLabels[runner]}:${support[runner] && support[runner].supported ? "yes" : "no"}`).join(" "),
    tooltip: failures.length ? `${parts.join("; ")}\n${failures.join("\n")}` : parts.join("; "),
  };
}

function taskRecipeConfigFromRecipe(recipe) {
  const steps = (recipe && recipe.steps) || [];
  const task = researchTaskForSteps(steps);
  const dataStep = stepById(steps, "data") || findStepByOpIn(steps, "source.task_labels_smoke") || findStepByOpIn(steps, "source.coco128_detection") || findStepByOpIn(steps, "source.coco8_segmentation") || findStepByOpIn(steps, "source.flickr8k_retrieval") || findStepByOpIn(steps, "source.retrieval_smoke") || findStepByOpIn(steps, "source.vqa_smoke") || findStepByOpIn(steps, "source.vqa_manifest") || findStepByOpIn(steps, "source.vqa_small_hf") || {};
  const taskId = task.id || (dataStep.op === "source.vqa_smoke" ? "visual_question_answering" : (dataStep.op === "source.retrieval_smoke" || dataStep.op === "source.flickr8k_retrieval" ? "image_text_retrieval" : (dataStep.op === "source.coco128_detection" ? "object_detection" : (dataStep.op === "source.coco8_segmentation" ? "segmentation" : "classification"))));
  const vqaReceiver = stepById(steps, "receiver") || {};
  const vqaMode = vqaReceiver.op === "foundation.vqa_transformers_answer" ? "pretrained_transformers" : "semantic_packet";
  const imageEncoder = stepById(steps, "image_encoder") || {};
  const textEncoder = stepById(steps, "text_encoder") || {};
  const retrievalReceiver = stepById(steps, "receiver") || {};
  const retrievalBackend = (imageEncoder.params || {}).backend || (textEncoder.params || {}).backend || "local_semantic";
  const visionReceiver = stepById(steps, "receiver") || {};
  const evalStep = stepById(steps, "evaluation") || {};
  const visionParams = visionReceiver.params || {};
  const evalParams = evalStep.params || {};
  const isSegmentation = taskId === "segmentation";
  const generationReceiver = findStepByOpIn(steps, "foundation.diffusion_state_to_image") || {};
  const generationParams = generationReceiver.params || {};
  const generationTextEncoder = stepById(steps, "text_encoder") || {};
  const generationImageEncoder = stepById(steps, "generated_image_encoder") || stepById(steps, "source_image_encoder") || {};
  const clipParams = generationTextEncoder.params || generationImageEncoder.params || {};
  return {
    name: (recipe && recipe.name) || (taskId === "visual_question_answering" ? "vqa_goal_oriented_smoke" : (taskId === "image_generation" ? "diffusion_flickr8k_generation" : (taskId === "image_text_retrieval" ? "clip_retrieval_flickr8k_clip" : (taskId === "object_detection" ? "yolo_coco128_detection" : (taskId === "segmentation" ? "yolo_coco8_segmentation" : "task_classification_smoke"))))),
    task: { id: taskId },
    data: {
      source: dataStep.op === "source.vqa_manifest" ? "manifest" : (dataStep.op === "source.vqa_small_hf" ? "vqa_small" : (dataStep.op === "source.coco128_detection" ? "coco128_detection" : (dataStep.op === "source.coco8_segmentation" ? "coco8_segmentation" : (dataStep.op === "source.flickr8k_retrieval" ? "flickr8k" : (dataStep.op === "source.retrieval_smoke" ? "retrieval_smoke" : "smoke"))))),
      dataset: dataStep.params && dataStep.params.dataset ? dataStep.params.dataset : (taskId === "image_text_retrieval" ? "flickr8k" : (taskId === "object_detection" ? "coco128_detection" : (taskId === "segmentation" ? "coco8_segmentation" : (taskId === "visual_question_answering" ? "coco_vqa_smoke" : "task_smoke")))),
      sample_ids: dataStep.params && dataStep.params.sample_ids ? dataStep.params.sample_ids : "",
      manifest_path: dataStep.params && dataStep.params.manifest_path ? dataStep.params.manifest_path : "",
      image_root: dataStep.params && dataStep.params.image_root ? dataStep.params.image_root : "",
      dataset_dir: dataStep.params && dataStep.params.dataset_dir ? dataStep.params.dataset_dir : (taskId === "object_detection" ? ".noema/datasets/coco128" : (taskId === "segmentation" ? ".noema/datasets/coco8-seg" : ".noema/datasets/flickr8k")),
      limit: dataStep.params && dataStep.params.limit ? integerOr(dataStep.params.limit, taskId === "image_text_retrieval" ? 16 : (taskId === "segmentation" ? 4 : 8)) : (taskId === "image_text_retrieval" ? 16 : (taskId === "segmentation" ? 4 : 8)),
      image_size: dataStep.params && dataStep.params.image_size ? integerOr(dataStep.params.image_size, taskId === "image_generation" ? 512 : (taskId === "object_detection" || taskId === "segmentation" ? 320 : 224)) : (taskId === "image_generation" ? 512 : (taskId === "object_detection" || taskId === "segmentation" ? 320 : 224)),
      split: dataStep.params && dataStep.params.split ? dataStep.params.split : (taskId === "object_detection" ? "train2017" : (taskId === "segmentation" ? "val" : "validation")),
      caption_index: dataStep.params && dataStep.params.caption_index ? integerOr(dataStep.params.caption_index, 0) : 0,
    },
    vqa: {
      mode: vqaMode,
      model_id: (vqaReceiver.params || {}).model_id || "dandelin/vilt-b32-finetuned-vqa",
      device: (vqaReceiver.params || {}).device || "cpu",
      top_k: integerOr((vqaReceiver.params || {}).top_k, 1),
    },
    retrieval: {
      backend: retrievalBackend,
      model_id: (imageEncoder.params || {}).model_id || (textEncoder.params || {}).model_id || "openai/clip-vit-base-patch32",
      device: (imageEncoder.params || {}).device || (textEncoder.params || {}).device || "cpu",
      top_k: integerOr((retrievalReceiver.params || {}).top_k, 10),
    },
    generation: {
      preset: inferGenerationPresetId(generationParams, (recipe && recipe.metadata) || {}),
      backend: generationParams.backend || "diffusers",
      model_id: generationParams.model_id || "segmind/tiny-sd",
      device: generationParams.device || "cpu",
      height: integerOr(generationParams.height, 512),
      width: integerOr(generationParams.width, 512),
      num_inference_steps: integerOr(generationParams.num_inference_steps, 20),
      guidance_scale: numberOr(generationParams.guidance_scale, 7.5),
      prompt_template: generationParams.prompt_template || GENERATION_PROMPT_TEMPLATE,
      negative_prompt: generationParams.negative_prompt !== undefined ? generationParams.negative_prompt : GENERATION_NEGATIVE_PROMPT,
      disable_safety_checker: generationParams.disable_safety_checker === true,
      use_safetensors: generationParams.use_safetensors === true ? true : (generationParams.use_safetensors === false ? false : null),
    },
    clip: {
      backend: clipParams.backend || "transformers_clip",
      model_id: clipParams.model_id || "openai/clip-vit-base-patch32",
      device: clipParams.device || "cpu",
    },
    vision: {
      model_id: visionParams.model_id || (isSegmentation ? "yolo11n-seg.pt" : "yolo11n.pt"),
      device: visionParams.device || "cpu",
      confidence: numberOr(visionParams.confidence, 0.25),
      iou: numberOr(visionParams.iou, 0.7),
      mask_threshold: numberOr(visionParams.mask_threshold, 0.5),
      eval_iou: numberOr(evalParams.iou_threshold, 0.5),
    },
  };
}

function defaultTaskRecipeConfig(taskId = "classification") {
  const isVqa = taskId === "visual_question_answering";
  const isRetrieval = taskId === "image_text_retrieval";
  const isGeneration = taskId === "image_generation";
  const isDetection = taskId === "object_detection";
  const isSegmentation = taskId === "segmentation";
  return {
    name: isVqa ? "vqa_pretrained_transformers_smoke" : (isGeneration ? "diffusion_flickr8k_generation" : (isRetrieval ? "clip_retrieval_flickr8k_clip" : (isDetection ? "yolo_coco128_detection" : (isSegmentation ? "yolo_coco8_segmentation" : (taskId === "classification" ? "task_classification_smoke" : `${taskId}_contract_smoke`))))),
    task: { id: taskId || "classification" },
    data: {
      source: isRetrieval || isGeneration ? "flickr8k" : (isDetection ? "coco128_detection" : (isSegmentation ? "coco8_segmentation" : (isVqa ? "vqa_small" : "smoke"))),
      dataset: isRetrieval || isGeneration ? "flickr8k" : (isDetection ? "coco128_detection" : (isSegmentation ? "coco8_segmentation" : (isVqa ? "vqa_small" : "task_smoke"))),
      sample_ids: "",
      manifest_path: "",
      image_root: "",
      dataset_dir: isDetection ? ".noema/datasets/coco128" : (isSegmentation ? ".noema/datasets/coco8-seg" : ".noema/datasets/flickr8k"),
      limit: isGeneration ? 1 : (isRetrieval ? 16 : (isSegmentation ? 4 : 8)),
      image_size: isGeneration ? 512 : (isDetection || isSegmentation ? 320 : 224),
      split: isDetection ? "train2017" : (isSegmentation ? "val" : "validation"),
      caption_index: 0,
    },
    vqa: {
      mode: isVqa ? "pretrained_transformers" : "semantic_packet",
      model_id: "dandelin/vilt-b32-finetuned-vqa",
      device: "cpu",
      top_k: 1,
    },
    retrieval: {
      backend: "transformers_clip",
      model_id: "openai/clip-vit-base-patch32",
      device: "cpu",
      top_k: 10,
    },
    generation: {
      backend: "diffusers",
      preset: "local_quality",
      model_id: "segmind/tiny-sd",
      device: "cpu",
      height: 512,
      width: 512,
      num_inference_steps: 20,
      guidance_scale: 7.5,
      prompt_template: GENERATION_PROMPT_TEMPLATE,
      negative_prompt: GENERATION_NEGATIVE_PROMPT,
      disable_safety_checker: false,
      use_safetensors: false,
    },
    clip: {
      backend: "transformers_clip",
      model_id: "openai/clip-vit-base-patch32",
      device: "cpu",
    },
    vision: {
      model_id: isSegmentation ? "yolo11n-seg.pt" : "yolo11n.pt",
      device: "cpu",
      confidence: 0.25,
      iou: 0.7,
      mask_threshold: 0.5,
      eval_iou: 0.5,
    },
  };
}

function inheritedTaskMetadata(previousRecipe) {
  const source = (previousRecipe && previousRecipe.metadata) || {};
  const metadata = {};
  ["seed", "repeat_count", "data_plane_backend"].forEach((key) => {
    if (source[key] !== undefined) metadata[key] = source[key];
  });
  return metadata;
}

function taskCodecTimingMetadata(runner) {
  return {
    enabled: true,
    runner,
    runtime_adapter_available: true,
    warmup_runs: 0,
    timed_runs: 1,
  };
}


function buildTaskRecipeFromConfig(config, previousRecipe) {
  const taskId = config && config.task ? config.task.id || "classification" : "classification";
  const name = config.name || (previousRecipe && previousRecipe.name) || (taskId === "classification" ? "task_classification_smoke" : `${taskId}_contract_smoke`);
  if (taskId === "visual_question_answering") {
    return buildVqaTaskRecipeFromConfig(config, previousRecipe, name);
  }
  if (taskId === "image_text_retrieval") {
    return buildRetrievalTaskRecipeFromConfig(config, previousRecipe, name);
  }
  if (taskId === "image_generation") {
    return buildGenerationTaskRecipeFromConfig(config, previousRecipe, name);
  }
  if (taskId === "object_detection" || taskId === "segmentation") {
    return buildVisionTaskRecipeFromConfig(config, previousRecipe, name);
  }
  const steps = [
    makeRecipeStep("data", "source.task_labels_smoke", {}, {
      ...defaultParamsFor(operationById("source.task_labels_smoke")),
      dataset: config.data && config.data.dataset ? config.data.dataset : "task_smoke",
      sample_ids: config.data && config.data.sample_ids ? config.data.sample_ids : "",
    }),
    makeRecipeStep("evaluation", "metrics.classification", {
      reference: "data.reference",
      candidate: "data.candidate",
    }, {}),
  ];
  return {
    schema_version: 1,
    name,
    description: "Dependency-light task-oriented classification smoke recipe.",
    execution_profile: { id: EXECUTION_PROFILE_IDS.taskEvaluation, version: 1 },
    metadata: {
      ...inheritedTaskMetadata(previousRecipe),
      research_stage: "phase6_task_benchmark_core",
      ui_configured: true,
      channel_enabled: false,
      channel_mode: "disabled",
      research: { task: { id: taskId } },
    },
    steps,
  };
}

function buildGenerationTaskRecipeFromConfig(config, previousRecipe, name) {
  const data = config && config.data ? config.data : {};
  const generation = config && config.generation ? config.generation : {};
  const clip = config && config.clip ? config.clip : {};
  const preset = generationPresetById(generation.preset || "local_quality");
  const modelId = generation.model_id || preset.model_id || "segmind/tiny-sd";
  const clipModelId = clip.model_id || "openai/clip-vit-base-patch32";
  const dataStep = makeRecipeStep("data", "source.flickr8k_retrieval", {}, {
    ...defaultParamsFor(operationById("source.flickr8k_retrieval")),
    dataset_dir: data.dataset_dir || ".noema/datasets/flickr8k",
    split: data.split || "validation",
    limit: integerOr(data.limit, 1),
    image_size: integerOr(data.image_size, 512),
    caption_index: integerOr(data.caption_index, 0),
    download: true,
  });
  const steps = [
    dataStep,
    makeRecipeStep("semantic_encoder", "foundation.text_semantic_state_encode", {
      texts: "data.texts",
    }, {
      extractor: "local_rules",
      include_text: true,
      max_concepts: 24,
    }),
    makeRecipeStep("sender", "foundation.semantic_state_payload_encode", {
      state: "semantic_encoder.state",
    }, {
      payload_format: "semantic_state_json_utf8",
    }),
    makeRecipeStep("payload_bit_boundary", "channel.bit_boundary", {
      bits: "sender.bits",
    }, {
      role: "payload_input",
      label: "payload_input",
      data_plane_backend: "auto",
      expected_bit_count: 0,
    }),
    makeRecipeStep("channel_encoder", "channel.identity_encoder", {
      bits: "payload_bit_boundary.bits",
    }, {
      data_plane_backend: "auto",
    }),
    makeRecipeStep("tx_bit_boundary", "channel.bit_boundary", {
      bits: "channel_encoder.coded_bits",
    }, {
      role: "modulator_input",
      label: "modulator_input",
      data_plane_backend: "auto",
      expected_bit_count: 0,
    }),
    makeRecipeStep("wireless_channel", "channel.identity_link", {
      bits: "tx_bit_boundary.bits",
    }, {
      label: "disabled_generation_channel",
      data_plane_backend: "auto",
    }),
    makeRecipeStep("rx_bit_boundary", "channel.bit_boundary", {
      bits: "wireless_channel.bits",
    }, {
      role: "identity_channel_output",
      label: "identity_channel_output",
      data_plane_backend: "auto",
      expected_bit_count: 0,
    }),
    makeRecipeStep("channel_bit_count_match", "channel.bit_count_match", {
      reference: "tx_bit_boundary.bits",
      candidate: "rx_bit_boundary.bits",
    }, {
      label: "channel_io",
      data_plane_backend: "auto",
    }),
    makeRecipeStep("channel_decoder", "channel.identity_decoder", {
      coded_bits: "rx_bit_boundary.bits",
    }, {
      data_plane_backend: "auto",
    }),
    makeRecipeStep("payload_decoder", "foundation.semantic_state_payload_decode", {
      bits: "channel_decoder.bits",
    }, {
      on_error: "fail",
    }),
    makeRecipeStep("receiver", "foundation.diffusion_state_to_image", {
      state: "payload_decoder.state",
    }, {
      ...defaultParamsFor(operationById("foundation.diffusion_state_to_image")),
      backend: "diffusers",
      model_id: modelId,
      device: generation.device || "cpu",
      height: integerOr(generation.height, preset.height || 512),
      width: integerOr(generation.width, preset.width || 512),
      num_inference_steps: integerOr(generation.num_inference_steps, preset.num_inference_steps || 20),
      guidance_scale: numberOr(generation.guidance_scale, preset.guidance_scale !== undefined ? preset.guidance_scale : 7.5),
      prompt_template: generation.prompt_template || preset.prompt_template || GENERATION_PROMPT_TEMPLATE,
      negative_prompt: generation.negative_prompt !== undefined ? generation.negative_prompt : (preset.negative_prompt || ""),
      disable_safety_checker: generation.disable_safety_checker === true,
      use_safetensors: generation.use_safetensors === true ? true : (generation.use_safetensors === false ? false : (preset.use_safetensors === undefined ? null : preset.use_safetensors)),
    }),
    makeRecipeStep("text_encoder", "foundation.clip_text_embed", {
      texts: "data.texts",
    }, {
      ...defaultParamsFor(operationById("foundation.clip_text_embed")),
      backend: "transformers_clip",
      model_id: clipModelId,
      device: clip.device || "cpu",
      dimensions: 128,
    }),
    makeRecipeStep("source_image_encoder", "foundation.clip_image_embed", {
      images: "data.images",
    }, {
      ...defaultParamsFor(operationById("foundation.clip_image_embed")),
      backend: "transformers_clip",
      model_id: clipModelId,
      device: clip.device || "cpu",
      bins: 16,
      dimensions: 128,
    }),
    makeRecipeStep("generated_image_encoder", "foundation.clip_image_embed", {
      images: "receiver.images",
    }, {
      ...defaultParamsFor(operationById("foundation.clip_image_embed")),
      backend: "transformers_clip",
      model_id: clipModelId,
      device: clip.device || "cpu",
      bins: 16,
      dimensions: 128,
    }),
    makeRecipeStep("text_image_alignment", "metrics.embedding_similarity", {
      reference: "text_encoder.embeddings",
      candidate: "generated_image_encoder.embeddings",
    }, {
      label: "generation.text_image_clip",
      normalize: true,
    }),
    makeRecipeStep("image_image_alignment", "metrics.embedding_similarity", {
      reference: "source_image_encoder.embeddings",
      candidate: "generated_image_encoder.embeddings",
    }, {
      label: "generation.image_image_clip",
      normalize: true,
    }),
  ];
  return {
    schema_version: 1,
    name: name || "diffusion_flickr8k_generation",
    description: "Real Flickr8k caption-to-image generative receiver baseline with diffusers and CLIP alignment metrics.",
    execution_profile: { id: EXECUTION_PROFILE_IDS.layered, version: 1 },
    metadata: {
      ...inheritedTaskMetadata(previousRecipe),
      benchmark_id: "diffusion_flickr8k_generation",
      benchmark_version: "v1",
      research_stage: "phase11_diffusion_generative_receiver",
      ui_configured: true,
      generation_preset: generation.preset || "local_quality",
      channel_enabled: false,
      channel_mode: "disabled",
      research: { task: { id: "image_generation" } },
      codec_profile: "semantic_state_diffusion",
      codec_label: "SemanticState payload plus Diffusers text-to-image receiver",
      codec_format: "semantic_state_json_utf8",
      codec_output_form: "generated_images",
      semantic_representation: "semantic_state",
      transport_representation: "semantic_state_payload_bits",
      channel_bit_contract: "np.uint8 unpacked bits, one bit per element, values 0 or 1",
      rate_count_fixed_point: "tx_bit_boundary.channel.fixed.modulator_input.bit_count",
      seed: previousRecipe && previousRecipe.metadata && previousRecipe.metadata.seed !== undefined ? previousRecipe.metadata.seed : 23,
      measure_codec_timing: true,
      codec_timing: taskCodecTimingMetadata("pytorch"),
    },
    steps,
  };
}

function buildVisionTaskRecipeFromConfig(config, previousRecipe, name) {
  const taskId = config && config.task ? config.task.id || "object_detection" : "object_detection";
  const isSegmentation = taskId === "segmentation";
  const data = config && config.data ? config.data : {};
  const vision = config && config.vision ? config.vision : {};
  const modelId = vision.model_id || (isSegmentation ? "yolo11n-seg.pt" : "yolo11n.pt");
  const device = vision.device || "cpu";
  const confidence = numberOr(vision.confidence, 0.25);
  const iou = numberOr(vision.iou, 0.7);
  const imageSize = integerOr(data.image_size, 320);
  const limit = integerOr(data.limit, isSegmentation ? 4 : 8);
  const dataStep = isSegmentation
    ? makeRecipeStep("data", "source.coco8_segmentation", {}, {
      ...defaultParamsFor(operationById("source.coco8_segmentation")),
      dataset_dir: data.dataset_dir || ".noema/datasets/coco8-seg",
      split: data.split || "val",
      limit,
      image_size: imageSize,
      download: true,
    })
    : makeRecipeStep("data", "source.coco128_detection", {}, {
      ...defaultParamsFor(operationById("source.coco128_detection")),
      dataset_dir: data.dataset_dir || ".noema/datasets/coco128",
      split: "train2017",
      limit,
      image_size: imageSize,
      download: true,
    });
  const receiverStep = isSegmentation
    ? makeRecipeStep("receiver", "foundation.yolo_segment", {
      images: "data.images",
    }, {
      ...defaultParamsFor(operationById("foundation.yolo_segment")),
      model_id: modelId,
      device,
      confidence,
      iou,
      mask_threshold: numberOr(vision.mask_threshold, 0.5),
    })
    : makeRecipeStep("receiver", "foundation.yolo_detect", {
      images: "data.images",
    }, {
      ...defaultParamsFor(operationById("foundation.yolo_detect")),
      model_id: modelId,
      device,
      confidence,
      iou,
    });
  const evaluationStep = isSegmentation
    ? makeRecipeStep("evaluation", "metrics.segmentation", {
      reference: "data.segmentation",
      candidate: "receiver.segmentation",
    }, {})
    : makeRecipeStep("evaluation", "metrics.detection", {
      reference: "data.detections",
      candidate: "receiver.detections",
    }, {
      iou_threshold: numberOr(vision.eval_iou, 0.5),
    });
  return {
    schema_version: 1,
    name: name || (isSegmentation ? "yolo_coco8_segmentation" : "yolo_coco128_detection"),
    description: isSegmentation
      ? "Real COCO8-seg segmentation baseline with pretrained Ultralytics YOLO segmentation and mask metrics."
      : "Real COCO128 object-detection baseline with pretrained Ultralytics YOLO and IoU metrics.",
    execution_profile: { id: EXECUTION_PROFILE_IDS.taskEvaluation, version: 1 },
    metadata: {
      ...inheritedTaskMetadata(previousRecipe),
      benchmark_id: isSegmentation ? "yolo_coco8_segmentation" : "yolo_coco128_detection",
      benchmark_version: "v1",
      research_stage: "phase10_detection_segmentation",
      ui_configured: true,
      channel_enabled: false,
      channel_mode: isSegmentation ? "no_channel_full_image_segmentation_baseline" : "no_channel_full_image_detection_baseline",
      codec_format: "pretrained_yolo_full_image",
      codec_label: isSegmentation ? "Ultralytics YOLO instance segmenter" : "Ultralytics YOLO object detector",
      codec_output_form: isSegmentation ? "segmentation_mask" : "detections",
      codec_profile: isSegmentation ? "yolo_segmentation" : "yolo_detection",
      semantic_representation: isSegmentation ? "segmentation_masks" : "detections",
      transport_representation: "none_no_channel_baseline",
      measure_codec_timing: true,
      codec_timing: taskCodecTimingMetadata("pytorch"),
      research: { task: { id: taskId } },
    },
    steps: [dataStep, receiverStep, evaluationStep],
  };
}

function buildRetrievalTaskRecipeFromConfig(config, previousRecipe, name) {
  const data = config && config.data ? config.data : {};
  const retrieval = config && config.retrieval ? config.retrieval : {};
  const isFlickr = true;
  const backend = "transformers_clip";
  const realClip = backend === "transformers_clip";
  const modelId = retrieval.model_id || "openai/clip-vit-base-patch32";
  const device = retrieval.device || "cpu";
  const topK = integerOr(retrieval.top_k, 10);
  const dataStep = isFlickr
    ? makeRecipeStep("data", "source.flickr8k_retrieval", {}, {
      ...defaultParamsFor(operationById("source.flickr8k_retrieval")),
      dataset_dir: data.dataset_dir || ".noema/datasets/flickr8k",
      split: data.split || "validation",
      limit: integerOr(data.limit, 16),
      image_size: integerOr(data.image_size, 224),
      caption_index: integerOr(data.caption_index, 0),
      download: true,
    })
    : makeRecipeStep("data", "source.retrieval_smoke", {}, {
      ...defaultParamsFor(operationById("source.retrieval_smoke")),
      dataset: "retrieval_smoke",
      sample_ids: data.sample_ids || "",
      image_size: integerOr(data.image_size, 224),
    });
  const steps = [
    dataStep,
    makeRecipeStep("image_encoder", "foundation.clip_image_embed", {
      images: "data.images",
    }, {
      ...defaultParamsFor(operationById("foundation.clip_image_embed")),
      backend,
      model_id: modelId,
      bins: 16,
      dimensions: 8,
      device,
    }),
    makeRecipeStep("text_encoder", "foundation.clip_text_embed", {
      texts: "data.texts",
    }, {
      ...defaultParamsFor(operationById("foundation.clip_text_embed")),
      backend,
      model_id: modelId,
      dimensions: realClip ? 128 : 8,
      device,
    }),
    makeRecipeStep("receiver", "foundation.clip_retrieval_rank", {
      image_embeddings: "image_encoder.embeddings",
      text_embeddings: "text_encoder.embeddings",
      targets: "data.targets",
    }, {
      normalize: true,
      top_k: topK,
    }),
    makeRecipeStep("evaluation", "metrics.retrieval", {
      rankings: "receiver.rankings",
    }, {
      k_values: "1,5,10",
    }),
  ];
  return {
    schema_version: 1,
    name: name || (isFlickr ? "clip_retrieval_flickr8k_clip" : "clip_retrieval_debug"),
    description: isFlickr
      ? "Real Flickr8k image-text retrieval baseline with pretrained CLIP embeddings and Recall@K metrics."
      : "Synthetic image-text retrieval debug recipe for validating CLIP-style ranking plumbing.",
    execution_profile: { id: EXECUTION_PROFILE_IDS.taskEvaluation, version: 1 },
    metadata: {
      ...inheritedTaskMetadata(previousRecipe),
      benchmark_id: isFlickr ? "clip_retrieval_flickr8k_clip" : "clip_retrieval_debug",
      benchmark_version: "v1",
      research_stage: "phase9_clip_retrieval",
      ui_configured: true,
      channel_enabled: false,
      channel_mode: "no_channel_embedding_retrieval_baseline",
      codec_format: "clip_embedding_retrieval",
      codec_label: realClip ? "Transformers CLIP image/text retrieval" : "Local CLIP-style retrieval debug",
      codec_output_form: "rankings",
      codec_profile: "clip_retrieval",
      semantic_representation: "image_text_embeddings",
      transport_representation: "none_no_channel_baseline",
      measure_codec_timing: true,
      research: { task: { id: "image_text_retrieval" } },
      codec_timing: taskCodecTimingMetadata(realClip ? "pytorch" : "local_python"),
    },
    steps,
  };
}

function buildVqaTaskRecipeFromConfig(config, previousRecipe, name) {
  const data = config && config.data ? config.data : {};
  const vqa = config && config.vqa ? config.vqa : {};
  if (vqa.mode === "pretrained_transformers") {
    return buildPretrainedVqaTaskRecipeFromConfig(config, previousRecipe, name);
  }
  const smokeData = { ...data, source: "smoke" };
  const steps = [
    buildVqaDataStep(smokeData),
    makeRecipeStep("semantic_selector", "foundation.vqa_semantic_select", {
      images: "data.images",
      questions: "data.questions",
    }, { selector: "local_rules" }),
    makeRecipeStep("sender", "foundation.vqa_payload_encode", {
      packet: "semantic_selector.packet",
    }, { payload_format: "json_utf8" }),
    makeRecipeStep("payload_bit_boundary", "channel.bit_boundary", {
      bits: "sender.bits",
    }, { data_plane_backend: "auto", expected_bit_count: 0, label: "payload_input", role: "payload_input" }),
    makeRecipeStep("channel_encoder", "channel.identity_encoder", {
      bits: "payload_bit_boundary.bits",
    }, { data_plane_backend: "auto" }),
    makeRecipeStep("tx_bit_boundary", "channel.bit_boundary", {
      bits: "channel_encoder.coded_bits",
    }, { data_plane_backend: "auto", expected_bit_count: 0, label: "modulator_input", role: "modulator_input" }),
    makeRecipeStep("wireless_channel", "channel.identity_link", {
      bits: "tx_bit_boundary.bits",
    }, { data_plane_backend: "auto", label: "disabled_vqa_channel" }),
    makeRecipeStep("rx_bit_boundary", "channel.bit_boundary", {
      bits: "wireless_channel.bits",
    }, { data_plane_backend: "auto", expected_bit_count: 0, label: "identity_channel_output", role: "identity_channel_output" }),
    makeRecipeStep("channel_bit_count_match", "channel.bit_count_match", {
      reference: "tx_bit_boundary.bits",
      candidate: "rx_bit_boundary.bits",
    }, { data_plane_backend: "auto", label: "channel_io" }),
    makeRecipeStep("channel_decoder", "channel.identity_decoder", {
      coded_bits: "rx_bit_boundary.bits",
    }, { data_plane_backend: "auto" }),
    makeRecipeStep("payload_decoder", "foundation.vqa_payload_decode", {
      bits: "channel_decoder.bits",
    }, { on_error: "fail" }),
    makeRecipeStep("receiver", "foundation.vqa_answer_from_packet", {
      packet: "payload_decoder.packet",
    }, { receiver: "selected_label" }),
    makeRecipeStep("evaluation", "metrics.vqa", {
      reference: "data.answers",
      candidate: "receiver.answers",
    }, {}),
    makeRecipeStep("region_evaluation", "metrics.detection", {
      reference: "data.detections",
      candidate: "semantic_selector.detections",
    }, { iou_threshold: 0.5 }),
  ];
  return {
    schema_version: 1,
    name: name || "vqa_goal_oriented_smoke",
    description: "Goal-oriented VQA smoke recipe with semantic packet transmission over fixed bit boundaries.",
    execution_profile: { id: EXECUTION_PROFILE_IDS.layered, version: 1 },
    metadata: {
      ...inheritedTaskMetadata(previousRecipe),
      benchmark_id: "vqa_goal_oriented_smoke_v1",
      benchmark_version: "v1",
      research_stage: "phase8_goal_oriented_vqa",
      ui_configured: true,
      channel_enabled: false,
      channel_mode: "disabled",
      codec_format: "vqa_semantic_packet_json_utf8",
      codec_label: "VQA semantic packet JSON payload codec",
      codec_output_form: "bits",
      codec_profile: "vqa_semantic_packet",
      semantic_representation: "vqa_semantic_packet",
      transport_representation: "json_utf8_bits",
      measure_codec_timing: true,
      codec_timing: taskCodecTimingMetadata("local_python"),
      research: { task: { id: "visual_question_answering" } },
    },
    steps,
  };
}

function buildPretrainedVqaTaskRecipeFromConfig(config, previousRecipe, name) {
  const data = config && config.data ? config.data : {};
  const vqa = config && config.vqa ? config.vqa : {};
  const steps = [
    buildVqaDataStep(data),
    makeRecipeStep("receiver", "foundation.vqa_transformers_answer", {
      images: "data.images",
      questions: "data.questions",
    }, {
      ...defaultParamsFor(operationById("foundation.vqa_transformers_answer")),
      model_id: vqa.model_id || "dandelin/vilt-b32-finetuned-vqa",
      device: vqa.device || "cpu",
      top_k: integerOr(vqa.top_k, 1),
    }),
    makeRecipeStep("evaluation", "metrics.vqa", {
      reference: "data.answers",
      candidate: "receiver.answers",
    }, {}),
  ];
  return {
    schema_version: 1,
    name: name || "vqa_pretrained_transformers_smoke",
    description: "Pretrained full-image VQA baseline over the built-in VQA smoke examples.",
    execution_profile: { id: EXECUTION_PROFILE_IDS.taskEvaluation, version: 1 },
    metadata: {
      ...inheritedTaskMetadata(previousRecipe),
      benchmark_id: "vqa_pretrained_transformers_smoke",
      benchmark_version: "v1",
      research_stage: "phase8_goal_oriented_vqa",
      ui_configured: true,
      channel_enabled: false,
      channel_mode: "no_channel_full_image_vqa_baseline",
      codec_format: "pretrained_vqa_full_image",
      codec_label: "Pretrained Transformers full-image VQA baseline",
      codec_output_form: "answers",
      codec_profile: "pretrained_vqa",
      semantic_representation: "full_image_question",
      transport_representation: "none_no_channel_baseline",
      measure_codec_timing: true,
      codec_timing: taskCodecTimingMetadata("pytorch"),
      research: { task: { id: "visual_question_answering" } },
    },
    steps,
  };
}

function buildVqaDataStep(data) {
  if (data && data.source === "vqa_small") {
    return makeRecipeStep("data", "source.vqa_small_hf", {}, {
      ...defaultParamsFor(operationById("source.vqa_small_hf")),
      split: data.split || "validation",
      limit: integerOr(data.limit, 8),
      image_size: integerOr(data.image_size, 224),
    });
  }
  if (data && data.source === "manifest") {
    return makeRecipeStep("data", "source.vqa_manifest", {}, {
      ...defaultParamsFor(operationById("source.vqa_manifest")),
      manifest_path: data.manifest_path || "",
      image_root: data.image_root || "",
      limit: integerOr(data.limit, 8),
      image_size: integerOr(data.image_size, 224),
    });
  }
  return makeRecipeStep("data", "source.vqa_smoke", {}, {
    ...defaultParamsFor(operationById("source.vqa_smoke")),
    dataset: data.dataset || "coco_vqa_smoke",
    sample_ids: data.sample_ids || "",
  });
}

function applyTaskRecipeConfig(config, renderControls) {
  const previousRecipe = state.editRecipe;
  const baselineRecipe = buildTaskRecipeFromConfig(
    taskRecipeConfigFromRecipe(previousRecipe),
    previousRecipe
  );
  const rebuiltRecipe = buildTaskRecipeFromConfig(config, previousRecipe);
  state.editRecipe = recipeWithPreservedEditedTopology(
    previousRecipe,
    rebuiltRecipe,
    baselineRecipe
  );
  applyBuiltRecipe(state.editRecipe, renderControls);
}

function recipeConfigFromRecipe(recipe) {
  const steps = recipe.steps || [];
  const metadata = recipe.metadata || {};
  const timingMetadata = metadata.codec_timing || {};
  const metadataRunner = String(timingMetadata.requested_runner || timingMetadata.runner || "");
  const baseProfile = codecProfileFromMetadata(metadata) || inferCodecProfile(steps);
  const profile = codecProfile(baseProfile.id, {
    external: { representation: metadata.external_representation || baseProfile.externalRepresentation || "bits" },
    metrics: { codecRunner: metadataRunner || baseProfile.runtime || "auto" },
  });
  const dataStep = stepById(steps, "data") || findStepByOpIn(steps, "source.image_dataset") || {};
  const senderStep = stepById(steps, "sender") || findStepByOpIn(steps, profile.encoder) || {};
  const receiverStep = stepById(steps, "receiver") || findStepByOpIn(steps, profile.decoder) || {};
  const conversionStep = profile.conversion ? stepById(steps, profile.conversion.id) || findStepByOpIn(steps, profile.conversion.op) || {} : {};
  const encoderParamStep = conversionStep.op ? conversionStep : senderStep;
  const sourceNoiseStep = stepById(steps, "sender_source_perturbation") || findStepByOpIn(steps, "noise.source_image_perturbation") || {};
  const senderNoiseStep = stepById(steps, "sender_representation_noise") || {};
  const receiverNoiseStep = stepById(steps, "receiver_representation_noise") || {};
  const channelEncoderStep = stepById(steps, "channel_encoder") || {};
  const channelDecoderStep = stepById(steps, "channel_decoder") || {};
  const wirelessStep = stepById(steps, "wireless_channel") || {};
  const channelStateStep = stepById(steps, "channel_state") || findStepByOpIn(steps, "wireless.ofdm_channel_state") || {};
  const txPowerStep = stepById(steps, "tx_power") || stepById(steps, "tx_power_allocate") || findStepByOpIn(steps, "model.symbol_power_allocator") || stepById(steps, "tx_power_normalize") || findStepByOpIn(steps, "channel.symbol_power_normalize") || findStepByOpIn(steps, "channel.symbol_power_identity") || {};
  const modulatorStep = stepById(steps, "modulator") || {};
  const demodulatorStep = stepById(steps, "demodulator") || {};
  const digitalLinkStep = wirelessStep.op === "wireless.digital_link" ? wirelessStep : {};
  const coding = channelEncoderStep.op === "channel.repetition_encoder" ? "repetition" : "none";
  const channelStateParams = channelStateStep.params || {};
  const wirelessParams = { ...channelStateParams, ...(digitalLinkStep.params || {}), ...(wirelessStep.params || {}) };
  const dataPlaneBackend = String(
    metadata.data_plane_backend ||
      firstDefined(
        steps.map((step) => step && step.params ? step.params.data_plane_backend : undefined),
        "auto"
      )
  );
  const baseSeed = firstInteger(
    [
      metadata.seed,
      metadata.experiment_seed,
      metadata.ui_seed,
      wirelessParams.seed,
      (sourceNoiseStep.params || {}).seed,
      (senderNoiseStep.params || {}).seed,
      (receiverNoiseStep.params || {}).seed,
    ],
    23
  );
  const disabledMode = String(metadata.channel_disabled_mode || metadata.channel_mode || "");
  const identitySymbolSkeleton = wirelessStep.op === "channel.identity_symbol_link" && modulatorStep.op === "modulation.identity_modulate" && demodulatorStep.op === "demodulation.identity_demodulate";
  const wirelessMode = wirelessStep.op === "wireless.channel" || wirelessStep.op === "wireless.digital_link"
    ? String(wirelessParams.channel || "awgn")
    : identitySymbolSkeleton
      ? disabledMode === "bit_perfect_bypass" || disabledMode === "disabled" ? "skip" : "identity_phy"
      : "skip";
  const channelDisabled = !physicalChannelEnabled(wirelessMode);
  const senderRunner = String((senderStep.params || {}).runner || "");
  const receiverRunner = String((receiverStep.params || {}).runner || "");
  const requestedRunner = metadataRunner && metadataRunner !== "auto"
    ? metadataRunner
    : senderRunner || receiverRunner || metadataRunner || "";
  const codecRunner = actualCodecRunner(profile, { metrics: { codecRunner: requestedRunner } });
  const config = {
    name: recipe.name || "recipe",
    description: recipe.description || "",
    metadata: structuredCloneFallback(metadata),
    seed: baseSeed,
    repeatCount: Math.max(1, firstInteger([metadata.repeat_count, metadata.ui_repeat_count, (dataStep.params || {}).repeat_count], 1)),
    execution: {
      dataPlaneBackend: DATA_PLANE_BACKENDS.includes(dataPlaneBackend) ? dataPlaneBackend : "auto",
    },
    data: {
      ...defaultParamsFor(operationById("source.image_dataset")),
      ...(dataStep.params || {}),
    },
    codec: profile.id,
    external: {
      representation: profile.externalRepresentation || "bits",
    },
    sourceNoise: {
      ...defaultParamsFor(operationById("noise.source_image_perturbation")),
      mode: "none",
      ...(sourceNoiseStep.params || {}),
    },
    codecParams: {
      encoder: {
        ...defaultParamsFor(operationById(codecSettingsOperation(profile, "encoder"))),
        ...(encoderParamStep.params || {}),
        ...(profile.conversion ? paramsForOperation(senderStep.params || {}, profile.encoder) : {}),
      },
      decoder: {
        ...defaultParamsFor(operationById(codecSettingsOperation(profile, "decoder"))),
        ...(receiverStep.params || {}),
      },
      packer: {
        ...defaultParamsFor(operationById(profile.packer)),
        ...((stepById(steps, "payload_encoder") || stepById(steps, "payload_packer") || {}).params || {}),
      },
      unpacker: {
        ...defaultParamsFor(operationById(profile.unpacker)),
        ...((stepById(steps, "payload_decoder") || stepById(steps, "payload_unpacker") || {}).params || {}),
      },
    },
    semantic: {
      sender: {
        ...defaultParamsFor(operationById(representationNoiseOperationForProfile(profile))),
        mode: "none",
        ...(senderNoiseStep.params || {}),
      },
      receiver: {
        ...defaultParamsFor(operationById(representationNoiseOperationForProfile(profile))),
        mode: "none",
        ...(receiverNoiseStep.params || {}),
      },
    },
    channel: {
      coding,
      codingParams: {
        factor: 3,
        ...(coding === "repetition" ? channelEncoderStep.params || {} : channelDecoderStep.params || {}),
      },
      wireless: CHANNEL_MODES.includes(wirelessMode) ? wirelessMode : "awgn",
      wirelessBackend: WIRELESS_BACKENDS.includes(String(wirelessParams.wireless_backend || "auto")) ? String(wirelessParams.wireless_backend || "auto") : "auto",
      txPowerMode: txPowerStep.op === "model.symbol_power_allocator" ? "learned" : txPowerStep.op === "channel.symbol_power_normalize" ? "fixed" : "none",
      txPowerNormalize: txPowerStep.op !== undefined && txPowerStep.op !== "" && txPowerStep.op !== null,
      txPowerTarget: numberOr((txPowerStep.params || {}).target_power, 1),
      txPowerPolicy: String((txPowerStep.params || {}).policy || "snr_sigmoid"),
      txPowerGranularity: String((txPowerStep.params || {}).granularity || "global"),
      txPowerBudgetMode: String((txPowerStep.params || {}).budget_mode || "fixed_average"),
      txPowerContrast: numberOr((txPowerStep.params || {}).allocation_contrast, 0.6),
      txPowerSubcarrierCount: integerOr((txPowerStep.params || {}).subcarrier_count, numberOr(wirelessParams.ofdm_fft_size, 64)),
      txPowerStreamCount: integerOr((txPowerStep.params || {}).stream_count, numberOr(wirelessParams.tx_antennas, 1)),
      txPowerMin: numberOr((txPowerStep.params || {}).min_power, 0.25),
      txPowerMax: numberOr((txPowerStep.params || {}).max_power, 2),
      txPowerMidpointSnr: numberOr((txPowerStep.params || {}).midpoint_snr_db, 12),
      txPowerSlope: numberOr((txPowerStep.params || {}).slope_db, 4),
      txPowerUnit: String((txPowerStep.params || {}).power_unit || "normalized"),
      txPowerTransportMode: String((txPowerStep.params || {}).transport_mode || "fixed_modulation"),
      bitLoadingBpskMinSnrDb: numberOr((txPowerStep.params || {}).bit_loading_bpsk_min_snr_db, 6),
      bitLoadingQpskMinSnrDb: numberOr((txPowerStep.params || {}).bit_loading_qpsk_min_snr_db, 10),
      bitLoadingQam16MinSnrDb: numberOr((txPowerStep.params || {}).bit_loading_qam16_min_snr_db, 17),
      bitLoadingQam64MinSnrDb: numberOr((txPowerStep.params || {}).bit_loading_qam64_min_snr_db, 23),
      bitLoadingMaxBitsPerSymbol: integerOr((txPowerStep.params || {}).bit_loading_max_bits_per_symbol, 6),
      noiseMode: String(wirelessParams.noise_mode || "snr_at_unit_power"),
      noiseVariance: numberOr(wirelessParams.noise_variance, 0.1),
      snr_db: channelDisabled ? "" : numberOr(wirelessParams.snr_db, 12),
      modulation: channelDisabled ? "" : String((modulatorStep.params || {}).modulation || digitalLinkStep.params?.modulation || "qpsk"),
      demodulation: channelDisabled ? "" : "auto",
      tx_antennas: integerOr(wirelessParams.tx_antennas, 1),
      rx_antennas: integerOr(wirelessParams.rx_antennas, wirelessMode === "mimo_flat" ? 2 : 1),
      ofdm_fft_size: integerOr(wirelessParams.ofdm_fft_size, 64),
      num_ofdm_symbols: integerOr(wirelessParams.num_ofdm_symbols, 14),
      subcarrier_spacing_khz: numberOr(wirelessParams.subcarrier_spacing_khz, 15),
      carrier_frequency_ghz: numberOr(wirelessParams.carrier_frequency_ghz, 3.5),
      mobility_kmh: numberOr(wirelessParams.mobility_kmh, wirelessMode === "urban_micro" ? 30 : 3),
      tdlModel: String(channelStateParams.tdl_model || "A"),
      delaySpreadNs: numberOr(channelStateParams.delay_spread_ns, 100),
      normalizeChannel: channelStateParams.normalize_channel !== false,
      ofdmCapacityMultiplier: Math.max(1, integerOr(channelStateParams.capacity_multiplier, 1)),
      csiMode: channelStateStep.op ? "perfect_instantaneous" : "none",
      interferers: integerOr(wirelessParams.interferers, wirelessMode === "interference_awgn" || wirelessMode === "urban_micro" ? 1 : 0),
      interference_sir_db: numberOr(wirelessParams.interference_sir_db, wirelessMode === "urban_micro" ? 20 : 18),
    },
    metrics: {
      payloadBer: Boolean(stepById(steps, "payload_ber")),
      codedBer: Boolean(stepById(steps, "coded_ber")),
      codecTiming: timingMetadata.enabled !== false && metadata.measure_codec_timing !== false,
      codecRunner,
      timingWarmupRuns: Number(timingMetadata.warmup_runs || 0),
      timingTimedRuns: Number(timingMetadata.timed_runs || 1),
    },
  };
  applySweepDisplayParams(config, recipe);
  return config;
}

