      steps.push(makeRecipeStep("noisy_semantic_ground", "foundation.semantic_state_ground", {
        state: "noisy_semantic_encoder.state",
        kb: "knowledge_base.kb",
      }, {
        min_token_overlap: config.foundation.min_token_overlap || 1,
        max_matches_per_state: config.foundation.max_matches_per_state || 12,
      }));
      transmitStateRef = "noisy_semantic_ground.state";
