function datasetImageSelectorHint(config) {
  const key = datasetCacheKey(config);
  if (state.datasetImageLoads[key]) return "Loading image files from the dataset folder.";
  if (state.datasetImageErrors[key]) return state.datasetImageErrors[key];
  const payload = state.datasetImages[key];
  if (!payload) return "Kodak files are inspected without downloading. Use Download Kodak dataset, or run the recipe to materialize missing files.";
  if (!payload.images || !payload.images.length) return "No Kodak PNG files were found in this dataset folder.";
  return `${payload.count}/${payload.expected_count} Kodak files available. Missing files are downloaded only on an explicit request or when the recipe runs.`;
}

function datasetImageCountLabel(config) {
  const key = datasetCacheKey(config);
  if (state.datasetImageLoads[key]) return "...";
  const payload = state.datasetImages[key];
  if (payload && Number.isFinite(Number(payload.count))) {
    return `${Number(payload.count)} images`;
  }
  const selected = parseImageIds(config.data && config.data.image_ids);
  return selected.length ? `${selected.length} images` : "images";
}

async function loadDatasetImagesForConfig(config, force = false, ensure = false) {
  if (!config || !config.data || config.data.dataset !== "kodak") return;
  const key = datasetCacheKey(config);
  if (!force && (state.datasetImages[key] || state.datasetImageLoads[key] || state.datasetImageErrors[key])) return;
  state.datasetImageLoads[key] = true;
  delete state.datasetImageErrors[key];
  try {
    const query = new URLSearchParams({
      dataset: config.data.dataset || "kodak",
      dataset_dir: config.data.dataset_dir || ".noema/datasets/kodak",
      ensure: ensure ? "1" : "0",
    });
    const payload = await api(`/api/datasets/images?${query.toString()}`);
    state.datasetImages[key] = payload;
  } catch (error) {
    state.datasetImageErrors[key] = `Could not load dataset files: ${error.message}`;
  } finally {
    delete state.datasetImageLoads[key];
  }
  const currentConfig = state.editRecipe ? recipeConfigFromRecipe(state.editRecipe) : null;
  if (currentConfig && datasetCacheKey(currentConfig) === key) {
    renderRecipeControls();
  }
}

function datasetCacheKey(config) {
  const data = (config && config.data) || {};
  return `${data.dataset || "kodak"}::${data.dataset_dir || ".noema/datasets/kodak"}`;
}

function parseImageIds(value) {
  return String(value || "")
    .split(",")
    .map((item) => item.trim())
    .filter(Boolean);
}

function parseTextSampleIds(value) {
  return String(value || "")
    .split(",")
    .map((item) => item.trim())
    .filter(Boolean);
}

function codecOptions(current) {
  return CODEC_PROFILES.map((profile) => {
    const unavailable = unavailableOperationsForProfile(profile)[0];
    const available = !unavailable;
    const reason = unavailable ? ` - ${shortenLabel(operationUnavailableReason(unavailable), 52)}` : "";
    return `<option value="${escapeAttr(profile.id)}"${profile.id === current ? " selected" : ""}${available ? "" : " disabled"}>${escapeHtml(profile.label + reason)}</option>`;
  }).join("");
}

function semanticNoiseOptions(current) {
  return representationNoiseOptions(current, { form: "indices" });
}

function sourceImageNoiseOptions(current) {
  return SOURCE_IMAGE_NOISE_MODES.map((mode) => `<option value="${escapeAttr(mode)}"${mode === current ? " selected" : ""}>${escapeHtml(sourceImageNoiseLabel(mode))}</option>`).join("");
}

function sourceImageNoiseLabel(mode) {
  if (mode === "none") return "None";
  if (mode === "gaussian") return "Gaussian";
  if (mode === "blur") return "Blur";
  if (mode === "patch_mask") return "Patch mask";
  if (mode === "salt_pepper") return "Salt & pepper";
  return humanizeIdentifier(mode);
}

function representationNoiseOptions(current, profile) {
  return representationNoiseModesForProfile(profile).map((mode) => `<option value="${escapeAttr(mode)}"${mode === current ? " selected" : ""}>${escapeHtml(representationNoiseLabel(mode, profile))}</option>`).join("");
}

function representationNoiseLabel(mode, profile) {
  if (mode === "none") return "None";
  if (profile && profile.form === "latents") {
    if (mode === "gaussian") return "Gaussian";
    if (mode === "dropout") return "Dropout";
  }
  if (mode === "dropout") return "Dropout";
  if (mode === "random_replace") return "Random replace";
  if (mode === "burst") return "Burst";
  return humanizeIdentifier(mode);
}

function textSemanticNoiseOptions(current, options = {}) {
  const maskTokensSupported = options.maskTokensSupported !== false;
  return TEXT_SEMANTIC_NOISE_MODES.map((mode) => {
    const disabled = mode === "mask_words" && !maskTokensSupported;
    const title = disabled ? ' title="Requires a bit-preserving text codec"' : "";
    return `<option value="${escapeAttr(mode)}"${mode === current ? " selected" : ""}${disabled ? " disabled" : ""}${title}>${escapeHtml(textSemanticNoiseLabel(mode))}</option>`;
  }).join("");
}

function textSemanticNoiseLabel(mode) {
  if (mode === "none") return "None";
  if (mode === "drop_words") return "Drop words";
  if (mode === "mask_words") return "Mask words";
  if (mode === "shuffle_words") return "Shuffle words";
  return String(mode || "Noise");
}

function textCodecModeOptions(current) {
  const value = current || "utf8";
  return TEXT_CODEC_MODES.map((mode) => `<option value="${escapeAttr(mode.id)}"${mode.id === value ? " selected" : ""}>${escapeHtml(mode.label)}</option>`).join("");
}

function textExtractorOptions() {
  return '<option value="local_rules" selected>Rule-based keyword extractor</option>';
}

function textGeneratorOptions(current) {
  const value = current || "local_template";
  const supported = TEXT_GENERATOR_MODES.map((mode) => mode.id);
  return [
    unsupportedSavedSelectOption(value, supported),
    ...TEXT_GENERATOR_MODES.map((mode) => `<option value="${escapeAttr(mode.id)}"${mode.id === value ? " selected" : ""}>${escapeHtml(mode.label)}</option>`),
  ].join("");
}

function textReceiverRepairOptions(current, settings = {}) {
  const maskRepairSupported = settings.maskRepairSupported !== false;
  const value = current || "local_template";
  const choices = [
    { id: "local_template", label: "Show decoded text" },
    { id: "masked_lm", label: "Fill [MASK] with masked LM" },
  ];
  return [
    unsupportedSavedSelectOption(value, choices.map((mode) => mode.id)),
    ...choices.map((mode) => {
      const disabled = mode.id === "masked_lm" && !maskRepairSupported;
      const title = disabled ? ' title="Requires a bit-preserving text codec"' : "";
      return `<option value="${escapeAttr(mode.id)}"${mode.id === value ? " selected" : ""}${disabled ? " disabled" : ""}${title}>${escapeHtml(mode.label)}</option>`;
    }),
  ].join("");
}

function unsupportedSavedSelectOption(value, supportedValues) {
  const current = String(value || "");
  if (!current || supportedValues.includes(current)) return "";
  return `<option value="${escapeAttr(current)}" selected disabled>Unsupported saved value: ${escapeHtml(current)} — choose a supported option</option>`;
}

function textKnowledgeBaseOptions(current) {
  const options = [
    { id: "semantic_text_smoke_kb", label: "Built-in text facts" },
    { id: "empty", label: "No grounding facts" },
    { id: "inline_json", label: "Custom facts JSON" },
  ];
  return options.map((item) => `<option value="${escapeAttr(item.id)}"${item.id === current ? " selected" : ""}>${escapeHtml(item.label)}</option>`).join("");
}

function textGeneratorHint(generator) {
  if (generator === "kb_reconstruct") {
    return "Ranks knowledge-base text by token overlap with the received semantic evidence and selects the strongest match; if none matches, the normal received-text or concept fallback applies.";
  }
  if (generator === "masked_lm") {
    return 'Uses a small Transformers fill-mask model to replace mask tokens in the carried received text. Install with python -m pip install "noema-lab[textgen]" in an installed environment, or uv sync --extra textgen in a source checkout.';
  }
  return "Renders the received carried text when available; sender mask tokens remain visible.";
}

function textCodecRepresentationLabel(config) {
  if (config && config.codec && config.codec.mode === "neural_jscc") return "semantic symbols";
  return config && config.codec && config.codec.mode === "semantic_state" ? "structured text state" : "raw text";
}

function textCodecFormatLabel(config) {
  if (config && config.codec && config.codec.mode === "neural_jscc") return "BART hidden state -> complex64";
  return config && config.codec && config.codec.mode === "semantic_state" ? "JSON state -> bits" : "UTF-8 JSON -> bits";
}

function channelCodingOptions(current) {
  return Object.entries(CHANNEL_CODING_PROFILES)
    .map(([id, profile]) => `<option value="${escapeAttr(id)}"${id === current ? " selected" : ""}>${escapeHtml(profile.label)}</option>`)
    .join("");
}

function channelModeOptions(current) {
  return CHANNEL_MODES.map((mode) => `<option value="${escapeAttr(mode)}"${mode === current ? " selected" : ""}>${escapeHtml(channelModeLabel(mode))}</option>`).join("");
}

function channelModeIsBitBypass(mode) {
  return String(mode || "skip") === "skip";
}

function channelModeIsIdentityPhy(mode) {
  return String(mode || "") === "identity_phy";
}

function physicalChannelEnabled(mode) {
  const value = String(mode || "skip");
  return value !== "skip" && value !== "identity_phy";
}

function channelDisabledModeLabel(mode) {
  return channelModeIsIdentityPhy(mode) ? "identity_phy" : "bit_perfect_bypass";
}

function channelDisabledModeText(mode) {
  return channelModeIsIdentityPhy(mode) ? "identity PHY" : "bit-perfect bypass";
}

function channelDisabledSettingsHint(mode) {
  if (channelModeIsIdentityPhy(mode)) {
    return "Identity PHY: null modulator, identity symbol channel, null demodulator.";
  }
  return "Bit-perfect bypass: lossless direct bit path.";
}

function wirelessBackendOptions(current) {
  const value = current || "auto";
  return WIRELESS_BACKENDS.map((backend) => `<option value="${escapeAttr(backend)}"${backend === value ? " selected" : ""}>${escapeHtml(wirelessBackendLabel(backend))}</option>`).join("");
}

function dataPlaneBackendOptions(config) {
  const current = dataPlaneBackendFromConfig(config);
  return DATA_PLANE_BACKENDS.map((backend) => (
    `<option value="${escapeAttr(backend)}"${backend === current ? " selected" : ""}>${escapeHtml(dataPlaneBackendLabel(backend))}</option>`
  )).join("");
}

function dataPlaneBackendLabel(backend) {
  return {
    auto: "Auto",
    python_numpy: "Python / NumPy",
    cpp_native: "Native C++",
  }[backend] || String(backend || "auto");
}

function modulationOptions(current, includeEmpty = false) {
  const empty = includeEmpty ? '<option value="" selected></option>' : "";
  return empty + MODULATION_MODES.map((mode) => `<option value="${escapeAttr(mode)}"${mode === current ? " selected" : ""}>${escapeHtml(mode)}</option>`).join("");
}

function channelModeLabel(mode) {
  return {
    skip: "Bit-perfect bypass",
    identity_phy: "Identity PHY",
    awgn: "AWGN",
    flat_rayleigh: "Flat Rayleigh",
    interference_awgn: "Interference + AWGN",
    mimo_flat: "Flat MIMO",
    ofdm_tdl: "OFDM TDL",
    ofdm_cdl: "OFDM CDL",
    urban_micro: "Urban Micro",
  }[mode] || String(mode || "");
}

function wirelessBackendLabel(backend) {
  return {
    auto: "Auto",
    numpy: "NumPy",
    sionna: "Sionna",
  }[backend] || String(backend || "auto");
}

function runtimeOptions(current, profile) {
  const value = current || "auto";
  const supported = codecSupportedRunners(profile);
  const orderedSupported = uniqueStrings([
    ...KNOWN_CODEC_RUNTIME_OPTIONS.filter((mode) => supported.includes(mode)),
    ...supported,
    ...codecVisibleUnsupportedRunners(profile),
  ]);
  const modes = orderedSupported.includes(value)
    ? orderedSupported
    : uniqueStrings([value, ...orderedSupported.filter((mode) => mode !== value)]);
  return modes
    .map((mode) => {
      const supportedMode = supported.includes(mode);
      const selected = mode === value ? " selected" : "";
      const disabled = supportedMode || selectableUnsupportedRunner(mode, profile) ? "" : " disabled";
      const suffix = supportedMode ? "" : " (no adapter)";
      return `<option value="${escapeAttr(mode)}"${selected}${disabled}>${escapeHtml(runtimeLabel(mode) + suffix)}</option>`;
    })
    .join("");
}

function codecRuntimeRow(config, profile) {
  const runner = actualCodecRunner(profile, config);
  const support = codecRunnerSupport(profile, runner);
  const locked = Boolean(profile && profile.runnerLocked);
  const supportBadge =
    !locked && runner && runner !== "auto" && !support.supported
      ? '<span class="inline-badge warning">no adapter</span>'
      : "";
  return `
    <div class="compact-control-row codec-runtime-row">
      <label class="compact-field runtime-field">
        <span>Runner</span>
        <select data-config="metrics.codecRunner"${locked ? " disabled" : ""}>${runtimeOptions(runner, profile)}</select>
      </label>
      ${supportBadge}
    </div>
  `;
}

function normalizeCodecRunnerValue(profile, config) {
  if (profile && profile.runnerLocked) return "auto";
  const raw = config && config.metrics ? config.metrics.codecRunner : "";
  return actualCodecRunner(profile, { metrics: { codecRunner: firstCodecRunnerValue(raw) } });
}

function firstCodecRunnerValue(value) {
  return parseCategoricalSweepValues(value)[0] || String(value || "").trim() || "auto";
}

function actualCodecRunner(profile, config = null) {
  if (profile && profile.runnerLocked) return "auto";
  const requested = config && config.metrics ? firstCodecRunnerValue(config.metrics.codecRunner) : "";
  if (requested && requested !== "auto") return requested;
  if (profile && profile.runtime) return profile.runtime;
  return profile && profile.external ? "local_python" : "auto";
}

function executionCodecRunner(profile, config = null) {
  const selected = actualCodecRunner(profile, config);
  if (!selected || selected === "auto") return nativeCodecRunner(profile);
  if (codecRunnerSupport(profile, selected).supported) return selected;
  return nativeCodecRunner(profile);
}

function nativeCodecRunner(profile) {
  if (!profile) return "local_python";
  if (profile.nativeRuntime) return profile.nativeRuntime;
  if (profile.runtime) return profile.runtime;
  return profile.external ? "local_python" : "auto";
}

function runtimeAdapters(profile) {
  return (profile && profile.runtimeAdapters) || {};
}

function codecRunnerSupport(profile, runner) {
  const selected = runner || "auto";
  if (!profile) return { supported: selected === "auto", native: "auto", adapter: null };
  const native = nativeCodecRunner(profile);
  if (!selected || selected === "auto") return { supported: true, native, adapter: null };
  if (selected === native) return { supported: true, native, adapter: null };
  const adapter = runtimeAdapters(profile)[selected] || null;
  if (adapter) return { supported: true, native, adapter };
  return {
    supported: false,
    native,
    adapter: null,
    reason: runtimeCompatibilityReason(profile, selected),
  };
}

function runtimeCompatibilityReason(profile, selected) {
  if (selected === "onnxruntime_cpp") {
    return (
      `ONNX Runtime C++ API is a separate runner from the existing ONNX Runtime Python API path. ` +
      `${profile.label} has ONNX export/Python-binding adapters, but no registered C++ API encoder, decoder, and payload adapter yet.`
    );
  }
  if (selected === "libtorch") {
    return `LibTorch C++ is the PyTorch C++ frontend/runtime path, but ${profile.label} does not yet have a registered LibTorch export plus C++ encoder/decoder adapter. Add that adapter before running this codec on LibTorch C++.`;
  }
  if (selected === "torchscript") {
    return `TorchScript is a JIT/serialized model artifact target, not the same thing as the LibTorch C++ execution path here. ${profile.label} does not yet have a registered TorchScript adapter.`;
  }
  if (selected === "aot_inductor") {
    return `AOT Inductor needs a registered torch.export/Inductor compile step plus runtime-specific encoder, decoder, and entropy/payload adapter for ${profile.label}. That adapter is not implemented yet.`;
  }
  return `${runtimeLabel(selected)} is not registered for ${profile.label}. Add a conversion step plus runtime-specific encoder, decoder, and entropy/payload adapter before running this codec on ${runtimeLabel(selected)}.`;
}

function codecSupportedRunners(profile) {
  if (!profile) return ["auto"];
  if (profile.runnerLocked) return ["auto"];
  return uniqueStrings(["auto", nativeCodecRunner(profile), ...Object.keys(runtimeAdapters(profile))]).filter(Boolean);
}

function codecVisibleUnsupportedRunners(profile) {
  if (!profile || profile.runnerLocked) return [];
  return runtimeAdapters(profile).onnxruntime ? ["onnxruntime_cpp"] : [];
}

function selectableUnsupportedRunner(mode, profile) {
  return mode === "onnxruntime_cpp" && codecVisibleUnsupportedRunners(profile).includes(mode);
}

function uniqueStrings(values) {
  const seen = new Set();
  const next = [];
  (values || []).forEach((value) => {
    const item = String(value || "").trim();
    if (!item || seen.has(item)) return;
    seen.add(item);
    next.push(item);
  });
  return next;
}

function runtimeLabel(value) {
  return {
    auto: "Auto",
    local_python: "Local Python",
    pytorch: "PyTorch",
    onnxruntime: "ONNX Runtime (Python API)",
    onnxruntime_cpp: "ONNX Runtime C++ API",
    openvino: "OpenVINO",
    torchscript: "TorchScript JIT",
    aot_inductor: "AOT Inductor",
    libtorch: "LibTorch C++",
  }[value] || String(value || "auto");
}

function compactRuntimeRecipeLabel(value) {
  return {
    auto: "Auto",
    local_python: "Python",
    pytorch: "PyTorch",
    onnxruntime: "ONNX",
    onnxruntime_cpp: "ONNX C++",
    openvino: "OpenVINO",
    torchscript: "TorchScript",
    aot_inductor: "AOTI",
    libtorch: "LibTorch",
  }[value] || runtimeLabel(value);
}

function onnxProviderLabel(value) {
  return `provider ${String(value || "").replace(/ExecutionProvider$/, "") || "default"}`;
}

function firstTruthy(values) {
  return (values || []).find((value) => value !== undefined && value !== null && String(value).trim() !== "") || "";
}

function codecRepresentationLabel(profile) {
  return {
    bits: "bits",
    indices: "indices",
    latents: "latents",
    symbols: "symbols",
  }[profile.form] || String(profile.form || "payload");
}

function codecFormatLabel(profile, config) {
  if (!profile) return "adapter";
  if (profile.format) return profile.format;
  if (profile.external) return "python";
  if (profile.id === "compressai") return "*.pt";
  if (profile.id === "jpeg") return "*.jpg";
  if (profile.id === "diffusers_autoencoderkl" || profile.id === "diffusers_vqmodel") return "hf/*.safetensors";
  const runner = config && config.metrics ? firstCodecRunnerValue(config.metrics.codecRunner) : "";
  return runner && runner !== "auto" ? runtimeLabel(runner) : "adapter";
}

function codecProfileSettingsSummary(profile) {
  if (!profile) return "";
  const runnerLabels = codecSupportedRunners(profile)
    .filter((runner) => runner !== "auto")
    .map(runtimeLabel)
    .join(", ");
  const rows = [
    `${codecRepresentationLabel(profile)} output - ${profile.format || codecFormatLabel(profile, null)} - ${runtimeLabel(profile.runtime || "auto")}`,
  ];
  if (runnerLabels) rows.push(`Runners: ${runnerLabels}`);
  if (profile.upstreamSetup) rows.push(profile.upstreamSetup);
  if (profile.compressionNote) rows.push(profile.compressionNote);
  if (profile.adapterNote) rows.push(profile.adapterNote);
  return rows.map((row) => `<div class="field-hint">${escapeHtml(row)}</div>`).join("");
}

function externalAdapterCatalogHint() {
  return '<div class="field-hint">Use this for a private codec or a paper implementation that is not registered here yet. The adapter must provide Python callables matching the selected output contract. LALIC belongs here until a public implementation/checkpoint is available.</div>';
}

function operationSchema(operationId) {
  return (operationById(operationId) || {}).params_schema || { properties: {}, additionalProperties: false };
}

function inferCodecProfile(steps) {
  const sender = stepById(steps, "sender") || {};
  if (sender.op === "model.text_utf8_encode") {
    return textUtf8CodecProfile();
  }
  if (sender.op === "model.text_bart_jscc_encode") {
    return textBartJsccCodecProfile();
  }
  if (sender.op === "foundation.semantic_state_payload_encode" || findStepByOpIn(steps, "foundation.text_semantic_state_encode")) {
    return semanticStateCodecProfile();
  }
  if (sender.op === "model.compressai_onnx_encode") {
    return codecProfile("compressai", { metrics: { codecRunner: "onnxruntime" } });
  }
  if (sender.op === "model.compressai_onnx_cpp_encode") {
    return codecProfile("compressai", { metrics: { codecRunner: "onnxruntime_cpp" } });
  }
  if (sender.op === "model.compressai_aoti_encode") {
    return codecProfile("compressai", { metrics: { codecRunner: "aot_inductor" } });
  }
  if (sender.op === "model.compressai_openvino_encode") {
    return codecProfile("compressai", { metrics: { codecRunner: "openvino" } });
  }
  if (sender.op === "model.evc_onnx_encode") {
    return codecProfile("evc", { metrics: { codecRunner: "onnxruntime" } });
  }
  if (sender.op === "model.eflic_onnx_encode" || sender.op === "model.eflic_onnx_encode_indices") {
    return codecProfile("eflic", { metrics: { codecRunner: "onnxruntime" } });
  }
  if (sender.op === "model.eflic_aoti_encode" || sender.op === "model.eflic_aoti_encode_indices") {
    return codecProfile("eflic", { metrics: { codecRunner: "aot_inductor" } });
  }
  if (sender.op === "model.eflic_openvino_encode" || sender.op === "model.eflic_openvino_encode_indices") {
    return codecProfile("eflic", { metrics: { codecRunner: "openvino" } });
  }
  const ops = new Set((steps || []).map((step) => step.op));
  if (ops.has("foundation.vqa_transformers_answer")) return taskCodecProfile("pretrained_vqa");
  if (ops.has("foundation.vqa_payload_encode") || ops.has("foundation.vqa_answer_from_packet")) return taskCodecProfile("vqa_semantic_packet");
  if (ops.has("foundation.clip_retrieval_rank")) return taskCodecProfile("clip_retrieval");
  if (ops.has("foundation.yolo_segment")) return taskCodecProfile("yolo_segmentation");
  if (ops.has("foundation.yolo_detect")) return taskCodecProfile("yolo_detection");
  if (ops.has("foundation.diffusion_state_to_image")) return taskCodecProfile("semantic_state_diffusion");
  const externalRepresentation = externalRepresentationForOperation(sender.op);
  if (externalRepresentation) return externalCodecProfile(externalRepresentation);
  const byEncoder = CODEC_PROFILES.find((profile) => profile.encoder === sender.op);
  if (byEncoder) return byEncoder;
  const foundExternal = Object.entries(EXTERNAL_REPRESENTATIONS).find(([_id, representation]) =>
    findStepByOpIn(steps, representation.encoder)
  );
  if (foundExternal) return externalCodecProfile(foundExternal[0]);
  const found = CODEC_PROFILES.find((profile) => findStepByOpIn(steps, profile.encoder));
  return found || CODEC_PROFILES[0];
}

function codecProfileFromMetadata(metadata) {
  const profileId = metadata && metadata.codec_profile ? String(metadata.codec_profile) : "";
  if (!profileId) return null;
  if (profileId === "text_utf8") return textUtf8CodecProfile();
  if (profileId === "text_bart_jscc") return textBartJsccCodecProfile();
  if (profileId === "semantic_state") return semanticStateCodecProfile();
  const taskProfile = taskCodecProfile(profileId);
  if (taskProfile) return taskProfile;
  const timing = metadata.codec_timing || {};
  const profile = codecProfile(profileId, {
    external: { representation: metadata.external_representation || "bits" },
    metrics: { codecRunner: timing.requested_runner || timing.runner },
  });
  return profile && profile.id === profileId ? profile : null;
}

function taskCodecProfile(profileId) {
  const profiles = {
    pretrained_vqa: {
      id: "pretrained_vqa",
      label: "Pretrained VQA receiver",
      runtime: "pytorch",
      format: "hf/transformers-vqa",
      form: "answers",
      pipeline: "answers",
      runnerLocked: true,
    },
    vqa_semantic_packet: {
      id: "vqa_semantic_packet",
      label: "VQA semantic packet payload",
      runtime: "local_python",
      format: "json_utf8",
      form: "bits",
      pipeline: "bits",
      runnerLocked: true,
    },
    clip_retrieval: {
      id: "clip_retrieval",
      label: "CLIP retrieval receiver",
      runtime: "pytorch",
      format: "hf/clip",
      form: "rankings",
      pipeline: "rankings",
      runnerLocked: true,
    },
    yolo_detection: {
      id: "yolo_detection",
      label: "YOLO object detector",
      runtime: "pytorch",
      format: "*.pt",
      form: "detections",
      pipeline: "detections",
      runnerLocked: true,
    },
    yolo_segmentation: {
      id: "yolo_segmentation",
      label: "YOLO instance segmenter",
      runtime: "pytorch",
      format: "*.pt",
      form: "segmentation_mask",
      pipeline: "segmentation_mask",
      runnerLocked: true,
    },
    semantic_state_diffusion: {
      id: "semantic_state_diffusion",
      label: "SemanticState plus diffusion receiver",
      runtime: "pytorch",
      format: "semantic_state_json_utf8 + diffusers",
      form: "generated_images",
      pipeline: "bits",
      runnerLocked: true,
    },
  };
  return profiles[String(profileId || "")] || null;
}

function textUtf8CodecProfile() {
  return {
    id: "text_utf8",
    label: "Raw text bytes (UTF-8)",
    runtime: "local_python",
    format: "json_utf8",
    form: "bits",
    pipeline: "bits",
    runnerLocked: true,
  };
}

function textBartJsccCodecProfile() {
  return {
    id: "text_bart_jscc",
    label: "BART JSCC-lite semantic symbols",
    runtime: "pytorch",
    format: "facebook/bart-base",
    form: "symbols",
    pipeline: "symbols",
    encoder: "model.text_bart_jscc_encode",
    decoder: "model.text_bart_jscc_decode",
    encoderOutput: "symbols",
    decoderInput: "symbols",
    runnerLocked: true,
  };
}

function semanticStateCodecProfile() {
  return {
    id: "semantic_state",
    label: "SemanticState JSON payload",
    runtime: "local_python",
    format: "semantic_state_json_utf8",
    form: "bits",
    pipeline: "bits",
    runnerLocked: true,
  };
}

function codecProfile(id, config = null) {
  if (id === "external") {
    const representation = (config && config.external && config.external.representation) || "bits";
    return externalCodecProfile(representation);
  }
  const legacyExternal = legacyExternalProfile(id);
  if (legacyExternal) return externalCodecProfile(legacyExternal);
  const base = CODEC_PROFILES.find((profile) => profile.id === id) || CODEC_PROFILES[0];
  const runner = config && config.metrics ? firstCodecRunnerValue(config.metrics.codecRunner) : "auto";
  const adapter = runtimeAdapters(base)[runner];
  if (adapter) return { ...base, nativeRuntime: nativeCodecRunner(base), ...adapter, runtimeAdapters: base.runtimeAdapters || {} };
  return base;
}

function externalCodecProfile(representation) {
  const id = EXTERNAL_REPRESENTATIONS[representation] ? representation : "bits";
  return {
    id: "external",
    label: "Custom external codec",
    external: true,
    externalRepresentation: id,
    ...EXTERNAL_REPRESENTATIONS[id],
  };
}

function externalRepresentationForOperation(op) {
  const found = Object.entries(EXTERNAL_REPRESENTATIONS).find(([_id, representation]) => representation.encoder === op || representation.decoder === op);
  return found ? found[0] : "";
}

function legacyExternalProfile(id) {
  return {
    external_bits: "bits",
    external_indices: "indices",
    external_latents: "latents",
    external_deepjscc: "symbols",
  }[id] || "";
}

function stepById(steps, id) {
  return (steps || []).find((step) => step.id === id) || null;
}

function findStepByOpIn(steps, op) {
  if (!op) return null;
  return (steps || []).find((step) => step.op === op) || null;
}

function setDeep(target, path, value) {
  const parts = String(path).split(".");
  let cursor = target;
  parts.slice(0, -1).forEach((part) => {
    if (!cursor[part] || typeof cursor[part] !== "object") cursor[part] = {};
    cursor = cursor[part];
  });
  cursor[parts[parts.length - 1]] = value;
}

function getDeep(target, path) {
  return String(path)
    .split(".")
    .reduce((cursor, part) => (cursor && Object.prototype.hasOwnProperty.call(cursor, part) ? cursor[part] : undefined), target);
}

function numberOr(value, fallback) {
  const parsed = parseFloat(value);
  return Number.isFinite(parsed) ? parsed : fallback;
}

function integerOr(value, fallback) {
  const parsed = parseInt(value, 10);
  return Number.isFinite(parsed) ? parsed : fallback;
}

function firstInteger(values, fallback) {
  for (const value of values) {
    const parsed = parseInt(value, 10);
    if (Number.isFinite(parsed)) return parsed;
  }
  return fallback;
}

function firstDefined(values, fallback) {
  for (const value of values || []) {
    if (value !== undefined && value !== null && String(value).trim() !== "") return value;
  }
  return fallback;
}

function experimentSeed(config) {
  return Math.max(0, integerOr(config && config.seed, 23));
}

function derivedSeed(baseSeed, label) {
  let hash = 2166136261;
  const text = `${String(label)}:${String(Math.max(0, integerOr(baseSeed, 23)))}`;
  for (let index = 0; index < text.length; index += 1) {
    hash ^= text.charCodeAt(index);
    hash = Math.imul(hash, 16777619);
  }
  return hash >>> 0;
}

function graphFromRecipePayload(recipe) {
  const nodes = (recipe.steps || []).map((step) => {
    const operation = operationById(step.op) || {};
    return {
      id: step.id,
      op: step.op,
      name: operation.name || step.op,
      status: operationAvailable(operation) ? operation.status || "implemented" : "unavailable",
      inputs: operationInputKinds(operation),
      optional_inputs: Object.keys(operation.optional_input_kinds || {}),
      outputs: operation.output_kinds || {},
      params: step.params || {},
      entropyInfo: operation.entropy_info || null,
      differentiability: operation.differentiability || null,
      training_capabilities: operation.training_capabilities || {},
      fine_tuning_supported: Boolean(operation.training_capabilities && operation.training_capabilities.built_in_fine_tuning),
      replacement_ready: Boolean(operation.training_capabilities && operation.training_capabilities.portable_replacement),
      backends: operation.backends || {},
      equivalence: operation.equivalence || {},
      formats: operation.formats || {},
      materializations: operation.materializations || [],
      runner_support: operation.runner_support || runnerSupportFromOperation(operation),
    };
  });
  const edges = [];
  (recipe.steps || []).forEach((step) => {
    Object.entries(step.inputs || {}).forEach(([inputName, reference]) => {
      const parts = String(reference).split(".");
      if (parts.length !== 2) return;
      edges.push({
        from_step: parts[0],
        from_output: parts[1],
        to_step: step.id,
        to_input: inputName,
      });
    });
  });
  return { schema_version: 1, recipe: recipe.name, nodes, edges };
}

function runnerSupportFromOperation(operation) {
  const opId = operation && operation.id ? String(operation.id) : "operation";
  const opName = operation && operation.name ? String(operation.name) : opId;
  const diff = (operation && operation.differentiability) || {};
  const materializations = Array.isArray(operation && operation.materializations) ? operation.materializations : [];
  const contracts = {
    benchmark_run: { label: "Benchmark Run", path: "artifact/evidence path" },
    dataset_capture: { label: "Dataset Capture", path: "artifact dataset path" },
    differentiable_export: { label: "Differentiable Export", path: "differentiable module path" },
  };
  const support = {};
  Object.entries(contracts).forEach(([runner, contract]) => {
    const runnerMaterializations = materializations.filter((item) => String(item.runner || "") === runner);
    const implemented = runnerMaterializations.filter((item) => String(item.status || "implemented") === "implemented");
    let supported = implemented.length > 0;
    let reason = "";
    if (!runnerMaterializations.length) reason = `No ${contract.label} materialization is declared for \`${opId}\`.`;
    else if (!implemented.length) reason = `No implemented ${contract.label} materialization is declared for \`${opId}\`.`;
    if (runner === "differentiable_export" && supported) {
      const gradient = String(diff.gradient || "none");
      if (gradient !== "full" && gradient !== "surrogate") {
        supported = false;
        reason = `${opName} is a gradient break for differentiable export: ${diff.reason || `gradient is \`${gradient}\``}`;
      } else if (!diff.exportable) {
        supported = false;
        reason = `${opName} is not exportable to the training graph: ${diff.reason || "operation is not exportable"}`;
      }
    }
    if (supported && !reason) {
      const backends = Array.from(new Set(implemented.map((item) => String(item.backend || "backend")))).sort();
      reason = `${contract.label} can use \`${opId}\` through ${backends.join(", ")}.`;
    }
    support[runner] = {
      runner,
      label: contract.label,
      path: contract.path,
      supported,
      reason,
      materializations: runnerMaterializations,
      implemented_materializations: implemented,
    };
  });
  return support;
}

async function runAllRecipes() {
  if (!state.recipes.length || state.batchRunning) return;
  let completed = 0;
  let failed = 0;
  let stopped = 0;
  try {
    syncSelectedRecipeFromEditor();
    state.resultSource = "current";
    state.selectedBenchmarkResultId = "";
    state.selectedRunId = "";
    state.activeBenchmarkResult = null;
    state.resultFacet = "overview";
    state.batchRunning = true;
    state.batchStopping = false;
    state.hasRunLog = true;
    state.runJobs = {};
    state.activeJobIds = {};
    state.recipes.forEach((recipe) => {
      recipe.lastRunId = null;
      recipe.lastRunIds = [];
      recipe.resultDirty = true;
      recipe.transientStatus = null;
      recipe.lastError = null;
      recipe.activityProgress = null;
      recipe.sweepProgress = null;
      setLocalRecipeJob(recipe, "queued", "Waiting to start", "info");
    });
    setBusy(true);
    renderRunControls();
    renderRunLog();
    renderRecipes();
    if (state.graph) renderGraph(state.graph);
    renderResultsDashboard(emptyCurrentRecipeResultRows());
    for (const recipe of state.recipes) {
      if (state.batchStopping) break;
      const status = await runRecipeJob(recipe);
      if (status === "completed") completed += 1;
      else if (status === "canceled") {
        stopped += 1;
        break;
      } else if (status === "resource_exhausted") {
        failed += 1;
        break;
      } else if (status === "timed_out") {
        failed += 1;
        break;
      } else failed += 1;
    }
    // attachRunSummary already adds every run produced by this batch. Rescan the
    // complete history only when the user previously opened and loaded history.
    if (runHistoryLoaded && runHistoryGeneration === startupLoadGeneration) {
      await loadDeferredRuns(startupLoadGeneration);
    }
    state.runningRecipeKey = null;
    await loadAllRecipeResults(true);
    notify(runAllSummary(completed, failed, stopped));
  } catch (error) {
    const message = error && error.message ? error.message : String(error || "Run All failed");
    markRunAllStartupError(message);
    notify(message);
  } finally {
    state.batchRunning = false;
    state.batchStopping = false;
    state.runningRecipeKey = null;
    state.activeJobIds = {};
    setBusy(false);
    renderRunControls();
    renderRunLog();
    renderRecipes();
    if (state.graph) renderGraph(state.graph);
  }
}

function emptyCurrentRecipeResultRows() {
  return (state.recipes || []).map((recipe) => ({
    recipe,
    runs: [],
    summaries: [],
    summary: null,
  }));
}

function markRunAllStartupError(message) {
  const text = `Run All could not start: ${message}`;
  (state.recipes || []).forEach((recipe) => {
    const job = state.runJobs[recipe.key];
    if (!job || !Array.isArray(job.events) || !job.events.some((event) => String(event.message || "") === text)) {
      setLocalRecipeJob(recipe, "failed", text, "error");
    }
  });
  renderRunLog();
}

async function runRecipeJob(recipe) {
  try {
    await ensureRecipePayload(recipe);
    if (!recipeUsesUiConfigurator(recipe.recipe) || recipePreservesWorkingTopology(recipe.recipe)) {
      recipe.recipe = structuredCloneFallback(recipe.recipe);
    } else if (isTextSemanticRecipe(recipe.recipe)) {
      const config = textRecipeConfigFromRecipe(recipe.recipe);
      normalizeTextRecipeConfig(config);
      recipe.recipe = buildTextRecipeFromConfig(config, recipe.recipe);
    } else if (isTaskBuilderRecipe(recipe.recipe)) {
      const config = taskRecipeConfigFromRecipe(recipe.recipe);
      recipe.recipe = buildTaskRecipeFromConfig(config, recipe.recipe);
    } else {
      const config = recipeConfigFromRecipe(recipe.recipe);
      normalizeRecipeConfig(config);
      recipe.recipe = buildRecipeFromConfig(config, recipe.recipe);
    }
    stripRecipeWorkingStateMetadata(recipe.recipe);
    recipe.name = recipe.recipe.name || recipe.name;
    recipe.step_count = (recipe.recipe.steps || []).length;
    const issues = recipeConfigurationIssues(recipe.recipe);
    if (issues.length) {
      throw new Error(issues[0]);
    }
  } catch (error) {
    recipe.transientStatus = "failed";
    recipe.lastError = error.message;
    recipe.resultDirty = true;
    setLocalRecipeJob(recipe, "failed", `Could not prepare recipe: ${error.message}`, "error");
    renderRecipes();
    renderRunLog();
    return "failed";
  }

  let variants;
  try {
    variants = await recipeRunVariants(recipe);
    if (!Array.isArray(variants) || !variants.length) {
      throw new Error("matrix expansion returned no runnable variants");
    }
  } catch (error) {
    const message = error && error.message ? error.message : String(error || "matrix expansion failed");
    recipe.transientStatus = "failed";
    recipe.lastError = message;
    recipe.resultDirty = true;
    setLocalRecipeJob(recipe, "failed", `Could not expand recipe matrix: ${message}`, "error");
    renderRecipes();
    renderRunLog();
    return "failed";
  }
  recipe.lastRunId = null;
  recipe.lastRunIds = [];
  recipe.sweepProgress = {
    total: variants.length,
    completed: 0,
    currentIndex: 0,
    currentLabel: variants[0] ? variants[0].label : "default",
    currentFraction: 0,
    status: "running",
  };
  recipe.transientStatus = "running";
  state.runningRecipeKey = recipe.key;
  await focusRecipeInGraphForRun(recipe);
  renderRecipes();
  if (state.graph) renderGraph(state.graph);
  renderRunLog();

  let finalStatus = "completed";
  for (let variantIndex = 0; variantIndex < variants.length; variantIndex += 1) {
    const variant = variants[variantIndex];
    if (state.batchStopping) {
      finalStatus = "canceled";
      break;
    }
    updateRecipeSweepProgress(recipe, {
      currentIndex: variantIndex,
      currentLabel: variant.label,
      currentFraction: 0,
      status: "running",
    });
    appendLocalRecipeLog(recipe, `Starting ${variant.label}`, "info");
    let job;
    try {
      job = await runSingleRecipeVariant(recipe, variant);
    } catch (error) {
      finalStatus = "failed";
      recipe.transientStatus = "failed";
      recipe.lastError = error.message;
      const prefix = error.jobStarted ? `Lost connection during ${variant.label}` : `Failed to start ${variant.label}`;
      appendLocalRecipeLog(recipe, `${prefix}: ${error.message}`, "error");
      renderRecipes();
      if (state.graph) renderGraph(state.graph);
      renderRunLog();
      break;
    }
    if (job.run_id) {
      recipe.lastRunId = job.run_id;
      recipe.lastRunIds = [...(recipe.lastRunIds || []), job.run_id];
      await loadAllRecipeResults(false);
    }
    if (job.status === "canceled") {
      updateRecipeSweepProgress(recipe, { currentFraction: jobVariantProgressFraction(recipe, job), status: "stopped" });
      finalStatus = "canceled";
      break;
    }
    if (job.status === "resource_exhausted") {
      updateRecipeSweepProgress(recipe, { currentFraction: jobVariantProgressFraction(recipe, job), status: "failed" });
      finalStatus = "resource_exhausted";
      break;
    }
    if (job.status === "timed_out") {
      updateRecipeSweepProgress(recipe, { currentFraction: jobVariantProgressFraction(recipe, job), status: "failed" });
      finalStatus = "timed_out";
      break;
    }
    if (job.status !== "completed") {
      updateRecipeSweepProgress(recipe, { currentFraction: jobVariantProgressFraction(recipe, job), status: "failed" });
      finalStatus = "failed";
      break;
    } else {
      updateRecipeSweepProgress(recipe, { completed: variantIndex + 1, currentFraction: 0, status: "running" });
    }
  }

  delete state.activeJobIds[recipe.key];
  recipe.resultDirty = false;
  if (finalStatus === "completed") {
    recipe.transientStatus = null;
    updateRecipeSweepProgress(recipe, { completed: variants.length, currentFraction: 0, status: "completed" });
  } else if (finalStatus === "canceled") {
    recipe.transientStatus = "stopped";
    recipe.lastError = "Stopped";
    updateRecipeSweepProgress(recipe, { status: "stopped" });
  } else {
    recipe.transientStatus = "failed";
    recipe.lastError = recipe.lastError || "Run failed";
    updateRecipeSweepProgress(recipe, { status: "failed" });
  }
  state.runningRecipeKey = null;
  await loadAllRecipeResults(false);
  renderRecipes();
  if (state.graph) renderGraph(state.graph);
  renderRunLog();
  return finalStatus;
}

async function runSingleRecipeVariant(recipe, variant) {
  let job = await api("/api/run-jobs", {
    method: "POST",
    body: JSON.stringify({
      recipe: variant.recipe,
      execution: executionRequestOptions(),
    }),
  });
  job.variant_label = variant.label;
  updateRecipeJob(recipe, job);
  let cancelRequested = false;
  while (!isTerminalJobStatus(job.status) || job.events_truncated === true) {
    if (state.batchStopping && !cancelRequested) {
      const recordedJob = state.runJobs[recipe.key] || {};
      if (recordedJob.cancel_requested) {
        cancelRequested = true;
      } else {
        job = await cancelRecipeJob(recipe, job.job_id);
        cancelRequested = true;
      }
    }
    if (!isTerminalJobStatus(job.status)) await sleep(550);
    job = await pollRunJobWithRetry(recipe, job, variant);
    job.variant_label = variant.label;
    updateRecipeJob(recipe, job);
    if (job.run_id) {
      await attachRunSummary(job.run_id, job.status, variant.recipe.name);
    }
  }
  if (job.run_id) {
    const summary = await attachRunSummary(job.run_id, job.status, variant.recipe.name);
    if (summary) {
      state.runSummaries[job.run_id] = summary;
    }
  }
  if (job.status !== "completed") {
    recipe.lastError = job.error || `${variant.label} failed`;
  }
  return job;
}

async function pollRunJobWithRetry(recipe, job, variant) {
  const maxAttempts = 20;
  let attempt = 0;
  while (attempt < maxAttempts) {
    try {
      const recorded = state.runJobs[recipe.key] || job;
      const afterSeq = runJobEventCursor(recorded);
      const query = `after_seq=${encodeURIComponent(afterSeq)}&event_limit=${encodeURIComponent(RUN_JOB_EVENT_REQUEST_LIMIT)}`;
      return await api(`/api/run-jobs/${encodeURIComponent(job.job_id)}?${query}`);
    } catch (error) {
      attempt += 1;
      const seconds = Math.min(1 + attempt, 6);
      if (attempt === 1 || attempt % 5 === 0) {
        appendLocalRecipeLog(
          recipe,
          `Polling lost contact during ${variant.label}; retry ${attempt}/${maxAttempts}: ${error.message}`,
          "warning"
        );
        renderRunLog();
      }
      if (attempt >= maxAttempts) {
        const wrapped = new Error(`UI server polling failed while job was running: ${error.message}`);
        wrapped.jobStarted = true;
        wrapped.job_id = job.job_id;
        wrapped.run_id = job.run_id;
        throw wrapped;
      }
      await sleep(seconds * 1000);
    }
  }
  const wrapped = new Error("UI server polling failed while job was running");
  wrapped.jobStarted = true;
  throw wrapped;
}

async function recipeRunVariants(recipe) {
  const base = structuredCloneFallback(recipe.recipe);
  if (!recipeHasSweepDefinition(base)) {
    return [{ recipe: base, label: "default", value: null, sweep: null }];
  }
  const expanded = await api("/api/recipe/matrix/expand", {
    method: "POST",
    body: JSON.stringify({ recipe: base }),
  });
  return (expanded.recipes || []).map((payload, index) => {
    const variantRecipe = structuredCloneFallback(payload);
    const selection = (variantRecipe.metadata && variantRecipe.metadata.matrix_selection) || {};
    const combo = Object.entries(selection).map(([path, value]) => ({ path, value }));
    return {
      recipe: variantRecipe,
      label: canonicalMatrixVariantIdentityLabel(variantRecipe, index),
      value: combo.length === 1 ? combo[0].value : Object.fromEntries(combo.map((item) => [item.path, item.value])),
      sweep: combo,
    };
  });
}

function sweepPathLabel(path) {
  if (path === "codecParams.encoder.quality") return "quality";
  if (path === "codecParams.encoder.vbr_scale_index") return "vbr scale";
  if (path === "codecParams.encoder.force_ind") return "force";
  if (path === "codecParams.encoder.model") return "model";
  if (path === "codecParams.encoder.checkpoint_preset") return "model";
  if (path === "channel.snr_db") return "SNR";
  if (path === "channel.txPowerTarget" || path.endsWith(".target_power")) return "Normalized TX power";
  return String(path || "").split(".").pop() || "value";
}

function sweepValueLabel(path, value, recipe = null) {
  if (path === "channel.snr_db") {
    return `${formatValue(value)} dB`;
  }
  if (path === "channel.txPowerTarget" || path.endsWith(".target_power")) {
    return formatValue(value);
  }
  if (path === "codecParams.encoder.model") {
    return compressAiModelShortLabel(value);
  }
  if (path === "codecParams.encoder.checkpoint_preset") {
    const profile = codecProfileFromMetadata((recipe && recipe.metadata) || {}) || codecProfile("evc", null);
    return upstreamPresetShortLabel(profile, value);
  }
  return formatValue(value);
}

function sweepValuesForPath(path, spec, recipe = null) {
  if (path === "codecParams.encoder.vbr_scale_index") {
    return parseNumericSweepValues(spec).filter((value) => Number.isInteger(Number(value)) && Number(value) >= 0 && Number(value) <= 7);
  }
  if (path === "codecParams.encoder.force_ind") {
    return parseNumericSweepValues(spec).filter((value) => Number.isInteger(Number(value)) && Number(value) >= 0 && Number(value) <= 4);
  }
  if (path === "codecParams.encoder.model") {
    const valid = new Set(compressAiModelIds());
    return parseCategoricalSweepValues(spec).filter((value) => valid.has(value));
  }
  if (path === "codecParams.encoder.checkpoint_preset") {
    const profile = codecProfileFromMetadata((recipe && recipe.metadata) || {}) || codecProfile("evc", null);
    const valid = new Set((profile.checkpointPresets || []).map((preset) => preset.id));
    return parseCategoricalSweepValues(spec).filter((value) => valid.has(value));
  }
  if (Array.isArray(spec)) return structuredCloneFallback(spec);
  if (spec !== null && typeof spec === "object") return [structuredCloneFallback(spec)];
  if (typeof spec === "boolean" || typeof spec === "number") return [spec];
  const raw = String(spec === undefined || spec === null ? "" : spec).trim();
  if (!raw) return [];
  if (raw.startsWith("[") || raw.startsWith("{") || raw.startsWith('"')) {
    try {
      const parsed = parseRecipeSettingText(raw);
      return Array.isArray(parsed) ? parsed : [parsed];
    } catch (_error) {
      return [];
    }
  }
  if (raw.includes(":")) return parseNumericSweepValues(raw);
  if (raw.includes(",")) {
    const numeric = parseNumericSweepValues(raw);
    return numeric.length ? numeric : raw.split(",").map((value) => value.trim()).filter(Boolean);
  }
  const numeric = Number(raw);
  return Number.isFinite(numeric) ? [integerIfWhole(numeric)] : [raw];
}

function upstreamPresetShortLabel(profile, presetId) {
  const preset = (profile.checkpointPresets || []).find((item) => item.id === presetId);
  const raw = preset ? preset.label : String(presetId || "");
  if (profile.id === "tcm") {
    return raw.replace(/^N(\d+) lambda /, "N$1 l").replace(" MSE", "");
  }
  if (profile.id === "hpcm") {
    return raw
      .replace(" lambda ", " l")
      .replace("PhiContext", "Phi")
      .replace("Base ", "B ")
      .replace("Large ", "L ");
  }
  return raw
    .replace(/^EVC_/, "")
    .replace(/^Scale_EVC_/, "Scale_")
    .replace(/_MDRRL$/, "")
    .replace(/^evc_/, "")
    .replace(/_/g, "_");
}

async function focusRecipeInGraphForRun(recipe) {
  if (state.activeView !== "graph" || !recipe || state.selectedRecipeKey === recipe.key) return;
  await selectRecipe(recipe);
}

async function stopActiveRuns() {
  if (!state.batchRunning || state.batchStopping) return;
  state.batchStopping = true;
  renderRunControls();
  const activeIds = Object.values(state.activeJobIds).filter(Boolean);
  if (!activeIds.length) {
    notify("stop requested");
    return;
  }
  await Promise.all(
    activeIds.map(async (jobId) => {
      const recipe = recipeForJobId(jobId);
      try {
        if (recipe) {
          state.runJobs[recipe.key] = {
            ...(state.runJobs[recipe.key] || {}),
            cancel_requested: true,
          };
        }
        const job = await cancelRecipeJob(recipe, jobId);
        if (recipe) updateRecipeJob(recipe, job);
      } catch (error) {
        if (recipe) appendLocalRecipeLog(recipe, `Stop request failed: ${error.message}`, "error");
      }
    })
  );
  notify("stop requested");
  renderRunLog();
}

async function cancelRecipeJob(recipe, jobId) {
  const job = await api(`/api/run-jobs/${encodeURIComponent(jobId)}/cancel`, { method: "POST" });
  job.cancel_requested = true;
  if (recipe) updateRecipeJob(recipe, job);
  return job;
}

function updateRecipeJob(recipe, job) {
  if (!recipe || !job) return;
  const previous = state.runJobs[recipe.key] || {};
  const next = {
    ...previous,
    ...job,
    events: mergeRunJobEvents(previous.events, job.events),
    recipeKey: recipe.key,
    displayName: recipeDisplayName(recipe),
  };
  next.event_cursor = Math.max(
    runJobEventCursor(previous),
    runJobEventCursor(next),
  );
  const changed = runJobUiRevision(previous) !== runJobUiRevision(next);
  state.runJobs[recipe.key] = next;
  if (!isTerminalJobStatus(job.status)) {
    state.activeJobIds[recipe.key] = job.job_id;
  } else {
    delete state.activeJobIds[recipe.key];
  }
  if (recipe.sweepProgress) {
    updateRecipeSweepProgress(recipe, {
      currentFraction: jobVariantProgressFraction(recipe, job),
      status: isTerminalJobStatus(job.status) ? recipe.sweepProgress.status : "running",
    }, false);
  }
  if (!changed) return;
  renderRecipes();
  renderRunLog();
  if (state.graph && state.selectedRecipeKey === recipe.key) {
    renderGraph(state.graph);
  }
}

function runJobEventCursor(job) {
  const declared = Number(job && job.event_cursor);
  const serverCursor = Number(job && job.next_event_seq);
  const events = job && Array.isArray(job.events) ? job.events : [];
  const observed = events.reduce((maximum, event) => {
    const seq = Number(event && event.seq);
    return Number.isInteger(seq) && seq > maximum ? seq : maximum;
  }, 0);
  return Math.max(
    Number.isInteger(declared) && declared > 0 ? declared : 0,
    Number.isInteger(serverCursor) && serverCursor > 0 ? serverCursor : 0,
    observed,
  );
}

function runJobEventIdentity(event, index = 0) {
  const seq = Number(event && event.seq);
  if (Number.isInteger(seq) && seq > 0) return `server:${seq}`;
  return `local:${String((event && event.kind) || "event")}:${String((event && event.time) || "")}:${String((event && event.message) || "")}:${index}`;
}

function mergeRunJobEvents(previousEvents, incomingEvents) {
  const previous = Array.isArray(previousEvents) ? previousEvents : [];
  if (!Array.isArray(incomingEvents)) return previous.slice(-RUN_JOB_EVENT_RETENTION_LIMIT);
  const merged = [];
  const indexByIdentity = new Map();
  [...previous, ...incomingEvents].forEach((event, index) => {
    if (!event || typeof event !== "object") return;
    const identity = runJobEventIdentity(event, index);
    if (indexByIdentity.has(identity)) {
      merged[indexByIdentity.get(identity)] = event;
      return;
    }
    indexByIdentity.set(identity, merged.length);
    merged.push(event);
  });
  return merged.slice(-RUN_JOB_EVENT_RETENTION_LIMIT);
}

function runJobUiRevision(job) {
  if (!job || typeof job !== "object") return "";
  const events = Array.isArray(job.events) ? job.events : [];
  const last = events[events.length - 1] || {};
  return JSON.stringify([
    job.status || "",
    job.run_id || "",
    job.error || "",
    runJobEventCursor(job),
    events.length,
    last.kind || "",
    last.message || "",
    job.progress || null,
  ]);
}

function updateRecipeSweepProgress(recipe, patch, render = true) {
  if (!recipe || !recipe.sweepProgress) return;
  recipe.sweepProgress = {
    ...recipe.sweepProgress,
    ...(patch || {}),
  };
  if (render) renderRecipes();
}

function startRecipeActivityProgress(recipe, details = {}, render = true) {
  if (!recipe) return;
  recipe.activityProgress = {
    kind: String(details.kind || "activity"),
    total: Math.max(1, integerOr(details.total, 1)),
    completed: Math.max(0, numberOr(details.completed, 0)),
    currentIndex: Math.max(0, integerOr(details.currentIndex, 0)),
    currentLabel: String(details.currentLabel || "Working"),
    currentFraction: Math.max(0, Math.min(1, numberOr(details.currentFraction, 0))),
    status: String(details.status || "running"),
  };
  if (render) renderRecipes();
}

function updateRecipeActivityProgress(recipe, patch, render = true) {
  if (!recipe || !recipe.activityProgress) return;
  recipe.activityProgress = {
    ...recipe.activityProgress,
    ...(patch || {}),
  };
  if (render) renderRecipes();
}

function jobVariantProgressFraction(recipe, job) {
  if (!job) return 0;
  if (job.status === "completed") return 1;
  const steps = (recipe && recipe.recipe && recipe.recipe.steps) || [];
  const total = Math.max(1, steps.length || Object.keys((job.progress && job.progress.steps) || {}).length || 1);
  const live = stepStateFromEvents(job.events || []);
  const completed = Math.min(total, live.completed.size);
  const progressSteps = (job.progress && job.progress.steps) || {};
  let activePercent = 0;
  if (live.activeStep && progressSteps[live.activeStep]) {
    activePercent = Math.max(activePercent, numberOr(progressPercentValue(progressSteps[live.activeStep]), 0) / 100);
  }
  Object.values(progressSteps).forEach((progress) => {
    if (!progress || progress.status !== "running") return;
    activePercent = Math.max(activePercent, numberOr(progressPercentValue(progress), 0) / 100);
  });
  return Math.max(0, Math.min(1, (completed + Math.min(1, activePercent)) / total));
}

function setLocalRecipeJob(recipe, status, message, level = "info") {
  if (!recipe) return;
  state.runJobs[recipe.key] = {
    recipeKey: recipe.key,
    displayName: recipeDisplayName(recipe),
    status,
    events: [localLogEvent(message, level, "local")],
  };
}

function appendLocalRecipeLog(recipe, message, level = "info") {
  if (!recipe) return;
  const current = state.runJobs[recipe.key] || {
    recipeKey: recipe.key,
    displayName: recipeDisplayName(recipe),
    status: recipe.transientStatus || "queued",
    events: [],
  };
  current.status = recipe.transientStatus || current.status || "queued";
  current.events = [...(current.events || []), localLogEvent(message, level, "local")]
    .slice(-RUN_JOB_EVENT_RETENTION_LIMIT);
  state.runJobs[recipe.key] = current;
}

function localLogEvent(message, level, kind) {
  return {
    seq: 0,
    time: new Date().toLocaleTimeString([], { hour12: false }),
    kind,
    level,
    message,
  };
}

function recipeForJobId(jobId) {
  return state.recipes.find((recipe) => state.activeJobIds[recipe.key] === jobId) || null;
}

function isTerminalJobStatus(status) {
  return ["completed", "failed", "canceled", "resource_exhausted", "timed_out"].includes(String(status || ""));
}

function sleep(ms) {
  return new Promise((resolve) => window.setTimeout(resolve, ms));
}

function syncSelectedRecipeFromEditor() {
  if (!state.selectedRecipe || !state.editRecipe || state.editRecipeKey !== state.selectedRecipe.key) return;
  state.selectedRecipe.recipe = state.editRecipe;
  state.selectedRecipe.name = state.editRecipe.name || state.selectedRecipe.name;
  state.selectedRecipe.step_count = (state.editRecipe.steps || []).length;
}

async function saveCurrentRecipe() {
  if (!state.selectedRecipe || !state.editRecipe || state.busy) return;
  syncSelectedRecipeFromEditor();
  const recipe = structuredCloneFallback(state.editRecipe);
  stripRecipeWorkingStateMetadata(recipe);
  const existingPath = String(state.selectedRecipe.path || "");
  const filename = existingPath
    ? existingPath.split("/").filter(Boolean).pop()
    : String(recipe.name || "recipe");
  const previousLabel = els.saveRecipeButton ? els.saveRecipeButton.textContent : "";
  if (els.saveRecipeButton) {
    els.saveRecipeButton.disabled = true;
    els.saveRecipeButton.textContent = "Saving";
  }
  try {
    const payload = await api("/api/recipe/save", {
      method: "POST",
      body: JSON.stringify({ recipe, filename }),
    });
    state.selectedRecipe.path = payload.path;
    state.selectedRecipe.source = "project";
    state.selectedRecipe.workingCopy = false;
    state.selectedRecipe.recipe = structuredCloneFallback(payload.recipe);
    state.editRecipe = state.selectedRecipe.recipe;
    const recipes = await api("/api/recipes");
    state.recipeFiles = recipes.recipes || [];
    notify(`saved ${payload.path}`);
    renderRecipes();
    renderRecipeControls();
  } catch (error) {
    notify(`could not save recipe: ${error.message}`);
  } finally {
    if (els.saveRecipeButton) {
      els.saveRecipeButton.textContent = previousLabel || "Save";
      els.saveRecipeButton.disabled = state.busy || !state.editRecipe;
    }
  }
}

async function ensureRecipePayload(recipe) {
  if (!recipe || recipe.recipe) return;
  if (!recipe.path) throw new Error("recipe tab has no payload");
  const payload = await api(`/api/recipe?path=${encodeURIComponent(recipe.path)}`);
  recipe.recipe = structuredCloneFallback(payload.recipe);
}

function runAllSummary(completed, failed, stopped = 0) {
  const total = completed + failed;
  if (stopped) return `stopped after ${completed} completed, ${failed} failed`;
  if (failed) return `ran ${total} recipes: ${completed} completed, ${failed} failed`;
  return `completed ${completed} recipe${completed === 1 ? "" : "s"}`;
}

function openRunLog() {
  els.logOverlay.hidden = false;
  renderRunLog();
}

function closeRunLog() {
  els.logOverlay.hidden = true;
}

function renderRunLog() {
  if (!els.logBody) return;
  syncRunLogButtonSeverity();
  const rows = state.recipes
    .map((recipe) => ({ recipe, job: state.runJobs[recipe.key] }))
    .filter((row) => row.job);
  const active = rows.filter((row) => !isTerminalJobStatus(row.job.status)).length;
  const finished = rows.filter((row) => isTerminalJobStatus(row.job.status)).length;
  els.logSubtitle.textContent = rows.length
    ? `${finished}/${rows.length} finished${active ? ` - ${active} active` : ""}`
    : "no run log";
  if (!rows.length) {
    els.logBody.innerHTML = '<div class="log-empty">Run an experiment to collect execution logs.</div>';
    return;
  }
  const labels = recipeDisplayLabels(rows.map((row) => row.recipe));
  els.logBody.innerHTML = rows.map((row) => runLogSection(row.recipe, row.job, labels)).join("");
  if (!els.logOverlay.hidden) {
    els.logBody.scrollTop = els.logBody.scrollHeight;
  }
}

function runLogSection(recipe, job, labels) {
  const title = recipeDisplayName(recipe, labels);
  const allEvents = Array.isArray(job.events) ? job.events : [];
  const visibleEvents = allEvents.slice(-RUN_JOB_LOG_RENDER_LIMIT);
  const omitted = Math.max(0, allEvents.length - visibleEvents.length);
  const events = visibleEvents.length
    ? `${omitted ? `<div class="log-event log-event-omitted"><span></span><span class="log-event-kind">earlier</span><span class="log-event-message">${escapeHtml(`${omitted} earlier events omitted from this bounded view.`)}</span></div>` : ""}${visibleEvents.map(logEventRow).join("")}`
    : '<div class="log-event"><span></span><span class="log-event-kind">empty</span><span class="log-event-message">Waiting for job events.</span></div>';
  return `
    <section class="log-recipe">
      <div class="log-recipe-header">
        <strong title="${escapeAttr(title)}">${escapeHtml(title)}</strong>
        <span class="log-status">${escapeHtml(logStatusLabel(job.status))}</span>
      </div>
      <div class="log-events">${events}</div>
    </section>
  `;
}

function logEventRow(event) {
  const message = logEventMessage(event);
  const level = event.level || "info";
  return `
    <div class="log-event ${escapeAttr(level)}">
      <span class="log-event-time">${escapeHtml(event.time || "")}</span>
      <span class="log-event-kind">${escapeHtml(logKindLabel(event.kind))}</span>
      <span class="log-event-message">${escapeHtml(message)}</span>
    </div>
  `;
}

function logEventMessage(event) {
  const suffix = event.step_id && event.op ? ` [${event.step_id}: ${event.op}]` : event.step_id ? ` [${event.step_id}]` : "";
  return `${event.message || event.kind || "event"}${suffix}`;
}

function logKindLabel(kind) {
  return String(kind || "event").replace(/^run_/, "").replace(/^job_/, "").replace(/^step_/, "step ");
}

function logStatusLabel(status) {
  if (status === "canceled") return "stopped";
  if (status === "resource_exhausted") return "stopped · memory protection";
  if (status === "timed_out") return "stopped · execution deadline";
  return status || "queued";
}

async function attachRunSummary(runId, fallbackStatus, fallbackRecipeName) {
  if (!runId) return null;
  let summary = null;
  try {
    summary = await api(`/api/runs/${encodeURIComponent(runId)}`);
    state.runSummaries[runId] = summary;
  } catch (_error) {
    // A later result refresh can retry if the run summary is momentarily unavailable.
  }
  upsertRun({
    run_id: runId,
    status: (summary && summary.status) || fallbackStatus || "completed",
    recipe_name: (summary && summary.recipe_name) || fallbackRecipeName || "",
  });
  return summary;
}

function upsertRun(row) {
  if (!row || !row.run_id) return;
  const index = (state.runs || []).findIndex((item) => item.run_id === row.run_id);
  if (index >= 0) {
    state.runs[index] = { ...state.runs[index], ...row };
  } else {
    state.runs = [...(state.runs || []), row];
  }
}

async function loadAllRecipeResults(showResults) {
  const rows = resultsSourceIsBenchmark()
    ? await loadBenchmarkResultRows()
    : resultsSourceIsRun()
      ? await loadPastRunResultRows()
      : await loadCurrentRecipeResultRows();
  renderResultsDashboard(rows);
  renderRecipes();
  if (state.activeView === "graph" && state.graph) renderGraph(state.graph);
  if (showResults) setActiveView("results", false);
}

async function loadCurrentRecipeResultRows() {
  state.activeBenchmarkResult = null;
  const rows = await Promise.all(
    state.recipes.map(async (recipe) => {
      const runIds = recipeRunIds(recipe);
      if (!runIds.length) return { recipe, runs: [], summaries: [], summary: null };
      const loaded = await Promise.all(
        runIds.map(async (runId) => {
          const run = runById(runId) || { run_id: runId, status: "", recipe_name: recipe.name };
          if (state.runSummaries[runId]) {
            return { run, summary: state.runSummaries[runId] };
          }
          try {
            const summary = await api(`/api/runs/${encodeURIComponent(runId)}`);
            state.runSummaries[runId] = summary;
            return { run, summary };
          } catch (error) {
            return { run, summary: null, error: error.message };
          }
        })
      );
      const summaries = loaded.map((item) => item.summary).filter(Boolean);
      const last = loaded[loaded.length - 1] || {};
      return {
        recipe,
        runs: loaded.map((item) => item.run).filter(Boolean),
        run: last.run || null,
        summaries,
        summary: summaries[summaries.length - 1] || null,
        error: loaded.find((item) => item.error)?.error,
      };
    })
  );
  return rows;
}

async function loadPastRunResultRows() {
  state.activeBenchmarkResult = null;
  if (!state.selectedRunId) return [];
  const runId = state.selectedRunId;
  let summary = null;
  let error = "";
  try {
    summary = state.runSummaries[runId] || await api(`/api/runs/${encodeURIComponent(runId)}`);
    state.runSummaries[runId] = summary;
  } catch (fetchError) {
    error = fetchError.message;
  }
  const verification = await verifyRunById(runId, { render: false, notify: false });
  if (verification && verification.status === "invalid" && !error) {
    error = (verification.errors || [])[0] || "run verification failed";
  }
  const run = runById(runId) || {
    run_id: runId,
    status: (summary && summary.status) || "",
    recipe_name: (summary && summary.recipe_name) || "",
  };
  const recipe = pastRunRecipeFromSummary(runId, summary, run);
  return [{
    recipe,
    run,
    runs: [run],
    summary,
    summaries: summary ? [summary] : [],
    error,
    source: "run",
  }];
}

function pastRunRecipeFromSummary(runId, summary, run) {
  const recipePayload = summary && summary.recipe ? summary.recipe : null;
  const name = (summary && summary.recipe_name) || (run && run.recipe_name) || runId;
  return {
    key: `run:${runId}`,
    color: recipeColorForIndex(0),
    displayName: name,
    tabLabel: name,
    name,
    path: "",
    source: "run",
    templatePath: "",
    description: runId,
    step_count: recipePayload && Array.isArray(recipePayload.steps) ? recipePayload.steps.length : 0,
    metadata: { run_id: runId },
    suite: (recipePayload && recipePayload.suite) || (run && run.suite) || {},
    lastRunId: runId,
    resultDirty: false,
    transientStatus: null,
    recipe: recipePayload,
  };
}

async function loadBenchmarkResultRows() {
  if (!state.selectedBenchmarkResultId) {
    state.activeBenchmarkResult = null;
    return [];
  }
  let result = null;
  try {
    const payload = await api(`/api/benchmarks/results/${encodeURIComponent(state.selectedBenchmarkResultId)}`);
    result = payload.result || {
      status: "missing",
      benchmark: { id: state.selectedBenchmarkResultId },
      recipes: [],
    };
  } catch (error) {
    state.activeBenchmarkResult = {
      status: "error",
      error: error.message,
      benchmark: { id: state.selectedBenchmarkResultId },
      recipes: [],
    };
    return [];
  }
  state.activeBenchmarkResult = result;
  const entries = Array.isArray(result.recipes) ? result.recipes : [];
  const rows = await Promise.all(
    entries.map(async (entry, index) => {
      const runId = String(entry.run_id || "");
      let summary = null;
      let error = entry.error || "";
      if (runId) {
        try {
          summary = state.runSummaries[runId] || await loadBenchmarkRunSummary(
            state.selectedBenchmarkResultId,
            runId,
          );
          state.runSummaries[runId] = summary;
        } catch (fetchError) {
          error = error || fetchError.message;
        }
      } else if (!error && entry.status !== "completed") {
        error = entry.status || "no run";
      }
      const recipe = benchmarkRecipeFromEntry(entry, result, index, summary);
      const run = runId
        ? {
            run_id: runId,
            status: entry.status || (summary && summary.status) || "",
            recipe_name: entry.recipe_name || (summary && summary.recipe_name) || "",
          }
        : null;
      return {
        recipe,
        run,
        runs: run ? [run] : [],
        summary,
        summaries: summary ? [summary] : [],
        error,
        benchmarkEntry: entry,
        benchmarkResult: result,
      };
    })
  );
  return rows;
}

async function loadBenchmarkRunSummary(resultId, runId) {
  try {
    return await api(`/api/runs/${encodeURIComponent(runId)}`);
  } catch (runError) {
    try {
      return await api(
        `/api/benchmarks/results/${encodeURIComponent(resultId)}/runs/${encodeURIComponent(runId)}`
      );
    } catch (snapshotError) {
      throw new Error(
        snapshotError.message
        || runError.message
        || `Unable to load benchmark run ${runId}`
      );
    }
  }
}

function benchmarkRecipeFromEntry(entry, result, index, summary) {
  const benchmark = (result && result.benchmark) || {};
  const label = entry.label || entry.recipe_name || entry.id || `Recipe ${index + 1}`;
  const recipePayload = summary && summary.recipe ? summary.recipe : null;
  return {
    key: `benchmark:${state.selectedBenchmarkResultId}:${entry.id || index}`,
    color: recipeColorForIndex(index),
    displayName: label,
    tabLabel: label,
    name: entry.recipe_name || label,
    path: entry.recipe_path || "",
    source: "benchmark",
    templatePath: entry.recipe_path || "",
    description: benchmark.name || benchmark.id || "",
    step_count: recipePayload && Array.isArray(recipePayload.steps) ? recipePayload.steps.length : 0,
    metadata: {
      benchmark_result_id: state.selectedBenchmarkResultId,
      benchmark_id: benchmark.id || "",
      benchmark_version: benchmark.version || "",
      benchmark_recipe_id: entry.id || "",
      benchmark_role: entry.role || "",
    },
    suite: (recipePayload && recipePayload.suite) || benchmark.suite || {},
    lastRunId: entry.run_id || null,
    resultDirty: false,
    transientStatus: null,
    recipe: recipePayload,
  };
}

function collectRunDetails(summary) {
  const metrics = [];
  const settings = [];
  const artifacts = [];
  Object.entries(summary.metrics || {}).forEach(([name, value]) => {
    if (isConfigurationMetric(name)) {
      settings.push({ step: "run", setting: `reported.${name}`, value });
    } else {
      metrics.push({ step: "run", metric: name, value });
    }
  });
  (summary.recipe && summary.recipe.steps || []).forEach((step) => {
    Object.entries(step.params || {}).forEach(([name, value]) => {
      settings.push({ step: step.id, setting: `param.${name}`, value });
    });
  });
  (summary.steps || []).forEach((step) => {
    Object.entries(step.metrics || {}).forEach(([name, value]) => {
      if (isConfigurationMetric(name)) {
        settings.push({ step: step.id, setting: `reported.${name}`, value });
      } else {
        metrics.push({ step: step.id, metric: name, value });
      }
    });
    addCodecTimingDerivedMetrics(metrics, step);
    Object.entries(step.outputs || {}).forEach(([name, artifact]) => {
      artifacts.push({ step: step.id, name, artifact });
    });
  });
  addCodecAggregateTimingMetrics(metrics, summary);
  return { metrics, settings, artifacts };
}

function addCodecAggregateTimingMetrics(metrics, summary) {
  const grouped = new Map();
  const addSample = (key, sampleKey, duration) => {
    const seconds = Number(duration);
    if (!key || !Number.isFinite(seconds) || seconds <= 0) return;
    const samples = grouped.get(key) || new Map();
    samples.set(sampleKey, (samples.get(sampleKey) || 0) + seconds);
    grouped.set(key, samples);
  };
  (summary.steps || []).forEach((step) => {
    codecTimingMeasurements(step).forEach((record, recordIndex) => {
      const stage = String(record.stage || "").trim();
      const seconds = Number(record.duration_s);
      if (!stage || !Number.isFinite(seconds) || seconds <= 0) return;
      const role = stage.split(".")[0] || "";
      if (role !== "encoder" && role !== "decoder") return;
      const leaf = stage.split(".").slice(1).join(".");
      const key = leaf === "total" ? `${role}.total` : timingComponentKey(stage, step);
      if (!key) return;
      addSample(key, timingRecordSampleKey(record, step, stage, recordIndex), seconds);
    });
  });
  grouped.forEach((samples, stage) => {
    const stats = timingStats(Array.from(samples.values()));
    Object.entries(stats).forEach(([name, value]) => {
      metrics.push({
        step: "codec",
        metric: `codec_timing.${stage}.${name}${name === "count" ? "" : "_s"}`,
        value,
      });
    });
  });
}

function addCodecTimingDerivedMetrics(metrics, step) {
  const measurements = codecTimingMeasurements(step);
  if (!measurements.length) return;
  const grouped = new Map();
  const canonicalGrouped = new Map();
  const addGroupedSample = (target, key, sampleKey, duration) => {
    const samples = target.get(key) || new Map();
    samples.set(sampleKey, (samples.get(sampleKey) || 0) + duration);
    target.set(key, samples);
  };
  measurements.forEach((record, recordIndex) => {
    const stage = String(record.stage || "").trim();
    const duration = Number(record.duration_s);
    if (!stage || !Number.isFinite(duration)) return;
    const sampleKey = timingRecordSampleKey(record, step, stage, recordIndex);
    addGroupedSample(grouped, stage, sampleKey, duration);
    if (!stage.endsWith(".total")) {
      const canonicalStage = timingComponentKey(stage, step);
      if (canonicalStage) addGroupedSample(canonicalGrouped, canonicalStage, sampleKey, duration);
    }
  });
  canonicalGrouped.forEach((samples, stage) => {
    grouped.set(stage, samples);
  });
  grouped.forEach((samples, stage) => {
    const stats = timingStats(Array.from(samples.values()));
    Object.entries(stats).forEach(([name, value]) => {
      metrics.push({
        step: step.id,
        metric: `codec_timing.${stage}.${name}${name === "count" ? "" : "_s"}`,
        value,
      });
    });
  });
}

function codecTimingMeasurements(step) {
  const timing = codecTimingMetadata(step);
  const rows = Array.isArray(timing.measurements) ? timing.measurements : [];
  return rows.filter((row) => row && typeof row === "object");
}

function codecTimingMetadata(step) {
  const metadata = (step && step.metadata) || {};
  return metadata.codec_timing || (metadata.timing && metadata.timing.codec_timing) || {};
}

function timingStats(values) {
  const sorted = values.map(Number).filter(Number.isFinite).sort((left, right) => left - right);
  if (!sorted.length) return {};
  const mean = sorted.reduce((sum, value) => sum + value, 0) / sorted.length;
  const variance = sorted.reduce((sum, value) => sum + (value - mean) ** 2, 0) / sorted.length;
  return {
    sum: sorted.reduce((sum, value) => sum + value, 0),
    mean,
    p50: percentile(sorted, 0.5),
    p90: percentile(sorted, 0.9),
    p95: percentile(sorted, 0.95),
    p99: percentile(sorted, 0.99),
    std: Math.sqrt(variance),
    count: sorted.length,
  };
}

function percentile(sortedValues, ratio) {
  if (!sortedValues.length) return NaN;
  if (sortedValues.length === 1) return sortedValues[0];
  const position = Math.max(0, Math.min(1, ratio)) * (sortedValues.length - 1);
  const lower = Math.floor(position);
  const upper = Math.ceil(position);
  if (lower === upper) return sortedValues[lower];
  const weight = position - lower;
  return sortedValues[lower] * (1 - weight) + sortedValues[upper] * weight;
}

function timingCompositionPanel(summary) {
  const components = timingCompositionForSummary(summary);
  const stat = selectedTimeStat();
  const statLabel = timeStatLabel(stat);
  const drillPath = selectedTimeDrillPath();
  const breadcrumb = timeDrillBreadcrumb(drillPath);
  const languageBadge = timingLanguageBadge(summary);
  if (!components.length) {
    return `
      <div class="time-composition-panel empty">
        <div class="time-composition-header">
          <div class="time-composition-title">
            <strong>Time Composition</strong>
            ${languageBadge}
          </div>
          <span>${escapeHtml(statLabel)} - no codec timing</span>
        </div>
        ${breadcrumb}
      </div>
    `;
  }
  const hidden = new Set(state.timeHiddenComponents || []);
  const visibleComponents = components.filter((item) => !hidden.has(item.key));
  const totalSeconds = components.reduce((sum, item) => sum + item.seconds, 0);
  const visibleSeconds = visibleComponents.reduce((sum, item) => sum + item.seconds, 0);
  const segments = visibleComponents.map((item) => {
    const percent = visibleSeconds > 0 ? (item.seconds / visibleSeconds) * 100 : 0;
    const title = timeComponentTooltip(item, statLabel, percent, true);
    return `
      <span
        class="time-stack-segment${item.drillTarget ? " is-drillable" : ""}"
        data-time-component="${escapeAttr(item.key)}"
        ${item.drillTarget ? `data-time-drill-target="${escapeAttr(item.drillTarget)}"` : ""}
        data-time-segment
        ${item.drillTarget ? 'role="button" tabindex="0"' : ""}
        style="--time-color: ${escapeAttr(item.color)}; --time-width: ${percent.toFixed(4)}%;"
        title="${escapeAttr(title)}"
        aria-label="${escapeAttr(title)}"
      ></span>
    `;
  }).join("");
  const legend = components.map((item) => {
    const percent = totalSeconds > 0 ? (item.seconds / totalSeconds) * 100 : 0;
    const isHidden = hidden.has(item.key);
    const title = timeComponentTooltip(item, statLabel, percent, false);
    const action = item.drillTarget ? "Open" : (isHidden ? "Show" : "Hide");
    return `
      <button
        class="time-legend-item${isHidden ? " is-hidden" : ""}${item.drillTarget ? " is-drillable" : ""}"
        type="button"
        data-time-component="${escapeAttr(item.key)}"
        data-time-legend
        ${item.drillTarget ? `data-time-drill-target="${escapeAttr(item.drillTarget)}"` : ""}
        style="--time-color: ${escapeAttr(item.color)}"
        title="${escapeAttr(`${action}\n${title}`)}"
        aria-pressed="${isHidden ? "true" : "false"}"
      >
        <span class="time-legend-swatch"></span>
        <span>${escapeHtml(item.label)}</span>
        <strong>${escapeHtml(isHidden ? "off" : formatPercent(percent))}</strong>
      </button>
    `;
  }).join("");
  const headerDetail = hidden.size && visibleSeconds < totalSeconds
    ? `${statLabel} ${formatTimingDuration(visibleSeconds)} visible / ${formatTimingDuration(totalSeconds)} total`
    : `${statLabel} ${formatTimingDuration(totalSeconds)}`;
  return `
    <div class="time-composition-panel">
      <div class="time-composition-header">
        <div class="time-composition-title">
          <strong>Time Composition</strong>
          ${languageBadge}
        </div>
        <span>${escapeHtml(headerDetail)}</span>
      </div>
      ${breadcrumb}
      <div class="time-stack" role="img" aria-label="Codec time composition">
        ${visibleSeconds > 0 ? segments : '<span class="time-stack-empty">selected stat is 0</span>'}
      </div>
      <div class="time-legend">${legend}</div>
    </div>
  `;
}

function timingLanguageBadge(summary) {
  const label = timingLanguageLabelForSummary(summary);
  if (!label) return "";
  return `<span class="inline-badge time-language-badge" title="${escapeAttr(`Codec runtime language: ${label}`)}">${escapeHtml(label)}</span>`;
}

function timingLanguageLabelForSummary(summary) {
  const tags = new Set();
  (summary && summary.steps || []).forEach((step) => {
    const timing = codecTimingMetadata(step);
    if (timing && (timing.runner || timing.notes || (Array.isArray(timing.measurements) && timing.measurements.length))) {
      collectTimingLanguageTokens(timing.runner, tags);
      collectTimingLanguageTokens(timing.notes, tags);
    }
    const metadata = (step && step.metadata) || {};
    collectTimingLanguageTokens(metadata.runtime, tags);
    collectTimingLanguageTokens(metadata.runtime_evidence, tags);
    collectTimingLanguageTokens(metadata.entropy_language, tags);
    collectTimingLanguageTokens(metadata.entropy_implementation, tags);
  });
  const recipeTiming = summary && summary.recipe && summary.recipe.metadata ? summary.recipe.metadata.codec_timing || {} : {};
  collectTimingLanguageTokens(recipeTiming.runner, tags);
  collectTimingLanguageTokens(recipeTiming.requested_runner, tags);
  return formatTimingLanguageTags(tags);
}

const TIMING_LANGUAGE_KEYS = new Set([
  "runner",
  "runtime",
  "requested_runner",
  "source_runtime",
  "runtime_engine",
  "runtime_execution_language",
  "runtime_api",
  "runtime_api_binding",
  "entropy_language",
  "entropy_implementation",
  "language",
  "implementation",
]);

function collectTimingLanguageTokens(value, tags, key = "") {
  if (value === undefined || value === null) return;
  if (typeof value === "string") {
    if (!key || TIMING_LANGUAGE_KEYS.has(key) || key.includes("evidence") || key.includes("runtime") || key.includes("entropy")) {
      addTimingLanguageToken(value, tags);
    }
    return;
  }
  if (Array.isArray(value)) {
    value.forEach((item) => collectTimingLanguageTokens(item, tags, key));
    return;
  }
  if (typeof value === "object") {
    Object.entries(value).forEach(([childKey, childValue]) => {
      if (
        TIMING_LANGUAGE_KEYS.has(childKey) ||
        childKey.includes("evidence") ||
        childKey.includes("runtime") ||
        childKey.includes("entropy")
      ) {
        collectTimingLanguageTokens(childValue, tags, childKey);
      }
    });
  }
}

function addTimingLanguageToken(value, tags) {
  const text = String(value || "").toLowerCase();
  if (!text) return;
  if (text.includes("c/python")) {
    tags.add("C");
    tags.add("Python");
  }
  if (text.includes("c++") || text.includes("cxx") || text.includes("libtorch") || text.includes("openvino") || text.includes("onnxruntime") || text.includes("c_api") || text.includes("c api")) {
    tags.add("C++");
  }
  if (text === "c" || text.includes("c backend")) tags.add("C");
  if (text.includes("python") || text.includes("pytorch") || text.includes("numpy") || text.includes("torch")) {
    tags.add("Python");
  }
  if (text.includes("aot_inductor") || text.includes("aot inductor") || text.includes("aoti")) {
    tags.add("C++");
    tags.add("Python");
  }
  if (text === "local_python" || text === "pytorch") tags.add("Python");
}

function formatTimingLanguageTags(tags) {
  const hasC = tags.has("C");
  const hasCpp = tags.has("C++");
  const parts = [];
  if (hasC && hasCpp) parts.push("C/C++");
  else if (hasCpp) parts.push("C++");
  else if (hasC) parts.push("C");
  if (tags.has("Python")) parts.push("Python");
  return parts.join(" + ");
}

function timingCompositionForSummary(summary) {
  const stat = selectedTimeStat();
  const drillPath = selectedTimeDrillPath();
  const currentKey = drillPath[drillPath.length - 1] || TIME_DRILL_ROOT;
  if (currentKey.startsWith("raw:")) {
    return rawTimeCompositionForSummary(summary, currentKey, stat);
  }
  const node = timeDrillNodeSpec(currentKey) || TIME_DRILL_NODES.root;
  const children = node.children || [];
  const sampleBuckets = timingComponentSampleBucketsForSummary(summary);
  const details = timingComponentSourceDetailsForSummary(summary);
  const rawSources = timingRawSourceBucketsForSummary(summary);
  return children
    .map((childKey) => timeCompositionItemForNode(childKey, sampleBuckets, details, rawSources, stat))
    .filter((item) => item && item.count > 0);
}

function timeCompositionItemForNode(nodeKey, sampleBuckets, details, rawSources, stat) {
  const spec = timeDrillNodeSpec(nodeKey);
  if (!spec) return null;
  const componentKeys = timeDrillComponentKeys(nodeKey);
  const bucket = combineTimingSampleBuckets(sampleBuckets, componentKeys);
  const values = Array.from(bucket.values());
  const stats = timingStats(values);
  const rawCount = componentKeys.reduce((sum, key) => sum + ((rawSources.get(key) || []).length), 0);
  return {
    ...spec,
    key: spec.key || nodeKey,
    seconds: Number(stats[stat]) || 0,
    count: Number(stats.count) || 0,
    stats,
    details: groupTimingDetails(componentKeys, details),
    drillTarget: spec.children || rawCount ? (spec.children ? nodeKey : `raw:${nodeKey}`) : "",
  };
}

function rawTimeCompositionForSummary(summary, rawKey, stat) {
  const parentKey = String(rawKey || "").slice(4);
  const componentKeys = timeDrillComponentKeys(parentKey);
  const rawSources = timingRawSourceBucketsForSummary(summary);
  return componentKeys
    .flatMap((componentKey) => {
      const component = TIME_COMPONENT_BY_KEY[componentKey] || {};
      return (rawSources.get(componentKey) || []).map((source) => {
        const stats = timingStats(Array.from(source.bucket.values()));
        return {
          key: `raw:${parentKey}:${source.key}`,
          label: rawTimeSourceLabel(source),
          color: component.color || "#94a3b8",
          description: `Raw timing source for ${component.label || componentKey}.`,
          seconds: Number(stats[stat]) || 0,
          count: Number(stats.count) || 0,
          stats,
          details: {
            sources: new Map([[source.key, {
              step: source.step,
              stage: source.stage,
              seconds: Array.from(source.bucket.values()).reduce((sum, value) => sum + value, 0),
              count: source.bucket.size,
            }]]),
            notes: new Set(source.note ? [source.note] : []),
          },
          drillTarget: "",
        };
      });
    })
    .filter((item) => item.count > 0);
}

function rawTimeSourceLabel(source) {
  const stage = String(source.stage || "").replace(/_/g, " ");
  const step = source.step ? `${String(source.step).replace(/_/g, " ")} ` : "";
  return trim(`${step}${stage}`.trim(), 42);
}

function timeDrillBreadcrumb(path = selectedTimeDrillPath()) {
  const crumbs = path.map((key, index) => {
    const active = index === path.length - 1;
    return `
      <button
        class="time-drill-crumb${active ? " is-active" : ""}"
        type="button"
        data-time-drill-index="${index}"
        ${active ? 'aria-current="page"' : ""}
      >${escapeHtml(timeDrillLabel(key))}</button>
    `;
  }).join("");
  return `<div class="time-drill-breadcrumb">${crumbs}</div>`;
}

function timeDrillLabel(key) {
  if (String(key || "").startsWith("raw:")) return "raw stages";
  const spec = timeDrillNodeSpec(key);
  return spec ? spec.label : String(key || "all").replace(/_/g, " ");
}

function selectedTimeDrillPath() {
  const raw = Array.isArray(state.timeDrillPath) && state.timeDrillPath.length ? state.timeDrillPath : [TIME_DRILL_ROOT];
  const path = raw[0] === TIME_DRILL_ROOT ? [TIME_DRILL_ROOT] : [TIME_DRILL_ROOT];
  for (let index = 1; index < raw.length; index += 1) {
    const current = path[path.length - 1];
    const next = String(raw[index] || "");
    if (!next) break;
    if (next.startsWith("raw:")) {
      const parent = next.slice(4);
      if (parent === current || timeDrillComponentKeys(parent).length) path.push(next);
      break;
    }
    const currentSpec = timeDrillNodeSpec(current);
    if (currentSpec && Array.isArray(currentSpec.children) && currentSpec.children.includes(next)) {
      path.push(next);
    } else {
      break;
    }
  }
  return path;
}

function timeDrillNodeSpec(key) {
  return TIME_DRILL_NODES[key] || TIME_COMPONENT_BY_KEY[key] || null;
}

function timeDrillComponentKeys(key, seen = new Set()) {
  if (!key || seen.has(key)) return [];
  seen.add(key);
  const spec = timeDrillNodeSpec(key);
  if (!spec) return [];
  if (Array.isArray(spec.componentKeys)) return spec.componentKeys.slice();
  if (TIME_COMPONENT_BY_KEY[key]) return [key];
  return (spec.children || []).flatMap((child) => timeDrillComponentKeys(child, seen));
}

function combineTimingSampleBuckets(sampleBuckets, componentKeys) {
  const combined = new Map();
  componentKeys.forEach((key) => {
    const bucket = sampleBuckets.get(key);
    if (!bucket) return;
    bucket.forEach((seconds, sampleKey) => {
      combined.set(sampleKey, (combined.get(sampleKey) || 0) + seconds);
    });
  });
  return combined;
}

function groupTimingDetails(componentKeys, details) {
  const grouped = { sources: new Map(), notes: new Set() };
  componentKeys.forEach((key) => {
    const detail = details.get(key);
    if (!detail) return;
    (detail.sources || new Map()).forEach((source, sourceKey) => {
      const current = grouped.sources.get(sourceKey) || {
        step: source.step,
        stage: source.stage,
        seconds: 0,
        count: 0,
      };
      current.seconds += Number(source.seconds) || 0;
      current.count += Number(source.count) || 0;
      grouped.sources.set(sourceKey, current);
    });
    (detail.notes || new Set()).forEach((note) => grouped.notes.add(note));
  });
  return grouped.sources.size || grouped.notes.size ? grouped : null;
}

function timeComponentTooltip(item, statLabel, percent, visiblePercent) {
  const lines = [
    `${item.label}: ${statLabel} ${formatTimingDuration(item.seconds)}`,
    `n=${formatValue(item.count)}; ${formatPercent(percent)} of ${visiblePercent ? "visible" : "total"} time`,
  ];
  if (item.description) lines.push(item.description);
  const detail = item.details;
  if (detail) {
    const sources = timeComponentSourceLines(detail);
    if (sources.length) {
      lines.push("Raw sources:");
      sources.forEach((line) => lines.push(`- ${line}`));
    }
    const notes = timeComponentNoteLines(detail);
    if (notes.length) {
      lines.push("Adapter notes:");
      notes.forEach((line) => lines.push(`- ${line}`));
    }
  }
  return lines.join("\n");
}

function timeComponentSourceLines(detail) {
  const sources = Array.from((detail && detail.sources ? detail.sources : new Map()).values())
    .sort((left, right) => String(left.stage).localeCompare(String(right.stage)));
  const visible = sources.slice(0, 6).map((source) => {
    const step = source.step ? `${source.step}: ` : "";
    return `${step}${source.stage} (${formatTimingDuration(source.seconds)}, n=${formatValue(source.count)})`;
  });
  if (sources.length > visible.length) visible.push(`${sources.length - visible.length} more source stages`);
  return visible;
}

function timeComponentNoteLines(detail) {
  const notes = Array.from(detail && detail.notes ? detail.notes : [])
    .map((note) => String(note || "").trim())
    .filter(Boolean);
  const visible = notes.slice(0, 4).map((note) => trim(note, 180));
  if (notes.length > visible.length) visible.push(`${notes.length - visible.length} more notes`);
  return visible;
}

function timingComponentSampleBucketsForSummary(summary) {
  const sampleBuckets = new Map();
  const directByExample = new Map();
  const addSample = (key, sampleKey, seconds) => {
    const value = Number(seconds);
    if (!key || !Number.isFinite(value) || value <= 0) return;
    const bucket = sampleBuckets.get(key) || new Map();
    bucket.set(sampleKey, (bucket.get(sampleKey) || 0) + value);
    sampleBuckets.set(key, bucket);
  };
  const addDirectForResidual = (stepId, role, exampleKey, seconds) => {
    const key = `${stepId}:${role}:${exampleKey}`;
    directByExample.set(key, (directByExample.get(key) || 0) + seconds);
  };
  (summary.steps || []).forEach((step) => {
    codecTimingMeasurements(step).forEach((record, recordIndex) => {
      const stage = String(record.stage || "").trim();
      const seconds = Number(record.duration_s);
      if (!stage || !Number.isFinite(seconds) || seconds <= 0) return;
      const parts = stage.split(".");
      const role = parts[0] || "";
      const leaf = parts.slice(1).join(".");
      const exampleKey = timingRecordSampleKey(record, step, stage, recordIndex);
      if (leaf === "setup") {
        addSample(`${role}.setup`, exampleKey, seconds);
        return;
      }
      if (leaf === "total") {
        return;
      }
      const componentKey = timingComponentKey(stage, step);
      if (componentKey) {
        addSample(componentKey, exampleKey, seconds);
        addDirectForResidual(step.id, role, exampleKey, seconds);
      }
    });
  });
  (summary.steps || []).forEach((step) => {
    const totalsByRoleExample = new Map();
    codecTimingMeasurements(step).forEach((record, recordIndex) => {
      const stage = String(record.stage || "").trim();
      const seconds = Number(record.duration_s);
      if (!stage.endsWith(".total") || !Number.isFinite(seconds) || seconds <= 0) return;
      const role = stage.split(".")[0] || "";
      const exampleKey = timingRecordSampleKey(record, step, stage, recordIndex);
      const key = `${step.id}:${role}:${exampleKey}`;
      totalsByRoleExample.set(key, (totalsByRoleExample.get(key) || 0) + seconds);
    });
    totalsByRoleExample.forEach((seconds, key) => {
      const role = key.split(":")[1] || "";
      const residual = seconds - (directByExample.get(key) || 0);
      const exampleKey = key.split(":").slice(2).join(":");
      if (residual > Math.max(1e-9, seconds * 0.01)) addSample(`${role}.other`, exampleKey, residual);
    });
  });
  return sampleBuckets;
}

function timingComponentSamplesForSummary(summary) {
  return new Map(
    Array.from(timingComponentSampleBucketsForSummary(summary).entries()).map(([key, bucket]) => [
      key,
      Array.from(bucket.values()),
    ])
  );
}

function timingComponentSourceDetailsForSummary(summary) {
  const details = new Map();
  const directByExample = new Map();
  const addDetail = (key, step, stage, seconds, note = "") => {
    const value = Number(seconds);
    if (!key || !stage || !Number.isFinite(value) || value <= 0) return;
    const detail = details.get(key) || { sources: new Map(), notes: new Set() };
    const sourceKey = `${step && step.id ? step.id : "step"}:${stage}`;
    const source = detail.sources.get(sourceKey) || {
      step: step && step.id ? step.id : "",
      stage,
      seconds: 0,
      count: 0,
    };
    source.seconds += value;
    source.count += 1;
    detail.sources.set(sourceKey, source);
    if (note) detail.notes.add(note);
    details.set(key, detail);
  };
  const addDirectForResidual = (stepId, role, exampleKey, seconds) => {
    const key = `${stepId}:${role}:${exampleKey}`;
    directByExample.set(key, (directByExample.get(key) || 0) + seconds);
  };
  (summary.steps || []).forEach((step) => {
    codecTimingMeasurements(step).forEach((record, recordIndex) => {
      const stage = String(record.stage || "").trim();
      const seconds = Number(record.duration_s);
      if (!stage || !Number.isFinite(seconds) || seconds <= 0) return;
      const parts = stage.split(".");
      const role = parts[0] || "";
      const leaf = parts.slice(1).join(".");
      const exampleKey = timingRecordSampleKey(record, step, stage, recordIndex);
      if (leaf === "setup") {
        addDetail(`${role}.setup`, step, stage, seconds, timingStageNote(step, stage, `${role}.setup`));
        return;
      }
      if (leaf === "total") return;
      const componentKey = timingComponentKey(stage, step);
      if (componentKey) {
        addDetail(componentKey, step, stage, seconds, timingStageNote(step, stage, componentKey));
        addDirectForResidual(step.id, role, exampleKey, seconds);
      }
    });
  });
  (summary.steps || []).forEach((step) => {
    const totalsByRoleExample = new Map();
    codecTimingMeasurements(step).forEach((record, recordIndex) => {
      const stage = String(record.stage || "").trim();
      const seconds = Number(record.duration_s);
      if (!stage.endsWith(".total") || !Number.isFinite(seconds) || seconds <= 0) return;
      const role = stage.split(".")[0] || "";
      const exampleKey = timingRecordSampleKey(record, step, stage, recordIndex);
      const key = `${step.id}:${role}:${exampleKey}`;
      totalsByRoleExample.set(key, (totalsByRoleExample.get(key) || 0) + seconds);
    });
    totalsByRoleExample.forEach((seconds, key) => {
      const role = key.split(":")[1] || "";
      const residual = seconds - (directByExample.get(key) || 0);
      if (residual > Math.max(1e-9, seconds * 0.01)) {
        addDetail(
          `${role}.other`,
          step,
          `${role}.total residual`,
          residual,
          `Computed as ${role}.total minus known ${role} components for this step/example.`
        );
      }
    });
  });
  return details;
}

function timingRawSourceBucketsForSummary(summary) {
  const rawByComponent = new Map();
  const directByExample = new Map();
  const addRaw = (componentKey, step, stage, sampleKey, seconds, note = "") => {
    const value = Number(seconds);
    if (!componentKey || !stage || !sampleKey || !Number.isFinite(value) || value <= 0) return;
    const sources = rawByComponent.get(componentKey) || new Map();
    const sourceKey = `${step && step.id ? step.id : "step"}:${stage}`;
    const source = sources.get(sourceKey) || {
      key: sourceKey,
      step: step && step.id ? step.id : "",
      stage,
      note,
      bucket: new Map(),
    };
    source.bucket.set(sampleKey, (source.bucket.get(sampleKey) || 0) + value);
    if (note && !source.note) source.note = note;
    sources.set(sourceKey, source);
    rawByComponent.set(componentKey, sources);
  };
  const addDirectForResidual = (stepId, role, exampleKey, seconds) => {
    const key = `${stepId}:${role}:${exampleKey}`;
    directByExample.set(key, (directByExample.get(key) || 0) + seconds);
  };
  (summary.steps || []).forEach((step) => {
    codecTimingMeasurements(step).forEach((record, recordIndex) => {
      const stage = String(record.stage || "").trim();
      const seconds = Number(record.duration_s);
      if (!stage || !Number.isFinite(seconds) || seconds <= 0) return;
      const parts = stage.split(".");
      const role = parts[0] || "";
      const leaf = parts.slice(1).join(".");
      const sampleKey = timingRecordSampleKey(record, step, stage, recordIndex);
      if (leaf === "setup") {
        addRaw(`${role}.setup`, step, stage, sampleKey, seconds, timingStageNote(step, stage, `${role}.setup`));
        return;
      }
      if (leaf === "total") return;
      const componentKey = timingComponentKey(stage, step);
      if (componentKey) {
        addRaw(componentKey, step, stage, sampleKey, seconds, timingStageNote(step, stage, componentKey));
        addDirectForResidual(step.id, role, sampleKey, seconds);
      }
    });
  });
  (summary.steps || []).forEach((step) => {
    const totalsByRoleExample = new Map();
    codecTimingMeasurements(step).forEach((record, recordIndex) => {
      const stage = String(record.stage || "").trim();
      const seconds = Number(record.duration_s);
      if (!stage.endsWith(".total") || !Number.isFinite(seconds) || seconds <= 0) return;
      const role = stage.split(".")[0] || "";
      const sampleKey = timingRecordSampleKey(record, step, stage, recordIndex);
      const key = `${step.id}:${role}:${sampleKey}`;
      totalsByRoleExample.set(key, (totalsByRoleExample.get(key) || 0) + seconds);
    });
    totalsByRoleExample.forEach((seconds, key) => {
      const role = key.split(":")[1] || "";
      const sampleKey = key.split(":").slice(2).join(":");
      const residual = seconds - (directByExample.get(key) || 0);
      if (residual > Math.max(1e-9, seconds * 0.01)) {
        addRaw(
          `${role}.other`,
          step,
          `${role}.total residual`,
          sampleKey,
          residual,
          `Computed as ${role}.total minus known ${role} components for this step/example.`
        );
      }
    });
  });
  return new Map(
    Array.from(rawByComponent.entries()).map(([componentKey, sources]) => [
      componentKey,
      Array.from(sources.values()).sort((left, right) => String(left.stage).localeCompare(String(right.stage))),
    ])
  );
}

function timingStageNote(step, stage, componentKey = "") {
  const notes = codecTimingMetadata(step).notes || {};
  return String(notes[stage] || notes[componentKey] || "").trim();
}

function timingRecordSampleKey(record, step, stage, recordIndex) {
  const indexedFields = ["example_index", "sample_index", "warmup_index", "run_index", "pass_index"];
  for (const field of indexedFields) {
    const value = record[field];
    if (value !== undefined && value !== null && value !== "") return `${field}:${value}`;
  }
  return `record:${step.id}:${stage}:${recordIndex}`;
}

function timingComponentKey(stage, step = null) {
  if (TIME_COMPONENT_BY_KEY[stage]) return stage;
  const role = String(stage || "").split(".")[0] || "";
  if (!role) return "";
  const notes = codecTimingMetadata(step).notes || {};
  const note = String(notes[stage] || "").toLowerCase();
  if (note.includes("bitstream api") || note.includes("public bitstream")) {
    if (role === "encoder") return "encoder.payload_encode";
    if (role === "decoder") return "decoder.payload_decode";
  }
  if (stage.includes("external")) return `${role}.external_call`;
  if (stage.includes("payload_model") || stage.includes("hyper_analysis") || stage.includes("hyper_synthesis")) {
    return `${role}.payload_model_inference`;
  }
  if (stage.includes("symbol_encode") || stage.includes("fixed_length_pack")) return `${role}.symbol_encode`;
  if (stage.includes("symbol_decode") || stage.includes("fixed_length_unpack")) return `${role}.symbol_decode`;
  if (stage.includes("bitstream_encode")) return `${role}.payload_encode`;
  if (stage.includes("bitstream_decode")) return `${role}.payload_decode`;
  if (stage.includes("entropy_encode") || stage.includes("compress") || stage.includes("jpeg_encode")) {
    return role === "decoder" ? "decoder.payload_decode" : `${role}.payload_encode`;
  }
  if (stage.includes("entropy_decode") || stage.includes("decompress") || stage.includes("jpeg_decode")) {
    return role === "encoder" ? "encoder.payload_encode" : `${role}.payload_decode`;
  }
  if (stage.includes("preprocess")) return `${role}.preprocess`;
  if (stage.includes("postprocess")) return `${role}.postprocess`;
  if (stage.includes("model")) return `${role}.inference`;
  return "";
}

function renderResultsDashboard(rows) {
  const sourceRows = rows || [];
  state.resultRows = sourceRows;
  const displayRows = resultSuiteFilteredRows(sourceRows);
  reconcileHiddenResultRows(displayRows);
  const eligibleFigureRows = completedFigureResultRows(displayRows, { includeHidden: true });
  const figureRows = visibleResultRows(displayRows);
  const hiddenCount = eligibleFigureRows.length - figureRows.length;
  const nonFigureCount = displayRows.length - eligibleFigureRows.length;
  const imageCount = resultImageCount(displayRows);
  if (!Number.isFinite(state.resultImageIndex) || state.resultImageIndex < 0) state.resultImageIndex = 0;
  if (imageCount > 0 && state.resultImageIndex >= imageCount) state.resultImageIndex = 0;
  const suiteFilterNote = sourceRows.length !== displayRows.length ? ` (${displayRows.length}/${sourceRows.length} match suite filter)` : "";
  els.resultsSummaryLabel.textContent = displayRows.length
    ? `${figureRows.length} completed recipe${figureRows.length === 1 ? "" : "s"} shown in figures${hiddenCount ? `, ${hiddenCount} hidden from figures` : ""}${nonFigureCount ? `, ${nonFigureCount} without completed figure evidence` : ""}${suiteFilterNote}`
    : sourceRows.length
      ? `no recipes match suite filter${suiteFilterNote}`
      : "no recipes";
  if (state.activeView === "results") {
    renderResultsHeader(rows);
  }
  if (!displayRows.length) {
    const emptyMessage = sourceRows.length ? suiteFilterEmptyMessage() : sourceEmptyMessage();
    els.resultsComparison.innerHTML = `<div class="result-empty">${escapeHtml(emptyMessage)}</div>`;
    return;
  }
  const facets = availableResultFacets(displayRows, figureRows);
  const facet = activeResultFacet(facets);
  const facetMarkup = {
    overview: () => resultOverviewPanel(displayRows, figureRows, hiddenCount, imageCount, nonFigureCount),
    examples: () => resultExamplesPanel(displayRows, imageCount),
    quality: () => resultQualityPanel(displayRows, figureRows),
    communication: () => resultCommunicationPanel(displayRows, figureRows),
    systems: () => resultSystemsPanel(displayRows, figureRows),
    exports: () => resultExportsPanel(displayRows),
  };
  els.resultsComparison.innerHTML = `
    ${resultFacetTabs(facet, facets)}
    <div class="results-facet-panels">
      ${facets.map((item) => resultFacetPanel(item.id, facetMarkup[item.id](), facet)).join("")}
    </div>
  `;
  bindResultFacetTabs();
  bindResultVisibilityButtons();
  bindRdSettingsButton();
  bindModelTimeSettingsButton();
  bindCommunicationSettingsButton();
  bindChannelResponseSettingsButton();
  bindChannelResponseFigureControls();
  bindTxPowerSettingsButton();
  bindResourceAllocationFigureControls();
  bindResourcePerformanceFigureControls();
  bindCsiFeedbackFigureControls();
  bindReceiverPhaseTrackingControls();
  bindTimeBoxSettingsButton();
  bindRdChartInteractions();
  bindDomainChartInteractions();
  bindCompareSliders();
  bindResultVariantSelectors();
  bindResultImageSelector();
  bindResultHoverInteractions();
  bindResultValueTooltips();
  bindVisualizationControls();
  bindTimingCompositionInteractions();
  bindResultExportButtons();
}

function availableResultFacets(rows, figureRows = visibleResultRows(rows)) {
  const availability = {
    overview: true,
    examples: resultRowsHaveExamples(rows),
    quality: resultRowsHavePerformanceEvidence(rows),
    communication: resultRowsHaveCommunicationEvidence(rows, figureRows),
    systems: resultRowsHaveSystemEvidence(rows),
    exports: true,
  };
  return RESULT_FACETS.filter((facet) => availability[facet.id]);
}

function activeResultFacet(facets = RESULT_FACETS) {
  const current = String(state.resultFacet || "overview");
  if ((facets || []).some((facet) => facet.id === current)) return current;
  state.resultFacet = (facets && facets[0] && facets[0].id) || "overview";
  return state.resultFacet;
}

function resultFacetTabs(active, facets = RESULT_FACETS) {
  return `
    <nav class="results-facet-tabs" role="tablist" aria-label="Result sections">
      ${(facets || []).map((facet) => `
        <button
          type="button"
          class="results-facet-button${facet.id === active ? " active" : ""}"
          id="results-facet-tab-${escapeAttr(facet.id)}"
          role="tab"
          aria-selected="${facet.id === active ? "true" : "false"}"
          aria-controls="results-facet-panel-${escapeAttr(facet.id)}"
          tabindex="${facet.id === active ? "0" : "-1"}"
          data-result-facet="${escapeAttr(facet.id)}"
        >${escapeHtml(facet.label)}</button>
      `).join("")}
    </nav>
  `;
}

function resultFacetPanel(id, markup, active) {
  return `<section id="results-facet-panel-${escapeAttr(id)}" class="results-facet-panel" role="tabpanel" aria-labelledby="results-facet-tab-${escapeAttr(id)}" data-result-facet-panel="${escapeAttr(id)}"${id === active ? "" : " hidden"}>${markup}</section>`;
}

function resultOverviewPanel(rows, figureRows, hiddenCount, imageCount, nonFigureCount = 0) {
  const variantCount = rows.reduce((sum, row) => sum + Math.max(1, resultSummaries(row).length), 0);
  const completedCount = rows.filter((row) => aggregateResultStatus(resultSummaries(row)) === "completed").length;
  const taskLabels = resultTaskLabels(rows);
  const primaryFigures = resultOverviewPrimaryFigures(figureRows);
  return `
    <section class="results-summary-strip">
      ${resultSummaryPill("Recipes", rows.length)}
      ${resultSummaryPill("Variants", variantCount)}
      ${resultSummaryPill("Completed", completedCount)}
      ${resultSummaryPill("Completed in figures", figureRows.length)}
      ${hiddenCount ? resultSummaryPill("Hidden from figures", hiddenCount) : ""}
      ${nonFigureCount ? resultSummaryPill("Without completed figure evidence", nonFigureCount) : ""}
      ${resultSummaryPill("Purposes", taskLabels.length ? taskLabels.join(", ") : "Custom / unspecified")}
      ${imageCount ? resultSummaryPill("Image samples", imageCount) : ""}
    </section>
    ${primaryFigures ? `<section class="results-overview results-chart-row results-chart-row-overview" data-results-overview-figure>${primaryFigures}</section>` : ""}
  `;
}

function resultOverviewPrimaryFigures(rows) {
  const visibleRows = rows || [];
  const resourceRows = visibleRows.filter(rowIsResourceAllocation);
  const finiteBlocklengthResourceRows = resourceRows.filter(rowHasFiniteBlocklengthAllocationEvidence);
  const csiRows = visibleRows.filter(rowIsCsiFeedback);
  const taskRows = visibleRows.filter((row) => !rowIsResourceAllocation(row) && !rowIsCsiFeedback(row));
  const spatialRows = taskRows.filter((row) => resultSummaries(row).some((summary) => Boolean(spatialResultEvidence(summary, row))));
  const neuralReceiverRows = taskRows.filter(rowIsNeuralReceiver);
  const modulationRecognitionRows = taskRows.filter(rowIsAutomaticModulationRecognition);
  const ordinaryTaskRows = taskRows.filter((row) => (
    !spatialRows.includes(row)
    && !neuralReceiverRows.includes(row)
    && !modulationRecognitionRows.includes(row)
  ));
  const resourcePrimary = resourceRows.length
    ? finiteBlocklengthResourceRows.length
      ? resourceFiniteBlocklengthOverviewFigures(finiteBlocklengthResourceRows)
      : resourceSpectralEfficiencyFigure(resourceRows) || (resultRowsHavePerformanceEvidence(resourceRows) ? resultPerformancePlots(resourceRows) : "")
    : "";
  const csiPrimary = csiRows.length
    ? csiFeedbackQualityFigure(csiRows) || csiFeedbackPreviewFigure(csiRows) || (resultRowsHavePerformanceEvidence(csiRows) ? resultPerformancePlots(csiRows) : "")
    : "";
  const figures = [
    resourcePrimary,
    csiPrimary,
    spatialRows.length ? spatialResultsFigures(spatialRows, { context: "overview" }) : "",
    neuralReceiverRows.length ? neuralReceiverPerformanceFigures(neuralReceiverRows, { overview: true }) : "",
    modulationRecognitionRows.length
      ? automaticModulationRecognitionFigures(modulationRecognitionRows, { overview: true })
      : "",
    ordinaryTaskRows.length && resultRowsHavePerformanceEvidence(ordinaryTaskRows)
      ? resultPerformancePlots(ordinaryTaskRows)
      : "",
  ].filter(Boolean);
  if (figures.length) return figures.join("");
  const exampleRows = visibleRows
    .map((row) => resultRowWithExampleKinds(row, null, new Set(["csi"])))
    .filter(Boolean);
  return exampleRows.length
    ? `<div class="result-grid overview-example-result-grid">${resultCard(exampleRows[0], 0, [exampleRows[0]], { showMetrics: false, showTiming: false })}</div>`
    : "";
}

function resultExamplesPanel(rows, imageCount) {
  const csiFeedbackRows = (rows || []).map((row) => resultRowWithExampleKinds(row, new Set(["csi"]))).filter(Boolean);
  const ordinaryRows = (rows || []).map((row) => resultRowWithExampleKinds(row, null, new Set(["csi"]))).filter(Boolean);
  return `
    ${resultImageSelector(imageCount)}
    ${csiFeedbackRows.length ? `<section class="results-overview results-chart-row">${csiFeedbackPreviewFigure(csiFeedbackRows)}</section>` : ""}
    ${ordinaryRows.length ? `<div class="result-grid examples-result-grid">${ordinaryRows.map((row, index) => resultCard(row, index, ordinaryRows, { showMetrics: false, showTiming: false })).join("")}</div>` : ""}
  `;
}

function resultTaskPresentation(taskId) {
  const presentation = RESULT_TASK_PRESENTATIONS[String(taskId || "")] || null;
  if (presentation && presentation.alias) return RESULT_TASK_PRESENTATIONS[presentation.alias] || null;
  return presentation;
}

function resultExampleKind(summary, row) {
  if (!summary) return "";
  const details = collectRunDetails(summary);
  const artifacts = details.artifacts || [];
  const taskId = summaryTaskId(summary, row);
  const presentation = resultTaskPresentation(taskId);
  const requested = presentation && presentation.example ? presentation.example : "";
  const available = (kind) => {
    if (kind === "csi") return Boolean(csiFeedbackPreview(details));
    if (kind === "generation") return Boolean(generationPairFromArtifacts(artifacts));
    if (kind === "image") return Boolean(imagePairFromArtifacts(artifacts));
    if (kind === "detection") return Boolean(detectionPairFromArtifacts(artifacts, summary));
    if (kind === "segmentation") return Boolean(segmentationPairFromArtifacts(artifacts, summary));
    if (kind === "text") return Boolean(textPairFromArtifacts(artifacts));
    if (kind === "vqa") return Boolean(vqaPairFromArtifacts(artifacts));
    if (kind === "retrieval") return Boolean(retrievalPairFromArtifacts(artifacts));
    return false;
  };
  if (requested) return available(requested) ? requested : "";
  if (presentation) return "";
  return ["generation", "image", "detection", "segmentation", "text", "vqa", "retrieval"]
    .find(available) || "";
}

function resultRowExampleKinds(row) {
  return Array.from(new Set(resultSummaries(row).map((summary) => resultExampleKind(summary, row)).filter(Boolean)));
}

function resultRowWithExampleKinds(row, includedKinds = null, excludedKinds = new Set()) {
  const summaries = resultSummaries(row).filter((summary) => {
    const kind = resultExampleKind(summary, row);
    if (!kind || excludedKinds.has(kind)) return false;
    return !includedKinds || includedKinds.has(kind);
  });
  return summaries.length ? { ...row, summary: null, summaries } : null;
}

function resultRowsHaveExamples(rows) {
  return (rows || []).some((row) => resultRowExampleKinds(row).length > 0);
}

function resultRowsHavePerformanceEvidence(rows) {
  return (rows || []).some((row) => resultSummaries(row).some((summary) => {
    const details = collectRunDetails(summary);
    if (primaryTaskMetric(details, summary, row)) return true;
    const presentation = resultTaskPresentation(summaryTaskId(summary, row));
    return Boolean(presentation && (presentation.metrics || []).some((metric) => (
      Number.isFinite(numberMetricValue(details, metric.keys || []))
    )));
  }));
}

function rowHasCommunicationErrorEvidence(row) {
  return resultSummaries(row).some((summary) => {
    const details = collectRunDetails(summary);
    return details.metrics.some((item) => /(^|\.)(ber|bler|block_error_rate)$/.test(String(item.metric || "")));
  });
}

function resultRowsHaveCommunicationEvidence(rows, figureRows = visibleResultRows(rows)) {
  const candidates = [...(rows || []), ...(figureRows || [])];
  return candidates.some((row) => (
    rowIsResourceAllocation(row) ||
    rowIsCsiFeedback(row) ||
    rowHasPhysicalWirelessChannel(row) ||
    rowHasCommunicationErrorEvidence(row)
  ));
}

function summaryHasSystemEvidence(summary) {
  const details = collectRunDetails(summary);
  if ((summary.steps || []).some((step) => codecTimingMeasurements(step).length > 0)) return true;
  if (details.metrics.some((item) => (
    String(item.metric || "").includes("codec_timing") ||
    /(^|\.)(peak_rss_bytes|max_memory_bytes|model_size_bytes|artifact_bytes)$/.test(String(item.metric || ""))
  ))) return true;
  return ["encoder", "decoder"].some((side) => Number.isFinite(modelArtifactBytes(details, side)));
}

function resultRowsHaveSystemEvidence(rows) {
  return (rows || []).some((row) => resultSummaries(row).some(summaryHasSystemEvidence));
}

function resultQualityPanel(rows, figureRows) {
  const resourceFigureRows = (figureRows || []).filter(rowIsResourceAllocation);
  const csiFeedbackFigureRows = (figureRows || []).filter(rowIsCsiFeedback);
  const taskFigureRows = (figureRows || []).filter((row) => !rowIsResourceAllocation(row) && !rowIsCsiFeedback(row));
  return `
    <section class="results-overview results-chart-row results-chart-row-performance">
      ${resourceFigureRows.length ? resourceSpectralEfficiencyFigure(resourceFigureRows) : ""}
      ${csiFeedbackFigureRows.length ? csiFeedbackQualityFigure(csiFeedbackFigureRows) : ""}
      ${taskFigureRows.length ? spatialResultsFigures(taskFigureRows, { context: "performance" }) : ""}
      ${taskFigureRows.length ? resultPerformancePlots(taskFigureRows) : ""}
    </section>
    ${resultMetricTableSections(rows)}
  `;
}

function resultMetricTableSections(rows) {
  const resourceRows = (rows || []).filter(rowIsResourceAllocation);
  const finiteBlocklengthResourceRows = resourceRows.filter(rowHasFiniteBlocklengthAllocationEvidence);
  const shannonResourceRows = resourceRows.filter((row) => !rowHasFiniteBlocklengthAllocationEvidence(row));
  const csiFeedbackRows = (rows || []).filter(rowIsCsiFeedback);
  const taskRows = (rows || []).filter((row) => !rowIsResourceAllocation(row) && !rowIsCsiFeedback(row));
  return `
    ${finiteBlocklengthResourceRows.length ? `
      <section class="results-overview table-section">
        <div class="table-section-heading">Reliability-aware allocation · delayed-CSI finite-blocklength metrics</div>
        <div class="resource-comparison-scope-note">Expected goodput and predicted BLER use the current channel outcome; the allocator receives only its delayed/noisy CSI observation.</div>
        <div class="table-wrap table-wrap-tall">${resourceFiniteBlocklengthComparisonTable(finiteBlocklengthResourceRows)}</div>
      </section>
    ` : ""}
    ${shannonResourceRows.length ? `
      <section class="results-overview table-section">
        <div class="table-section-heading">Power-allocation comparison · complete-run metrics</div>
        ${resourceAllocationComparisonScopeNote()}
        <div class="table-wrap table-wrap-tall">${resourceAllocationComparisonTable(shannonResourceRows)}</div>
      </section>
      <section class="results-overview table-section">
        <div class="table-section-heading">Power-allocation diagnostics · oracle gap and constraints</div>
        <div class="table-wrap">${resourceAllocationDiagnosticsTable(shannonResourceRows)}</div>
      </section>
    ` : ""}
    ${csiFeedbackRows.length ? `
      <section class="results-overview table-section">
        <div class="table-section-heading">CSI compression and feedback · complete-run comparison</div>
        <div class="resource-comparison-scope-note">Continuous feedback reports dimensions; quantized feedback reports transmitted bits.</div>
        <div class="table-wrap table-wrap-tall">${csiFeedbackComparisonTable(csiFeedbackRows)}</div>
      </section>
    ` : ""}
    ${Array.from(resultRowsGroupedByTask(taskRows).entries()).map(([taskId, groupedRows]) => `
      <section class="results-overview table-section" data-result-metrics-task="${escapeAttr(taskId)}">
        <div class="table-section-heading">${escapeHtml(taskLabel(taskId))} metrics</div>
        <div class="table-wrap">${qualityMetricsTable(groupedRows, taskId)}</div>
      </section>
    `).join("")}
  `;
}

function resultRowsGroupedByTask(rows) {
  const groups = new Map();
  (rows || []).forEach((row) => {
    const summaries = resultSummaries(row);
    if (!summaries.length) {
      const taskId = summaryTaskId(null, row) || "custom";
      if (!groups.has(taskId)) groups.set(taskId, []);
      groups.get(taskId).push(row);
      return;
    }
    const summariesByTask = new Map();
    summaries.forEach((summary) => {
      const taskId = summaryTaskId(summary, row) || "custom";
      if (!summariesByTask.has(taskId)) summariesByTask.set(taskId, []);
      summariesByTask.get(taskId).push(summary);
    });
    summariesByTask.forEach((taskSummaries, taskId) => {
      if (!groups.has(taskId)) groups.set(taskId, []);
      groups.get(taskId).push({ ...row, summary: null, summaries: taskSummaries });
    });
  });
  return groups;
}

function resultPerformancePlots(rows) {
  const groups = resultRowsGroupedByTask(rows);
  if (!groups.size) return '<div class="result-empty">No visible performance results.</div>';
  return Array.from(groups.entries()).map(([taskId, taskRows]) => `
    <div class="result-performance-group" data-result-performance-task="${escapeAttr(taskId)}">
      ${groups.size > 1 ? `<div class="table-section-heading">${escapeHtml(taskLabel(taskId))}</div>` : ""}
      ${taskId === "neural_receiver_demapping"
        ? neuralReceiverPerformanceFigures(taskRows)
        : taskId === "automatic_modulation_recognition"
          ? automaticModulationRecognitionFigures(taskRows)
        : overviewPrimaryMetricPlot(taskRows)}
    </div>
  `).join("");
}

function rowIsNeuralReceiver(row) {
  return rowTaskIds(row).includes("neural_receiver_demapping");
}

function rowIsAutomaticModulationRecognition(row) {
  return rowTaskIds(row).includes("automatic_modulation_recognition");
}

function automaticModulationRecognitionFigures(rows, options = {}) {
  const accuracyFigure = communicationScatterPlot(rows, {
    metric: "accuracy",
    title: "Modulation recognition accuracy vs SNR",
    visualizationId: options.overview
      ? "modulation-recognition-accuracy-overview"
      : "modulation-recognition-accuracy-vs-snr",
    showSettings: false,
    hideWhenEmpty: true,
  });
  if (options.overview) return accuracyFigure;
  const macroF1Figure = communicationScatterPlot(rows, {
    metric: "macro_f1",
    title: "Modulation recognition macro F1 vs SNR",
    visualizationId: "modulation-recognition-macro-f1-vs-snr",
    showSettings: false,
    hideWhenEmpty: true,
  });
  return `${accuracyFigure}${macroF1Figure}`;
}

function neuralReceiverPerformanceFigures(rows, options = {}) {
  const berFigure = communicationScatterPlot(rows, {
    metric: "ber",
    title: "Receiver BER vs SNR",
    visualizationId: options.overview ? "receiver-ber-overview" : "receiver-ber-vs-snr",
    showSettings: true,
    hideWhenEmpty: true,
  });
  if (options.overview) return berFigure;
  const blerFigure = communicationScatterPlot(rows, {
    metric: "bler",
    title: "Receiver BLER vs SNR",
    visualizationId: "receiver-bler-vs-snr",
    showSettings: true,
    hideWhenEmpty: true,
  });
  return `${berFigure}${blerFigure}`;
}

function spatialResultsFigures(rows, options = {}) {
  const context = String(options.context || "results");
  const labels = recipeDisplayLabels((rows || []).map((row) => row.recipe));
  const entries = [];
  (rows || []).forEach((row) => {
    const summaries = resultSummaries(row);
    const title = recipeDisplayName(row.recipe, labels);
    summaries.forEach((summary, index) => {
      const evidence = spatialResultEvidence(summary, row);
      if (!evidence) return;
      entries.push({
        ...evidence,
        key: resultRowKey(row),
        title: summaries.length > 1 ? `${title} - ${resultVariantLabel(summary, index)}` : title,
        color: recipeColor(row.recipe),
        context,
        index: entries.length,
      });
    });
  });
  return entries.map((entry) => (
    entry.kind === "localization"
      ? localizationMapFigure(entry)
      : entry.kind === "channel_estimation"
        ? channelEstimationHeatmapFigure(entry)
        : aoaBearingFigure(entry)
  )).join("");
}

function spatialResultEvidence(summary, row) {
  const taskId = summaryTaskId(summary, row);
  const presentation = resultTaskPresentation(taskId);
  if (!presentation || !presentation.visualization) return null;
  const details = collectRunDetails(summary);
  if (presentation.visualization === "localization_map") {
    const preview = spatialPreviewFromArtifacts(details.artifacts, "localization_preview");
    const normalized = normalizeLocalizationPreview(preview);
    return normalized ? { kind: "localization", preview: normalized } : null;
  }
  if (presentation.visualization === "aoa_bearing") {
    const preview = spatialPreviewFromArtifacts(details.artifacts, "aoa_preview")
      || aoaPreviewFromReportArtifacts(details.artifacts);
    const normalized = normalizeAoaPreview(preview);
    return normalized ? { kind: "aoa", preview: normalized } : null;
  }
  if (presentation.visualization === "channel_estimation_heatmaps") {
    const preview = spatialPreviewFromArtifacts(
      details.artifacts,
      "channel_estimation_preview",
    );
    const normalized = normalizeChannelEstimationPreview(preview);
    return normalized ? { kind: "channel_estimation", preview: normalized } : null;
  }
  return null;
}

function normalizeChannelEstimationPreview(preview) {
  if (!preview || typeof preview !== "object") return null;
  const matrix = (name) => {
    const rows = preview[name];
    if (!Array.isArray(rows) || !rows.length) return [];
    const normalized = rows.map((row) => (
      Array.isArray(row)
        ? row.map(Number).filter(Number.isFinite)
        : []
    )).filter((row) => row.length);
    if (!normalized.length) return [];
    const width = normalized[0].length;
    return normalized.every((row) => row.length === width) ? normalized : [];
  };
  const trueMagnitude = matrix("true_magnitude");
  const estimatedMagnitude = matrix("estimated_magnitude");
  const absoluteError = matrix("absolute_error");
  if (
    !trueMagnitude.length ||
    estimatedMagnitude.length !== trueMagnitude.length ||
    absoluteError.length !== trueMagnitude.length ||
    estimatedMagnitude[0].length !== trueMagnitude[0].length ||
    absoluteError[0].length !== trueMagnitude[0].length
  ) return null;
  const labels = Array.isArray(preview.link_labels)
    ? preview.link_labels.map(String)
    : trueMagnitude.map((_, index) => `Link ${index + 1}`);
  return {
    trueMagnitude,
    estimatedMagnitude,
    absoluteError,
    linkLabels: labels,
    estimatorLabel: String(preview.estimator_label || "Channel estimator"),
    snrDb: Number(preview.snr_db),
    pilotDensity: Number(preview.pilot_density),
  };
}

function channelEstimationHeatmapFigure(entry) {
  const preview = entry.preview;
  const trueMagnitude = preview.trueMagnitude;
  const estimatedMagnitude = preview.estimatedMagnitude;
  const absoluteError = preview.absoluteError;
  const magnitudeMax = Math.max(
    ...trueMagnitude.flat(),
    ...estimatedMagnitude.flat(),
    1e-12,
  );
  const errorMax = Math.max(...absoluteError.flat(), 1e-12);
  const width = 1280;
  const height = 360;
  const layout = { left: 52, top: 70, panelWidth: 370, panelHeight: 210, gap: 32 };
  const titleContext = [
    preview.estimatorLabel,
    Number.isFinite(preview.snrDb) ? `${formatMetricNumber(preview.snrDb, 4)} dB` : "",
  ].filter(Boolean).join(" · ");
  return `
    <div class="rd-chart-wrap channel-estimation-preview-chart-wrap">
      <svg class="rd-chart channel-estimation-preview-chart" data-visualization-id="channel-estimation-preview" viewBox="0 0 ${width} ${height}" preserveAspectRatio="xMidYMid meet" role="img" aria-label="True, estimated, and channel-estimation error magnitudes">
        <text class="rd-plot-title" x="${width / 2}" y="18" text-anchor="middle">MIMO-OFDM Channel Estimate${titleContext ? ` · ${escapeHtml(titleContext)}` : ""}</text>
        ${["True channel magnitude", "Estimated channel magnitude", "Absolute estimation error"].map((title, index) => `<text class="csi-feedback-heatmap-title" x="${layout.left + index * (layout.panelWidth + layout.gap) + layout.panelWidth / 2}" y="53" text-anchor="middle">${escapeHtml(title)}</text>`).join("")}
        ${csiFeedbackHeatmapCells(trueMagnitude, 0, "magnitude", layout, magnitudeMax, "linear", preview.linkLabels)}
        ${csiFeedbackHeatmapCells(estimatedMagnitude, 1, "magnitude", layout, magnitudeMax, "linear", preview.linkLabels)}
        ${csiFeedbackHeatmapCells(absoluteError, 2, "error", layout, errorMax, "linear", preview.linkLabels)}
        ${[0, 1, 2].map((index) => `<rect class="csi-feedback-heatmap-frame" x="${layout.left + index * (layout.panelWidth + layout.gap)}" y="${layout.top}" width="${layout.panelWidth}" height="${layout.panelHeight}"></rect>`).join("")}
        <text class="rd-axis-label" x="${width / 2}" y="${height - 15}">OFDM subcarrier index</text>
        <text class="rd-axis-label y" x="16" y="${layout.top + layout.panelHeight / 2}" transform="rotate(-90 16 ${layout.top + layout.panelHeight / 2})">RX–TX link</text>
        <text class="csi-feedback-scale-label" x="${width / 2}" y="${height - 34}" text-anchor="middle">Rows: ${escapeHtml(preview.linkLabels.join(", "))}${Number.isFinite(preview.pilotDensity) ? ` · pilot density ${escapeHtml(formatMetricNumber(preview.pilotDensity, 4))}` : ""}</text>
      </svg>
    </div>
  `;
}

function spatialPreviewFromArtifacts(artifacts, key) {
  for (const item of artifacts || []) {
    const metadata = item && item.artifact && item.artifact.metadata;
    for (const layer of spatialMetadataLayers(metadata)) {
      if (layer && layer[key] && typeof layer[key] === "object") return layer[key];
    }
  }
  return null;
}

function spatialMetadataLayers(metadata) {
  if (!metadata || typeof metadata !== "object") return [];
  const layers = [metadata];
  const nested = metadata.metadata;
  if (nested && typeof nested === "object") layers.push(nested);
  [metadata, nested].filter(Boolean).forEach((layer) => {
    ["problem_metadata", "estimate_metadata", "result_metadata"].forEach((key) => {
      if (layer[key] && typeof layer[key] === "object") layers.push(layer[key]);
    });
  });
  return layers;
}

function finiteCoordinatePairs(value, limit = 16) {
  if (!Array.isArray(value)) return [];
  return value.slice(0, limit).map((point) => {
    if (!Array.isArray(point) || point.length < 2) return null;
    const x = Number(point[0]);
    const y = Number(point[1]);
    return Number.isFinite(x) && Number.isFinite(y) ? [x, y] : null;
  }).filter(Boolean);
}

function finiteNumberArray(value, limit = 16) {
  if (!Array.isArray(value)) return [];
  return value.slice(0, limit).map(Number).filter(Number.isFinite);
}

function normalizeLocalizationPreview(preview) {
  if (!preview || typeof preview !== "object") return null;
  const anchors = finiteCoordinatePairs(preview.anchors, 64);
  const truth = finiteCoordinatePairs(preview.true_positions || preview.positions);
  const estimates = finiteCoordinatePairs(preview.estimated_positions || preview.estimates);
  const count = Math.min(truth.length, estimates.length);
  if (anchors.length < 3 || count < 1) return null;
  const errors = truth.slice(0, count).map((point, index) => (
    Math.hypot(estimates[index][0] - point[0], estimates[index][1] - point[1])
  ));
  return {
    anchors,
    truth: truth.slice(0, count),
    estimates: estimates.slice(0, count),
    errors,
    shownCount: count,
    totalCount: Math.max(count, Number(preview.total_example_count) || count),
    coordinateSystem: String(preview.coordinate_system || "cartesian_xy_metres"),
  };
}

function aoaPreviewFromReportArtifacts(artifacts) {
  for (const item of artifacts || []) {
    const metadata = item && item.artifact && item.artifact.metadata;
    const rows = metadata && Array.isArray(metadata.rows) ? metadata.rows : [];
    const valid = rows.filter((row) => (
      Number.isFinite(Number(row && row.true_angle_deg))
      && Number.isFinite(Number(row && row.estimated_angle_deg))
    ));
    if (!valid.length) continue;
    const layers = spatialMetadataLayers(metadata);
    const problem = layers.find((layer) => Number.isFinite(Number(layer.antenna_count))) || {};
    return {
      true_angles_deg: valid.map((row) => Number(row.true_angle_deg)),
      estimated_angles_deg: valid.map((row) => Number(row.estimated_angle_deg)),
      antenna_count: Number(problem.antenna_count) || 0,
      element_spacing_wavelengths: Number(problem.element_spacing_wavelengths) || 0.5,
      angle_convention: String(problem.angle_convention || "broadside_azimuth_degrees"),
      total_example_count: valid.length,
    };
  }
  return null;
}

function normalizeAoaPreview(preview) {
  if (!preview || typeof preview !== "object") return null;
  const truth = finiteNumberArray(preview.true_angles_deg || preview.angles_deg);
  const estimates = finiteNumberArray(preview.estimated_angles_deg || preview.estimates_deg || preview.estimates);
  const count = Math.min(truth.length, estimates.length);
  if (count < 1) return null;
  return {
    truth: truth.slice(0, count),
    estimates: estimates.slice(0, count),
    errors: truth.slice(0, count).map((angle, index) => Math.abs(estimates[index] - angle)),
    antennaCount: Math.max(2, Number(preview.antenna_count) || 2),
    spacing: Number.isFinite(Number(preview.element_spacing_wavelengths))
      ? Number(preview.element_spacing_wavelengths)
      : 0.5,
    convention: String(preview.angle_convention || "broadside_azimuth_degrees"),
    shownCount: count,
    totalCount: Math.max(count, Number(preview.total_example_count) || count),
  };
}

function localizationMapFigure(entry) {
  const width = RESULT_FIGURE_WIDTH;
  const height = RESULT_FIGURE_HEIGHT;
  const preview = entry.preview;
  const map = spatialMapTransform([...preview.anchors, ...preview.truth, ...preview.estimates], {
    left: 40,
    right: 356,
    top: 34,
    bottom: height - 30,
  });
  const xTicks = spatialLinearTicks(map.domainX, 4);
  const yTicks = spatialLinearTicks(map.domainY, 4);
  const legendX = 402;
  const visualizationId = `localization-map-${entry.context}-${entry.index + 1}`;
  return `
    <div class="rd-chart-wrap spatial-result-chart-wrap localization-map-chart-wrap" data-spatial-visualization="localization-map" style="--recipe-color: ${escapeAttr(entry.color)}">
      <svg class="rd-chart spatial-result-chart localization-map-chart" data-visualization-id="${escapeAttr(visualizationId)}" viewBox="0 0 ${width} ${height}" preserveAspectRatio="xMidYMid meet" role="img" aria-label="${escapeAttr(`${entry.title} localization geometry, anchors, true tags, and estimates`)}">
        <text class="rd-plot-title" x="${width / 2}" y="13" text-anchor="middle">${escapeHtml(`${entry.title} · Localization geometry`)}</text>
        <rect class="spatial-map-domain" x="${map.plotLeft.toFixed(1)}" y="${map.plotTop.toFixed(1)}" width="${map.plotWidth.toFixed(1)}" height="${map.plotHeight.toFixed(1)}"></rect>
        <g class="spatial-grid">
          ${xTicks.map((tick) => `<line x1="${map.x(tick).toFixed(1)}" y1="${map.plotTop.toFixed(1)}" x2="${map.x(tick).toFixed(1)}" y2="${(map.plotTop + map.plotHeight).toFixed(1)}"></line>`).join("")}
          ${yTicks.map((tick) => `<line x1="${map.plotLeft.toFixed(1)}" y1="${map.y(tick).toFixed(1)}" x2="${(map.plotLeft + map.plotWidth).toFixed(1)}" y2="${map.y(tick).toFixed(1)}"></line>`).join("")}
        </g>
        <g class="spatial-axis-values">
          ${xTicks.map((tick) => `<text x="${map.x(tick).toFixed(1)}" y="${height - 13}" text-anchor="middle">${escapeHtml(formatSpatialCoordinate(tick))}</text>`).join("")}
          ${yTicks.map((tick) => `<text x="${(map.plotLeft - 7).toFixed(1)}" y="${(map.y(tick) + 3).toFixed(1)}" text-anchor="end">${escapeHtml(formatSpatialCoordinate(tick))}</text>`).join("")}
          <text class="spatial-axis-unit" x="${(map.plotLeft + map.plotWidth / 2).toFixed(1)}" y="${height - 2}" text-anchor="middle">x (m)</text>
          <text class="spatial-axis-unit" x="9" y="${(map.plotTop + map.plotHeight / 2).toFixed(1)}" transform="rotate(-90 9 ${(map.plotTop + map.plotHeight / 2).toFixed(1)})" text-anchor="middle">y (m)</text>
        </g>
        <g class="spatial-error-vectors" data-visualization-series-key="localization-error">
          ${preview.truth.map((point, index) => `<line class="spatial-error-vector" x1="${map.x(point[0]).toFixed(1)}" y1="${map.y(point[1]).toFixed(1)}" x2="${map.x(preview.estimates[index][0]).toFixed(1)}" y2="${map.y(preview.estimates[index][1]).toFixed(1)}"></line>`).join("")}
        </g>
        <g class="spatial-anchor-series" data-visualization-series-key="localization-anchor">
          ${preview.anchors.map((point, index) => {
            const x = map.x(point[0]);
            const y = map.y(point[1]);
            const tooltip = `Anchor ${index + 1}: (${formatSpatialCoordinate(point[0])}, ${formatSpatialCoordinate(point[1])}) m`;
            return `<g class="spatial-anchor" transform="translate(${x.toFixed(1)} ${y.toFixed(1)})" tabindex="0" role="img" aria-label="${escapeAttr(tooltip)}" data-result-tooltip="${escapeAttr(tooltip)}"><path d="M0 -6 L6 5 L-6 5 Z"></path><text x="8" y="-6">A${index + 1}</text></g>`;
          }).join("")}
        </g>
        <g class="spatial-true-series" data-visualization-series-key="localization-true">
          ${preview.truth.map((point, index) => {
            const estimate = preview.estimates[index];
            const tooltip = `Tag ${index + 1}: true (${formatSpatialCoordinate(point[0])}, ${formatSpatialCoordinate(point[1])}) m; estimate (${formatSpatialCoordinate(estimate[0])}, ${formatSpatialCoordinate(estimate[1])}) m; error ${formatMetricDisplay("Localization error (m)", preview.errors[index])}`;
            return `<circle class="spatial-true-position" cx="${map.x(point[0]).toFixed(1)}" cy="${map.y(point[1]).toFixed(1)}" r="3.4" tabindex="0" role="img" aria-label="${escapeAttr(tooltip)}" data-result-tooltip="${escapeAttr(tooltip)}"></circle>`;
          }).join("")}
        </g>
        <g class="spatial-estimate-series" data-visualization-series-key="localization-estimate">
          ${preview.estimates.map((point, index) => {
            const x = map.x(point[0]);
            const y = map.y(point[1]);
            return `<path class="spatial-estimated-position" d="M${(x - 4).toFixed(1)} ${(y - 4).toFixed(1)} L${(x + 4).toFixed(1)} ${(y + 4).toFixed(1)} M${(x - 4).toFixed(1)} ${(y + 4).toFixed(1)} L${(x + 4).toFixed(1)} ${(y - 4).toFixed(1)}"></path>`;
          }).join("")}
        </g>
        <g class="spatial-inline-legend" transform="translate(${legendX} 65)">
          <g transform="translate(0 0)"><path class="spatial-anchor-key" d="M0 -5 L5 4 L-5 4 Z"></path><text x="16" y="4">Anchors</text></g>
          <g transform="translate(0 29)"><circle class="spatial-true-key" cx="0" cy="0" r="3.4"></circle><text x="16" y="4">True tag positions</text></g>
          <g transform="translate(0 58)"><path class="spatial-estimate-key" d="M-4 -4 L4 4 M-4 4 L4 -4"></path><text x="16" y="4">Estimated positions</text></g>
          <g transform="translate(0 87)"><line class="spatial-error-key" x1="-5" y1="0" x2="7" y2="0"></line><text x="16" y="4">Estimation error</text></g>
          <text class="spatial-evidence-count" x="0" y="124">${escapeHtml(spatialEvidenceCountLabel(preview))}</text>
        </g>
      </svg>
    </div>
  `;
}

function spatialMapTransform(points, bounds) {
  const xs = points.map((point) => point[0]);
  const ys = points.map((point) => point[1]);
  let minX = Math.min(...xs);
  let maxX = Math.max(...xs);
  let minY = Math.min(...ys);
  let maxY = Math.max(...ys);
  const span = Math.max(maxX - minX, maxY - minY, 1e-6);
  const padding = Math.max(span * 0.06, 0.1);
  const centerX = (minX + maxX) / 2;
  const centerY = (minY + maxY) / 2;
  const domainSpan = span + 2 * padding;
  minX = centerX - domainSpan / 2;
  maxX = centerX + domainSpan / 2;
  minY = centerY - domainSpan / 2;
  maxY = centerY + domainSpan / 2;
  const availableWidth = bounds.right - bounds.left;
  const availableHeight = bounds.bottom - bounds.top;
  const plotSize = Math.min(availableWidth, availableHeight);
  const plotLeft = bounds.left + (availableWidth - plotSize) / 2;
  const plotTop = bounds.top + (availableHeight - plotSize) / 2;
  return {
    domainX: [minX, maxX],
    domainY: [minY, maxY],
    plotLeft,
    plotTop,
    plotWidth: plotSize,
    plotHeight: plotSize,
    x: (value) => plotLeft + ((value - minX) / (maxX - minX)) * plotSize,
    y: (value) => plotTop + plotSize - ((value - minY) / (maxY - minY)) * plotSize,
  };
}

function spatialLinearTicks(domain, intervalCount) {
  const count = Math.max(1, Number(intervalCount) || 1);
  return Array.from({ length: count + 1 }, (_item, index) => (
    domain[0] + ((domain[1] - domain[0]) * index) / count
  ));
}

function formatSpatialCoordinate(value) {
  const number = Number(value);
  if (!Number.isFinite(number)) return "";
  if (Math.abs(number) >= 10) return number.toFixed(1).replace(/\.0$/, "");
  return number.toFixed(2).replace(/0+$/, "").replace(/\.$/, "");
}

function spatialEvidenceCountLabel(preview) {
  return preview.totalCount > preview.shownCount
    ? `${preview.shownCount} of ${preview.totalCount} examples shown`
    : `${preview.shownCount} ${preview.shownCount === 1 ? "example" : "examples"}`;
}

function bearingPoint(centerX, centerY, radius, angleDeg) {
  const radians = Number(angleDeg) * Math.PI / 180;
  return {
    x: centerX + radius * Math.sin(radians),
    y: centerY - radius * Math.cos(radians),
  };
}

function aoaBearingFigure(entry) {
  const width = RESULT_FIGURE_WIDTH;
  const height = RESULT_FIGURE_HEIGHT;
  const preview = entry.preview;
  const sampleIndex = 0;
  const truth = preview.truth[sampleIndex];
  const estimate = preview.estimates[sampleIndex];
  const error = preview.errors[sampleIndex];
  const center = { x: 320, y: height - 34 };
  const radius = 188;
  const truePoint = bearingPoint(center.x, center.y, radius, truth);
  const estimatePoint = bearingPoint(center.x, center.y, radius, estimate);
  const arcRadius = 108;
  const arcStart = bearingPoint(center.x, center.y, arcRadius, Math.min(truth, estimate));
  const arcEnd = bearingPoint(center.x, center.y, arcRadius, Math.max(truth, estimate));
  const antennaDrawCount = Math.min(16, preview.antennaCount);
  const antennaSpacing = antennaDrawCount > 1 ? 184 / (antennaDrawCount - 1) : 0;
  const visualizationId = `aoa-bearing-${entry.context}-${entry.index + 1}`;
  const shownExampleLabel = preview.totalCount > 1 ? `Showing example 1 of ${preview.totalCount}` : "1 example";
  const tooltip = `Example 1: true angle ${formatSpatialCoordinate(truth)} degrees; estimated angle ${formatSpatialCoordinate(estimate)} degrees; absolute error ${formatSpatialCoordinate(error)} degrees`;
  return `
    <div class="rd-chart-wrap spatial-result-chart-wrap aoa-bearing-chart-wrap" data-spatial-visualization="aoa-bearing" style="--recipe-color: ${escapeAttr(entry.color)}">
      <svg class="rd-chart spatial-result-chart aoa-bearing-chart" data-visualization-id="${escapeAttr(visualizationId)}" viewBox="0 0 ${width} ${height}" preserveAspectRatio="xMidYMid meet" role="img" aria-label="${escapeAttr(`${entry.title} ULA true and estimated angle of arrival`)}">
        <text class="rd-plot-title" x="${width / 2}" y="13" text-anchor="middle">${escapeHtml(`${entry.title} · AoA bearing`)}</text>
        <g class="aoa-angle-grid spatial-grid">
          <path d="M${bearingPoint(center.x, center.y, radius, -75).x.toFixed(1)} ${bearingPoint(center.x, center.y, radius, -75).y.toFixed(1)} A${radius} ${radius} 0 0 1 ${bearingPoint(center.x, center.y, radius, 75).x.toFixed(1)} ${bearingPoint(center.x, center.y, radius, 75).y.toFixed(1)}"></path>
          ${[-60, -30, 0, 30, 60].map((angle) => {
            const inner = bearingPoint(center.x, center.y, radius - 8, angle);
            const outer = bearingPoint(center.x, center.y, radius + 2, angle);
            const label = bearingPoint(center.x, center.y, radius + 15, angle);
            return `<line x1="${inner.x.toFixed(1)}" y1="${inner.y.toFixed(1)}" x2="${outer.x.toFixed(1)}" y2="${outer.y.toFixed(1)}"></line><text x="${label.x.toFixed(1)}" y="${(label.y + 3).toFixed(1)}" text-anchor="middle">${angle}°</text>`;
          }).join("")}
          <line class="aoa-broadside" x1="${center.x}" y1="${center.y}" x2="${center.x}" y2="${(center.y - radius).toFixed(1)}"></line>
        </g>
        <g class="aoa-bearing-evidence" tabindex="0" role="img" aria-label="${escapeAttr(tooltip)}" data-result-tooltip="${escapeAttr(tooltip)}">
          <line class="aoa-true-bearing" data-visualization-series-key="aoa-true" x1="${center.x}" y1="${center.y}" x2="${truePoint.x.toFixed(1)}" y2="${truePoint.y.toFixed(1)}"></line>
          <line class="aoa-estimated-bearing" data-visualization-series-key="aoa-estimate" x1="${center.x}" y1="${center.y}" x2="${estimatePoint.x.toFixed(1)}" y2="${estimatePoint.y.toFixed(1)}"></line>
          ${error > 0.0001 ? `<path class="aoa-error-arc" data-visualization-series-key="aoa-error" d="M${arcStart.x.toFixed(1)} ${arcStart.y.toFixed(1)} A${arcRadius} ${arcRadius} 0 0 1 ${arcEnd.x.toFixed(1)} ${arcEnd.y.toFixed(1)}"></path>` : ""}
        </g>
        <g class="aoa-array" data-visualization-series-key="aoa-array">
          <line x1="${center.x - 104}" y1="${center.y}" x2="${center.x + 104}" y2="${center.y}"></line>
          ${Array.from({ length: antennaDrawCount }, (_item, index) => `<circle cx="${(center.x - 92 + index * antennaSpacing).toFixed(1)}" cy="${center.y}" r="4"></circle>`).join("")}
          <text x="${center.x}" y="${height - 8}" text-anchor="middle">${preview.antennaCount}-element ULA · ${formatSpatialCoordinate(preview.spacing)}λ spacing</text>
        </g>
        <g class="aoa-readout" transform="translate(478 61)">
          <text class="aoa-readout-label" x="0" y="0">Example 1</text>
          <text x="0" y="24">True <tspan class="aoa-true-text">${escapeHtml(formatSpatialCoordinate(truth))}°</tspan></text>
          <text x="0" y="46">Estimate <tspan class="aoa-estimate-text">${escapeHtml(formatSpatialCoordinate(estimate))}°</tspan></text>
          <text x="0" y="68">Error <tspan class="aoa-error-text">${escapeHtml(formatSpatialCoordinate(error))}°</tspan></text>
          <text class="spatial-evidence-count" x="0" y="100">${escapeHtml(shownExampleLabel)}</text>
        </g>
        <g class="spatial-inline-legend aoa-inline-legend" transform="translate(34 68)">
          <g transform="translate(0 0)"><line class="aoa-true-key" x1="0" y1="0" x2="18" y2="0"></line><text x="28" y="4">True bearing</text></g>
          <g transform="translate(0 28)"><line class="aoa-estimate-key" x1="0" y1="0" x2="18" y2="0"></line><text x="28" y="4">Estimated bearing</text></g>
          <text class="aoa-convention-label" x="0" y="62">0° = broadside</text>
        </g>
      </svg>
    </div>
  `;
}

function overviewPrimaryMetricPlot(rows) {
  const presentation = rateDistortionPresentation(rows);
  const rdRows = rateDistortionEligibleRows(rows);
  if (rdRows.length) {
    const omitted = Math.max(0, (rows || []).length - rdRows.length);
    const note = omitted
      ? `<div class="rd-chart-note">${escapeHtml(String(omitted))} ${omitted === 1 ? "result is" : "results are"} omitted from this rate-distortion plot because PSNR or rate accounting is unavailable.</div>`
      : "";
    const accountingNote = presentation.note
      ? `<div class="rd-chart-note">${escapeHtml(presentation.note)}</div>`
      : "";
    return `<div class="rd-chart-note-wrap">${rateDistortionPlot(rdRows, presentation)}${accountingNote}${note}</div>`;
  }
  return taskPerformancePlot(rows);
}

function rateDistortionEligibleRows(rows) {
  const presentation = rateDistortionPresentation(rows);
  const definitions = scatterMetricDefinitions(rows || []);
  const settings = presentation.settings || RD_DEFAULT_SETTINGS;
  return (rows || []).filter((row) =>
    resultSummaries(row).some((summary) => {
      const details = collectRunDetails(summary);
      return Number.isFinite(scatterMetricValue(details, settings.x, settings.xStat, summary, definitions))
        && Number.isFinite(scatterMetricValue(details, settings.y, settings.yStat, summary, definitions));
    })
  );
}

function rateDistortionPresentation(rows) {
  const summaries = (rows || []).flatMap((row) => resultSummaries(row));
  const imageOnly = summaries.length > 0 && summaries.every((summary) => (
    summaryTaskId(summary, null) === "image_reconstruction"
  ));
  if (!imageOnly) {
    return {
      context: "generic-rate-distortion",
      settings: { ...RD_DEFAULT_SETTINGS },
      title: "Rate Distortion",
      ariaLabel: "Rate distortion plot",
      note: "",
    };
  }
  const accounted = summaries.map((summary) => {
    const details = collectRunDetails(summary);
    return {
      bandwidthRatio: channelUsesPerSourcePixel(details),
      bpp: transmittedBitsPerSourcePixel(details),
    };
  });
  const allDigital = accounted.length > 0 && accounted.every((item) => Number.isFinite(item.bpp));
  if (allDigital) {
    return {
      context: "image-reconstruction-digital-rate",
      settings: { ...RD_DEFAULT_SETTINGS },
      title: "Image Reconstruction · Rate–Distortion",
      ariaLabel: "Image reconstruction distortion versus transmitted bits per source pixel",
      note: "x: measured transmit-boundary bits per source pixel (bpp). This is on-air coded bpp; with identity channel coding it is the sent codec-bitstream bpp, while FEC or framing can make it differ from compression-only source-codec bpp.",
    };
  }
  const hasChannelResource = accounted.some((item) => Number.isFinite(item.bandwidthRatio));
  if (!hasChannelResource) {
    return {
      context: "image-reconstruction-digital-rate",
      settings: { ...RD_DEFAULT_SETTINGS },
      title: "Image Reconstruction · Rate–Distortion",
      ariaLabel: "Image reconstruction rate distortion plot",
      note: "A measured transmitted bitstream is required for bpp; continuous-symbol runs require measured channel uses instead.",
    };
  }
  const includesDigital = accounted.some((item) => Number.isFinite(item.bpp));
  return {
    context: "image-reconstruction-channel-resource",
    settings: { ...IMAGE_RECONSTRUCTION_RESOURCE_SETTINGS },
    title: "Image Reconstruction · Rate–Distortion",
    ariaLabel: "Image reconstruction distortion versus complex channel uses per source pixel",
    note: includesDigital
      ? "x: common physical-channel resource in complex channel uses per source pixel. Digital transmit bpp remains available in point details; continuous-symbol JSCC has no transmitted bitstream to count."
      : "x: measured complex channel uses per source pixel; continuous-symbol JSCC has no transmitted bitstream to count.",
  };
}

function taskPerformancePlot(rows) {
  const labels = recipeDisplayLabels((rows || []).map((row) => row.recipe));
  const points = taskPerformancePoints(rows, labels);
  if (!points.length) {
    return `
      <div class="rd-chart-wrap task-performance-chart-wrap empty">
        <div class="result-empty">Run task recipes with task metrics to draw task performance.</div>
      </div>
    `;
  }
  const width = RESULT_FIGURE_WIDTH;
  const height = RESULT_FIGURE_HEIGHT;
  const margin = { left: 68, right: 18, top: 18, bottom: 58 };
  const plotWidth = width - margin.left - margin.right;
  const values = points.map((point) => point.y);
  const labelsSet = new Set(points.map((point) => point.metricLabel));
  const taskSet = new Set(points.map((point) => point.task));
  const visualizationId = `task-performance-${slugName(Array.from(taskSet).join("-")) || "custom"}`;
  const supportsLog = values.every((value) => value > 0);
  const defaultLog = points.every((point) => point.scale === "log" && point.y > 0);
  const useLog = supportsLog && visualizationAxisLogEnabled(visualizationId, "y", defaultLog);
  const scoreLike = !useLog && values.every((value) => value >= 0 && value <= 1.000001);
  const yDomain = scoreLike ? [0, 1] : chartDomainForValues(values, 0.12, !useLog && values.every((value) => value >= 0), useLog);
  const yScale = chartScale(yDomain, height - margin.bottom, margin.top, useLog);
  const yTicks = chartTicksForDomain(yDomain, 4, useLog);
  const step = plotWidth / Math.max(1, points.length);
  const barWidth = Math.max(8, Math.min(34, step * 0.52));
  const xFor = (index) => margin.left + step * index + step / 2;
  const axisLabel = labelsSet.size === 1 ? points[0].metricLabel : "Primary task metric";
  const purposeLabel = taskSet.size === 1 ? points[0].task : "Task comparison";
  const plotTitle = labelsSet.size === 1 ? `${purposeLabel} · ${axisLabel}` : purposeLabel;
  return `
    <div class="rd-chart-wrap task-performance-chart-wrap">
      <svg class="rd-chart task-performance-chart" data-visualization-id="${escapeAttr(visualizationId)}"${supportsLog ? ' data-log-axes="y"' : ""} data-y-log="${useLog ? "true" : "false"}" viewBox="0 0 ${width} ${height}" preserveAspectRatio="xMidYMid meet" role="img" aria-label="${escapeAttr(plotTitle)} plot">
        <text class="rd-plot-title" x="${width / 2}" y="12" text-anchor="middle">${escapeHtml(plotTitle)}</text>
        <line class="rd-axis" x1="${margin.left}" y1="${height - margin.bottom}" x2="${width - margin.right}" y2="${height - margin.bottom}"></line>
        <line class="rd-axis" x1="${margin.left}" y1="${margin.top}" x2="${margin.left}" y2="${height - margin.bottom}"></line>
        ${yTicks.map((tick) => `
          <g class="rd-tick y">
            <line x1="${margin.left}" y1="${yScale(tick)}" x2="${width - margin.right}" y2="${yScale(tick)}"></line>
            <text x="${margin.left - 12}" y="${yScale(tick) + 3}">${escapeHtml(formatTaskMetricTick(tick, axisLabel))}</text>
          </g>
        `).join("")}
        ${points.map((point, index) => {
          const x = xFor(index);
          const y = yScale(point.y);
          const base = yScale(useLog ? yDomain[0] : Math.max(0, yDomain[0]));
          const top = Math.min(y, base);
          const heightValue = Math.max(1, Math.abs(base - y));
          return `
            <g class="task-performance-point" data-result-key="${escapeAttr(point.key)}" data-draw-order="${index}" transform="translate(${x.toFixed(1)}, 0)" style="--recipe-color: ${escapeAttr(point.color)}" tabindex="0" role="img" aria-label="${escapeAttr(taskPerformancePointTitle(point))}" data-result-tooltip="${escapeAttr(taskPerformancePointTitle(point))}">
              <rect x="${(-barWidth / 2).toFixed(1)}" y="${top.toFixed(1)}" width="${barWidth.toFixed(1)}" height="${heightValue.toFixed(1)}"></rect>
              <circle cx="0" cy="${y.toFixed(1)}" r="4.5"></circle>
              <text class="task-performance-value" x="0" y="${(y - 8).toFixed(1)}" text-anchor="middle">${escapeHtml(formatMetricDisplay(point.metricLabel, point.y))}</text>
              <text class="task-performance-label" x="0" y="${height - 18}" transform="rotate(-28 0 ${height - 18})">${escapeHtml(trim(point.label, 18))}</text>
            </g>
          `;
        }).join("")}
        <text class="rd-axis-label y" x="14" y="${height / 2}" transform="rotate(-90 14 ${height / 2})">${escapeHtml(axisLabel)}</text>
      </svg>
    </div>
  `;
}

function taskPerformancePoints(rows, labels) {
  const points = [];
  (rows || []).forEach((row) => {
    const title = recipeDisplayName(row.recipe, labels);
    const summaries = resultSummaries(row);
    summaries.forEach((summary, index) => {
      const details = collectRunDetails(summary);
      const metric = primaryTaskMetric(details, summary, row);
      if (!metric || !Number.isFinite(metric.value)) return;
      points.push({
        key: resultRowKey(row),
        title: summaries.length > 1 ? `${title} - ${resultVariantLabel(summary, index)}` : title,
        label: summaries.length > 1 ? resultVariantValueLabel(summary, index) : title,
        task: summaryTaskLabel(summary, row),
        metricLabel: metric.label,
        y: metric.value,
        display: metric.display,
        direction: metric.direction || "higher_is_better",
        scale: metric.scale || "linear",
        color: recipeColor(row.recipe),
      });
    });
  });
  return points;
}

function primaryTaskMetric(details, summary, row) {
  const taskId = summaryTaskId(summary, row);
  const presentation = resultTaskPresentation(taskId);
  const candidates = (presentation && presentation.primaryMetrics) || [];
  for (const candidate of candidates) {
    const value = numberMetricValue(details, candidate.keys || []);
    if (Number.isFinite(value)) {
      return {
        label: candidate.label,
        value,
        display: formatMetricDisplay(candidate.label, value),
        direction: candidate.direction || "higher_is_better",
        scale: candidate.scale || "linear",
      };
    }
  }
  const genericCandidates = [
    { label: "Task score", keys: ["evaluation.task.score", "task.score"], direction: "higher_is_better" },
    { label: "Task accuracy", keys: ["evaluation.task.accuracy", "task.accuracy"], direction: "higher_is_better" },
    { label: "Spectral efficiency (bit/s/Hz)", keys: ["evaluation.channel.spectral_efficiency_bps_hz", "channel.spectral_efficiency_bps_hz"], direction: "higher_is_better" },
  ];
  for (const candidate of genericCandidates) {
    const value = numberMetricValue(details, candidate.keys);
    if (Number.isFinite(value)) {
      return {
        label: candidate.label,
        value,
        display: formatMetricDisplay(candidate.label, value),
        direction: candidate.direction,
        scale: "linear",
      };
    }
  }
  const fallback = overviewQualityMetric(details);
  return Number.isFinite(fallback.value)
    ? { ...fallback, direction: "higher_is_better", scale: "linear" }
    : null;
}

function summaryTaskId(summary, row) {
  const recipe = (summary && summary.recipe) || (row && row.recipe && row.recipe.recipe) || {};
  const benchmarkTask = row && row.benchmarkResult && row.benchmarkResult.benchmark
    ? row.benchmarkResult.benchmark.task
    : null;
  const benchmarkTaskId = benchmarkTask && typeof benchmarkTask === "object" ? benchmarkTask.id : "";
  return recipeDeclaredTaskId(recipe) || benchmarkTaskId || currentRecipeTaskId(recipe) || "";
}

function formatTaskMetricTick(value, label) {
  const number = Number(value);
  if (!Number.isFinite(number)) return formatValue(value);
  const text = String(label || "").toLowerCase();
  if (number >= 0 && number <= 1 && (text.includes("accuracy") || text.includes("recall") || text.includes("iou") || text.includes("f1") || text.includes("match"))) {
    return number.toFixed(2).replace(/0+$/, "").replace(/\.$/, "");
  }
  return formatRdTick(number, "task_metric");
}

function taskPerformancePointTitle(point) {
  const direction = point.direction === "lower_is_better" ? ", lower is better" : "";
  return `${point.title}: ${point.metricLabel} ${point.display || formatMetricDisplay(point.metricLabel, point.y)} (${point.task}${direction})`;
}

function resultCommunicationPanel(rows, figureRows = visibleResultRows(rows)) {
  const resourceRows = (rows || []).filter(rowIsResourceAllocation);
  const resourceFigureRows = (figureRows || []).filter(rowIsResourceAllocation);
  const payloadDeliveryResourceRows = resourceFigureRows.filter((row) => !rowHasFiniteBlocklengthAllocationEvidence(row));
  const modeledFiniteBlocklengthRow = (row) => (
    rowIsResourceAllocation(row) && rowHasFiniteBlocklengthAllocationEvidence(row)
  );
  const csiFeedbackRows = (rows || []).filter(rowIsCsiFeedback);
  const csiFeedbackFigureRows = (figureRows || []).filter(rowIsCsiFeedback);
  const physicalRows = (figureRows || []).filter(rowHasPhysicalWirelessChannel);
  const errorRateRows = (figureRows || []).filter((row) => (
    !modeledFiniteBlocklengthRow(row) && rowHasCommunicationErrorEvidence(row)
  ));
  const communicationTableRows = (rows || []).filter((row) => (
    !modeledFiniteBlocklengthRow(row) &&
    (rowHasPhysicalWirelessChannel(row) || rowHasCommunicationErrorEvidence(row))
  ));
  const receiverDecisionFigure = receiverDecisionRegionFigure(figureRows || []);
  const phaseTrackingFigure = receiverPhaseTrackingFigure(figureRows || []);
  return `
    <section class="results-overview results-chart-row results-chart-row-communication">
      ${csiFeedbackRows.length && csiFeedbackFigureRows.length ? csiFeedbackRateFigure(csiFeedbackFigureRows) : ""}
      ${resourceRows.length && resourceFigureRows.length ? resourceAllocationFigure(resourceFigureRows) : ""}
      ${resourceRows.length && payloadDeliveryResourceRows.length ? resourceDeliveryFigure(payloadDeliveryResourceRows) : ""}
      ${errorRateRows.length ? communicationScatterPlot(errorRateRows) : ""}
      ${receiverDecisionFigure}
      ${phaseTrackingFigure}
      ${physicalRows.length ? channelResponseSeriesPlot(physicalRows) : ""}
      ${physicalRows.length ? txPowerBeforeAfterPlot(physicalRows) : ""}
      ${physicalRows.length ? txPowerSeriesPlot(physicalRows) : ""}
    </section>
    ${communicationTableRows.length ? `
      <section class="results-overview table-section">
        <div class="table-wrap table-wrap-tall">${communicationMetricsTable(communicationTableRows)}</div>
      </section>
    ` : ""}
  `;
}

function receiverDecisionPreview(details) {
  for (const item of (details && details.artifacts) || []) {
    const metadata = item && item.artifact && item.artifact.metadata;
    if (!metadata || typeof metadata !== "object") continue;
    const candidates = [
      metadata.receiver_decision_preview,
      metadata.metadata && metadata.metadata.receiver_decision_preview,
    ];
    for (const candidate of candidates) {
      const normalized = normalizeReceiverDecisionPreview(candidate);
      if (normalized) return normalized;
    }
  }
  return null;
}

function normalizeReceiverDecisionPreview(preview) {
  if (!preview || typeof preview !== "object") return null;
  if (String(preview.kind || "") !== "memoryless_qpsk_iq_decision_regions") return null;
  const grid = preview.grid && typeof preview.grid === "object" ? preview.grid : {};
  const width = Number(grid.width);
  const height = Number(grid.height);
  const iMin = Number(grid.i_min);
  const iMax = Number(grid.i_max);
  const qMin = Number(grid.q_min);
  const qMax = Number(grid.q_max);
  const classRows = Array.isArray(grid.class_rows) ? grid.class_rows.map((row) => String(row)) : [];
  if (
    !Number.isInteger(width) || !Number.isInteger(height) || width < 2 || height < 2 ||
    width > 96 || height > 96 || !(iMax > iMin) || !(qMax > qMin) ||
    classRows.length !== height || classRows.some((row) => row.length !== width || /[^0-3]/.test(row))
  ) return null;
  const constellation = (Array.isArray(preview.constellation) ? preview.constellation : [])
    .map((point) => ({
      classId: Number(point && point.class_id),
      bits: String(point && point.bits || ""),
      i: Number(point && point.i),
      q: Number(point && point.q),
    }))
    .filter((point) => (
      Number.isInteger(point.classId) && point.classId >= 0 && point.classId <= 3 &&
      /^[01]{2}$/.test(point.bits) && Number.isFinite(point.i) && Number.isFinite(point.q)
    ));
  if (constellation.length !== 4) return null;
  return {
    receiverMode: String(preview.receiver_mode || "qpsk_receiver"),
    receiverLabel: String(preview.receiver_label || "QPSK receiver"),
    modelSha256: String(preview.model_sha256 || ""),
    coordinateSpace: String(preview.coordinate_space || "received_iq"),
    width,
    height,
    iMin,
    iMax,
    qMin,
    qMax,
    classRows,
    constellation,
  };
}

function receiverDecisionBenchmarkSeries(row, methodId) {
  const metadata = row && row.benchmarkResult && row.benchmarkResult.benchmark
    ? row.benchmarkResult.benchmark.metadata || {}
    : {};
  const demo = metadata && typeof metadata.demo === "object" ? metadata.demo : {};
  const series = Array.isArray(demo.series) ? demo.series : [];
  return series.find((item) => item && String(item.id || "") === methodId) || null;
}

function receiverDecisionEntries(rows) {
  const labels = recipeDisplayLabels((rows || []).map((row) => row.recipe));
  const entries = [];
  const signatures = new Set();
  (rows || []).forEach((row) => {
    resultSummaries(row).forEach((summary) => {
      const preview = receiverDecisionPreview(collectRunDetails(summary));
      if (!preview) return;
      const recipeMetadata = summary && summary.recipe && summary.recipe.metadata ? summary.recipe.metadata : {};
      const benchmarkMethod = String(recipeMetadata.benchmark_method || "").trim();
      const benchmarkLabel = String(row && row.benchmarkEntry && row.benchmarkEntry.label || "").trim();
      const series = benchmarkMethod
        ? receiverDecisionBenchmarkSeries(row, benchmarkMethod)
        : null;
      const ordinaryMethodId = resultRowKey(row) || preview.receiverMode;
      const methodId = series ? benchmarkMethod : ordinaryMethodId;
      const recipeLabel = recipeDisplayName(row.recipe, labels);
      const methodLabel = String(
        series && series.label ||
        recipeLabel ||
        benchmarkLabel ||
        preview.receiverLabel
      );
      const signature = series
        ? `${methodId}\u0000${preview.modelSha256 || preview.receiverMode}`
        : `${ordinaryMethodId}\u0000${preview.modelSha256 || preview.receiverMode}`;
      if (signatures.has(signature)) return;
      signatures.add(signature);
      entries.push({
        ...preview,
        key: resultRowKey(row),
        methodId,
        methodLabel,
        color: series
          ? benchmarkMethodColor(row, methodId, recipeColor(row.recipe))
          : recipeColor(row.recipe),
      });
    });
  });
  return entries;
}

function receiverDecisionBoundaryPath(entry, plot) {
  const cellWidth = plot.width / entry.width;
  const cellHeight = plot.height / entry.height;
  const segments = [];
  entry.classRows.forEach((row, sourceRow) => {
    const visualRow = entry.height - sourceRow - 1;
    for (let column = 1; column < entry.width; column += 1) {
      if (row[column] === row[column - 1]) continue;
      const x = plot.left + column * cellWidth;
      const y = plot.top + visualRow * cellHeight;
      segments.push(`M${x.toFixed(2)},${y.toFixed(2)}v${cellHeight.toFixed(2)}`);
    }
  });
  for (let sourceRow = 1; sourceRow < entry.height; sourceRow += 1) {
    const previous = entry.classRows[sourceRow - 1];
    const current = entry.classRows[sourceRow];
    const y = plot.top + (entry.height - sourceRow) * cellHeight;
    for (let column = 0; column < entry.width; column += 1) {
      if (current[column] === previous[column]) continue;
      const x = plot.left + column * cellWidth;
      segments.push(`M${x.toFixed(2)},${y.toFixed(2)}h${cellWidth.toFixed(2)}`);
    }
  }
  return segments.join("");
}

function receiverDecisionRegionFigure(rows) {
  const entries = receiverDecisionEntries(rows);
  if (!entries.length) return "";
  const width = RESULT_FIGURE_WIDTH;
  const reference = entries[0];
  const plotSize = Math.min(320, width - 116);
  const plot = {
    left: (width - plotSize) / 2,
    top: 31,
    width: plotSize,
    height: plotSize,
  };
  const xScale = (value) => plot.left + ((value - reference.iMin) / (reference.iMax - reference.iMin)) * plot.width;
  const yScale = (value) => plot.top + plot.height - ((value - reference.qMin) / (reference.qMax - reference.qMin)) * plot.height;
  const ticks = [reference.iMin, 0, reference.iMax];
  const dashPatterns = ["", "7 4", "2 3", "10 3 2 3"];
  const legendColumns = entries.length === 1 ? 1 : 2;
  const legendRows = Math.ceil(entries.length / legendColumns);
  const legendWidth = Math.min(238, (width - 40) / legendColumns);
  const legendTop = plot.top + plot.height + 48;
  const height = legendTop + legendRows * 22 + 10;
  const constellationCenter = reference.constellation.reduce(
    (sum, point) => ({
      i: sum.i + point.i / reference.constellation.length,
      q: sum.q + point.q / reference.constellation.length,
    }),
    { i: 0, q: 0 },
  );
  const boundaries = entries.map((entry, index) => {
    const color = entry.color || recipeColorForIndex(index);
    const dash = dashPatterns[index % dashPatterns.length];
    return `
      <path
        class="receiver-decision-boundary visualization-series"
        data-method-id="${escapeAttr(entry.methodId)}"
        data-visualization-series-key="${escapeAttr(entry.methodId)}"
        d="${receiverDecisionBoundaryPath(entry, plot)}"
        style="stroke:${escapeAttr(color)}${dash ? `;stroke-dasharray:${dash}` : ""}"
      ><title>${escapeHtml(entry.methodLabel)}</title></path>
    `;
  }).join("");
  const legend = entries.map((entry, index) => {
    const column = index % legendColumns;
    const row = Math.floor(index / legendColumns);
    const x = width / 2 - (legendColumns * legendWidth) / 2 + column * legendWidth;
    const y = legendTop + row * 22;
    const color = entry.color || recipeColorForIndex(index);
    const dash = dashPatterns[index % dashPatterns.length];
    return `
      <g
        class="receiver-decision-method-legend visualization-series-legend"
        data-visualization-legend-key="${escapeAttr(entry.methodId)}"
        data-ui-tooltip="${escapeAttr(entry.methodLabel)}"
        tabindex="0"
        role="button"
        aria-label="${escapeAttr(`Highlight ${entry.methodLabel}`)}"
        transform="translate(${x.toFixed(1)}, ${y.toFixed(1)})"
      >
        <line x1="0" y1="0" x2="27" y2="0" style="stroke:${escapeAttr(color)}${dash ? `;stroke-dasharray:${dash}` : ""}"></line>
        <text x="34" y="4">${escapeHtml(trim(entry.methodLabel, 34))}</text>
      </g>
    `;
  }).join("");
  return `
    <div class="rd-chart-wrap receiver-decision-chart-wrap">
      <svg class="rd-chart receiver-decision-chart" data-visualization-id="receiver-decision-regions" viewBox="0 0 ${width} ${height}" preserveAspectRatio="xMidYMid meet" role="img" aria-label="QPSK receiver decision-boundary comparison">
        <text class="rd-plot-title" x="${width / 2}" y="13" text-anchor="middle">QPSK receiver decision boundaries</text>
        <g class="receiver-decision-panel" tabindex="0" role="img" aria-label="Overlaid QPSK I/Q decision boundaries">
          <rect class="receiver-decision-domain" x="${plot.left.toFixed(1)}" y="${plot.top.toFixed(1)}" width="${plot.width.toFixed(1)}" height="${plot.height.toFixed(1)}"></rect>
          ${ticks.map((tick) => `
            <g class="receiver-decision-tick">
              <line x1="${xScale(tick).toFixed(1)}" y1="${plot.top.toFixed(1)}" x2="${xScale(tick).toFixed(1)}" y2="${(plot.top + plot.height).toFixed(1)}"></line>
              <line x1="${plot.left.toFixed(1)}" y1="${yScale(tick).toFixed(1)}" x2="${(plot.left + plot.width).toFixed(1)}" y2="${yScale(tick).toFixed(1)}"></line>
              <text x="${xScale(tick).toFixed(1)}" y="${(plot.top + plot.height + 14).toFixed(1)}" text-anchor="middle">${escapeHtml(formatValue(tick))}</text>
              <text x="${(plot.left - 7).toFixed(1)}" y="${(yScale(tick) + 3).toFixed(1)}" text-anchor="end">${escapeHtml(formatValue(tick))}</text>
            </g>
          `).join("")}
          ${boundaries}
          ${reference.constellation.map((point) => {
            const labelRight = point.i >= constellationCenter.i;
            const labelAbove = point.q >= constellationCenter.q;
            return `
              <g class="receiver-decision-symbol" transform="translate(${xScale(point.i).toFixed(1)}, ${yScale(point.q).toFixed(1)})">
                <title>Noiseless received centroid ${escapeHtml(point.bits)}</title>
                <circle r="4.6"></circle>
                <text
                  x="${labelRight ? 7 : -7}"
                  y="${labelAbove ? -6 : 10}"
                  text-anchor="${labelRight ? "start" : "end"}"
                >${escapeHtml(point.bits)}</text>
              </g>
            `;
          }).join("")}
          <rect class="receiver-decision-border" x="${plot.left.toFixed(1)}" y="${plot.top.toFixed(1)}" width="${plot.width.toFixed(1)}" height="${plot.height.toFixed(1)}"></rect>
          <text class="receiver-decision-axis-label" x="${(plot.left + plot.width / 2).toFixed(1)}" y="${(plot.top + plot.height + 29).toFixed(1)}" text-anchor="middle">In-phase I</text>
          <text class="receiver-decision-axis-label" x="${(plot.left - 29).toFixed(1)}" y="${(plot.top + plot.height / 2).toFixed(1)}" text-anchor="middle" transform="rotate(-90 ${plot.left - 29} ${plot.top + plot.height / 2})">Quadrature Q</text>
        </g>
        ${legend}
      </svg>
    </div>
  `;
}

function benchmarkDemoSeries(row) {
  const benchmark = row && row.benchmarkResult && row.benchmarkResult.benchmark
    ? row.benchmarkResult.benchmark
    : {};
  const metadata = benchmark && benchmark.metadata && typeof benchmark.metadata === "object"
    ? benchmark.metadata
    : {};
  const demo = metadata.demo && typeof metadata.demo === "object" ? metadata.demo : {};
  return Array.isArray(demo.series) ? demo.series.filter((item) => item && typeof item === "object") : [];
}

function benchmarkMethodSeries(row, methodId) {
  return benchmarkDemoSeries(row).find((item) => String(item.id || "") === String(methodId || "")) || null;
}

function summaryBenchmarkMethod(summary) {
  const metadata = summary && summary.recipe && summary.recipe.metadata ? summary.recipe.metadata : {};
  return String(metadata.benchmark_method || "").trim();
}

function summaryBenchmarkPairedSeed(summary) {
  const metadata = summary && summary.recipe && summary.recipe.metadata ? summary.recipe.metadata : {};
  const direct = Number(metadata.benchmark_paired_seed);
  if (Number.isFinite(direct)) return direct;
  const selected = Number(summarySweepValue(summary, "benchmark.paired_seed"));
  return Number.isFinite(selected) ? selected : NaN;
}

function benchmarkMethodLabel(row, methodId, fallback = "") {
  const series = benchmarkMethodSeries(row, methodId);
  if (series && String(series.label || "").trim()) return String(series.label).trim();
  const benchmarkLabel = String(row && row.benchmarkEntry && row.benchmarkEntry.label || "").trim();
  if (benchmarkLabel && !methodId) return benchmarkLabel;
  const raw = String(fallback || methodId || "receiver").trim().replace(/[_-]+/g, " ");
  return raw ? raw[0].toUpperCase() + raw.slice(1) : "Receiver";
}

function benchmarkMethodColor(row, methodId, fallbackColor = "") {
  const method = String(methodId || "").trim();
  if (!method) return fallbackColor || recipeColor(row && row.recipe);
  const seriesIndex = benchmarkDemoSeries(row).findIndex((item) => String(item.id || "") === method);
  if (seriesIndex >= 0) return recipeColorForIndex(seriesIndex);
  let hash = 2166136261;
  for (let index = 0; index < method.length; index += 1) {
    hash ^= method.charCodeAt(index);
    hash = Math.imul(hash, 16777619);
  }
  return recipeColorForIndex((hash >>> 0) % RECIPE_COLORS.length);
}

function benchmarkScopeId(row) {
  const benchmark = row && row.benchmarkResult && row.benchmarkResult.benchmark
    ? row.benchmarkResult.benchmark
    : {};
  const metadata = benchmark && benchmark.metadata && typeof benchmark.metadata === "object"
    ? benchmark.metadata
    : {};
  const demo = metadata.demo && typeof metadata.demo === "object" ? metadata.demo : {};
  if (benchmark.id || demo.slug || demo.title) {
    return String(benchmark.id || demo.slug || demo.title);
  }
  const recipe = row && row.recipe && row.recipe.recipe ? row.recipe.recipe : {};
  const recipeMetadata = recipe && recipe.metadata && typeof recipe.metadata === "object"
    ? recipe.metadata
    : {};
  const provenance = recipeMetadata.template_provenance && typeof recipeMetadata.template_provenance === "object"
    ? recipeMetadata.template_provenance
    : {};
  return String(
    provenance.template_id ||
    provenance.id ||
    recipeMetadata.research_stage ||
    recipe.name ||
    resultRowKey(row) ||
    "result"
  );
}

function receiverPhaseTraceSignature(truth) {
  const points = truth && Array.isArray(truth.points) ? truth.points : [];
  let hash = 2166136261;
  const text = points.map((point) => (
    `${Number(point.x).toPrecision(12)}:${Number(point.y).toPrecision(12)}`
  )).join("|");
  for (let index = 0; index < text.length; index += 1) {
    hash ^= text.charCodeAt(index);
    hash = Math.imul(hash, 16777619);
  }
  return `${points.length}:${(hash >>> 0).toString(16).padStart(8, "0")}`;
}

function receiverPhaseRecipeSeedSignature(summary) {
  const recipe = summary && summary.recipe && typeof summary.recipe === "object" ? summary.recipe : {};
  const metadata = recipe.metadata && typeof recipe.metadata === "object" ? recipe.metadata : {};
  const seeds = [["recipe", metadata.seed]];
  (recipe.steps || []).forEach((step) => {
    const params = step && step.params && typeof step.params === "object" ? step.params : {};
    Object.entries(params).forEach(([name, value]) => {
      if (name === "seed" || name.endsWith("_seed")) seeds.push([`${step.id}.${name}`, value]);
    });
  });
  return JSON.stringify(seeds);
}

function resultArtifactMetadataObjects(details) {
  const objects = [];
  ((details && details.artifacts) || []).forEach((item) => {
    const metadata = item && item.artifact && item.artifact.metadata;
    if (!metadata || typeof metadata !== "object") return;
    objects.push(metadata);
    if (metadata.metadata && typeof metadata.metadata === "object") objects.push(metadata.metadata);
  });
  return objects;
}

function normalizePhaseTracePreview(preview, valueKey) {
  if (!preview || typeof preview !== "object") return null;
  const rawIndices = Array.isArray(preview.frame_symbol_index) ? preview.frame_symbol_index : [];
  const rawValues = Array.isArray(preview[valueKey]) ? preview[valueKey] : [];
  if (!rawIndices.length || rawIndices.length !== rawValues.length) return null;
  const points = rawIndices
    .map((value, index) => ({ x: Number(value), y: Number(rawValues[index]) }))
    .filter((point) => Number.isFinite(point.x) && Number.isFinite(point.y))
    .sort((left, right) => left.x - right.x);
  if (!points.length) return null;
  return {
    packetIndex: Number.isFinite(Number(preview.packet_index)) ? Number(preview.packet_index) : 0,
    points,
  };
}

function circularPhaseErrorRad(estimate, truth) {
  const estimatedPhase = Number(estimate);
  const truePhase = Number(truth);
  if (!Number.isFinite(estimatedPhase) || !Number.isFinite(truePhase)) return NaN;
  const difference = estimatedPhase - truePhase;
  return Math.atan2(Math.sin(difference), Math.cos(difference));
}

function phaseTraceValueAt(points, x) {
  if (!Array.isArray(points) || !points.length || !Number.isFinite(Number(x))) return NaN;
  const target = Number(x);
  let left = null;
  for (const point of points) {
    if (!point || !Number.isFinite(Number(point.x)) || !Number.isFinite(Number(point.y))) continue;
    const current = { x: Number(point.x), y: Number(point.y) };
    if (current.x === target) return current.y;
    if (current.x > target) {
      if (!left) return current.y;
      const span = current.x - left.x;
      if (!(span > 0)) return current.y;
      const ratio = (target - left.x) / span;
      return left.y + ratio * (current.y - left.y);
    }
    left = current;
  }
  return left ? left.y : NaN;
}

function truthAlignedPhaseEstimatePoints(estimateTrace, truthTrace) {
  const estimatePoints = Array.isArray(estimateTrace)
    ? estimateTrace
    : estimateTrace && Array.isArray(estimateTrace.points) ? estimateTrace.points : [];
  const truthPoints = Array.isArray(truthTrace)
    ? truthTrace
    : truthTrace && Array.isArray(truthTrace.points) ? truthTrace.points : [];
  // Keep the simulator samples exact.  Estimate previews can be denser than
  // truth previews, so interpolate the estimate onto truth indices rather
  // than inventing intermediate simulator-truth values.
  return truthPoints.map((point) => {
    const x = Number(point && point.x);
    const truth = Number(point && point.y);
    const estimate = phaseTraceValueAt(estimatePoints, x);
    const error = circularPhaseErrorRad(estimate, truth);
    if (!Number.isFinite(x) || !Number.isFinite(truth) || !Number.isFinite(error)) return null;
    return {
      x,
      y: truth + error,
      error,
      truth,
      estimate,
    };
  }).filter(Boolean);
}

function receiverPhaseTruthPreview(details) {
  for (const metadata of resultArtifactMetadataObjects(details)) {
    const normalized = normalizePhaseTracePreview(metadata.phase_truth_preview, "true_phase_rad");
    if (normalized) {
      const wirelessHistory = Array.isArray(metadata.wireless_history) ? metadata.wireless_history : [];
      const wirelessRecord = wirelessHistory.length ? wirelessHistory[wirelessHistory.length - 1] : {};
      const carrierSeed = Number(metadata.carrier_phase_seed);
      const wirelessSeed = Number(wirelessRecord && wirelessRecord.seed);
      const pilotSeed = Number(metadata.pilot_seed);
      return {
        ...normalized,
        carrierSeed: Number.isFinite(carrierSeed) ? carrierSeed : NaN,
        wirelessSeed: Number.isFinite(wirelessSeed) ? wirelessSeed : NaN,
        pilotSeed: Number.isFinite(pilotSeed) ? pilotSeed : NaN,
      };
    }
  }
  return null;
}

function receiverPhaseDiagnostic(details) {
  for (const metadata of resultArtifactMetadataObjects(details)) {
    const decision = metadata.receiver_decision_preview;
    const rawPreview = metadata.phase_tracking_preview;
    const isPhaseReceiver = Boolean(
      rawPreview ||
      Object.prototype.hasOwnProperty.call(metadata, "phase_estimate_available") ||
      (decision && typeof decision === "object" && String(decision.context || "").includes("packet"))
    );
    if (!isPhaseReceiver) continue;
    const estimate = normalizePhaseTracePreview(rawPreview, "estimated_phase_rad");
    return {
      mode: String(metadata.receiver_mode || (rawPreview && rawPreview.receiver_mode) || (decision && decision.receiver_mode) || "phase_tracking_receiver"),
      estimate,
      estimateAvailable: metadata.phase_estimate_available === true && Boolean(estimate),
      truthUsedForDecisions: metadata.phase_truth_used_for_decisions === true,
      truthForwardedToLearnedRuntime: metadata.phase_truth_forwarded_to_learned_runtime === true,
    };
  }
  return null;
}

function receiverPhaseTrackingEvidence(rows) {
  const labels = recipeDisplayLabels((rows || []).map((row) => row.recipe));
  const conditions = new Map();
  (rows || []).forEach((row) => {
    resultSummaries(row).forEach((summary) => {
      const details = collectRunDetails(summary);
      const truth = receiverPhaseTruthPreview(details);
      const diagnostic = receiverPhaseDiagnostic(details);
      if (!truth && !diagnostic) return;
      const benchmarkBacked = Boolean(
        row && row.benchmarkResult && row.benchmarkResult.benchmark && row.benchmarkResult.benchmark.id
      );
      const declaredMethodId = benchmarkBacked ? summaryBenchmarkMethod(summary) : "";
      const methodId = declaredMethodId || `recipe:${resultRowKey(row)}`;
      const recipeLabel = recipeDisplayName(row.recipe, labels);
      const methodLabel = declaredMethodId
        ? benchmarkMethodLabel(row, declaredMethodId, recipeLabel)
        : recipeLabel;
      const snr = summarySnrDb(summary, details);
      const pairedSeed = summaryBenchmarkPairedSeed(summary);
      const carrierSeed = truth && Number.isFinite(truth.carrierSeed) ? truth.carrierSeed : NaN;
      const wirelessSeed = truth && Number.isFinite(truth.wirelessSeed) ? truth.wirelessSeed : NaN;
      const pilotSeed = truth && Number.isFinite(truth.pilotSeed) ? truth.pilotSeed : NaN;
      const realizationKey = Number.isFinite(pairedSeed)
        ? `paired:${pairedSeed}`
        : [
          `carrier:${Number.isFinite(carrierSeed) ? carrierSeed : "na"}`,
          `wireless:${Number.isFinite(wirelessSeed) ? wirelessSeed : "na"}`,
          `pilot:${Number.isFinite(pilotSeed) ? pilotSeed : "na"}`,
          `recipe-seeds:${receiverPhaseRecipeSeedSignature(summary)}`,
          `truth:${truth ? receiverPhaseTraceSignature(truth) : resultRowKey(row)}`,
        ].join("|");
      const conditionKey = [
        benchmarkScopeId(row),
        Number.isFinite(snr) ? snr.toPrecision(8) : "snr-na",
        realizationKey,
      ];
      const serializedConditionKey = JSON.stringify(conditionKey);
      const condition = conditions.get(serializedConditionKey) || {
        key: serializedConditionKey,
        scopeId: conditionKey[0],
        truth: null,
        methods: new Map(),
        snr,
        pairedSeed,
        carrierSeed,
        wirelessSeed,
        pilotSeed,
        order: conditions.size,
      };
      if (!condition.truth && truth) condition.truth = truth;
      if (!condition.methods.has(methodId)) {
        condition.methods.set(methodId, {
          key: resultRowKey(row),
          methodId,
          methodLabel,
          color: benchmarkMethodColor(row, declaredMethodId || methodId, recipeColor(row.recipe)),
          diagnostic,
        });
      }
      conditions.set(serializedConditionKey, condition);
    });
  });
  const candidates = Array.from(conditions.values()).filter((condition) => condition.truth && condition.methods.size);
  candidates.sort(compareReceiverPhaseConditions);
  const selectionScope = [
    currentResultsSourceValue(),
    ...Array.from(new Set(candidates.map((condition) => condition.scopeId))).sort(),
  ].join("::");
  const configured = state.receiverPhaseTrackingSelections && state.receiverPhaseTrackingSelections[selectionScope];
  const selected = candidates.find((condition) => condition.key === configured)
    || defaultReceiverPhaseTrackingCondition(candidates);
  if (!selected) return null;
  state.receiverPhaseTrackingSelections = {
    ...(state.receiverPhaseTrackingSelections || {}),
    [selectionScope]: selected.key,
  };
  return {
    ...selected,
    methods: Array.from(selected.methods.values()),
    conditions: candidates.map((condition) => ({
      ...condition,
      methods: Array.from(condition.methods.values()),
    })),
    selectionScope,
  };
}

function compareReceiverPhaseConditions(left, right) {
  const leftSnr = Number(left && left.snr);
  const rightSnr = Number(right && right.snr);
  if (Number.isFinite(leftSnr) && Number.isFinite(rightSnr) && leftSnr !== rightSnr) return leftSnr - rightSnr;
  if (Number.isFinite(leftSnr) !== Number.isFinite(rightSnr)) return Number.isFinite(leftSnr) ? -1 : 1;
  const leftSeed = Number(left && left.pairedSeed);
  const rightSeed = Number(right && right.pairedSeed);
  if (Number.isFinite(leftSeed) && Number.isFinite(rightSeed) && leftSeed !== rightSeed) return leftSeed - rightSeed;
  if (Number.isFinite(leftSeed) !== Number.isFinite(rightSeed)) return Number.isFinite(leftSeed) ? -1 : 1;
  const leftCarrierSeed = Number(left && left.carrierSeed);
  const rightCarrierSeed = Number(right && right.carrierSeed);
  if (Number.isFinite(leftCarrierSeed) && Number.isFinite(rightCarrierSeed) && leftCarrierSeed !== rightCarrierSeed) {
    return leftCarrierSeed - rightCarrierSeed;
  }
  return Number(left && left.order) - Number(right && right.order);
}

function defaultReceiverPhaseTrackingCondition(candidates) {
  if (!Array.isArray(candidates) || !candidates.length) return null;
  const maxMethodCount = Math.max(...candidates.map((condition) => condition.methods.size));
  const complete = candidates.filter((condition) => condition.methods.size === maxMethodCount);
  const ordered = complete.slice().sort(compareReceiverPhaseConditions);
  return ordered[Math.floor(ordered.length / 2)] || ordered[0] || null;
}

function receiverPhaseConditionLabel(condition, includeScope = false) {
  const parts = [
    Number.isFinite(condition && condition.snr) ? `SNR ${formatValue(condition.snr)} dB` : "SNR unavailable",
    Number.isFinite(condition && condition.pairedSeed) ? `paired seed ${formatValue(condition.pairedSeed)}` : "",
    !Number.isFinite(condition && condition.pairedSeed) && Number.isFinite(condition && condition.carrierSeed)
      ? `carrier seed ${formatValue(condition.carrierSeed)}`
      : "",
    !Number.isFinite(condition && condition.pairedSeed) && Number.isFinite(condition && condition.wirelessSeed)
      ? `channel seed ${formatValue(condition.wirelessSeed)}`
      : "",
    includeScope ? String(condition && condition.scopeId || "") : "",
  ].filter(Boolean);
  return parts.join(" · ");
}

function receiverPhaseTrackingFigure(rows) {
  const evidence = receiverPhaseTrackingEvidence(rows);
  if (!evidence) return "";
  const width = RESULT_FIGURE_WIDTH;
  const height = 456;
  const phasePlot = { left: 68, right: 18, top: 78, bottom: 250 };
  const errorPlot = { left: phasePlot.left, right: phasePlot.right, top: 294, bottom: 410 };
  const estimateCandidates = evidence.methods.filter((item) => (
    item.diagnostic && item.diagnostic.estimateAvailable && item.diagnostic.estimate
  ));
  const estimated = estimateCandidates.map((item) => {
    const alignedPoints = truthAlignedPhaseEstimatePoints(item.diagnostic.estimate, evidence.truth);
    return {
      ...item,
      alignedPoints,
      correctionPoints: alignedPoints.map((point) => ({
        ...point,
        // The receiver multiplies by exp(-j*estimate).  This is the actual
        // correction angle and the phase that remains after applying it.
        y: -point.y,
        residual: -point.error,
      })),
    };
  }).filter((item) => item.alignedPoints.length);
  const direct = evidence.methods.filter((item) => !estimateCandidates.includes(item));
  const requiredCorrectionPoints = evidence.truth.points.map((point) => ({
    x: point.x,
    y: -point.y,
  }));
  const allPoints = [
    ...requiredCorrectionPoints,
    ...estimated.flatMap((item) => item.correctionPoints),
  ];
  const baseXDomain = chartDomainForValues(allPoints.map((point) => point.x), 0.02, true, false);
  const baseYDomain = chartDomainForValues(allPoints.map((point) => point.y), 0.08, false, false);
  const domainViewKey = "receiver-phase-tracking";
  const domainSignature = [
    "frame-symbol-index",
    "truth-aligned-correction-rad",
    evidence.key,
    Number.isFinite(evidence.snr) ? evidence.snr : "snr-na",
    Number.isFinite(evidence.pairedSeed) ? evidence.pairedSeed : "seed-na",
  ].join(":");
  const domains = domainChartVisibleDomains(
    domainViewKey,
    baseXDomain,
    baseYDomain,
    { signature: domainSignature, xMetric: "frame_symbol_index", yMetric: "truth_aligned_correction_rad" },
  );
  const xDomain = domains.x;
  const yDomain = domains.y;
  const xScale = chartScale(xDomain, phasePlot.left, width - phasePlot.right, false);
  const yScale = chartScale(yDomain, phasePlot.bottom, phasePlot.top, false);
  const errorScale = chartScale([-Math.PI, Math.PI], errorPlot.bottom, errorPlot.top, false);
  const xTicks = chartTicksForDomain(xDomain, 5, false);
  const yTicks = chartTicksForDomain(yDomain, 4, false);
  const errorTicks = [-Math.PI, 0, Math.PI];
  const context = [
    Number.isFinite(evidence.snr) ? `${formatValue(evidence.snr)} dB` : "",
    Number.isFinite(evidence.pairedSeed) ? `paired seed ${formatValue(evidence.pairedSeed)}` : "",
    !Number.isFinite(evidence.pairedSeed) && Number.isFinite(evidence.carrierSeed)
      ? `carrier seed ${formatValue(evidence.carrierSeed)}`
      : "",
  ].filter(Boolean).join(" · ");
  const truthTooltip = "Required correction −φ from simulator phase truth; evaluation evidence only";
  const multipleScopes = new Set(evidence.conditions.map((condition) => condition.scopeId)).size > 1;
  const baseConditionLabels = evidence.conditions.map((condition) => (
    receiverPhaseConditionLabel(condition, multipleScopes)
  ));
  const conditionLabelCounts = new Map();
  baseConditionLabels.forEach((label) => conditionLabelCounts.set(label, (conditionLabelCounts.get(label) || 0) + 1));
  const conditionLabelOccurrences = new Map();
  const conditionLabels = baseConditionLabels.map((label) => {
    if ((conditionLabelCounts.get(label) || 0) < 2) return label;
    const occurrence = (conditionLabelOccurrences.get(label) || 0) + 1;
    conditionLabelOccurrences.set(label, occurrence);
    return `${label} · realization ${occurrence}`;
  });
  return `
    <div class="rd-chart-wrap phase-tracking-chart-wrap">
      <div class="csi-feedback-preview-controls phase-tracking-condition-controls">
        <label>
          <span>SNR / seed</span>
          <select data-phase-condition-select data-phase-condition-scope="${escapeAttr(evidence.selectionScope)}" aria-label="Carrier phase tracking SNR and realization">
            ${evidence.conditions.map((condition, index) => `<option value="${escapeAttr(condition.key)}"${condition.key === evidence.key ? " selected" : ""}>${escapeHtml(conditionLabels[index])}</option>`).join("")}
          </select>
        </label>
      </div>
      <svg class="rd-chart phase-tracking-chart" data-visualization-id="receiver-phase-tracking"
        data-domain-chart data-domain-view-key="${domainViewKey}" data-domain-signature="${escapeAttr(domainSignature)}"
        data-width="${width}" data-height="${height}"
        data-left="${phasePlot.left}" data-right="${phasePlot.right}" data-top="${phasePlot.top}" data-bottom="${height - phasePlot.bottom}"
        data-x-min="${xDomain[0]}" data-x-max="${xDomain[1]}" data-y-min="${yDomain[0]}" data-y-max="${yDomain[1]}"
        data-x-metric="frame_symbol_index" data-y-metric="truth_aligned_correction_rad"
        data-x-log="false" data-y-log="false"
        viewBox="0 0 ${width} ${height}" preserveAspectRatio="xMidYMid meet" role="img" aria-label="Required and applied carrier phase corrections with residual phase">
        <defs>
          <clipPath id="phase-tracking-plot-clip">
            <rect x="${phasePlot.left}" y="${phasePlot.top}" width="${width - phasePlot.left - phasePlot.right}" height="${phasePlot.bottom - phasePlot.top}"></rect>
          </clipPath>
          <clipPath id="phase-error-plot-clip">
            <rect x="${errorPlot.left}" y="${errorPlot.top}" width="${width - errorPlot.left - errorPlot.right}" height="${errorPlot.bottom - errorPlot.top}"></rect>
          </clipPath>
        </defs>
        <text class="rd-plot-title" x="${width / 2}" y="54" text-anchor="middle">Carrier phase correction${context ? ` · ${escapeHtml(context)}` : ""}</text>
        <text class="rd-axis-label" x="${width / 2}" y="69" text-anchor="middle">Applied correction versus required correction</text>
        <line class="rd-axis" x1="${phasePlot.left}" y1="${phasePlot.bottom}" x2="${width - phasePlot.right}" y2="${phasePlot.bottom}"></line>
        <line class="rd-axis" x1="${phasePlot.left}" y1="${phasePlot.top}" x2="${phasePlot.left}" y2="${phasePlot.bottom}"></line>
        ${xTicks.map((tick) => `
          <g class="rd-tick">
            <line x1="${xScale(tick)}" y1="${phasePlot.top}" x2="${xScale(tick)}" y2="${phasePlot.bottom}"></line>
          </g>
        `).join("")}
        ${yTicks.map((tick) => `
          <g class="rd-tick y">
            <line x1="${phasePlot.left}" y1="${yScale(tick)}" x2="${width - phasePlot.right}" y2="${yScale(tick)}"></line>
            <text x="${phasePlot.left - 12}" y="${yScale(tick) + 3}">${escapeHtml(formatMetricNumber(tick, 3))}</text>
          </g>
        `).join("")}
        <g clip-path="url(#phase-tracking-plot-clip)" aria-label="Required and applied carrier phase correction${context ? ` · ${escapeAttr(context)}` : ""}">
          <g class="phase-truth-series" data-visualization-series-key="phase-truth" tabindex="0" role="img" aria-label="${escapeAttr(truthTooltip)}" data-result-tooltip="${escapeAttr(truthTooltip)}">
            <polyline points="${escapeAttr(requiredCorrectionPoints.map((point) => `${xScale(point.x).toFixed(1)},${yScale(point.y).toFixed(1)}`).join(" "))}"></polyline>
          </g>
          ${estimated.map((item, index) => {
          const oracle = item.diagnostic.truthUsedForDecisions;
          const tooltip = oracle
            ? `${item.methodLabel}: required correction from simulator truth; evaluation only`
            : `${item.methodLabel}: applied correction −estimate, shifted by integer multiples of 2π onto the required-correction branch for evaluation`;
          return `
            <g class="phase-estimate-series${oracle ? " oracle" : ""}" data-visualization-series-key="phase-estimate-${index + 1}" data-result-key="${escapeAttr(item.key)}" style="--recipe-color: ${escapeAttr(item.color)}" tabindex="0" role="img" aria-label="${escapeAttr(tooltip)}" data-result-tooltip="${escapeAttr(tooltip)}">
              <polyline points="${escapeAttr(item.correctionPoints.map((point) => `${xScale(point.x).toFixed(1)},${yScale(point.y).toFixed(1)}`).join(" "))}"></polyline>
            </g>
          `;
          }).join("")}
        </g>
        <text class="rd-axis-label y" x="14" y="${(phasePlot.top + phasePlot.bottom) / 2}" transform="rotate(-90 14 ${(phasePlot.top + phasePlot.bottom) / 2})">Correction angle (rad)</text>

        <text class="rd-plot-title" x="${width / 2}" y="279" text-anchor="middle">Residual phase after correction</text>
        <line class="rd-axis" x1="${errorPlot.left}" y1="${errorPlot.bottom}" x2="${width - errorPlot.right}" y2="${errorPlot.bottom}"></line>
        <line class="rd-axis" x1="${errorPlot.left}" y1="${errorPlot.top}" x2="${errorPlot.left}" y2="${errorPlot.bottom}"></line>
        ${xTicks.map((tick) => `
          <g class="rd-tick">
            <line x1="${xScale(tick)}" y1="${errorPlot.top}" x2="${xScale(tick)}" y2="${errorPlot.bottom}"></line>
            <text x="${xScale(tick)}" y="${errorPlot.bottom + 16}">${escapeHtml(formatValue(tick))}</text>
          </g>
        `).join("")}
        ${errorTicks.map((tick) => `
          <g class="rd-tick y">
            <line x1="${errorPlot.left}" y1="${errorScale(tick)}" x2="${width - errorPlot.right}" y2="${errorScale(tick)}"></line>
            <text x="${errorPlot.left - 12}" y="${errorScale(tick) + 3}">${tick === 0 ? "0" : tick > 0 ? "π" : "−π"}</text>
          </g>
        `).join("")}
        <line class="rd-axis phase-error-guide" data-phase-error-guide="positive" stroke-dasharray="5 4" x1="${errorPlot.left}" y1="${errorScale(Math.PI / 4)}" x2="${width - errorPlot.right}" y2="${errorScale(Math.PI / 4)}"></line>
        <line class="rd-axis phase-error-guide" data-phase-error-guide="negative" stroke-dasharray="5 4" x1="${errorPlot.left}" y1="${errorScale(-Math.PI / 4)}" x2="${width - errorPlot.right}" y2="${errorScale(-Math.PI / 4)}"></line>
        <text class="rd-axis-label" x="${width - errorPlot.right - 3}" y="${errorScale(Math.PI / 4) - 4}" text-anchor="end">+π/4</text>
        <text class="rd-axis-label" x="${width - errorPlot.right - 3}" y="${errorScale(-Math.PI / 4) - 4}" text-anchor="end">−π/4</text>
        <g clip-path="url(#phase-error-plot-clip)">
          ${estimated.map((item, index) => {
          const tooltip = `${item.methodLabel}: residual wrap(φ − estimate) after applying correction, in [−π, π]`;
          return `
            <g class="phase-estimate-series${item.diagnostic.truthUsedForDecisions ? " oracle" : ""}" data-phase-error-series="${escapeAttr(item.methodId)}" data-visualization-series-key="phase-estimate-${index + 1}" data-result-key="${escapeAttr(item.key)}" style="--recipe-color: ${escapeAttr(item.color)}" tabindex="0" role="img" aria-label="${escapeAttr(tooltip)}" data-result-tooltip="${escapeAttr(tooltip)}">
              <polyline points="${escapeAttr(item.correctionPoints.map((point) => `${xScale(point.x).toFixed(1)},${errorScale(point.residual).toFixed(1)}`).join(" "))}"></polyline>
            </g>
          `;
          }).join("")}
        </g>
        <text class="rd-axis-label" x="${width / 2}" y="${height - 5}">Frame symbol index</text>
        <text class="rd-axis-label y" x="14" y="${(errorPlot.top + errorPlot.bottom) / 2}" transform="rotate(-90 14 ${(errorPlot.top + errorPlot.bottom) / 2})">Residual phase (rad)</text>
      </svg>
      <div class="phase-tracking-legend visualization-legend" aria-label="Phase tracking methods">
        <button type="button" class="phase-truth-key" data-visualization-legend-key="phase-truth"><i aria-hidden="true"></i>Required correction · simulator truth</button>
        ${estimated.map((item, index) => `<button type="button" data-visualization-legend-key="phase-estimate-${index + 1}" style="--recipe-color: ${escapeAttr(item.color)}"><i aria-hidden="true"></i>${escapeHtml(item.methodLabel)}${item.diagnostic.truthUsedForDecisions ? " · oracle uses truth" : ""}</button>`).join("")}
        ${direct.map((item) => `<button type="button" class="phase-direct-detector" style="--recipe-color: ${escapeAttr(item.color)}"><i aria-hidden="true"></i>${escapeHtml(item.methodLabel)} · no explicit phase estimate</button>`).join("")}
      </div>
      <div class="phase-tracking-note">Truth alignment and residual evaluation use simulator phase only after the run; phase truth is not a learned-model input. Integer 2π shifts are equivalent. The ±π/4 guides are noiseless-QPSK decision boundaries, not hard BER thresholds under AWGN.</div>
    </div>
  `;
}

function rowHasPhysicalWirelessChannel(row) {
  const recipes = [];
  if (row && row.recipe && row.recipe.recipe) recipes.push(row.recipe.recipe);
  resultSummaries(row).forEach((summary) => {
    if (summary && summary.recipe) recipes.push(summary.recipe);
  });
  return recipes.some((recipe) => (recipe.steps || []).some((step) => step.op === "wireless.channel"));
}

function rowTaskIds(row) {
  const summaries = resultSummaries(row);
  const ids = summaries.length
    ? summaries.map((summary) => summaryTaskId(summary, row))
    : [summaryTaskId(null, row)];
  return Array.from(new Set(ids.filter(Boolean)));
}

function rowIsResourceAllocation(row) {
  const taskIds = rowTaskIds(row);
  if (taskIds.includes("resource_allocation")) return true;
  if (taskIds.some((taskId) => resultTaskPresentation(taskId))) return false;
  const recipes = [];
  if (row && row.recipe && row.recipe.recipe) recipes.push(row.recipe.recipe);
  resultSummaries(row).forEach((summary) => {
    if (summary && summary.recipe) recipes.push(summary.recipe);
  });
  return recipes.some((recipe) => (recipe.steps || []).some((step) => (
    step.op === "source.resource_allocation_scenario" ||
    step.op === "metrics.resource_allocation" ||
    step.op === "metrics.ofdm_power_allocation" ||
    (step.op === "model.symbol_power_allocator" && step.params && step.params.granularity === "per_subcarrier")
  )));
}

function rowHasFiniteBlocklengthAllocationEvidence(row) {
  return resultSummaries(row).some((summary) => {
    const details = collectRunDetails(summary);
    return Number.isFinite(numberMetricValue(details, [
      "evaluation.resource.finite_blocklength.expected_goodput_bps_hz",
      "resource.finite_blocklength.expected_goodput_bps_hz",
    ])) || Number.isFinite(numberMetricValue(details, [
      "evaluation.resource.finite_blocklength.predicted_bler",
      "resource.finite_blocklength.predicted_bler",
    ]));
  });
}

function rowIsCsiFeedback(row) {
  const taskIds = rowTaskIds(row);
  if (taskIds.includes("csi_compression_feedback") || taskIds.includes("csi_feedback")) return true;
  if (taskIds.some((taskId) => resultTaskPresentation(taskId))) return false;
  const recipes = [];
  if (row && row.recipe && row.recipe.recipe) recipes.push(row.recipe.recipe);
  resultSummaries(row).forEach((summary) => {
    if (summary && summary.recipe) recipes.push(summary.recipe);
  });
  return recipes.some((recipe) => (recipe.steps || []).some((step) => step.op === "metrics.csi_feedback"));
}

function csiFeedbackMetricValue(details, metricName) {
  return numberMetricValue(details, [
    `evaluation.csi_feedback.${metricName}`,
    `csi_feedback.${metricName}`,
  ]);
}

function csiFeedbackPreview(details) {
  for (const item of (details && details.artifacts) || []) {
    const metadata = item && item.artifact && item.artifact.metadata;
    if (!metadata || typeof metadata !== "object") continue;
    const candidates = [
      metadata.csi_feedback_preview,
      metadata.metadata && metadata.metadata.csi_feedback_preview,
    ];
    const preview = candidates.find((candidate) => candidate && typeof candidate === "object");
    if (preview) return preview;
  }
  return null;
}

function csiFeedbackRecipeParts(summary, row) {
  const recipe = (summary && summary.recipe) || (row && row.recipe && row.recipe.recipe) || {};
  const steps = Array.isArray(recipe.steps) ? recipe.steps : [];
  return {
    recipe,
    encoder: findStepByOpIn(steps, "model.csi_feedback_encoder") || {},
    link: findStepByOpIn(steps, "channel.csi_feedback_link") || {},
    channelState: findStepByOpIn(steps, "wireless.miso_ofdm_csi") || {},
  };
}

function csiFeedbackEntries(rows, labels = recipeDisplayLabels((rows || []).map((row) => row.recipe))) {
  return (rows || []).flatMap((row) => {
    const baseTitle = recipeDisplayName(row.recipe, labels);
    const summaries = resultSummaries(row);
    return summaries.map((summary, index) => {
      const details = collectRunDetails(summary);
      const parts = csiFeedbackRecipeParts(summary, row);
      const variantTitle = summaryDisplayTitle(baseTitle, summary, index, summaries);
      const feedbackDimension = csiFeedbackMetricValue(details, "feedback_dimension");
      const feedbackBits = csiFeedbackMetricValue(details, "feedback_bits_per_sample");
      const measuredSnr = numberMetricValue(details, ["channel_state.channel.snr_db", "channel.snr_db"]);
      const sweptSnr = summarySweepNumber(summary, "channel_state.downlink_snr_db");
      const configuredSnr = Number((parts.channelState.params || {}).downlink_snr_db);
      return {
        id: String(summary.run_id || `${resultRowKey(row)}:${index}`),
        key: resultRowKey(row),
        row,
        summary,
        details,
        preview: csiFeedbackPreview(details),
        baseTitle,
        title: variantTitle,
        color: recipeColor(row.recipe),
        runtime: String((parts.encoder.params || {}).runtime || "training_interface"),
        transportMode: String((parts.link.params || {}).mode || "ideal_noiseless"),
        feedbackDimension,
        feedbackBits,
        compressionFactor: csiFeedbackMetricValue(details, "compression_factor"),
        latentFraction: csiFeedbackMetricValue(details, "latent_fraction"),
        nmseDb: csiFeedbackMetricValue(details, "nmse_db"),
        cosine: csiFeedbackMetricValue(details, "phase_invariant_cosine"),
        achievedSe: csiFeedbackMetricValue(details, "achieved_spectral_efficiency_bps_hz"),
        perfectSe: csiFeedbackMetricValue(details, "perfect_csi_spectral_efficiency_bps_hz"),
        retention: csiFeedbackMetricValue(details, "spectral_efficiency_retention"),
        rateLoss: csiFeedbackMetricValue(details, "spectral_efficiency_loss_bps_hz"),
        downlinkSnr: Number.isFinite(measuredSnr) ? measuredSnr : Number.isFinite(sweptSnr) ? sweptSnr : configuredSnr,
      };
    });
  });
}

function csiFeedbackXAxis(items, requestedMode = "auto") {
  const hasItems = Boolean((items || []).length);
  const allHaveActualBits = hasItems && items.every((item) => Number.isFinite(item.feedbackBits));
  if (requestedMode === "actual_bits" && !allHaveActualBits) requestedMode = "latent_dimension";
  if (requestedMode === "actual_bits" || (requestedMode === "auto" && allHaveActualBits)) {
    return {
      key: "feedbackBits",
      label: "Actual feedback bits per CSI sample",
      shortLabel: "feedback bits",
      mixed: false,
    };
  }
  const mixed = hasItems && items.some((item) => Number.isFinite(item.feedbackBits));
  return {
    key: "feedbackDimension",
    label: mixed
      ? "Feedback latent dimension (mixed transport; actual bits shown in tooltips)"
      : "Continuous feedback latent dimension (real coefficients, not bits)",
    shortLabel: "latent dimension",
    mixed,
  };
}

function csiFeedbackSeriesKey(item, kind) {
  return `csi-${slugName(item.key || item.baseTitle)}-${slugName(kind)}`;
}

function csiFeedbackGroupedSeries(items, valueKey, kind, axis) {
  const groups = new Map();
  (items || []).forEach((item) => {
    const x = Number(item[axis.key]);
    const y = Number(item[valueKey]);
    if (!Number.isFinite(x) || !Number.isFinite(y)) return;
    const id = csiFeedbackSeriesKey(item, kind);
    if (!groups.has(id)) {
      groups.set(id, { id, label: item.baseTitle, color: item.color, kind, points: [] });
    }
    groups.get(id).points.push({ ...item, x, y });
  });
  return Array.from(groups.values()).map((series) => {
    const byX = new Map();
    series.points.forEach((point) => {
      const xKey = Number(point.x).toPrecision(12);
      const current = byX.get(xKey);
      if (!current) {
        byX.set(xKey, { ...point, valuesAtX: [point.y] });
        return;
      }
      current.valuesAtX.push(point.y);
    });
    const points = Array.from(byX.values()).map((point) => ({
      ...point,
      y: point.valuesAtX.reduce((sum, value) => sum + value, 0) / point.valuesAtX.length,
    })).sort((left, right) => left.x - right.x);
    return { ...series, points };
  });
}

function csiFeedbackLegendMarkup(series, labelsByKind) {
  return `
    <div class="csi-feedback-legend" aria-label="CSI feedback comparison legend">
      ${(series || []).map((item) => {
        const hasConfiguredLabel = labelsByKind && Object.prototype.hasOwnProperty.call(labelsByKind, item.kind);
        const kindLabel = hasConfiguredLabel ? labelsByKind[item.kind] : humanizeIdentifier(item.kind);
        return `
        <button type="button" class="visualization-series-legend csi-feedback-legend-entry csi-feedback-${escapeAttr(item.kind)}"
          data-visualization-legend-key="${escapeAttr(item.id)}" style="--recipe-color: ${escapeAttr(item.color)}"
          aria-label="Highlight ${escapeAttr(item.label)}${kindLabel ? ` ${escapeAttr(kindLabel)}` : ""}">
          <svg viewBox="0 0 24 10" aria-hidden="true"><line x1="1" y1="5" x2="23" y2="5"></line><circle cx="12" cy="5" r="2.4"></circle></svg>
          <span>${escapeHtml(item.label)}${kindLabel ? ` · ${escapeHtml(kindLabel)}` : ""}</span>
        </button>
      `;
      }).join("")}
    </div>
  `;
}

function csiFeedbackPointTooltip(item, metricLabel, metricValue, axis) {
  return [
    item.title,
    `${axis.shortLabel} ${formatMetricNumber(item[axis.key], 5)}`,
    Number.isFinite(item.feedbackBits) ? `actual feedback bits ${formatInteger(item.feedbackBits)}` : "continuous feedback; no synthetic bit count",
    `transport ${humanizeIdentifier(item.transportMode)}`,
    `${metricLabel} ${formatMetricNumber(metricValue, 5)}`,
    Number.isFinite(item.downlinkSnr) ? `downlink SNR ${formatMetricNumber(item.downlinkSnr, 4)} dB` : "",
  ].filter(Boolean).join("\n");
}

function csiFeedbackRateFigure(rows) {
  const items = csiFeedbackEntries(rows).filter((item) => (
    Number.isFinite(item.achievedSe) && Number.isFinite(item.downlinkSnr)
  ));
  if (!items.length) return "";
  const snrAxis = { key: "downlinkSnr", label: "Downlink SNR (dB)", shortLabel: "downlink SNR" };
  const series = csiFeedbackGroupedSeries(items, "achievedSe", "achieved", snrAxis);
  const snrValues = items.map((item) => item.downlinkSnr);
  const useLines = new Set(snrValues.map((value) => Number(value).toPrecision(12))).size > 1;
  const settings = state.csiFeedbackSettings || {};
  const width = RESULT_FIGURE_WIDTH;
  const height = RESULT_FIGURE_HEIGHT;
  const margin = { left: 76, right: 22, top: 36, bottom: useLines ? 50 : 76 };
  const baseline = height - margin.bottom;
  const xDomain = chartDomainForValues(snrValues, 0.08, false, false);
  const seValues = items.map((item) => item.achievedSe).filter(Number.isFinite);
  const yLog = coerceBoolean(settings.rateYLog) && seValues.every((value) => value > 0);
  const seDomain = chartDomainForValues(seValues, 0.14, !yLog, yLog);
  const xScale = chartScale(xDomain, margin.left, width - margin.right, false);
  const seScale = chartScale(seDomain, baseline, margin.top, yLog);
  const xTicks = useLines ? chartTicksForDomain(xDomain, 4, false) : [];
  const seTicks = chartTicksForDomain(seDomain, 4, yLog);
  const barSlot = (width - margin.left - margin.right) / Math.max(1, items.length);
  const barWidth = Math.max(14, Math.min(46, barSlot * 0.48));
  const singleSnr = useLines ? NaN : snrValues[0];
  const title = `Achieved Downlink Spectral Efficiency${Number.isFinite(singleSnr) ? ` · SNR ${formatMetricNumber(singleSnr, 4)} dB` : " vs Downlink SNR"}`;
  return `
    <div class="rd-chart-wrap csi-feedback-rate-chart-wrap">
      <button class="icon-button rd-settings-button" type="button" data-csi-feedback-settings="rate" aria-label="CSI feedback rate figure settings" data-ui-tooltip="Figure settings">&#9881;</button>
      <svg class="rd-chart csi-feedback-rate-chart" data-visualization-id="csi-feedback-rate" data-y-log="${yLog ? "true" : "false"}" viewBox="0 0 ${width} ${height}" preserveAspectRatio="xMidYMid meet" role="img" aria-label="Achieved downlink spectral efficiency by CSI feedback method">
        <text class="rd-plot-title" x="${width / 2}" y="14" text-anchor="middle">${escapeHtml(title)}</text>
        <line class="rd-axis" x1="${margin.left}" y1="${baseline}" x2="${width - margin.right}" y2="${baseline}"></line>
        <line class="rd-axis" x1="${margin.left}" y1="${margin.top}" x2="${margin.left}" y2="${baseline}"></line>
        ${xTicks.map((tick) => `<g class="rd-tick"><line x1="${xScale(tick)}" y1="${margin.top}" x2="${xScale(tick)}" y2="${baseline}"></line><text x="${xScale(tick)}" y="${height - 24}">${escapeHtml(formatMetricNumber(tick, 4))}</text></g>`).join("")}
        ${seTicks.map((tick) => `<g class="rd-tick y"><line x1="${margin.left}" y1="${seScale(tick)}" x2="${width - margin.right}" y2="${seScale(tick)}"></line><text x="${margin.left - 11}" y="${seScale(tick) + 3}">${escapeHtml(formatMetricNumber(tick, 4))}</text></g>`).join("")}
        ${useLines ? series.map((item) => {
          return `<g class="visualization-series csi-feedback-series csi-feedback-${escapeAttr(item.kind)}" data-visualization-series-key="${escapeAttr(item.id)}" style="--recipe-color: ${escapeAttr(item.color)}">
            ${item.points.length > 1 ? `<polyline class="rd-series-line" points="${escapeAttr(item.points.map((point) => `${xScale(point.x).toFixed(1)},${seScale(point.y).toFixed(1)}`).join(" "))}"></polyline>` : ""}
            ${item.points.map((point) => {
              const tooltip = csiFeedbackPointTooltip(point, "achieved spectral efficiency (bit/s/Hz)", point.y, snrAxis);
              return `<g class="rd-point" transform="translate(${xScale(point.x).toFixed(1)},${seScale(point.y).toFixed(1)})" tabindex="0" role="img" aria-label="${escapeAttr(tooltip)}" data-result-tooltip="${escapeAttr(tooltip)}"><circle r="4.7"></circle></g>`;
            }).join("")}
          </g>`;
        }).join("") : items.map((item, index) => {
          const center = margin.left + barSlot * (index + 0.5);
          const achievedY = seScale(item.achievedSe);
          const achievedKey = csiFeedbackSeriesKey(item, "achieved");
          return `<g class="csi-feedback-rate-bars" style="--recipe-color: ${escapeAttr(item.color)}">
            <rect class="csi-feedback-rate-bar achieved" data-visualization-series-key="${escapeAttr(achievedKey)}" x="${(center - barWidth / 2).toFixed(1)}" y="${achievedY.toFixed(1)}" width="${barWidth.toFixed(1)}" height="${Math.max(1, baseline - achievedY).toFixed(1)}" rx="2" tabindex="0" role="img" data-result-tooltip="${escapeAttr(csiFeedbackPointTooltip(item, "achieved spectral efficiency (bit/s/Hz)", item.achievedSe, snrAxis))}"></rect>
            <text class="csi-feedback-bar-label" x="${center.toFixed(1)}" y="${height - 36}" text-anchor="middle">${escapeHtml(trim(item.baseTitle, 24))}</text>
            <text class="csi-feedback-bar-label budget" x="${center.toFixed(1)}" y="${height - 20}" text-anchor="middle">${escapeHtml(Number.isFinite(item.feedbackBits) ? `${formatInteger(item.feedbackBits)} feedback bits` : `${formatInteger(item.feedbackDimension)} feedback latents`)}</text>
          </g>`;
        }).join("")}
        <text class="rd-axis-label" x="${width / 2}" y="${height - 5}">${useLines ? "Downlink SNR (dB)" : "CSI feedback method"}</text>
        <text class="rd-axis-label y" x="14" y="${height / 2}" transform="rotate(-90 14 ${height / 2})">Spectral efficiency (bit/s/Hz)</text>
      </svg>
      ${csiFeedbackLegendMarkup(series, { achieved: "" })}
    </div>
  `;
}

function csiFeedbackQualityFigure(rows) {
  const items = csiFeedbackEntries(rows).filter((item) => (
    Number.isFinite(item.feedbackDimension) && Number.isFinite(item.nmseDb)
  ));
  if (!items.length) return "";
  const settings = state.csiFeedbackSettings || {};
  const axis = csiFeedbackXAxis(items, settings.qualityXAxis || "auto");
  const series = csiFeedbackGroupedSeries(items, "nmseDb", "nmse", axis);
  const useLines = new Set(series.flatMap((item) => item.points.map((point) => Number(point.x).toPrecision(12)))).size > 1;
  const width = RESULT_FIGURE_WIDTH;
  const height = RESULT_FIGURE_HEIGHT;
  const margin = { left: 76, right: 22, top: 36, bottom: useLines ? 50 : 70 };
  const baseline = height - margin.bottom;
  const xValues = series.flatMap((item) => item.points.map((point) => point.x));
  const nmseValues = series.flatMap((item) => item.points.map((point) => point.y));
  const xLog = useLines && coerceBoolean(settings.qualityXLog) && xValues.every((value) => value > 0);
  const xDomain = chartDomainForValues(xValues, 0.12, false, xLog);
  const nmseDomain = chartDomainForValues(nmseValues.length ? nmseValues : [-1, 0], 0.12, false, false);
  const xScale = chartScale(xDomain, margin.left, width - margin.right, xLog);
  const nmseScale = chartScale(nmseDomain, baseline, margin.top, false);
  const xTicks = useLines ? chartTicksForDomain(xDomain, 4, xLog) : [];
  const nmseTicks = chartTicksForDomain(nmseDomain, 4, false);
  const barSlot = (width - margin.left - margin.right) / Math.max(1, series.length);
  const barWidth = Math.max(14, Math.min(46, barSlot * 0.48));
  const qualityTooltip = (point) => [
    csiFeedbackPointTooltip(point, "CSI NMSE (dB; lower is better)", point.y, axis),
    Number.isFinite(point.cosine) ? `phase-invariant cosine ${formatMetricNumber(point.cosine, 5)}` : "",
  ].filter(Boolean).join("\n");
  return `
    <div class="rd-chart-wrap csi-feedback-quality-chart-wrap">
      <button class="icon-button rd-settings-button" type="button" data-csi-feedback-settings="quality" aria-label="CSI reconstruction quality figure settings" data-ui-tooltip="Figure settings">&#9881;</button>
      <svg class="rd-chart csi-feedback-quality-chart" data-visualization-id="csi-feedback-quality" data-x-log="${xLog ? "true" : "false"}" viewBox="0 0 ${width} ${height}" preserveAspectRatio="xMidYMid meet" role="img" aria-label="CSI reconstruction NMSE by feedback method">
        <text class="rd-plot-title" x="${width / 2}" y="14" text-anchor="middle">CSI Reconstruction NMSE${useLines ? " vs Feedback Budget" : ""}</text>
        <line class="rd-axis" x1="${margin.left}" y1="${baseline}" x2="${width - margin.right}" y2="${baseline}"></line>
        <line class="rd-axis" x1="${margin.left}" y1="${margin.top}" x2="${margin.left}" y2="${baseline}"></line>
        ${xTicks.map((tick) => `<g class="rd-tick"><line x1="${xScale(tick)}" y1="${margin.top}" x2="${xScale(tick)}" y2="${baseline}"></line><text x="${xScale(tick)}" y="${height - 23}">${escapeHtml(formatMetricNumber(tick, 4))}</text></g>`).join("")}
        ${nmseTicks.map((tick) => `<g class="rd-tick y"><line x1="${margin.left}" y1="${nmseScale(tick)}" x2="${width - margin.right}" y2="${nmseScale(tick)}"></line><text x="${margin.left - 11}" y="${nmseScale(tick) + 3}">${escapeHtml(formatMetricNumber(tick, 4))}</text></g>`).join("")}
        ${useLines ? series.map((item) => {
          return `<g class="visualization-series csi-feedback-series csi-feedback-${escapeAttr(item.kind)}" data-visualization-series-key="${escapeAttr(item.id)}" style="--recipe-color: ${escapeAttr(item.color)}">
            ${item.points.length > 1 ? `<polyline class="rd-series-line" points="${escapeAttr(item.points.map((point) => `${xScale(point.x).toFixed(1)},${nmseScale(point.y).toFixed(1)}`).join(" "))}"></polyline>` : ""}
            ${item.points.map((point) => {
              const tooltip = qualityTooltip(point);
              return `<g class="rd-point" transform="translate(${xScale(point.x).toFixed(1)},${nmseScale(point.y).toFixed(1)})" tabindex="0" role="img" aria-label="${escapeAttr(tooltip)}" data-result-tooltip="${escapeAttr(tooltip)}"><circle r="4.7"></circle></g>`;
            }).join("")}
          </g>`;
        }).join("") : series.map((item, index) => {
          const point = item.points[0];
          const center = margin.left + barSlot * (index + 0.5);
          const y = nmseScale(point.y);
          const zeroY = nmseScale(Math.min(0, nmseDomain[1]));
          const top = Math.min(y, zeroY);
          const barHeight = Math.max(1, Math.abs(zeroY - y));
          return `<g class="visualization-series csi-feedback-series csi-feedback-nmse" data-visualization-series-key="${escapeAttr(item.id)}" style="--recipe-color: ${escapeAttr(item.color)}">
            <rect class="csi-feedback-rate-bar achieved" x="${(center - barWidth / 2).toFixed(1)}" y="${top.toFixed(1)}" width="${barWidth.toFixed(1)}" height="${barHeight.toFixed(1)}" rx="2" tabindex="0" role="img" data-result-tooltip="${escapeAttr(qualityTooltip(point))}"></rect>
            <text class="csi-feedback-bar-label" x="${center.toFixed(1)}" y="${height - 27}" text-anchor="middle">${escapeHtml(trim(item.label, 24))}</text>
          </g>`;
        }).join("")}
        <text class="rd-axis-label" x="${width / 2}" y="${height - 5}">${useLines ? escapeHtml(axis.label) : "CSI feedback method"}</text>
        <text class="rd-axis-label y" x="14" y="${height / 2}" transform="rotate(-90 14 ${height / 2})">NMSE (dB) · lower is better</text>
      </svg>
      ${csiFeedbackLegendMarkup(series, { nmse: "" })}
    </div>
  `;
}

function csiFeedbackPreviewSamples(preview) {
  if (!preview || typeof preview !== "object") return [];
  const rows = Array.isArray(preview.samples)
    ? preview.samples
    : Array.isArray(preview.snapshots)
      ? preview.snapshots
      : [preview];
  return rows.map((sample, index) => ({
    ...(sample || {}),
    sample_index: Number.isFinite(Number(sample && sample.sample_index))
      ? Number(sample.sample_index)
      : Number.isFinite(Number(sample && sample.index))
        ? Number(sample.index)
        : index,
  }));
}

function csiFeedbackPreviewMatrix(sample, name) {
  const value = sample && (sample[name] || (sample.matrices && sample.matrices[name]));
  if (!Array.isArray(value)) return [];
  return value.map((row) => (Array.isArray(row) ? row.map(Number).filter(Number.isFinite) : [])).filter((row) => row.length);
}

function csiFeedbackHeatmapColor(value, maxValue, kind, scaleMode = "linear") {
  const ratio = Math.max(0, Number(value) / Math.max(Number(maxValue), 1e-12));
  const normalized = scaleMode === "log"
    ? Math.max(0, Math.min(1, Math.log1p(99 * ratio) / Math.log(100)))
    : Math.max(0, Math.min(1, ratio));
  if (kind === "error") return `hsl(${(42 - 36 * normalized).toFixed(1)} 86% ${(18 + 48 * normalized).toFixed(1)}%)`;
  return `hsl(${(224 - 174 * normalized).toFixed(1)} 76% ${(18 + 48 * normalized).toFixed(1)}%)`;
}

function csiFeedbackHeatmapCells(
  matrix,
  panelIndex,
  kind,
  layout,
  maxValue,
  scaleMode = "linear",
  rowLabels = null,
) {
  const rows = matrix.length;
  const columns = rows ? Math.max(...matrix.map((row) => row.length)) : 0;
  if (!rows || !columns) return "";
  const cellWidth = layout.panelWidth / columns;
  const cellHeight = layout.panelHeight / rows;
  const values = matrix.flat().filter(Number.isFinite);
  const effectiveMax = Number.isFinite(Number(maxValue)) ? Number(maxValue) : Math.max(...values, 1e-12);
  const panelX = layout.left + panelIndex * (layout.panelWidth + layout.gap);
  return matrix.map((row, antennaIndex) => row.map((value, subcarrierIndex) => {
    const x = panelX + subcarrierIndex * cellWidth;
    const y = layout.top + antennaIndex * cellHeight;
    const rowLabel = Array.isArray(rowLabels) && rowLabels[antennaIndex]
      ? String(rowLabels[antennaIndex])
      : `TX antenna ${antennaIndex}`;
    const tooltip = `${rowLabel}\nsubcarrier ${subcarrierIndex}\n${kind === "error" ? "absolute error" : "magnitude"} ${formatMetricNumber(value, 6)}`;
    return `<rect class="csi-feedback-heatmap-cell" x="${x.toFixed(2)}" y="${y.toFixed(2)}" width="${Math.max(0.45, cellWidth + 0.08).toFixed(2)}" height="${Math.max(0.45, cellHeight + 0.08).toFixed(2)}" fill="${escapeAttr(csiFeedbackHeatmapColor(value, effectiveMax, kind, scaleMode))}" tabindex="0" role="img" aria-label="${escapeAttr(tooltip)}" data-result-tooltip="${escapeAttr(tooltip)}"></rect>`;
  }).join("")).join("");
}

function csiFeedbackRuntimeDisplayLabel(runtime) {
  const labels = {
    learned_artifact: "Learned CSI codec",
    truncated_angular_delay: "Truncated angular-delay",
    identity: "Perfect CSI upper bound",
    training_interface: "Training interface",
  };
  return labels[String(runtime || "")] || humanizeIdentifier(runtime || "CSI codec");
}

function csiFeedbackPreviewEntryLabel(item) {
  return [
    item.baseTitle || csiFeedbackRuntimeDisplayLabel(item.runtime),
    Number.isFinite(item.downlinkSnr) ? `SNR ${formatMetricNumber(item.downlinkSnr, 4)} dB` : "",
    Number.isFinite(item.feedbackBits) ? `${formatInteger(item.feedbackBits)} bits` : Number.isFinite(item.feedbackDimension) ? `${formatInteger(item.feedbackDimension)} latents` : "",
  ].filter(Boolean).join(" · ");
}

function csiFeedbackPreviewFigure(rows) {
  const entries = csiFeedbackEntries(rows).filter((item) => csiFeedbackPreviewSamples(item.preview).length);
  if (!entries.length) return "";
  const configured = state.csiFeedbackSettings || {};
  const entry = entries.find((item) => item.id === configured.entryId) || entries[0];
  const samples = csiFeedbackPreviewSamples(entry.preview);
  const requestedSample = Number(configured.sampleIndex);
  const sample = samples.find((item) => item.sample_index === requestedSample) || samples[0];
  state.csiFeedbackSettings = { ...configured, entryId: entry.id, sampleIndex: sample.sample_index };
  const trueMagnitude = csiFeedbackPreviewMatrix(sample, "true_magnitude");
  const reconstructedMagnitude = csiFeedbackPreviewMatrix(sample, "reconstructed_magnitude");
  const absoluteError = csiFeedbackPreviewMatrix(sample, "absolute_error");
  if (!trueMagnitude.length || !reconstructedMagnitude.length || !absoluteError.length) return "";
  const magnitudeOnlyScaleMax = Math.max(
    ...trueMagnitude.flat().filter(Number.isFinite),
    ...reconstructedMagnitude.flat().filter(Number.isFinite),
    1e-12,
  );
  const absoluteErrorMax = Math.max(...absoluteError.flat().filter(Number.isFinite), 1e-12);
  const independentErrorScale = configured.independentErrorScale === true;
  const sharedScaleMax = Math.max(magnitudeOnlyScaleMax, absoluteErrorMax);
  const magnitudeScaleMax = independentErrorScale ? magnitudeOnlyScaleMax : sharedScaleMax;
  const errorScaleMax = independentErrorScale ? absoluteErrorMax : sharedScaleMax;
  const scaleMode = configured.previewScale === "log" ? "log" : "linear";
  const width = 1280;
  const height = 375;
  const layout = { left: 46, top: 70, panelWidth: 376, panelHeight: 225, gap: 30 };
  const panelTitles = ["True CSI magnitude", "Reconstructed CSI magnitude", "Absolute error"];
  return `
    <div class="rd-chart-wrap csi-feedback-preview-chart-wrap">
      <button class="icon-button rd-settings-button" type="button" data-csi-feedback-settings="preview" aria-label="CSI feedback preview figure settings" data-ui-tooltip="Figure settings">&#9881;</button>
      <div class="csi-feedback-preview-controls">
        <label>
          <span>Method / SNR</span>
          <select data-csi-feedback-preview-entry aria-label="CSI feedback result and SNR">
            ${entries.map((item) => `<option value="${escapeAttr(item.id)}"${item.id === entry.id ? " selected" : ""}>${escapeHtml(csiFeedbackPreviewEntryLabel(item))}</option>`).join("")}
          </select>
        </label>
        <label>
          <span>CSI sample</span>
          <select data-csi-feedback-preview-sample aria-label="CSI realization sample">
            ${samples.map((item) => `<option value="${escapeAttr(item.sample_index)}"${item.sample_index === sample.sample_index ? " selected" : ""}>${escapeHtml(`Realization ${item.sample_index + 1}`)}</option>`).join("")}
          </select>
        </label>
      </div>
      <svg class="rd-chart csi-feedback-preview-chart" data-visualization-id="csi-feedback-preview" viewBox="0 0 ${width} ${height}" preserveAspectRatio="xMidYMid meet" role="img" aria-label="True and reconstructed CSI heatmaps">
        <defs>
          <linearGradient id="csi-feedback-magnitude-scale" x1="0" x2="1"><stop offset="0%" stop-color="${escapeAttr(csiFeedbackHeatmapColor(0, magnitudeScaleMax, "magnitude", scaleMode))}"></stop><stop offset="100%" stop-color="${escapeAttr(csiFeedbackHeatmapColor(magnitudeScaleMax, magnitudeScaleMax, "magnitude", scaleMode))}"></stop></linearGradient>
          <linearGradient id="csi-feedback-error-scale" x1="0" x2="1"><stop offset="0%" stop-color="${escapeAttr(csiFeedbackHeatmapColor(0, errorScaleMax, "error", scaleMode))}"></stop><stop offset="100%" stop-color="${escapeAttr(csiFeedbackHeatmapColor(errorScaleMax, errorScaleMax, "error", scaleMode))}"></stop></linearGradient>
        </defs>
        <text class="rd-plot-title" x="${width / 2}" y="20" text-anchor="middle">CSI Reconstruction Preview</text>
        ${panelTitles.map((title, index) => `<text class="csi-feedback-heatmap-title" x="${layout.left + index * (layout.panelWidth + layout.gap) + layout.panelWidth / 2}" y="55" text-anchor="middle">${escapeHtml(title)}</text>`).join("")}
        ${csiFeedbackHeatmapCells(trueMagnitude, 0, "magnitude", layout, magnitudeScaleMax, scaleMode)}
        ${csiFeedbackHeatmapCells(reconstructedMagnitude, 1, "magnitude", layout, magnitudeScaleMax, scaleMode)}
        ${csiFeedbackHeatmapCells(absoluteError, 2, "error", layout, errorScaleMax, scaleMode)}
        ${[0, 1, 2].map((index) => `<rect class="csi-feedback-heatmap-frame" x="${layout.left + index * (layout.panelWidth + layout.gap)}" y="${layout.top}" width="${layout.panelWidth}" height="${layout.panelHeight}"></rect>`).join("")}
        <rect class="csi-feedback-scale-bar" x="${layout.left}" y="306" width="${layout.panelWidth * 2 + layout.gap}" height="8" fill="url(#csi-feedback-magnitude-scale)"></rect>
        <text class="csi-feedback-scale-label" x="${layout.left}" y="328">0</text>
        <text class="csi-feedback-scale-label" x="${layout.left + layout.panelWidth * 2 + layout.gap}" y="328" text-anchor="end">${escapeHtml(formatMetricNumber(magnitudeScaleMax, 5))}</text>
        <text class="csi-feedback-scale-label" x="${layout.left + (layout.panelWidth * 2 + layout.gap) / 2}" y="328" text-anchor="middle">${independentErrorScale ? "Shared true/reconstructed" : "Shared true/reconstructed/error"} ${escapeHtml(scaleMode)} numeric range</text>
        <rect class="csi-feedback-scale-bar" x="${layout.left + 2 * (layout.panelWidth + layout.gap)}" y="306" width="${layout.panelWidth}" height="8" fill="url(#csi-feedback-error-scale)"></rect>
        <text class="csi-feedback-scale-label" x="${layout.left + 2 * (layout.panelWidth + layout.gap)}" y="328">0</text>
        <text class="csi-feedback-scale-label" x="${layout.left + 2 * (layout.panelWidth + layout.gap) + layout.panelWidth}" y="328" text-anchor="end">${escapeHtml(formatMetricNumber(errorScaleMax, 5))}</text>
        <text class="csi-feedback-scale-label" x="${layout.left + 2 * (layout.panelWidth + layout.gap) + layout.panelWidth / 2}" y="328" text-anchor="middle">${independentErrorScale ? "Independent error range" : "Shared range · error palette"}</text>
        <text class="rd-axis-label" x="${width / 2}" y="${height - 8}">OFDM subcarrier index</text>
        <text class="rd-axis-label y" x="15" y="${layout.top + layout.panelHeight / 2}" transform="rotate(-90 15 ${layout.top + layout.panelHeight / 2})">TX antenna index</text>
      </svg>
    </div>
  `;
}

function csiFeedbackComparisonTable(rows) {
  const headers = [
    "Result variant",
    "CSI codec",
    "Feedback transport",
    "Latent dimension",
    "Actual feedback bits / sample",
    "Compression factor",
    "NMSE (dB) ↓",
    "Phase-invariant cosine ↑",
    "Achievable SE (bit/s/Hz) ↑",
    "Perfect-CSI SE (bit/s/Hz)",
    "Rate retention ↑",
    "Rate loss (bit/s/Hz) ↓",
  ];
  const labels = recipeDisplayLabels((rows || []).map((row) => row.recipe));
  const body = resultSummaryTableRows(rows, labels, (row, summary, index, summaries, title, details) => {
    const parts = csiFeedbackRecipeParts(summary, row);
    const runtime = String((parts.encoder.params || {}).runtime || "training_interface");
    const transport = String((parts.link.params || {}).mode || "ideal_noiseless");
    const feedbackBits = csiFeedbackMetricValue(details, "feedback_bits_per_sample");
    return [
      summaryDisplayTitle(title, summary, index, summaries),
      humanizeIdentifier(runtime),
      transport === "uniform_quantized" ? "Uniform quantized" : "Ideal continuous (not bit-counted)",
      numericMetricCell("Feedback dimension", csiFeedbackMetricValue(details, "feedback_dimension")),
      Number.isFinite(feedbackBits) ? formatInteger(feedbackBits) : "continuous — not bits",
      numericMetricCell("Compression factor", csiFeedbackMetricValue(details, "compression_factor")),
      numericMetricCell("CSI NMSE dB", csiFeedbackMetricValue(details, "nmse_db")),
      numericMetricCell("CSI cosine", csiFeedbackMetricValue(details, "phase_invariant_cosine")),
      numericMetricCell("Achievable spectral efficiency", csiFeedbackMetricValue(details, "achieved_spectral_efficiency_bps_hz")),
      numericMetricCell("Perfect CSI spectral efficiency", csiFeedbackMetricValue(details, "perfect_csi_spectral_efficiency_bps_hz")),
      numericMetricCell("Spectral efficiency retention", csiFeedbackMetricValue(details, "spectral_efficiency_retention")),
      numericMetricCell("Spectral efficiency loss", csiFeedbackMetricValue(details, "spectral_efficiency_loss_bps_hz")),
    ];
  });
  return table(headers, body);
}

function resourceAllocationPreview(details) {
  for (const item of (details && details.artifacts) || []) {
    const metadata = item && item.artifact && item.artifact.metadata;
    if (!metadata || typeof metadata !== "object") continue;
    const candidates = [
      metadata.resource_allocation_preview,
      metadata.metadata && metadata.metadata.resource_allocation_preview,
    ];
    const preview = candidates.find((candidate) => candidate && Array.isArray(candidate.snapshots));
    if (preview) return preview;
  }
  return null;
}

function resourceAllocationEntries(rows, labels = recipeDisplayLabels((rows || []).map((row) => row.recipe))) {
  return (rows || []).flatMap((row) => {
    const title = recipeDisplayName(row.recipe, labels);
    const summaries = resultSummaries(row);
    return summaries.map((summary, index) => {
      const details = collectRunDetails(summary);
      const preview = resourceAllocationPreview(details);
      if (!preview) return null;
      const variant = resultVariantLabel(summary, index);
      const metadata = summary && summary.recipe && summary.recipe.metadata ? summary.recipe.metadata : {};
      const matrixSelection = resultMatrixSelection(metadata);
      const hasNamedVariant = summaries.length > 1 || Boolean(
        canonicalMatrixVariantLabel(summary && summary.recipe) ||
        legacyResultVariantLabel(summary) ||
        Object.keys(matrixSelection).length,
      );
      return {
        id: String(summary.run_id || `${resultRowKey(row)}:${index}`),
        key: resultRowKey(row),
        row,
        summary,
        details,
        preview,
        title: hasNamedVariant ? `${title} - ${variant}` : title,
        variant,
        variantIndex: index,
        variantCount: summaries.length,
        color: recipeColor(row.recipe),
      };
    });
  }).filter(Boolean);
}

function indexedResourceAllocationSnapshots(entry) {
  return ((entry && entry.preview && entry.preview.snapshots) || []).map((snapshot, index) => ({
    snapshot,
    index: Number.isFinite(Number(snapshot && snapshot.index)) ? Number(snapshot.index) : index,
  }));
}

function resourceAllocationSnapshotIndices(entries) {
  return Array.from(new Set((entries || []).flatMap((entry) => (
    indexedResourceAllocationSnapshots(entry).map((item) => item.index)
  )))).sort((left, right) => left - right);
}

function resourceAllocationSnapshotAt(entry, snapshotIndex) {
  const snapshots = indexedResourceAllocationSnapshots(entry);
  const exact = snapshots.find((item) => item.index === snapshotIndex);
  return exact ? exact.snapshot : null;
}

function resourceAllocationValuesMatch(left, right) {
  if (!Array.isArray(left) || !Array.isArray(right) || left.length !== right.length) return false;
  return left.every((value, index) => {
    const leftNumber = Number(value);
    const rightNumber = Number(right[index]);
    if (!Number.isFinite(leftNumber) || !Number.isFinite(rightNumber)) return false;
    return Math.abs(leftNumber - rightNumber) <= 1e-7 * Math.max(1, Math.abs(leftNumber), Math.abs(rightNumber));
  });
}

function resourceAllocationSnrGroups(
  series,
  valueKey = "snrValues",
  gainKey = "gainValues",
  inverseKey = "inverseValues",
) {
  const groups = [];
  (series || []).forEach((item) => {
    const values = Array.isArray(item[valueKey]) ? item[valueKey] : [];
    if (!values.length) return;
    const matching = groups.find((group) => resourceAllocationValuesMatch(group.values, values));
    if (matching) {
      matching.members.push(item);
      return;
    }
    groups.push({
      values,
      gainValues: Array.isArray(item[gainKey]) ? item[gainKey] : [],
      inverseValues: inverseKey && Array.isArray(item[inverseKey]) ? item[inverseKey] : [],
      members: [item],
    });
  });
  return groups;
}

function resourceAllocationLineDash(index) {
  return ["", "8 4", "3 3", "11 3 2 3", "2 3"][Math.abs(integerOr(index, 0)) % 5];
}

function resourceAllocationCommonValue(series, getter) {
  const values = (series || []).map(getter).map(Number);
  if (!values.length || values.some((value) => !Number.isFinite(value))) return NaN;
  return values.every((value) => Math.abs(value - values[0]) <= 1e-7 * Math.max(1, Math.abs(value), Math.abs(values[0])))
    ? values[0]
    : NaN;
}

function resourceAllocationPowerPolylineSegments(values, xAt, yScale, logarithmic) {
  const segments = [];
  let current = [];
  (values || []).forEach((value, index) => {
    const numeric = Number(value);
    if (Number.isFinite(numeric) && (!logarithmic || numeric > 0)) {
      current.push(`${xAt(index).toFixed(1)},${yScale(numeric).toFixed(1)}`);
      return;
    }
    if (current.length) segments.push(current.join(" "));
    current = [];
  });
  if (current.length) segments.push(current.join(" "));
  return segments;
}

function resourceSubcarrierTicks(domain, channelCount, targetCount = 12) {
  if (!validDomain(domain) || !(channelCount > 0)) return [];
  const first = Math.max(0, Math.ceil(domain[0]));
  const last = Math.min(channelCount - 1, Math.floor(domain[1]));
  if (last < first) return [];
  const step = Math.max(1, Math.ceil((last - first + 1) / Math.max(1, targetCount)));
  const alignedFirst = Math.ceil(first / step) * step;
  const ticks = [];
  for (let value = alignedFirst; value <= last; value += step) ticks.push(value);
  return ticks;
}

function resourceAllocationFigure(rows) {
  const labels = recipeDisplayLabels((rows || []).map((row) => row.recipe));
  const entries = resourceAllocationEntries(rows, labels);
  if (!entries.length) {
    return `
      <div class="rd-chart-wrap resource-allocation-chart-wrap empty">
        <div class="result-empty">Rerun an OFDM resource-allocation recipe to record per-subcarrier SNR and allocated-power values.</div>
      </div>
    `;
  }
  const settings = { ...RESOURCE_ALLOCATION_DEFAULT_SETTINGS, ...(state.resourceAllocationSettings || {}) };
  settings.powerYLog = coerceBoolean(settings.powerYLog);
  const snapshotIndices = resourceAllocationSnapshotIndices(entries);
  if (!snapshotIndices.length) return "";
  const requestedSnapshotIndex = Number(settings.snapshotIndex);
  const snapshotIndex = snapshotIndices.includes(requestedSnapshotIndex) ? requestedSnapshotIndex : snapshotIndices[0];
  const series = entries.map((entry) => {
    const snapshot = resourceAllocationSnapshotAt(entry, snapshotIndex);
    if (!snapshot) return null;
    const snrValues = Array.isArray(snapshot.unit_power_snr_db) ? snapshot.unit_power_snr_db.map(Number) : [];
    const powerValues = Array.isArray(snapshot.allocated_power) ? snapshot.allocated_power.map(Number) : [];
    const channelCount = Math.min(snrValues.length, powerValues.length);
    if (!channelCount) return null;
    return {
      ...entry,
      snapshot,
      snrValues: snrValues.slice(0, channelCount),
      observedSnrValues: (Array.isArray(snapshot.observed_unit_power_snr_db) ? snapshot.observed_unit_power_snr_db : []).map(Number).slice(0, channelCount),
      powerValues: powerValues.slice(0, channelCount),
      gainValues: (Array.isArray(snapshot.channel_gain) ? snapshot.channel_gain : []).map(Number).slice(0, channelCount),
      observedGainValues: (Array.isArray(snapshot.observed_channel_gain) ? snapshot.observed_channel_gain : []).map(Number).slice(0, channelCount),
      inverseValues: (Array.isArray(snapshot.inverse_unit_snr) ? snapshot.inverse_unit_snr : []).map(Number).slice(0, channelCount),
      channelCount,
      lineDash: resourceAllocationLineDash(entry.variantIndex),
      seriesId: `power:${entry.id}`,
    };
  }).filter(Boolean);
  if (!series.length) return "";
  state.resourceAllocationSettings = { ...settings, snapshotIndex };
  const actualSnrGroups = resourceAllocationSnrGroups(series).map((group, index, groups) => {
    const sharedByAll = groups.length === 1 && group.members.length === series.length;
    const memberLabel = group.members.map((item) => item.title).join(", ");
    const traceLabel = String(group.members[0].preview.actual_trace_label || "Channel SNR");
    return {
      ...group,
      id: `snr:actual:${index}`,
      color: groups.length === 1 ? "var(--cyan)" : group.members[0].color,
      lineDash: groups.length === 1 ? "" : resourceAllocationLineDash(index + 1),
      label: sharedByAll ? `${traceLabel} · shared by all runs` : `${traceLabel} · ${memberLabel}`,
      traceKind: "actual",
    };
  });
  const observedSnrGroups = resourceAllocationSnrGroups(
    series,
    "observedSnrValues",
    "observedGainValues",
    null,
  ).map((group, index, groups) => {
    const sharedByAll = groups.length === 1 && group.members.length === series.length;
    const memberLabel = group.members.map((item) => item.title).join(", ");
    const traceLabel = String(group.members[0].preview.observed_trace_label || "Delayed/noisy transmitter CSI");
    return {
      ...group,
      id: `snr:observed:${index}`,
      color: groups.length === 1 ? "var(--amber)" : group.members[0].color,
      lineDash: groups.length === 1 ? "7 4" : resourceAllocationLineDash(index + 2),
      label: sharedByAll ? `${traceLabel} · shared by all runs` : `${traceLabel} · ${memberLabel}`,
      traceKind: "observed",
    };
  });
  const snrGroups = [...actualSnrGroups, ...observedSnrGroups];
  const channelCount = Math.max(
    ...series.map((item) => item.channelCount),
    ...snrGroups.map((group) => group.values.length),
  );
  const width = 1280;
  const height = 380;
  const margin = { left: 72, right: 72, top: 54, bottom: 48 };
  const baseLeftDomain = paddedDomain(snrGroups.flatMap((group) => group.values), 0.1, false);
  const powerValues = series.flatMap((item) => item.powerValues).filter(Number.isFinite);
  const powerYLog = settings.powerYLog && powerValues.some((value) => value > 0);
  const baseRightDomain = powerYLog
    ? chartDomainForValues(powerValues, 0.08, false, true)
    : paddedDomain([0, ...powerValues], 0.08, true);
  const baseXDomain = [-0.5, Math.max(0.5, channelCount - 0.5)];
  const domainSignature = `snapshot:${snapshotIndex}:channels:${channelCount}:power-${powerYLog ? "log" : "linear"}`;
  const domains = domainChartVisibleDomains(
    "resource-allocation",
    baseXDomain,
    baseLeftDomain,
    {
      signature: domainSignature,
      xMetric: "subcarrier_index",
      yMetric: "unit_power_snr_db",
      y2Metric: "allocated_power",
      y2Domain: baseRightDomain,
      y2Log: powerYLog,
    },
  );
  const xDomain = domains.x;
  const leftDomain = domains.y;
  const rightDomain = domains.y2;
  const leftScale = chartScale(leftDomain, height - margin.bottom, margin.top, false);
  const rightScale = chartScale(rightDomain, height - margin.bottom, margin.top, powerYLog);
  const leftTicks = ticksForDomain(leftDomain, 5);
  const rightTicks = chartTicksForDomain(rightDomain, 5, powerYLog);
  const plotWidth = width - margin.left - margin.right;
  const xScale = chartScale(xDomain, margin.left, width - margin.right, false);
  const xAt = (index) => xScale(index);
  const xTicks = resourceSubcarrierTicks(xDomain, channelCount, 16);
  const referenceSnr = resourceAllocationCommonValue(series, (item) => item.preview.reference_snr_db);
  const noiseVariance = resourceAllocationCommonValue(series, (item) => item.preview.noise_variance);
  const titleDetails = [
    `OFDM state ${snapshotIndex + 1}`,
    Number.isFinite(referenceSnr) ? `reference SNR ${formatValue(referenceSnr)} dB` : "",
    Number.isFinite(noiseVariance) ? `noise ${formatPowerValue(noiseVariance)}` : "",
  ].filter(Boolean).join(" · ");
  return `
    <div class="rd-chart-wrap resource-allocation-chart-wrap"${titleDetails ? ` data-ui-tooltip="${escapeAttr(titleDetails)}"` : ""}>
      <div class="resource-allocation-toolbar">
        <label>
          <span>OFDM snapshot</span>
          <select data-resource-allocation-snapshot aria-label="OFDM channel snapshot">
            ${snapshotIndices.map((index) => `<option value="${escapeAttr(index)}"${index === snapshotIndex ? " selected" : ""}>${escapeHtml(`OFDM state ${index + 1}`)}</option>`).join("")}
          </select>
        </label>
        <button class="icon-button rd-settings-button" type="button" data-resource-allocation-settings aria-label="Subcarrier allocation figure settings" data-ui-tooltip="Figure settings">&#9881;</button>
      </div>
      <svg class="rd-chart resource-allocation-chart" data-visualization-id="resource-allocation" data-power-y-log="${powerYLog ? "true" : "false"}"
        data-domain-chart data-domain-view-key="resource-allocation" data-domain-signature="${escapeAttr(domainSignature)}"
        data-width="${width}" data-height="${height}"
        data-left="${margin.left}" data-right="${margin.right}" data-top="${margin.top}" data-bottom="${margin.bottom}"
        data-x-min="${xDomain[0]}" data-x-max="${xDomain[1]}" data-y-min="${leftDomain[0]}" data-y-max="${leftDomain[1]}"
        data-y2-min="${rightDomain[0]}" data-y2-max="${rightDomain[1]}"
        data-x-metric="subcarrier_index" data-y-metric="unit_power_snr_db" data-y2-metric="allocated_power"
        data-x-log="false" data-y-log="false" data-y2-log="${powerYLog ? "true" : "false"}"
        viewBox="0 0 ${width} ${height}" preserveAspectRatio="xMidYMid meet" role="img" aria-label="Per-subcarrier channel SNR and allocated-power comparison">
        <defs>
          <clipPath id="resource-allocation-plot-clip">
            <rect x="${margin.left}" y="${margin.top}" width="${width - margin.left - margin.right}" height="${height - margin.top - margin.bottom}"></rect>
          </clipPath>
        </defs>
        <text class="rd-plot-title" x="${width / 2}" y="18" text-anchor="middle">Subcarrier SNR &amp; Power</text>
        <line class="rd-axis" x1="${margin.left}" y1="${height - margin.bottom}" x2="${width - margin.right}" y2="${height - margin.bottom}"></line>
        <line class="rd-axis" x1="${margin.left}" y1="${margin.top}" x2="${margin.left}" y2="${height - margin.bottom}"></line>
        <line class="rd-axis resource-allocation-right-axis" x1="${width - margin.right}" y1="${margin.top}" x2="${width - margin.right}" y2="${height - margin.bottom}"></line>
        ${leftTicks.map((tick) => `
          <g class="rd-tick y">
            <line x1="${margin.left}" y1="${leftScale(tick)}" x2="${width - margin.right}" y2="${leftScale(tick)}"></line>
            <text x="${margin.left - 12}" y="${leftScale(tick) + 3}">${escapeHtml(formatValue(tick))}</text>
          </g>
        `).join("")}
        ${rightTicks.map((tick) => `
          <g class="rd-tick y resource-allocation-right-tick">
            <text x="${width - margin.right + 12}" y="${rightScale(tick) + 3}">${escapeHtml(formatPowerValue(tick))}</text>
          </g>
        `).join("")}
        ${snrGroups.map((group) => `
          <g class="resource-allocation-series resource-snr-series" clip-path="url(#resource-allocation-plot-clip)" data-resource-allocation-series-id="${escapeAttr(group.id)}" style="--series-color: ${escapeAttr(group.color)}">
            <polyline class="resource-snr-line" stroke-dasharray="${escapeAttr(group.lineDash || "none")}" points="${escapeAttr(group.values.map((snr, index) => `${xAt(index).toFixed(1)},${leftScale(snr).toFixed(1)}`).join(" "))}"></polyline>
            ${group.values.map((snr, index) => {
              const tooltip = [
                group.label,
                `OFDM state ${snapshotIndex + 1}`,
                `Subcarrier ${index}`,
                `unit-power SNR ${formatValue(snr)} dB`,
                Number.isFinite(group.gainValues[index]) ? `|H|² ${formatPowerValue(group.gainValues[index])}` : "",
                Number.isFinite(group.inverseValues[index]) ? `noise/|H|² ${formatPowerValue(group.inverseValues[index])}` : "",
              ].filter(Boolean).join("\n");
              return `<circle class="resource-snr-point" cx="${xAt(index).toFixed(1)}" cy="${leftScale(snr).toFixed(1)}" r="3" tabindex="0" role="img" aria-label="${escapeAttr(tooltip)}" data-result-tooltip="${escapeAttr(tooltip)}"></circle>`;
            }).join("")}
          </g>
        `).join("")}
        ${series.map((item) => {
          const averagePower = item.powerValues.reduce((sum, value) => sum + value, 0) / item.powerValues.length;
          const seriesTooltip = [
            item.title,
            `OFDM state ${snapshotIndex + 1}`,
            `average allocated power ${formatPowerValue(averagePower)}`,
          ].join("\n");
          return `
            <g class="resource-allocation-series resource-power-series" clip-path="url(#resource-allocation-plot-clip)" data-result-key="${escapeAttr(item.key)}" data-resource-allocation-series-id="${escapeAttr(item.seriesId)}" style="--series-color: ${escapeAttr(item.color)}" tabindex="0" role="img" aria-label="${escapeAttr(seriesTooltip)}" data-result-tooltip="${escapeAttr(seriesTooltip)}">
              ${resourceAllocationPowerPolylineSegments(item.powerValues, xAt, rightScale, powerYLog).map((points) => `<polyline class="resource-power-line" stroke-dasharray="${escapeAttr(item.lineDash || "none")}" points="${escapeAttr(points)}"></polyline>`).join("")}
              ${item.powerValues.map((power, index) => {
                if (powerYLog && !(power > 0)) return "";
                const waterLevel = Number(item.snapshot.water_level);
                const tooltip = [
                  item.title,
                  `OFDM state ${snapshotIndex + 1}`,
                  `Subcarrier ${index}`,
                  `unit-power SNR ${formatValue(item.snrValues[index])} dB`,
                  `allocated power ${formatPowerValue(power)}`,
                  Number.isFinite(item.gainValues[index]) ? `|H|² ${formatPowerValue(item.gainValues[index])}` : "",
                  Number.isFinite(item.inverseValues[index]) ? `noise/|H|² ${formatPowerValue(item.inverseValues[index])}` : "",
                  Number.isFinite(waterLevel) ? `water level ${formatPowerValue(waterLevel)}` : "",
                ].filter(Boolean).join("\n");
                return `<circle class="resource-power-point" cx="${xAt(index).toFixed(1)}" cy="${rightScale(power).toFixed(1)}" r="3" tabindex="0" role="img" aria-label="${escapeAttr(tooltip)}" data-result-tooltip="${escapeAttr(tooltip)}"></circle>`;
              }).join("")}
            </g>
          `;
        }).join("")}
        ${xTicks.map((index) => `<text class="resource-channel-label" x="${xAt(index).toFixed(1)}" y="${height - 27}" text-anchor="middle">${index}</text>`).join("")}
        <text class="rd-axis-label" x="${width / 2}" y="${height - 5}">OFDM subcarrier index</text>
        <text class="rd-axis-label y resource-snr-axis-label" x="14" y="${height / 2}" transform="rotate(-90 14 ${height / 2})">Unit-power SNR (dB)</text>
        <text class="rd-axis-label y resource-power-axis-label" x="${width - 10}" y="${height / 2}" transform="rotate(90 ${width - 10} ${height / 2})">Allocated power</text>
      </svg>
      <div class="resource-allocation-series-legend" aria-label="Subcarrier allocation comparison legend">
        ${snrGroups.map((group) => `
          <button type="button" data-resource-allocation-legend-id="${escapeAttr(group.id)}" style="--series-color: ${escapeAttr(group.color)}" title="${escapeAttr(group.label)}">
            <svg viewBox="0 0 24 8" aria-hidden="true"><line x1="1" y1="4" x2="23" y2="4" stroke-dasharray="${escapeAttr(group.lineDash || "none")}"></line></svg>
            <span>${escapeHtml(group.label)}</span>
          </button>
        `).join("")}
        ${series.map((item) => `
          <button type="button" data-resource-allocation-legend-id="${escapeAttr(item.seriesId)}" style="--series-color: ${escapeAttr(item.color)}" title="${escapeAttr(item.title)}">
            <svg viewBox="0 0 24 8" aria-hidden="true"><line x1="1" y1="4" x2="23" y2="4" stroke-dasharray="${escapeAttr(item.lineDash || "none")}"></line></svg>
            <span>${escapeHtml(item.title)}</span>
          </button>
        `).join("")}
      </div>
    </div>
  `;
}

function resourcePerformanceItems(rows, labels = recipeDisplayLabels((rows || []).map((row) => row.recipe))) {
  return resourceAllocationEntries(rows, labels).map((entry) => {
    const measuredPayloadGoodput = numberMetricValue(entry.details, [
      "evaluation.channel.achieved_payload_goodput_bits_per_resource_element",
      "channel.achieved_payload_goodput_bits_per_resource_element",
    ]);
    const finiteBlocklengthGoodput = numberMetricValue(entry.details, [
      "evaluation.resource.finite_blocklength.expected_goodput_bps_hz",
      "resource.finite_blocklength.expected_goodput_bps_hz",
    ]);
    const finiteBlocklengthBler = numberMetricValue(entry.details, [
      "evaluation.resource.finite_blocklength.predicted_bler",
      "resource.finite_blocklength.predicted_bler",
    ]);
    return {
      ...entry,
      goodput: Number.isFinite(finiteBlocklengthGoodput) ? finiteBlocklengthGoodput : measuredPayloadGoodput,
      measuredPayloadGoodput,
      finiteBlocklengthGoodput,
      finiteBlocklengthBler,
      powerBudget: numberMetricValue(entry.details, [
        "evaluation.resource.average_transmit_power_budget",
        "resource.average_transmit_power_budget",
      ]),
      noiseVariance: numberMetricValue(entry.details, [
        "evaluation.channel.noise_variance",
        "channel.noise_variance",
      ]),
      offeredRate: numberMetricValue(entry.details, [
        "evaluation.channel.offered_payload_bits_per_resource_element",
        "channel.offered_payload_bits_per_resource_element",
      ]),
      scheduled: numberMetricValue(entry.details, [
        "evaluation.channel.scheduled_resource_element_count",
        "channel.scheduled_resource_element_count",
      ]),
      energyPerBit: numberMetricValue(entry.details, [
        "evaluation.channel.tx_energy_per_delivered_payload_bit",
        "channel.tx_energy_per_delivered_payload_bit",
      ]),
      deliveryBler: numberMetricValue(entry.details, [
        "evaluation.channel.payload_delivery_block_error_rate",
        "channel.payload_delivery_block_error_rate",
      ]),
      energyEfficiency: numberMetricValue(entry.details, [
        "evaluation.channel.payload_energy_efficiency_bits_per_normalized_energy",
        "channel.payload_energy_efficiency_bits_per_normalized_energy",
      ]),
      outage: numberMetricValue(entry.details, [
        "evaluation.resource.theoretical_outage_probability",
        "resource.theoretical_outage_probability",
      ]),
      spectralEfficiency: numberMetricValue(entry.details, [
        "evaluation.resource.theoretical_shannon_spectral_efficiency_bps_hz",
        "resource.theoretical_shannon_spectral_efficiency_bps_hz",
      ]),
      oracleSpectralEfficiency: numberMetricValue(entry.details, [
        "evaluation.resource.water_filling_oracle_spectral_efficiency_bps_hz",
        "resource.water_filling_oracle_spectral_efficiency_bps_hz",
      ]),
      oracleGap: numberMetricValue(entry.details, [
        "evaluation.resource.water_filling_optimality_gap_bps_hz",
        "resource.water_filling_optimality_gap_bps_hz",
      ]),
      oracleRelativeGap: numberMetricValue(entry.details, [
        "evaluation.resource.water_filling_relative_optimality_gap",
        "resource.water_filling_relative_optimality_gap",
      ]),
      oraclePowerNormalizedRmse: numberMetricValue(entry.details, [
        "evaluation.resource.water_filling_power_normalized_rmse",
        "resource.water_filling_power_normalized_rmse",
      ]),
      oracleKktResidual: numberMetricValue(entry.details, [
        "evaluation.resource.water_filling_kkt_normalized_residual",
        "resource.water_filling_kkt_normalized_residual",
      ]),
      powerErrorAbs: numberMetricValue(entry.details, [
        "evaluation.resource.power_constraint.max_abs_error",
        "resource.power_constraint.max_abs_error",
      ]),
      powerErrorRelative: numberMetricValue(entry.details, [
        "evaluation.resource.power_constraint.max_relative_error",
        "resource.power_constraint.max_relative_error",
      ]),
      negativePowerViolation: numberMetricValue(entry.details, [
        "evaluation.resource.power_constraint.max_negative_violation",
        "resource.power_constraint.max_negative_violation",
      ]),
      targetSpectralEfficiency: numberMetricValue(entry.details, [
        "evaluation.resource.theoretical_outage_target_spectral_efficiency_bps_hz",
        "resource.theoretical_outage_target_spectral_efficiency_bps_hz",
      ]),
    };
  }).filter(Boolean);
}

function resourceAllocationPolicyName(item) {
  const rawPolicy = String((item.preview && item.preview.policy) || item.title || "policy");
  const normalized = rawPolicy.toLowerCase();
  if (
    normalized.includes("causal") &&
    (normalized.includes("ar") || normalized.includes("predict"))
  ) return "Complex-AR prediction + water filling";
  if (
    normalized.includes("robust") ||
    normalized.includes("shrunk") ||
    normalized.includes("shrinkage")
  ) return "Uncertainty-shrunk water filling";
  if (
    normalized.includes("water") &&
    (
      normalized.includes("observed") ||
      normalized.includes("stale") ||
      normalized.includes("delayed") ||
      normalized.includes("imperfect")
    )
  ) return "Water filling on delayed CSI";
  if (normalized.includes("water")) return "Water filling (Shannon oracle)";
  if (normalized === "fixed" || normalized.includes("equal power")) return "Equal power";
  if (normalized.includes("learned") || normalized.includes("checkpoint")) return "Learned allocation";
  return rawPolicy.replace(/_/g, " ");
}

function resourcePolicySeries(items, valueKey) {
  const grouped = new Map();
  (items || []).forEach((item) => {
    const policy = resourceAllocationPolicyName(item);
    if (!grouped.has(policy)) grouped.set(policy, []);
    grouped.get(policy).push(item);
  });
  return Array.from(grouped.entries()).map(([label, points]) => ({
    label,
    color: points[0].color,
    points: points
      .filter((point) => Number.isFinite(point.powerBudget) && Number.isFinite(point[valueKey]))
      .sort((left, right) => left.powerBudget - right.powerBudget),
  })).filter((item) => item.points.length);
}

function resourceFiniteBlocklengthOverviewFigures(rows) {
  const labels = recipeDisplayLabels((rows || []).map((row) => row.recipe));
  const items = resourcePerformanceItems(rows, labels);
  return [
    resourceFiniteBlocklengthMetricFigure(items, {
      valueKey: "finiteBlocklengthGoodput",
      visualizationId: "resource-finite-blocklength-goodput",
      title: "Finite-Blocklength Expected Goodput",
      yLabel: "Expected goodput (bit/s/Hz)",
      metricLabel: "expected goodput",
      defaultYLog: false,
    }),
    resourceFiniteBlocklengthMetricFigure(items, {
      valueKey: "finiteBlocklengthBler",
      visualizationId: "resource-finite-blocklength-bler",
      title: "Finite-Blocklength Predicted BLER",
      yLabel: "Predicted block error rate",
      metricLabel: "predicted BLER",
      defaultYLog: true,
    }),
  ].filter(Boolean).join("");
}

function resourceFiniteBlocklengthMetricFigure(items, config) {
  const candidates = (items || []).filter((item) => (
    Number.isFinite(item.powerBudget) && Number.isFinite(item[config.valueKey])
  ));
  const grouped = resourcePolicySeries(candidates, config.valueKey).map((item, index) => ({
    ...item,
    id: `${config.visualizationId}:${index}`,
  }));
  if (!grouped.length) return "";
  const useLines = resourceSeriesHasPowerSweep(grouped);
  const width = RESULT_FIGURE_WIDTH;
  const height = RESULT_FIGURE_HEIGHT;
  const margin = { left: 78, right: 24, top: 31, bottom: useLines ? 48 : 66 };
  const xValues = candidates.map((item) => item.powerBudget);
  const yValues = candidates.map((item) => item[config.valueKey]);
  const xSupportsLog = useLines && xValues.every((value) => value > 0);
  const ySupportsLog = yValues.every((value) => value > 0);
  const xLog = xSupportsLog && visualizationAxisLogEnabled(config.visualizationId, "x", false);
  const yLog = ySupportsLog && visualizationAxisLogEnabled(
    config.visualizationId,
    "y",
    Boolean(config.defaultYLog),
  );
  const baseXDomain = useLines
    ? chartDomainForValues(xValues, 0.12, !xLog, xLog)
    : null;
  const baseYDomain = chartDomainForValues(yValues, 0.14, !yLog, yLog);
  const domainSignature = `power-budget:${config.valueKey}:${xLog ? "log" : "linear"}:${yLog ? "log" : "linear"}`;
  const domains = useLines
    ? domainChartVisibleDomains(
      config.visualizationId,
      baseXDomain,
      baseYDomain,
      {
        signature: domainSignature,
        xMetric: "average_power_budget",
        yMetric: config.valueKey,
        xLog,
        yLog,
      },
    )
    : { x: null, y: baseYDomain };
  const xDomain = domains.x;
  const yDomain = domains.y;
  const xScale = useLines ? chartScale(xDomain, margin.left, width - margin.right, xLog) : null;
  const yScale = chartScale(yDomain, height - margin.bottom, margin.top, yLog);
  const xTicks = useLines ? chartTicksForDomain(xDomain, 4, xLog) : [];
  const yTicks = chartTicksForDomain(yDomain, 4, yLog);
  const barEntries = useLines ? [] : grouped.flatMap((item) => item.points.map((point, index) => ({
    id: `${item.id}:bar:${index}`,
    label: item.points.length > 1 ? point.title : item.label,
    color: point.color || item.color,
    point,
  })));
  const plotWidth = width - margin.left - margin.right;
  const barSlotWidth = plotWidth / Math.max(1, barEntries.length);
  const barWidth = Math.max(22, Math.min(58, barSlotWidth * 0.46));
  const legendEntries = useLines
    ? grouped.map((item) => ({ id: item.id, label: item.label, color: item.color }))
    : barEntries;
  const tooltipText = (label, point) => [
    label,
    `average power budget ${formatPowerValue(point.powerBudget)}`,
    `${config.metricLabel} ${formatMetricNumber(point[config.valueKey], 6)}`,
  ].join("\n");
  return `
    <div class="rd-chart-wrap resource-finite-blocklength-chart-wrap">
      <svg class="rd-chart resource-finite-blocklength-chart"
        data-visualization-id="${escapeAttr(config.visualizationId)}"
        data-log-axes="${useLines ? "x " : ""}y"
        data-x-log="${xLog ? "true" : "false"}" data-y-log="${yLog ? "true" : "false"}"
        ${useLines ? `data-domain-chart data-domain-view-key="${escapeAttr(config.visualizationId)}" data-domain-signature="${escapeAttr(domainSignature)}"
        data-width="${width}" data-height="${height}"
        data-left="${margin.left}" data-right="${margin.right}" data-top="${margin.top}" data-bottom="${margin.bottom}"
        data-x-min="${xDomain[0]}" data-x-max="${xDomain[1]}" data-y-min="${yDomain[0]}" data-y-max="${yDomain[1]}"
        data-x-metric="average_power_budget" data-y-metric="${escapeAttr(config.valueKey)}"` : ""}
        viewBox="0 0 ${width} ${height}" preserveAspectRatio="xMidYMid meet"
        role="img" aria-label="${escapeAttr(`${config.title} versus average transmit-power budget`)}">
        ${useLines ? `<defs>
          <clipPath id="${escapeAttr(config.visualizationId)}-clip">
            <rect x="${margin.left}" y="${margin.top}" width="${width - margin.left - margin.right}" height="${height - margin.top - margin.bottom}"></rect>
          </clipPath>
        </defs>` : ""}
        <text class="rd-plot-title" x="${width / 2}" y="14" text-anchor="middle">${escapeHtml(config.title)}${useLines ? " vs Power Budget" : ""}</text>
        <line class="rd-axis" x1="${margin.left}" y1="${height - margin.bottom}" x2="${width - margin.right}" y2="${height - margin.bottom}"></line>
        <line class="rd-axis" x1="${margin.left}" y1="${margin.top}" x2="${margin.left}" y2="${height - margin.bottom}"></line>
        ${xTicks.map((tick) => `
          <g class="rd-tick">
            <line x1="${xScale(tick)}" y1="${margin.top}" x2="${xScale(tick)}" y2="${height - margin.bottom}"></line>
            <text x="${xScale(tick)}" y="${height - 22}">${escapeHtml(formatPowerValue(tick))}</text>
          </g>
        `).join("")}
        ${yTicks.map((tick) => `
          <g class="rd-tick y">
            <line x1="${margin.left}" y1="${yScale(tick)}" x2="${width - margin.right}" y2="${yScale(tick)}"></line>
            <text x="${margin.left - 12}" y="${yScale(tick) + 3}">${escapeHtml(formatMetricNumber(tick, 4))}</text>
          </g>
        `).join("")}
        ${useLines ? `
          <g clip-path="url(#${escapeAttr(config.visualizationId)}-clip)">
            ${grouped.map((item) => `
              <g class="visualization-series resource-performance-series" data-visualization-series-key="${escapeAttr(item.id)}" style="--recipe-color: ${escapeAttr(item.color)}">
                <polyline class="rd-series-line" points="${escapeAttr(item.points.map((point) => `${xScale(point.powerBudget).toFixed(1)},${yScale(point[config.valueKey]).toFixed(1)}`).join(" "))}"></polyline>
                ${item.points.map((point) => `
                  <g class="rd-point" data-result-key="${escapeAttr(point.key)}" tabindex="0" role="img"
                    aria-label="${escapeAttr(tooltipText(item.label, point))}" data-result-tooltip="${escapeAttr(tooltipText(item.label, point))}"
                    transform="translate(${xScale(point.powerBudget).toFixed(1)}, ${yScale(point[config.valueKey]).toFixed(1)})"
                    style="--recipe-color: ${escapeAttr(item.color)}"><circle r="5"></circle></g>
                `).join("")}
              </g>
            `).join("")}
          </g>
        ` : barEntries.map((entry, index) => {
          const x = margin.left + barSlotWidth * (index + 0.5);
          const y = yScale(entry.point[config.valueKey]);
          const baseline = height - margin.bottom;
          return `
            <g class="visualization-series resource-performance-series" data-visualization-series-key="${escapeAttr(entry.id)}"
              data-result-key="${escapeAttr(entry.point.key)}" style="--recipe-color: ${escapeAttr(entry.color)}"
              tabindex="0" role="img" aria-label="${escapeAttr(tooltipText(entry.label, entry.point))}"
              data-result-tooltip="${escapeAttr(tooltipText(entry.label, entry.point))}">
              <rect class="resource-se-bar" x="${(x - barWidth / 2).toFixed(1)}" y="${y.toFixed(1)}"
                width="${barWidth.toFixed(1)}" height="${Math.max(1, baseline - y).toFixed(1)}" rx="3"></rect>
              <text class="resource-se-bar-label" x="${x.toFixed(1)}" y="${height - 31}" text-anchor="middle">${escapeHtml(trim(entry.label, 18))}</text>
              <text class="resource-se-bar-power" x="${x.toFixed(1)}" y="${height - 17}" text-anchor="middle">${escapeHtml(`P=${formatPowerValue(entry.point.powerBudget)}`)}</text>
            </g>
          `;
        }).join("")}
        ${useLines ? `<text class="rd-axis-label" x="${width / 2}" y="${height - 5}">Average transmit-power budget per subcarrier</text>` : ""}
        <text class="rd-axis-label y" x="14" y="${height / 2}" transform="rotate(-90 14 ${height / 2})">${escapeHtml(config.yLabel)}</text>
      </svg>
      ${resourcePerformanceLegendMarkup(legendEntries, useLines ? "line" : "bar", `${config.title} methods`)}
    </div>
  `;
}

function resourceDeliveryFigure(rows) {
  const labels = recipeDisplayLabels((rows || []).map((row) => row.recipe));
  const items = resourcePerformanceItems(rows, labels).filter((item) => Number.isFinite(item.goodput));
  if (!items.length) return "";
  const settings = normalizedResourcePerformanceSettings();
  const series = resourcePolicySeries(items, "goodput");
  if (resourceSeriesHasPowerSweep(series)) return resourceDeliverySweepFigure(items);
  const width = RESULT_FIGURE_WIDTH;
  const height = RESULT_FIGURE_HEIGHT;
  const margin = { left: 78, right: 18, top: 24, bottom: 66 };
  const baseline = height - margin.bottom;
  const yValues = items.map((item) => item.goodput);
  const yLog = settings.yLog && yValues.every((value) => value > 0);
  const yDomain = chartDomainForValues(yValues, 0.18, settings.includeZero && !yLog, yLog);
  const yScale = chartScale(yDomain, baseline, margin.top, yLog);
  const yTicks = chartTicksForDomain(yDomain, 4, yLog);
  const slotWidth = (width - margin.left - margin.right) / Math.max(1, items.length);
  const barWidth = Math.max(20, Math.min(54, slotWidth * 0.42));
  return `
    <div class="rd-chart-wrap resource-delivery-chart-wrap">
      <button class="icon-button rd-settings-button" type="button" data-resource-performance-settings="goodput" aria-label="Payload goodput figure settings">&#9881;</button>
      <svg class="rd-chart resource-delivery-chart" data-visualization-id="resource-goodput" data-y-log="${yLog ? "true" : "false"}" viewBox="0 0 ${width} ${height}" preserveAspectRatio="xMidYMid meet" role="img" aria-label="Measured payload goodput comparison">
        <text class="rd-plot-title" x="${width / 2}" y="12" text-anchor="middle">Measured Payload Goodput</text>
        <line class="rd-axis" x1="${margin.left}" y1="${baseline}" x2="${width - margin.right}" y2="${baseline}"></line>
        <line class="rd-axis" x1="${margin.left}" y1="${margin.top}" x2="${margin.left}" y2="${baseline}"></line>
        ${yTicks.map((tick) => `
          <g class="rd-tick y">
            <line x1="${margin.left}" y1="${yScale(tick)}" x2="${width - margin.right}" y2="${yScale(tick)}"></line>
            <text x="${margin.left - 12}" y="${yScale(tick) + 3}">${escapeHtml(formatMetricNumber(tick, 4))}</text>
          </g>
        `).join("")}
        ${items.map((item, index) => {
          const x = margin.left + slotWidth * (index + 0.5);
          const y = yScale(item.goodput);
          const tooltip = [
            item.title,
            Number.isFinite(item.powerBudget) ? `average power budget ${formatPowerValue(item.powerBudget)}` : "",
            Number.isFinite(item.offeredRate) ? `offered payload rate ${formatMetricNumber(item.offeredRate, 5)} bit/resource-element` : "",
            `achieved payload goodput ${formatMetricNumber(item.goodput, 5)} bit/resource-element`,
            Number.isFinite(item.scheduled) ? `scheduled resource elements ${formatValue(item.scheduled)}` : "",
            Number.isFinite(item.energyPerBit) ? `actual TX energy/delivered bit ${formatMetricNumber(item.energyPerBit, 5)}` : "",
            Number.isFinite(item.deliveryBler) ? `payload delivery BLER diagnostic ${formatBerNumber(item.deliveryBler)}` : "",
            Number.isFinite(item.energyEfficiency) ? `RF-only energy efficiency ${formatMetricNumber(item.energyEfficiency, 5)} bit/normalized-energy` : "",
            Number.isFinite(item.outage) ? `capacity outage ${formatBerNumber(item.outage)}` : "",
          ].filter(Boolean).join("\n");
          return `
            <g class="task-performance-point" data-result-key="${escapeAttr(item.key)}" style="--recipe-color: ${escapeAttr(item.color)}" tabindex="0" role="img" aria-label="${escapeAttr(tooltip)}" data-result-tooltip="${escapeAttr(tooltip)}">
              <rect x="${(x - barWidth / 2).toFixed(1)}" y="${y.toFixed(1)}" width="${barWidth.toFixed(1)}" height="${Math.max(1, baseline - y).toFixed(1)}" rx="3"></rect>
              <circle class="${settings.showMarkers ? "" : "resource-performance-marker-hidden"}" cx="${x.toFixed(1)}" cy="${y.toFixed(1)}" r="4.5"></circle>
              ${settings.showValues ? `<text class="task-performance-value" x="${x.toFixed(1)}" y="${(y - 8).toFixed(1)}" text-anchor="middle">${escapeHtml(formatMetricNumber(item.goodput, 5))}</text>` : ""}
              <text class="task-performance-label" x="${x.toFixed(1)}" y="${height - 30}" text-anchor="middle">${escapeHtml(trim(item.title, 22))}</text>
              ${Number.isFinite(item.scheduled) ? `<text class="task-performance-label" x="${x.toFixed(1)}" y="${height - 17}" text-anchor="middle">${escapeHtml(`${formatValue(item.scheduled)} scheduled RE`)}</text>` : ""}
            </g>
          `;
        }).join("")}
        <text class="rd-axis-label y" x="14" y="${height / 2}" transform="rotate(-90 14 ${height / 2})">Delivered payload bits / scheduled RE</text>
      </svg>
    </div>
  `;
}

function resourceDeliverySweepFigure(items) {
  const settings = normalizedResourcePerformanceSettings();
  const width = RESULT_FIGURE_WIDTH;
  const height = RESULT_FIGURE_HEIGHT;
  const margin = { left: 78, right: 24, top: 30, bottom: 48 };
  const xValues = items.map((item) => item.powerBudget).filter(Number.isFinite);
  const yValues = items.map((item) => item.goodput).filter(Number.isFinite);
  if (!xValues.length || !yValues.length) return "";
  const xLog = settings.xLog && xValues.every((value) => value > 0);
  const yLog = settings.yLog && yValues.every((value) => value > 0);
  const baseXDomain = chartDomainForValues(xValues, 0.12, !xLog, xLog);
  const baseYDomain = chartDomainForValues(yValues, 0.16, settings.includeZero && !yLog, yLog);
  const domainSignature = `power-budget:goodput:${xLog ? "log" : "linear"}:${yLog ? "log" : "linear"}`;
  const domains = domainChartVisibleDomains(
    "resource-goodput",
    baseXDomain,
    baseYDomain,
    { signature: domainSignature, xMetric: "average_power_budget", yMetric: "payload_goodput", xLog, yLog },
  );
  const xDomain = domains.x;
  const yDomain = domains.y;
  const xScale = chartScale(xDomain, margin.left, width - margin.right, xLog);
  const yScale = chartScale(yDomain, height - margin.bottom, margin.top, yLog);
  const xTicks = chartTicksForDomain(xDomain, 4, xLog);
  const yTicks = chartTicksForDomain(yDomain, 4, yLog);
  const series = resourcePolicySeries(items, "goodput").map((item, index) => ({
    ...item,
    id: `resource-goodput:${index}`,
  }));
  const legendEntries = series.map((item) => ({ id: item.id, label: item.label, color: item.color }));
  return `
    <div class="rd-chart-wrap resource-delivery-chart-wrap">
      <button class="icon-button rd-settings-button" type="button" data-resource-performance-settings="goodput" aria-label="Payload goodput figure settings">&#9881;</button>
      <svg class="rd-chart resource-delivery-chart" data-visualization-id="resource-goodput"
        data-domain-chart data-domain-view-key="resource-goodput" data-domain-signature="${escapeAttr(domainSignature)}"
        data-width="${width}" data-height="${height}"
        data-left="${margin.left}" data-right="${margin.right}" data-top="${margin.top}" data-bottom="${margin.bottom}"
        data-x-min="${xDomain[0]}" data-x-max="${xDomain[1]}" data-y-min="${yDomain[0]}" data-y-max="${yDomain[1]}"
        data-x-metric="average_power_budget" data-y-metric="payload_goodput"
        data-x-log="${xLog ? "true" : "false"}" data-y-log="${yLog ? "true" : "false"}"
        viewBox="0 0 ${width} ${height}" preserveAspectRatio="xMidYMid meet" role="img" aria-label="Seeded random-bit goodput versus average transmit-power budget">
        <defs>
          <clipPath id="resource-goodput-sweep-clip">
            <rect x="${margin.left}" y="${margin.top}" width="${width - margin.left - margin.right}" height="${height - margin.top - margin.bottom}"></rect>
          </clipPath>
        </defs>
        <text class="rd-plot-title" x="${width / 2}" y="14" text-anchor="middle">Payload Goodput vs Power Budget</text>
        <line class="rd-axis" x1="${margin.left}" y1="${height - margin.bottom}" x2="${width - margin.right}" y2="${height - margin.bottom}"></line>
        <line class="rd-axis" x1="${margin.left}" y1="${margin.top}" x2="${margin.left}" y2="${height - margin.bottom}"></line>
        ${xTicks.map((tick) => `
          <g class="rd-tick">
            <line x1="${xScale(tick)}" y1="${margin.top}" x2="${xScale(tick)}" y2="${height - margin.bottom}"></line>
            <text x="${xScale(tick)}" y="${height - 22}">${escapeHtml(formatPowerValue(tick))}</text>
          </g>
        `).join("")}
        ${yTicks.map((tick) => `
          <g class="rd-tick y">
            <line x1="${margin.left}" y1="${yScale(tick)}" x2="${width - margin.right}" y2="${yScale(tick)}"></line>
            <text x="${margin.left - 12}" y="${yScale(tick) + 3}">${escapeHtml(formatMetricNumber(tick, 4))}</text>
          </g>
        `).join("")}
        <g clip-path="url(#resource-goodput-sweep-clip)">
          ${series.map((item) => `
            <g class="visualization-series resource-performance-series" data-resource-performance-series-id="${escapeAttr(item.id)}" data-visualization-series-key="${escapeAttr(item.id)}" style="--recipe-color: ${escapeAttr(item.color)}">
            <polyline class="rd-series-line" points="${escapeAttr(item.points.map((point) => `${xScale(point.powerBudget).toFixed(1)},${yScale(point.goodput).toFixed(1)}`).join(" "))}"></polyline>
            ${item.points.map((point) => {
            const tooltip = [
              item.label,
              `average power budget ${formatPowerValue(point.powerBudget)}`,
              `error-free goodput ${formatMetricNumber(point.goodput, 5)} bit/resource-element`,
              Number.isFinite(point.deliveryBler) ? `transport-block BLER ${formatBerNumber(point.deliveryBler)}` : "",
              Number.isFinite(point.energyEfficiency) ? `RF-only energy efficiency ${formatMetricNumber(point.energyEfficiency, 5)} bit/normalized-energy` : "",
              Number.isFinite(point.outage) ? `capacity outage ${formatBerNumber(point.outage)}` : "",
            ].filter(Boolean).join("\n");
            return `
              <g class="rd-point" data-result-key="${escapeAttr(point.key)}" tabindex="0" role="img" aria-label="${escapeAttr(tooltip)}" data-result-tooltip="${escapeAttr(tooltip)}" transform="translate(${xScale(point.powerBudget).toFixed(1)}, ${yScale(point.goodput).toFixed(1)})" style="--recipe-color: ${escapeAttr(item.color)}">
                <circle class="${settings.showMarkers ? "" : "resource-performance-marker-hidden"}" r="5"></circle>
              </g>
            `;
            }).join("")}
            </g>
          `).join("")}
        </g>
        <text class="rd-axis-label" x="${width / 2}" y="${height - 5}">Average transmit-power budget per subcarrier</text>
        <text class="rd-axis-label y" x="14" y="${height / 2}" transform="rotate(-90 14 ${height / 2})">Error-free payload bits / scheduled RE</text>
      </svg>
      ${resourcePerformanceLegendMarkup(legendEntries, "line", "Payload goodput allocation methods")}
    </div>
  `;
}

function resourceSeriesHasPowerSweep(series) {
  return (series || []).some((item) => (
    new Set(item.points.map((point) => Number(point.powerBudget).toPrecision(12))).size > 1
  ));
}

function resourcePerformanceLegendMarkup(entries, mode, label) {
  return `
    <div class="resource-performance-legend" aria-label="${escapeAttr(label)}">
      ${(entries || []).map((entry) => `
        <button
          type="button"
          class="visualization-series-legend"
          data-resource-performance-legend-id="${escapeAttr(entry.id)}"
          data-visualization-legend-key="${escapeAttr(entry.id)}"
          style="--recipe-color: ${escapeAttr(entry.color)}"
          title="${escapeAttr(entry.label)}"
        >
          <svg viewBox="0 0 24 10" aria-hidden="true">
            ${mode === "bar"
              ? '<rect class="resource-performance-legend-bar" x="7" y="1" width="10" height="8" rx="1"></rect>'
              : '<line class="resource-performance-legend-line" x1="1" y1="5" x2="23" y2="5"></line><circle class="resource-performance-legend-point" cx="12" cy="5" r="2.5"></circle>'}
          </svg>
          <span>${escapeHtml(entry.label)}</span>
        </button>
      `).join("")}
    </div>
  `;
}

function resourceSpectralEfficiencyFigure(rows) {
  const labels = recipeDisplayLabels((rows || []).map((row) => row.recipe));
  const items = resourcePerformanceItems(rows, labels)
    .filter((item) => Number.isFinite(item.powerBudget) && Number.isFinite(item.spectralEfficiency));
  if (!items.length) return "";
  const series = resourcePolicySeries(items, "spectralEfficiency").map((item, index) => ({
    ...item,
    id: `resource-se:${index}`,
  }));
  if (!series.length) return "";
  const settings = normalizedResourcePerformanceSettings();
  const useLines = resourceSeriesHasPowerSweep(series);
  const mode = useLines ? "line" : "bar";
  const width = RESULT_FIGURE_WIDTH;
  const height = RESULT_FIGURE_HEIGHT;
  const margin = { left: 78, right: 24, top: 34, bottom: useLines ? 48 : 66 };
  const yValues = items.map((item) => item.spectralEfficiency);
  const yLog = settings.yLog && yValues.every((value) => value > 0);
  const baseYDomain = chartDomainForValues(yValues, 0.12, settings.includeZero && !yLog, yLog);
  const lineLegendEntries = series.map((item) => ({ id: item.id, label: item.label, color: item.color }));
  const barEntries = useLines ? [] : series.flatMap((item) => item.points.map((point, index) => ({
    id: `${item.id}:bar:${index}`,
    label: item.points.length > 1 ? point.title : item.label,
    color: point.color || item.color,
    point,
  })));
  const plotWidth = width - margin.left - margin.right;
  const barSlotWidth = plotWidth / Math.max(1, barEntries.length);
  const barWidth = Math.max(22, Math.min(58, barSlotWidth * 0.46));
  const xValues = items.map((item) => item.powerBudget);
  const xLog = useLines && settings.xLog && xValues.every((value) => value > 0);
  const baseXDomain = useLines ? chartDomainForValues(xValues, 0.12, !xLog, xLog) : null;
  const domainSignature = `power-budget:spectral-efficiency:${xLog ? "log" : "linear"}:${yLog ? "log" : "linear"}`;
  const domains = useLines
    ? domainChartVisibleDomains(
      "resource-spectral-efficiency",
      baseXDomain,
      baseYDomain,
      { signature: domainSignature, xMetric: "average_power_budget", yMetric: "spectral_efficiency", xLog, yLog },
    )
    : { x: null, y: baseYDomain };
  const xDomain = domains.x;
  const yDomain = domains.y;
  const xScale = useLines ? chartScale(xDomain, margin.left, width - margin.right, xLog) : null;
  const xTicks = useLines ? chartTicksForDomain(xDomain, 4, xLog) : [];
  const yScale = chartScale(yDomain, height - margin.bottom, margin.top, yLog);
  const yTicks = chartTicksForDomain(yDomain, 4, yLog);
  return `
    <div class="rd-chart-wrap resource-spectral-efficiency-chart-wrap">
      <button class="icon-button rd-settings-button" type="button" data-resource-performance-settings="spectralEfficiency" aria-label="Shannon spectral efficiency figure settings">&#9881;</button>
      <svg class="rd-chart resource-spectral-efficiency-chart" data-visualization-id="resource-spectral-efficiency" data-resource-performance-mode="${mode}"
        ${useLines ? `data-domain-chart data-domain-view-key="resource-spectral-efficiency" data-domain-signature="${escapeAttr(domainSignature)}"
        data-width="${width}" data-height="${height}"
        data-left="${margin.left}" data-right="${margin.right}" data-top="${margin.top}" data-bottom="${margin.bottom}"
        data-x-min="${xDomain[0]}" data-x-max="${xDomain[1]}" data-y-min="${yDomain[0]}" data-y-max="${yDomain[1]}"
        data-x-metric="average_power_budget" data-y-metric="spectral_efficiency"` : ""}
        data-x-log="${xLog ? "true" : "false"}" data-y-log="${yLog ? "true" : "false"}" viewBox="0 0 ${width} ${height}" preserveAspectRatio="xMidYMid meet" role="img" aria-label="Shannon spectral efficiency ${useLines ? "versus average transmit-power budget" : "comparison"}">
        ${useLines ? `<defs>
          <clipPath id="resource-spectral-efficiency-sweep-clip">
            <rect x="${margin.left}" y="${margin.top}" width="${width - margin.left - margin.right}" height="${height - margin.top - margin.bottom}"></rect>
          </clipPath>
        </defs>` : ""}
        <text class="rd-plot-title" x="${width / 2}" y="14" text-anchor="middle">Shannon Spectral Efficiency${useLines ? " vs Power Budget" : ""}</text>
        <line class="rd-axis" x1="${margin.left}" y1="${height - margin.bottom}" x2="${width - margin.right}" y2="${height - margin.bottom}"></line>
        <line class="rd-axis" x1="${margin.left}" y1="${margin.top}" x2="${margin.left}" y2="${height - margin.bottom}"></line>
        ${xTicks.map((tick) => `
          <g class="rd-tick">
            <line x1="${xScale(tick)}" y1="${margin.top}" x2="${xScale(tick)}" y2="${height - margin.bottom}"></line>
            <text x="${xScale(tick)}" y="${height - 22}">${escapeHtml(formatPowerValue(tick))}</text>
          </g>
        `).join("")}
        ${yTicks.map((tick) => `
          <g class="rd-tick y">
            <line x1="${margin.left}" y1="${yScale(tick)}" x2="${width - margin.right}" y2="${yScale(tick)}"></line>
            <text x="${margin.left - 12}" y="${yScale(tick) + 3}">${escapeHtml(formatMetricNumber(tick, 4))}</text>
          </g>
        `).join("")}
        ${useLines ? series.map((item) => `
          <g class="visualization-series resource-performance-series resource-se-series" clip-path="url(#resource-spectral-efficiency-sweep-clip)" data-resource-performance-series-id="${escapeAttr(item.id)}" data-visualization-series-key="${escapeAttr(item.id)}" style="--recipe-color: ${escapeAttr(item.color)}">
            <polyline class="rd-series-line" points="${escapeAttr(item.points.map((point) => `${xScale(point.powerBudget).toFixed(1)},${yScale(point.spectralEfficiency).toFixed(1)}`).join(" "))}"></polyline>
            ${item.points.map((point) => {
              const tooltip = [
                item.label,
                `average power budget ${formatPowerValue(point.powerBudget)}`,
                `Shannon spectral efficiency ${formatMetricNumber(point.spectralEfficiency, 5)} bit/s/Hz`,
              ].filter(Boolean).join("\n");
              return `
                <g class="rd-point" data-result-key="${escapeAttr(point.key)}" tabindex="0" role="img" aria-label="${escapeAttr(tooltip)}" data-result-tooltip="${escapeAttr(tooltip)}" transform="translate(${xScale(point.powerBudget).toFixed(1)}, ${yScale(point.spectralEfficiency).toFixed(1)})" style="--recipe-color: ${escapeAttr(item.color)}">
                  <circle class="${settings.showMarkers ? "" : "resource-performance-marker-hidden"}" r="5"></circle>
                </g>
              `;
            }).join("")}
          </g>
        `).join("") : barEntries.map((entry, index) => {
          const x = margin.left + barSlotWidth * (index + 0.5);
          const y = yScale(entry.point.spectralEfficiency);
          const baseline = height - margin.bottom;
          const tooltip = [
            entry.label,
            `average power budget ${formatPowerValue(entry.point.powerBudget)}`,
            `Shannon spectral efficiency ${formatMetricNumber(entry.point.spectralEfficiency, 5)} bit/s/Hz`,
          ].join("\n");
          return `
            <g class="visualization-series resource-performance-series resource-se-series resource-se-bar-series" data-resource-performance-series-id="${escapeAttr(entry.id)}" data-visualization-series-key="${escapeAttr(entry.id)}" data-result-key="${escapeAttr(entry.point.key)}" style="--recipe-color: ${escapeAttr(entry.color)}" tabindex="0" role="img" aria-label="${escapeAttr(tooltip)}" data-result-tooltip="${escapeAttr(tooltip)}">
              <rect class="resource-se-bar" x="${(x - barWidth / 2).toFixed(1)}" y="${y.toFixed(1)}" width="${barWidth.toFixed(1)}" height="${Math.max(1, baseline - y).toFixed(1)}" rx="3"></rect>
              ${settings.showValues ? `<text class="resource-se-bar-value" x="${x.toFixed(1)}" y="${Math.max(margin.top + 9, y - 7).toFixed(1)}" text-anchor="middle">${escapeHtml(formatMetricNumber(entry.point.spectralEfficiency, 4))}</text>` : ""}
              <text class="resource-se-bar-label" x="${x.toFixed(1)}" y="${height - 31}" text-anchor="middle">${escapeHtml(trim(entry.label, 18))}</text>
              <text class="resource-se-bar-power" x="${x.toFixed(1)}" y="${height - 17}" text-anchor="middle">${escapeHtml(`P=${formatPowerValue(entry.point.powerBudget)}`)}</text>
            </g>
          `;
        }).join("")}
        ${useLines ? `<text class="rd-axis-label" x="${width / 2}" y="${height - 5}">Average transmit-power budget per subcarrier</text>` : ""}
        <text class="rd-axis-label y" x="14" y="${height / 2}" transform="rotate(-90 14 ${height / 2})">Spectral efficiency (bit/s/Hz)</text>
      </svg>
      ${resourcePerformanceLegendMarkup(useLines ? lineLegendEntries : barEntries, mode, "Shannon spectral efficiency methods")}
    </div>
  `;
}

function resourceAllocationComparisonScopeNote() {
  return `
    <div class="resource-comparison-scope-note">
      Complete-run payload and allocation metrics; methods share the configured channel, noise, and power budget.
    </div>
  `;
}

function resourceFiniteBlocklengthComparisonTable(rows) {
  const headers = [
    "Result variant",
    "Allocation method",
    "Average power budget",
    "Expected goodput (bit/s/Hz) ↑",
    "Predicted BLER ↓",
    "Mean capacity (bit/s/Hz) ↑",
    "P05 goodput (bit/s/Hz) ↑",
    "CSI age (OFDM symbols)",
    "Observed/current gain correlation ↑",
    "CSI NMSE ↓",
    "Maximum power error ↓",
  ];
  const labels = recipeDisplayLabels(rows.map((row) => row.recipe));
  const body = resultSummaryTableRows(rows, labels, (row, summary, index, summaries, title, details) => {
    const recipe = summary && summary.recipe ? summary.recipe : row.recipe.recipe || {};
    const allocator = (recipe.steps || []).find((step) => String(step.op || "").includes("power_allocator") || step.op === "model.resource_allocation_adapter") || {};
    const preview = resourceAllocationPreview(details) || {};
    const rawPolicy = preview.policy || (allocator.params && allocator.params.policy) || resourceAllocationPolicyLabel(allocator.op);
    return [
      summaryDisplayTitle(title, summary, index, summaries),
      resourceAllocationPolicyName({ preview: { policy: rawPolicy }, title: rawPolicy }),
      metricCell(details, "Average power budget", ["evaluation.resource.average_transmit_power_budget", "resource.average_transmit_power_budget"]),
      metricCell(details, "Finite-blocklength expected goodput", ["evaluation.resource.finite_blocklength.expected_goodput_bps_hz", "resource.finite_blocklength.expected_goodput_bps_hz"]),
      metricCell(details, "Finite-blocklength predicted BLER", ["evaluation.resource.finite_blocklength.predicted_bler", "resource.finite_blocklength.predicted_bler"]),
      metricCell(details, "Finite-blocklength mean capacity", ["evaluation.resource.finite_blocklength.mean_capacity_bps_hz", "resource.finite_blocklength.mean_capacity_bps_hz"]),
      metricCell(details, "Finite-blocklength P05 goodput", ["evaluation.resource.finite_blocklength.p05_goodput_bps_hz", "resource.finite_blocklength.p05_goodput_bps_hz"]),
      metricCell(details, "CSI age", ["evaluation.resource.csi.feedback_delay_ofdm_symbols", "resource.csi.feedback_delay_ofdm_symbols"]),
      metricCell(details, "Observed/current gain correlation", ["evaluation.resource.csi.observed_actual_gain_correlation", "resource.csi.observed_actual_gain_correlation"]),
      metricCell(details, "Observed/current CSI NMSE", ["evaluation.resource.csi.observed_actual_complex_nmse", "resource.csi.observed_actual_complex_nmse"]),
      metricCell(details, "Maximum power error", ["evaluation.resource.power_constraint.max_abs_error", "resource.power_constraint.max_abs_error"]),
    ];
  });
  return table(headers, body);
}

function resourceAllocationCountCell(details, keys) {
  const value = numberMetricValue(details, keys);
  return Number.isFinite(value) ? formatInteger(value) : "";
}

function resourceAllocationComparisonTable(rows) {
  const headers = [
    "Result variant",
    "Allocation method",
    "Average power budget",
    "Offered payload bits",
    "Delivered payload bits ↑",
    "Scheduled resource elements",
    "Goodput (bit/RE) ↑",
    "Mean Shannon SE (bit/s/Hz) ↑",
    "5th-percentile Shannon SE ↑",
    "Capacity outage ↓",
    "Payload delivery BLER diagnostic ↓",
    "Total TX energy",
    "Energy efficiency (bit/energy) ↑",
    "Power constraint error ↓",
  ];
  const labels = recipeDisplayLabels(rows.map((row) => row.recipe));
  const body = resultSummaryTableRows(rows, labels, (row, summary, index, summaries, title, details) => {
    const recipe = summary && summary.recipe ? summary.recipe : row.recipe.recipe || {};
    const allocator = (recipe.steps || []).find((step) => String(step.op || "").includes("power_allocator") || step.op === "model.resource_allocation_adapter") || {};
    const preview = resourceAllocationPreview(details) || {};
    const rawPolicy = preview.policy || (allocator.params && allocator.params.policy) || resourceAllocationPolicyLabel(allocator.op);
    const policy = resourceAllocationPolicyName({ preview: { policy: rawPolicy }, title: rawPolicy });
    return [
      summaryDisplayTitle(title, summary, index, summaries),
      policy,
      metricCell(details, "Average power budget", ["evaluation.resource.average_transmit_power_budget", "resource.average_transmit_power_budget"]),
      resourceAllocationCountCell(details, ["evaluation.channel.payload_bit_count", "channel.payload_bit_count"]),
      resourceAllocationCountCell(details, ["evaluation.channel.delivered_payload_bit_count", "channel.delivered_payload_bit_count"]),
      resourceAllocationCountCell(details, ["evaluation.channel.scheduled_resource_element_count", "channel.scheduled_resource_element_count"]),
      metricCell(details, "Achieved payload goodput", ["evaluation.channel.achieved_payload_goodput_bits_per_resource_element", "channel.achieved_payload_goodput_bits_per_resource_element"]),
      metricCell(details, "Theoretical Shannon SE", ["evaluation.resource.theoretical_shannon_spectral_efficiency_bps_hz", "resource.theoretical_shannon_spectral_efficiency_bps_hz"]),
      metricCell(details, "5th-percentile Shannon SE", ["evaluation.resource.theoretical_p05_state_spectral_efficiency_bps_hz", "resource.theoretical_p05_state_spectral_efficiency_bps_hz"]),
      metricCell(details, "Capacity outage", ["evaluation.resource.theoretical_outage_probability", "resource.theoretical_outage_probability"]),
      metricCell(details, "Payload delivery BLER", ["evaluation.channel.payload_delivery_block_error_rate", "channel.payload_delivery_block_error_rate"]),
      metricCell(details, "Total TX energy", ["evaluation.channel.tx_energy_for_payload", "channel.tx_energy_for_payload"]),
      metricCell(details, "RF-only energy efficiency", ["evaluation.channel.payload_energy_efficiency_bits_per_normalized_energy", "channel.payload_energy_efficiency_bits_per_normalized_energy"]),
      metricCell(details, "Power error", ["evaluation.resource.power_constraint.max_abs_error", "resource.power_constraint.max_abs_error"]),
    ];
  });
  return table(headers, body);
}

function resourceAllocationDiagnosticsTable(rows) {
  const headers = [
    "Result variant",
    "Allocation method",
    "Average power budget",
    "Policy / WF SE ↑",
    "WF oracle SE ↑",
    "Gap to WF ↓",
    "Relative gap ↓",
    "WF allocation RMSE ↓",
    "WF KKT residual ↓",
    "Max power error ↓",
    "Relative power error ↓",
    "Negative-power violation ↓",
  ];
  const labels = recipeDisplayLabels(rows.map((row) => row.recipe));
  const body = resultSummaryTableRows(rows, labels, (row, summary, index, summaries, title, details) => {
    const recipe = summary && summary.recipe ? summary.recipe : row.recipe.recipe || {};
    const allocator = (recipe.steps || []).find((step) => String(step.op || "").includes("power_allocator") || step.op === "model.resource_allocation_adapter") || {};
    const preview = resourceAllocationPreview(details) || {};
    const rawPolicy = preview.policy || (allocator.params && allocator.params.policy) || resourceAllocationPolicyLabel(allocator.op);
    const policy = resourceAllocationPolicyName({ preview: { policy: rawPolicy }, title: rawPolicy });
    const spectralEfficiency = numberMetricValue(details, [
      "evaluation.resource.theoretical_shannon_spectral_efficiency_bps_hz",
      "resource.theoretical_shannon_spectral_efficiency_bps_hz",
    ]);
    const oracleSpectralEfficiency = numberMetricValue(details, [
      "evaluation.resource.water_filling_oracle_spectral_efficiency_bps_hz",
      "resource.water_filling_oracle_spectral_efficiency_bps_hz",
    ]);
    const oracleRelativeGap = numberMetricValue(details, [
      "evaluation.resource.water_filling_relative_optimality_gap",
      "resource.water_filling_relative_optimality_gap",
    ]);
    const ratio = Number.isFinite(spectralEfficiency) && Number.isFinite(oracleSpectralEfficiency) && oracleSpectralEfficiency > 0
      ? spectralEfficiency / oracleSpectralEfficiency
      : Number.isFinite(oracleRelativeGap)
        ? 1 - oracleRelativeGap
        : NaN;
    return [
      summaryDisplayTitle(title, summary, index, summaries),
      policy,
      metricCell(details, "Average power budget", ["evaluation.resource.average_transmit_power_budget", "resource.average_transmit_power_budget"]),
      numericMetricCell("Policy / water-filling SE", ratio),
      metricCell(details, "Water-filling oracle SE", ["evaluation.resource.water_filling_oracle_spectral_efficiency_bps_hz", "resource.water_filling_oracle_spectral_efficiency_bps_hz"]),
      metricCell(details, "Gap to water filling", ["evaluation.resource.water_filling_optimality_gap_bps_hz", "resource.water_filling_optimality_gap_bps_hz"]),
      metricCell(details, "Relative gap to water filling", ["evaluation.resource.water_filling_relative_optimality_gap", "resource.water_filling_relative_optimality_gap"]),
      metricCell(details, "Water-filling allocation normalized RMSE", ["evaluation.resource.water_filling_power_normalized_rmse", "resource.water_filling_power_normalized_rmse"]),
      metricCell(details, "Water-filling KKT residual", ["evaluation.resource.water_filling_kkt_normalized_residual", "resource.water_filling_kkt_normalized_residual"]),
      metricCell(details, "Max power error", ["evaluation.resource.power_constraint.max_abs_error", "resource.power_constraint.max_abs_error"]),
      metricCell(details, "Relative power error", ["evaluation.resource.power_constraint.max_relative_error", "resource.power_constraint.max_relative_error"]),
      metricCell(details, "Negative-power violation", ["evaluation.resource.power_constraint.max_negative_violation", "resource.power_constraint.max_negative_violation"]),
    ];
  });
  return table(headers, body);
}

function resourceAllocationPolicyLabel(op) {
  if (op === "model.water_filling_power_allocator") return "water filling (Shannon oracle)";
  if (op === "model.equal_power_allocator") return "equal power";
  if (op === "model.resource_allocation_adapter") return "resource adapter";
  return String(op || "power allocator").replace(/^model\./, "").replace(/_/g, " ");
}

function resultSystemsPanel(rows, figureRows) {
  const timingFigureRows = (figureRows || []).filter((row) => resultSummaries(row).some((summary) => (
    collectRunDetails(summary).metrics.some((item) => String(item.metric || "").includes("codec_timing"))
  )));
  const rawTimingFigureRows = timingFigureRows.filter((row) => resultSummaries(row).some((summary) => (
    (summary.steps || []).some((step) => codecTimingMeasurements(step).length > 0)
  )));
  return `
    ${timingFigureRows.length ? `
      <section class="results-overview results-chart-row results-chart-row-system">
        ${modelTimeScatterPlot(timingFigureRows)}
        ${rawTimingFigureRows.length ? timeBoxPlot(rawTimingFigureRows) : ""}
      </section>
    ` : ""}
    ${timingCompositionCards(rows)}
    <section class="results-overview table-section">
      <div class="table-wrap">${systemMetricsTable(rows)}</div>
    </section>
  `;
}

