function csiFeedbackAxisSettingMarkup(field, value, items) {
  const allHaveBits = Boolean((items || []).length) && items.every((item) => Number.isFinite(item.feedbackBits));
  const effective = value === "actual_bits" && !allHaveBits ? "latent_dimension" : value || "auto";
  return `
    <label>
      <span>Feedback budget axis</span>
      <select data-csi-feedback-setting="${escapeAttr(field)}">
        <option value="auto"${effective === "auto" ? " selected" : ""}>Auto · real bits when available</option>
        <option value="actual_bits"${effective === "actual_bits" ? " selected" : ""}${allHaveBits ? "" : " disabled"}>Actual feedback bits / CSI sample</option>
        <option value="latent_dimension"${effective === "latent_dimension" ? " selected" : ""}>Feedback latent dimension</option>
      </select>
    </label>
  `;
}

function openCsiFeedbackSettingsDialog(target) {
  const settings = state.csiFeedbackSettings || {};
  const rows = (state.resultRows || []).filter(rowIsCsiFeedback);
  const items = csiFeedbackEntries(rows);
  let taskSettingsGroup = "";
  state.settingsSection = `csi-feedback-${target}`;
  els.settingsSubtitle.textContent = RESULTS_VISUALIZATION_STANDARD.settingsSubtitle;
  if (target === "rate") {
    els.settingsTitle.textContent = "Downlink Spectral Efficiency Settings";
    taskSettingsGroup = settingsGroup(
      "Metric",
      `
        <div class="axis-log-group"><span>Axis scale</span><div>${axisScaleCompactControl("data-csi-feedback-setting", "rateYLog", settings.rateYLog, "Y log")}</div></div>
        <div class="field-hint figure-settings-hint">The primary task metric is achieved downlink spectral efficiency. Multiple downlink SNRs produce one method curve versus SNR; one SNR produces clear method bars. Perfect-CSI retention and reconstruction diagnostics remain in the comparison table.</div>
        <div class="field-hint figure-settings-hint">Downlink SNR is already expressed in dB, so an additional logarithm is not meaningful on X.</div>
      `
    );
  } else if (target === "quality") {
    els.settingsTitle.textContent = "CSI Reconstruction NMSE Settings";
    const qualityAxis = csiFeedbackXAxis(items, settings.qualityXAxis || "auto");
    const qualityBudgets = items.map((item) => Number(item[qualityAxis.key])).filter(Number.isFinite);
    const hasQualityBudgetSweep = new Set(qualityBudgets.map((value) => value.toPrecision(12))).size > 1;
    taskSettingsGroup = settingsGroup(
      "Feedback Budget Axis",
      `
        ${csiFeedbackAxisSettingMarkup("qualityXAxis", settings.qualityXAxis, items)}
        ${hasQualityBudgetSweep ? `<div class="axis-log-group"><span>Axis scale</span><div>${axisScaleCompactControl("data-csi-feedback-setting", "qualityXLog", settings.qualityXLog, "X log")}</div></div>` : ""}
        <div class="field-hint figure-settings-hint">NMSE is shown on one Y axis. Phase-invariant cosine remains available in tooltips and the complete-run comparison table.</div>
        <div class="field-hint figure-settings-hint">NMSE is already expressed in dB, so an additional logarithm is not meaningful on Y.</div>
      `
    );
  } else {
    els.settingsTitle.textContent = "CSI Preview Settings";
    const previewEntries = items.filter((item) => csiFeedbackPreviewSamples(item.preview).length);
    const entry = previewEntries.find((item) => item.id === settings.entryId) || previewEntries[0] || null;
    const samples = entry ? csiFeedbackPreviewSamples(entry.preview) : [];
    const sample = samples.find((item) => item.sample_index === Number(settings.sampleIndex)) || samples[0] || null;
    taskSettingsGroup = settingsGroup(
      "Sample and Scale",
      `
        <label>
          <span>Result variant</span>
          <select data-csi-feedback-setting="entryId">
            ${previewEntries.map((item) => `<option value="${escapeAttr(item.id)}"${entry && item.id === entry.id ? " selected" : ""}>${escapeHtml(item.title)}</option>`).join("")}
          </select>
        </label>
        <label>
          <span>CSI sample</span>
          <select data-csi-feedback-setting="sampleIndex">
            ${samples.map((item) => `<option value="${escapeAttr(item.sample_index)}"${sample && item.sample_index === sample.sample_index ? " selected" : ""}>${escapeHtml(`sample ${item.sample_index + 1}`)}</option>`).join("")}
          </select>
        </label>
        <label>
          <span>Shared color scale</span>
          <select data-csi-feedback-setting="previewScale">
            <option value="linear"${settings.previewScale !== "log" ? " selected" : ""}>Linear</option>
            <option value="log"${settings.previewScale === "log" ? " selected" : ""}>Log-compressed</option>
          </select>
        </label>
        ${figureSettingsToggleGrid("data-csi-feedback-setting", [
          { field: "independentErrorScale", value: settings.independentErrorScale === true, label: "Independent error color range" },
        ])}
        <div class="field-hint">By default, true CSI, reconstructed CSI, and absolute error use the same numeric range. Enable the independent error range only when inspecting small residual structure.</div>
      `
    );
  }
  const visualizationId = target === "quality" ? "csi-feedback-quality" : target === "preview" ? "csi-feedback-preview" : "csi-feedback-rate";
  els.settingsBody.innerHTML = visualizationSettingsBody(
    taskSettingsGroup,
    visualizationDisplaySettingsGroup(visualizationId)
  );
  els.settingsBody.querySelectorAll("[data-csi-feedback-setting]").forEach((input) => {
    input.addEventListener("change", () => {
      const field = input.getAttribute("data-csi-feedback-setting");
      const next = { ...(state.csiFeedbackSettings || {}) };
      next[field] = input.type === "checkbox" ? Boolean(input.checked) : input.value;
      if (field === "sampleIndex") next.sampleIndex = integerOr(input.value, 0);
      if (field === "entryId") next.sampleIndex = 0;
      state.csiFeedbackSettings = next;
      renderResultsDashboard(state.resultRows || []);
      if (field === "entryId") openCsiFeedbackSettingsDialog("preview");
    });
  });
  bindVisualizationDisplaySettingsFields();
  els.settingsOverlay.hidden = false;
}

