function scatterSettingsRows(prefix, definitions, settings) {
  const attr = prefix === "rd" ? "data-rd-setting" : "data-model-time-setting";
  const rows = [
    ["x", "X metric", "X stat", false],
    ["y", "Y metric", "Y stat", false],
    ["size", "Size metric", "Size stat", true],
  ].map(([field, metricLabel, statLabel, includeFixed]) => {
    const statField = `${field}Stat`;
    const logControl = field === "x"
      ? axisScaleCompactControl(attr, "xLog", settings.xLog, "X log")
      : field === "y"
        ? axisScaleCompactControl(attr, "yLog", settings.yLog, "Y log")
        : "";
    return `
      <div class="settings-triplet-row${logControl ? "" : " no-inline-control"}">
        ${searchableMetricControl(attr, field, metricLabel, definitions, settings[field], includeFixed)}
        <label>
          <span>${escapeHtml(statLabel)}</span>
          <select ${attr}="${escapeAttr(statField)}">${scatterStatSelectOptions(definitions, settings[field], settings[statField])}</select>
        </label>
        ${logControl || '<span aria-hidden="true"></span>'}
      </div>
    `;
  }).join("");
  return `${rows}${figureColorSettingRow(attr, "colorBy", settings.colorBy)}`;
}

function axisScaleCompactControl(attrName, field, value, label) {
  return `
    <label class="axis-log-compact" title="${escapeAttr(label)}">
      <input type="checkbox" ${attrName}="${escapeAttr(field)}"${coerceBoolean(value) ? " checked" : ""} />
      <span>${escapeHtml(label)}</span>
    </label>
  `;
}

function figureSettingsToggleGrid(attrName, controls) {
  return `
    <div class="figure-settings-toggle-grid" role="group" aria-label="Figure display options">
      ${(controls || []).map((control) => `
        <label class="figure-settings-toggle">
          <input type="checkbox" ${attrName}="${escapeAttr(control.field)}"${coerceBoolean(control.value) ? " checked" : ""} />
          <span>${escapeHtml(control.label)}</span>
        </label>
      `).join("")}
    </div>
  `;
}

function visualizationDisplaySettingsGroup(visualizationIds, options = {}) {
  const ids = (Array.isArray(visualizationIds) ? visualizationIds : [visualizationIds]).filter(Boolean);
  const settings = visualizationDisplaySettings(ids[0] || "visualization");
  const controls = [];
  if (options.showGrid !== false) controls.push({ field: "showGrid", value: settings.showGrid, label: "Grid lines" });
  if (options.showValues !== false) controls.push({ field: "showValues", value: settings.showValues, label: "Value annotations" });
  if (options.includeBackground !== false) {
    controls.push({ field: "includeBackground", value: settings.includeBackground, label: "Theme background in SVG" });
  }
  return settingsGroup(
    "Display and Export",
    `${figureSettingsToggleGrid("data-visualization-display-setting", controls)}
      <input type="hidden" data-visualization-display-targets value="${escapeAttr(ids.join(" "))}" />`
  );
}

function bindVisualizationDisplaySettingsFields(root = els.settingsBody) {
  if (!root) return;
  const targetField = Array.from(root.querySelectorAll("[data-visualization-display-targets]") || [])[0];
  const targets = String((targetField || {}).value || "")
    .split(/\s+/)
    .filter(Boolean);
  root.querySelectorAll("[data-visualization-display-setting]").forEach((input) => {
    input.addEventListener("change", () => {
      const field = input.getAttribute("data-visualization-display-setting");
      targets.forEach((id) => {
        const next = { ...visualizationDisplaySettings(id), [field]: Boolean(input.checked) };
        state.visualizationDisplaySettings = { ...(state.visualizationDisplaySettings || {}), [id]: next };
        if (!els.resultsComparison) return;
        els.resultsComparison.querySelectorAll(`[data-visualization-key="${cssEscape(id)}"]`).forEach((wrap) => {
          applyVisualizationDisplaySettings(wrap, next);
        });
      });
    });
  });
}

function axisScaleCompactGroup(attrName, settings, axes = { x: true, y: true }) {
  const controls = [];
  if (axes.x) controls.push(axisScaleCompactControl(attrName, "xLog", settings.xLog, "X log"));
  if (axes.y) controls.push(axisScaleCompactControl(attrName, "yLog", settings.yLog, "Y log"));
  if (!controls.length) return "";
  return `
    <div class="axis-log-group">
      <span>Axis scale</span>
      <div>${controls.join("")}</div>
    </div>
  `;
}

function figureColorSettingRow(attrName, field, current, leadingControl = "") {
  const options = resultColorOptions(visibleResultRows(state.resultRows || []));
  const safeCurrent = options.some((item) => item.id === current) ? current : "recipe";
  return `
    <div class="settings-pair-row${leadingControl ? "" : " settings-single-row"}">
      ${leadingControl}
      <label>
        <span>Color by</span>
        <select ${attrName}="${escapeAttr(field)}">
          ${options.map((item) => `<option value="${escapeAttr(item.id)}"${item.id === safeCurrent ? " selected" : ""}>${escapeHtml(item.label)}</option>`).join("")}
        </select>
      </label>
    </div>
  `;
}

function searchableMetricControl(attrName, field, label, definitions, current, includeFixed = false, inlineControl = "") {
  const options = includeFixed ? [{ id: "none", label: "Fixed size" }].concat(definitions) : definitions;
  const currentLabel = metricCurrentLabel(options, current);
  return `
    <div class="metric-menu-label field-control">
      <span>${escapeHtml(label)}</span>
      <div class="metric-control-row${inlineControl ? " with-inline-control" : ""}">
        <div class="metric-combobox" data-metric-menu>
          <input type="hidden" ${attrName}="${escapeAttr(field)}" value="${escapeAttr(current)}" data-metric-menu-value />
          <button type="button" class="metric-menu-button" data-metric-menu-button aria-haspopup="listbox" aria-expanded="false">
            <span data-metric-menu-label>${escapeHtml(currentLabel)}</span>
            <span class="metric-menu-caret" aria-hidden="true"></span>
          </button>
          <div class="metric-menu-panel" data-metric-menu-panel hidden>
            <input type="search" class="metric-menu-search" placeholder="Search metrics" data-metric-menu-search />
            <div class="metric-menu-options" role="listbox">
              ${metricMenuOptions(options, current)}
            </div>
          </div>
        </div>
        ${inlineControl}
      </div>
    </div>
  `;
}

function metricCurrentLabel(options, current) {
  const match = (options || []).find((item) => item.id === current);
  return match ? match.label || metricOptionSegmentLabel(match.id) : "Select metric";
}

function metricMenuOptions(options, current) {
  const root = { children: new Map(), item: null, segment: "" };
  (options || []).forEach((item) => {
    const path = metricOptionPath(item);
    let node = root;
    path.forEach((segment) => {
      if (!node.children.has(segment)) node.children.set(segment, { children: new Map(), item: null, segment });
      node = node.children.get(segment);
    });
    node.item = item;
  });
  const html = [];
  sortedMetricOptionChildren(root).forEach((node) => renderMetricMenuNode(node, 0, current, html));
  return html.join("");
}

function renderMetricMenuNode(node, depth, current, html) {
  if (node.item && !node.children.size) {
    html.push(metricMenuLeaf(node.item, depth, current, node.segment));
    return;
  }
  html.push(`<div class="metric-menu-heading" style="--metric-depth: ${depth}">${escapeHtml(metricOptionSegmentLabel(node.segment))}</div>`);
  if (node.item) html.push(metricMenuLeaf(node.item, depth + 1, current, node.segment));
  sortedMetricOptionChildren(node).forEach((child) => renderMetricMenuNode(child, depth + 1, current, html));
}

function metricMenuLeaf(item, depth, current, segment) {
  const label = metricOptionLeafLabel(item, segment);
  const selected = item.id === current;
  return `
    <button
      type="button"
      class="metric-menu-option${selected ? " selected" : ""}"
      role="option"
      aria-selected="${selected ? "true" : "false"}"
      data-metric-menu-option
      data-metric-value="${escapeAttr(item.id)}"
      data-metric-label="${escapeAttr(label)}"
      style="--metric-depth: ${depth}"
    >${escapeHtml(label)}</button>
  `;
}

function resultColorOptions(rows) {
  const fields = new Map();
  (rows || []).forEach((row) => {
    resultSummaries(row).forEach((summary) => {
      const metadata = summary && summary.recipe && summary.recipe.metadata ? summary.recipe.metadata : {};
      const values = resultMatrixSelection(metadata);
      if (!Object.keys(values).length) return;
      Object.entries(values).forEach(([path, value]) => {
        const set = fields.get(path) || new Set();
        set.add(String(value));
        fields.set(path, set);
      });
    });
  });
  const sweepOptions = Array.from(fields.entries())
    .filter(([_path, values]) => values.size > 1)
    .sort(([left], [right]) => sweepPathLabel(left).localeCompare(sweepPathLabel(right), undefined, { sensitivity: "base" }))
    .map(([path]) => ({ id: `sweep:${path}`, label: sweepPathLabel(path) }));
  return [{ id: "recipe", label: "Recipe color" }, ...sweepOptions];
}

function resultPointColor(row, summary, colorBySetting = "recipe") {
  const colorBy = String(colorBySetting || "recipe");
  if (!colorBy.startsWith("sweep:")) return recipeColor(row && row.recipe);
  const path = colorBy.slice("sweep:".length);
  const value = summarySweepValue(summary, path);
  if (value === null) return recipeColor(row && row.recipe);
  const categories = resultColorCategories(path);
  const index = categories.indexOf(String(value));
  return recipeColorForIndex(index >= 0 ? index : 0);
}

function summarySweepValue(summary, path) {
  const metadata = summary && summary.recipe && summary.recipe.metadata ? summary.recipe.metadata : {};
  const values = resultMatrixSelection(metadata);
  if (!Object.prototype.hasOwnProperty.call(values, path)) return null;
  return values[path];
}

function resultColorCategories(path) {
  const values = new Set();
  visibleResultRows(state.resultRows || []).forEach((row) => {
    resultSummaries(row).forEach((summary) => {
      const value = summarySweepValue(summary, path);
      if (value !== null) values.add(String(value));
    });
  });
  return Array.from(values).sort(compareMaybeNumericText);
}

function compareMaybeNumericText(left, right) {
  const leftNumber = Number(left);
  const rightNumber = Number(right);
  if (Number.isFinite(leftNumber) && Number.isFinite(rightNumber)) return leftNumber - rightNumber;
  return String(left).localeCompare(String(right), undefined, { numeric: true, sensitivity: "base" });
}

