function settingInputValue(input) {
  if (!input) return "";
  return input.type === "checkbox" ? Boolean(input.checked) : input.value;
}

function coerceBoolean(value) {
  return value === true || value === "true" || value === 1 || value === "1" || value === "on";
}

function bindSearchableMetricMenus() {
  els.settingsBody.querySelectorAll("[data-metric-menu]").forEach((menu) => {
    const button = menu.querySelector("[data-metric-menu-button]");
    const panel = menu.querySelector("[data-metric-menu-panel]");
    const search = menu.querySelector("[data-metric-menu-search]");
    const hidden = menu.querySelector("[data-metric-menu-value]");
    const label = menu.querySelector("[data-metric-menu-label]");
    if (!button || !panel || !hidden || !label) return;
    panel.addEventListener("click", (event) => event.stopPropagation());
    button.addEventListener("click", (event) => {
      event.preventDefault();
      event.stopPropagation();
      const opening = panel.hidden;
      closeSearchableMetricMenus();
      panel.hidden = !opening;
      button.setAttribute("aria-expanded", opening ? "true" : "false");
      if (opening) {
        positionMetricMenuPanel(menu);
        if (search) {
          search.value = "";
          filterMetricMenuOptions(menu, "");
          positionMetricMenuPanel(menu);
          window.setTimeout(() => search.focus(), 0);
        }
      }
    });
    if (search) {
      search.addEventListener("click", (event) => event.stopPropagation());
      search.addEventListener("input", () => filterMetricMenuOptions(menu, search.value));
      search.addEventListener("keydown", (event) => {
        if (event.key === "Escape") {
          closeSearchableMetricMenus();
          button.focus();
        }
      });
    }
    menu.querySelectorAll("[data-metric-menu-option]").forEach((option) => {
      option.addEventListener("click", (event) => {
        event.preventDefault();
        event.stopPropagation();
        const value = option.getAttribute("data-metric-value") || "";
        const optionLabel = option.getAttribute("data-metric-label") || value;
        hidden.value = value;
        label.textContent = optionLabel;
        menu.querySelectorAll("[data-metric-menu-option]").forEach((item) => {
          const selected = item === option;
          item.classList.toggle("selected", selected);
          item.setAttribute("aria-selected", selected ? "true" : "false");
        });
        closeSearchableMetricMenus();
        hidden.dispatchEvent(new Event("change", { bubbles: true }));
      });
    });
  });
  if (els.settingsBody && els.settingsBody.dataset.metricMenuCloserBound !== "true") {
    els.settingsBody.dataset.metricMenuCloserBound = "true";
    els.settingsBody.addEventListener("click", closeSearchableMetricMenus);
  }
  if (els.settingsBody && els.settingsBody.dataset.metricMenuViewportBound !== "true") {
    els.settingsBody.dataset.metricMenuViewportBound = "true";
    window.addEventListener("resize", repositionOpenMetricMenus, { passive: true });
    window.addEventListener("scroll", repositionOpenMetricMenus, true);
  }
}

function closeSearchableMetricMenus() {
  els.settingsBody.querySelectorAll("[data-metric-menu]").forEach((menu) => {
    const panel = menu.querySelector("[data-metric-menu-panel]");
    const button = menu.querySelector("[data-metric-menu-button]");
    if (panel) {
      panel.hidden = true;
      panel.style.left = "";
      panel.style.top = "";
      panel.style.width = "";
      panel.style.maxHeight = "";
    }
    if (button) button.setAttribute("aria-expanded", "false");
  });
}

function repositionOpenMetricMenus() {
  if (!els.settingsBody) return;
  els.settingsBody.querySelectorAll("[data-metric-menu]").forEach((menu) => {
    const panel = menu.querySelector("[data-metric-menu-panel]");
    if (panel && !panel.hidden) positionMetricMenuPanel(menu);
  });
}

function positionMetricMenuPanel(menu) {
  const button = menu && menu.querySelector("[data-metric-menu-button]");
  const panel = menu && menu.querySelector("[data-metric-menu-panel]");
  if (!button || !panel || panel.hidden) return;
  const rect = button.getBoundingClientRect();
  const viewportWidth = window.innerWidth || document.documentElement.clientWidth || 0;
  const viewportHeight = window.innerHeight || document.documentElement.clientHeight || 0;
  const margin = 12;
  const gap = 6;
  const maxViewportWidth = Math.max(180, viewportWidth - margin * 2);
  const panelWidth = Math.min(Math.max(rect.width, 360), maxViewportWidth);
  const left = Math.min(Math.max(rect.left, margin), Math.max(margin, viewportWidth - margin - panelWidth));
  const spaceBelow = viewportHeight - rect.bottom - margin - gap;
  const spaceAbove = rect.top - margin - gap;
  const openBelow = spaceBelow >= 180 || spaceBelow >= spaceAbove;
  const available = Math.max(120, openBelow ? spaceBelow : spaceAbove);
  const panelHeight = Math.min(520, available);
  const top = openBelow ? rect.bottom + gap : Math.max(margin, rect.top - gap - panelHeight);
  panel.style.left = `${left}px`;
  panel.style.top = `${top}px`;
  panel.style.width = `${panelWidth}px`;
  panel.style.maxHeight = `${panelHeight}px`;
}

function filterMetricMenuOptions(menu, query) {
  const text = String(query || "").trim().toLowerCase();
  const options = Array.from(menu.querySelectorAll("[data-metric-menu-option]"));
  options.forEach((option) => {
    const haystack = `${option.textContent || ""} ${option.getAttribute("data-metric-value") || ""}`.toLowerCase();
    option.hidden = Boolean(text) && !haystack.includes(text);
  });
  menu.querySelectorAll(".metric-menu-heading").forEach((heading) => {
    let cursor = heading.nextElementSibling;
    let hasVisibleOption = false;
    while (cursor && !cursor.classList.contains("metric-menu-heading")) {
      if (cursor.matches("[data-metric-menu-option]") && !cursor.hidden) {
        hasVisibleOption = true;
        break;
      }
      cursor = cursor.nextElementSibling;
    }
    heading.hidden = Boolean(text) && !hasVisibleOption;
  });
}

function scatterMetricSelectOptions(definitions, current, includeFixed = false) {
  const options = includeFixed ? [{ id: "none", label: "Fixed size" }].concat(definitions) : definitions;
  return hierarchicalMetricSelectOptions(options, current);
}

function hierarchicalMetricSelectOptions(options, current) {
  const root = { children: new Map(), item: null, segment: "" };
  options.forEach((item) => {
    const path = metricOptionPath(item);
    let node = root;
    path.forEach((segment) => {
      if (!node.children.has(segment)) node.children.set(segment, { children: new Map(), item: null, segment });
      node = node.children.get(segment);
    });
    node.item = item;
  });
  const html = [];
  sortedMetricOptionChildren(root).forEach((node) => renderMetricOptionNode(node, 0, current, html));
  return html.join("");
}

function renderMetricOptionNode(node, depth, current, html) {
  if (node.item && !node.children.size) {
    html.push(metricLeafOption(node.item, depth, current, node.segment));
    return;
  }
  html.push(`<option disabled>${metricOptionIndent(depth)}${escapeHtml(metricOptionSegmentLabel(node.segment))}</option>`);
  if (node.item) html.push(metricLeafOption(node.item, depth + 1, current, node.segment));
  sortedMetricOptionChildren(node).forEach((child) => renderMetricOptionNode(child, depth + 1, current, html));
}

function sortedMetricOptionChildren(node) {
  return Array.from((node && node.children ? node.children : new Map()).values()).sort(compareMetricOptionNodes);
}

function compareMetricOptionNodes(left, right) {
  return metricOptionSortLabel(left).localeCompare(metricOptionSortLabel(right), undefined, {
    numeric: true,
    sensitivity: "base",
  });
}

function metricOptionSortLabel(node) {
  if (!node) return "";
  if (node.item) return metricOptionLeafLabel(node.item, node.segment);
  return metricOptionSegmentLabel(node.segment);
}

function metricLeafOption(item, depth, current, segment) {
  return `<option value="${escapeAttr(item.id)}"${item.id === current ? " selected" : ""}>${metricOptionIndent(depth)}${escapeHtml(metricOptionLeafLabel(item, segment))}</option>`;
}

function metricOptionPath(item) {
  if (item.id === "none") return ["display", "fixed_size"];
  if (["rate_bpp", "tx_bits", "source_pixels"].includes(item.id)) return ["derived", item.id];
  return String(item.id || item.label || "metric").split(".").filter(Boolean);
}

function metricOptionLeafLabel(item, segment) {
  return item.label || metricOptionSegmentLabel(segment);
}

function metricOptionSegmentLabel(segment) {
  return String(segment || "metric").replace(/_/g, " ");
}

function metricOptionIndent(depth) {
  return Array.from({ length: Math.max(0, depth) }, () => "&nbsp;&nbsp;&nbsp;").join("");
}

function scatterStatSelectOptions(definitions, metricId, current) {
  const options = metricKindUsesTimingStats(scatterMetricKind(definitions, metricId))
    ? TIME_STAT_OPTIONS
    : [SCATTER_VALUE_STAT_OPTION];
  return options
    .map((item) => `<option value="${escapeAttr(item.id)}"${item.id === current ? " selected" : ""}>${escapeHtml(item.label)}</option>`)
    .join("");
}

function canonicalResultMatrixSelection(metadata) {
  if (!metadata || typeof metadata !== "object") return {};
  if (metadata.matrix_selection && typeof metadata.matrix_selection === "object" && !Array.isArray(metadata.matrix_selection)) {
    return metadata.matrix_selection;
  }
  return {};
}

function legacyResultMatrixSelection(metadata) {
  // Read-only compatibility for manifests written before canonical matrix_selection.
  if (!metadata || typeof metadata !== "object") return {};
  if (metadata.sweep_values && typeof metadata.sweep_values === "object" && !Array.isArray(metadata.sweep_values)) {
    return metadata.sweep_values;
  }
  return {};
}

function resultMatrixSelection(metadata) {
  if (metadata && Object.prototype.hasOwnProperty.call(metadata, "matrix_selection")) {
    return canonicalResultMatrixSelection(metadata);
  }
  return legacyResultMatrixSelection(metadata);
}

function canonicalMatrixVariantLabel(recipe) {
  const metadata = recipe && recipe.metadata && typeof recipe.metadata === "object" ? recipe.metadata : {};
  const entries = Object.entries(canonicalResultMatrixSelection(metadata));
  if (entries.length) {
    return entries.map(([path, value]) => `${sweepPathLabel(path)} ${sweepValueLabel(path, value, recipe)}`).join(", ");
  }
  const matrixIndex = Number(metadata.matrix_index);
  if (Number.isInteger(matrixIndex) && matrixIndex >= 0) return `variant ${matrixIndex + 1}`;
  const matrixVariantId = String(metadata.matrix_variant_id || "").trim();
  if (matrixVariantId) return `variant ${matrixVariantId}`;
  return "";
}

function canonicalMatrixVariantIdentityLabel(recipe, index = 0) {
  return canonicalMatrixVariantLabel(recipe) || `variant ${index + 1}`;
}

function legacyResultVariantLabel(summary) {
  // Read-only compatibility for result manifests written before canonical variant metadata.
  const metadata = summary && summary.recipe && summary.recipe.metadata ? summary.recipe.metadata : {};
  if (summary && summary.sweep_label) return summary.sweep_label;
  if (metadata.matrix_label) return metadata.matrix_label;
  if (metadata.sweep_label) return metadata.sweep_label;
  const entries = Object.entries(legacyResultMatrixSelection(metadata));
  if (entries.length) {
    return entries.map(([path, value]) => `${sweepPathLabel(path)} ${sweepValueLabel(path, value, summary.recipe)}`).join(", ");
  }
  return "";
}

function resultSummaries(row) {
  const summaries = row && Array.isArray(row.summaries) && row.summaries.length
    ? row.summaries
    : row && row.summary
      ? [row.summary]
      : [];
  return summaries.slice().sort((left, right) => {
    const leftMetadata = left.recipe && left.recipe.metadata ? left.recipe.metadata : {};
    const rightMetadata = right.recipe && right.recipe.metadata ? right.recipe.metadata : {};
    const leftIndex = Number(leftMetadata.matrix_index);
    const rightIndex = Number(rightMetadata.matrix_index);
    if (Number.isFinite(leftIndex) && Number.isFinite(rightIndex)) return leftIndex - rightIndex;
    if (Number.isFinite(leftIndex)) return -1;
    if (Number.isFinite(rightIndex)) return 1;
    // Read-only compatibility for result manifests written before canonical matrix_index.
    const leftLegacyIndex = Number(leftMetadata.sweep_index ?? left.sweep_index);
    const rightLegacyIndex = Number(rightMetadata.sweep_index ?? right.sweep_index);
    if (Number.isFinite(leftLegacyIndex) && Number.isFinite(rightLegacyIndex)) return leftLegacyIndex - rightLegacyIndex;
    if (Number.isFinite(leftLegacyIndex)) return -1;
    if (Number.isFinite(rightLegacyIndex)) return 1;
    return String(left.run_id || "").localeCompare(String(right.run_id || ""));
  });
}

function resultVariantLabel(summary, index = 0) {
  const canonical = canonicalMatrixVariantLabel(summary && summary.recipe);
  return canonical || legacyResultVariantLabel(summary) || `variant ${index + 1}`;
}

function resultVariantValueLabel(summary, index = 0) {
  const metadata = summary && summary.recipe && summary.recipe.metadata ? summary.recipe.metadata : {};
  const values = Object.entries(resultMatrixSelection(metadata));
  if (values.length === 1) return sweepValueLabel(values[0][0], values[0][1], summary.recipe);
  if (values.length > 1) {
    return values.map(([path, value]) => `${sweepPathLabel(path)} ${sweepValueLabel(path, value, summary.recipe)}`).join(", ");
  }
  const label = resultVariantLabel(summary, index);
  const parts = String(label).trim().split(/\s+/);
  return parts.length > 1 ? parts[parts.length - 1] : label;
}

function resultVariantControlLabel(summaries) {
  const labels = summaries.map((summary, index) => resultVariantLabel(summary, index));
  if (labels.length && labels.every((label) => String(label).toLowerCase().startsWith("quality "))) return "Quality";
  if (labels.length && labels.every((label) => String(label).toLowerCase().startsWith("vbr scale "))) return "VBR scale";
  if (labels.length && labels.every((label) => String(label).toLowerCase().startsWith("model "))) return "Model";
  if (labels.length && labels.every((label) => String(label).toLowerCase().startsWith("snr "))) return "SNR";
  return "Variant";
}

function resultVariantOptionLabel(summary, index, summaries) {
  const control = resultVariantControlLabel(summaries);
  return control === "Quality" || control === "Model" || control === "VBR scale" || control === "SNR"
    ? resultVariantValueLabel(summary, index)
    : resultVariantLabel(summary, index);
}

function aggregateResultStatus(summaries) {
  const statuses = summaries.map((summary) => summary.status);
  if (statuses.includes("timed_out")) return "timed_out";
  if (statuses.includes("resource_exhausted")) return "resource_exhausted";
  if (statuses.includes("failed")) return "failed";
  if (statuses.includes("canceled")) return "canceled";
  if (statuses.includes("running")) return "running";
  if (statuses.length && statuses.every((status) => status === "completed")) return "completed";
  return statuses[statuses.length - 1] || "result";
}

function comparisonTable(rows) {
  const headers = [
    "Recipe",
    "Run",
    "Channel",
    "Runner",
    "Purpose",
    "Primary metric",
    "Primary value",
    "Rate bpp",
    "Tx bits",
    "Channel uses / pixel",
    "PSNR",
    "MSE",
    "MAE",
    "Text sim",
    "BLEU",
    "Edit sim",
    "Exact",
    "BER",
    "Pre-decode BER",
    "Encoder infer p50",
    "Encoder payload p50",
    "Decoder infer p50",
    "Decoder payload p50",
  ];
  const labels = recipeDisplayLabels(rows.map((row) => row.recipe));
  const body = rows.flatMap((row) => {
    const title = recipeDisplayName(row.recipe, labels);
    const summaries = resultSummaries(row);
    if (!summaries.length) {
      const empty = Array(headers.length).fill("");
      empty[0] = title;
      empty[1] = row.error ? `error: ${row.error}` : "no result";
      return [empty];
    }
    return summaries.map((summary, index) => {
      const details = collectRunDetails(summary);
      const rate = rateDistortionPoint(row, labels, details, summary);
      const taskMetric = primaryTaskMetric(details, summary, row);
      const variant = resultVariantLabel(summary, index);
      return [
        summaries.length > 1 ? `${title} - ${variant}` : title,
        summary.run_id || "",
        channelStatusLabel(summary, details),
        codecRunnerLabelForSummary(summary),
        summaryTaskLabel(summary, row),
        taskMetric ? taskMetric.label : "",
        taskMetric ? taskMetric.value : "",
        rate ? rate.bpp : "",
        rate ? rate.bits : "",
        Number.isFinite(channelUsesPerSourcePixel(details)) ? channelUsesPerSourcePixel(details) : "",
        metricValue(details, ["evaluation.quality.psnr_db", "quality.psnr_db"]),
        metricValue(details, ["evaluation.quality.mse", "quality.mse"]),
        metricValue(details, ["evaluation.quality.mae", "quality.mae"]),
        metricValue(details, ["evaluation.semantic.lexical_similarity", "semantic.lexical_similarity"]),
        metricValue(details, ["evaluation.text.unigram_bleu_proxy", "text.unigram_bleu_proxy"]),
        metricValue(details, ["evaluation.text.edit_similarity", "text.edit_similarity"]),
        metricValue(details, ["evaluation.text.exact_match", "text.exact_match"]),
        metricValue(details, ["payload_ber.channel.payload.ber", "channel.payload.ber"]),
        metricValue(details, ["coded_ber.channel.coded.ber", "channel.coded.ber"]),
        metricValue(details, ["sender.codec_timing.encoder.inference.p50_s", "sender.codec_timing.encoder.model.p50_s", "sender.codec_timing.encoder.external_call.p50_s"]),
        metricValue(details, ["payload_encoder.codec_timing.encoder.total.p50_s", "payload_packer.codec_timing.encoder.total.p50_s", "payload_encoder.codec_timing.encoder.symbol_encode.p50_s", "payload_encoder.codec_timing.encoder.payload_model_inference.p50_s", "payload_packer.codec_timing.encoder.symbol_encode.p50_s", "payload_encoder.codec_timing.encoder.payload_encode.p50_s", "payload_packer.codec_timing.encoder.payload_encode.p50_s", "sender.codec_timing.encoder.payload_encode.p50_s", "payload_encoder.codec_timing.encoder.entropy_encode.p50_s", "payload_packer.codec_timing.encoder.entropy_encode.p50_s", "sender.codec_timing.encoder.entropy_encode.p50_s", "sender.codec_timing.encoder.bitstream_encode.p50_s"]),
        metricValue(details, ["receiver.codec_timing.decoder.inference.p50_s", "receiver.codec_timing.decoder.model.p50_s", "receiver.codec_timing.decoder.external_call.p50_s"]),
        metricValue(details, ["payload_decoder.codec_timing.decoder.total.p50_s", "payload_unpacker.codec_timing.decoder.total.p50_s", "payload_decoder.codec_timing.decoder.symbol_decode.p50_s", "payload_decoder.codec_timing.decoder.payload_model_inference.p50_s", "payload_unpacker.codec_timing.decoder.symbol_decode.p50_s", "payload_decoder.codec_timing.decoder.payload_decode.p50_s", "payload_unpacker.codec_timing.decoder.payload_decode.p50_s", "receiver.codec_timing.decoder.payload_decode.p50_s", "payload_decoder.codec_timing.decoder.entropy_decode.p50_s", "payload_unpacker.codec_timing.decoder.entropy_decode.p50_s", "receiver.codec_timing.decoder.entropy_decode.p50_s", "receiver.codec_timing.decoder.bitstream_decode.p50_s"]),
      ].map((value, columnIndex) => (value === "" ? "" : formatMetricDisplay(headers[columnIndex], value)));
    });
  });
  return table(headers, body);
}

function rateDistortionPlot(rows, presentation = rateDistortionPresentation(rows)) {
  const labels = recipeDisplayLabels(rows.map((row) => row.recipe));
  const metricDefinitions = scatterMetricDefinitions(rows);
  const settings = normalizedRdSettings(
    metricDefinitions,
    presentation.settings || RD_DEFAULT_SETTINGS,
    presentation.context || "generic-rate-distortion",
  );
  const points = filterChartPointsForAxisScale(rows
    .flatMap((row) => rdChartPoints(row, labels, settings, metricDefinitions))
    .filter(Boolean), settings);
  if (!points.length) {
    return `
      <div class="rd-chart-wrap empty">
        <button class="icon-button rd-settings-button" type="button" data-rd-settings aria-label="Rate-distortion figure settings">&#9881;</button>
        <div class="result-empty">Run recipes with numeric result metrics to draw this figure, or choose different x/y metrics from the chart settings.</div>
      </div>
    `;
  }
  const width = RESULT_FIGURE_WIDTH;
  const height = RESULT_FIGURE_HEIGHT;
  const margin = { left: 68, right: 18, top: 18, bottom: 42 };
  const xs = points.map((point) => point.x);
  const ys = points.map((point) => point.y);
  const sizes = points.map((point) => point.size).filter(Number.isFinite);
  const sizeDomain = sizes.length ? paddedDomain(sizes, 0, sizes.every((value) => value >= 0)) : null;
  const rScale = (value) => {
    if (!Number.isFinite(value) || !sizeDomain) return 6.5;
    if (sizeDomain[0] === sizeDomain[1]) return 8;
    return 5 + ((value - sizeDomain[0]) / (sizeDomain[1] - sizeDomain[0])) * 11;
  };
  const markerExtent = scatterMarkerExtent(points, rScale);
  const baseXDomain = scatterDomainWithMarkerPadding(
    chartDomainForValues(xs, 0.08, xs.every((value) => value >= 0), settings.xLog),
    xs,
    markerExtent,
    width - margin.left - margin.right,
    settings.xLog,
  );
  const baseYDomain = scatterDomainWithMarkerPadding(
    chartDomainForValues(ys, 0.08, ys.every((value) => value >= 0), settings.yLog),
    ys,
    markerExtent,
    height - margin.top - margin.bottom,
    settings.yLog,
  );
  const domains = rdVisibleDomains(baseXDomain, baseYDomain, settings);
  const xDomain = domains.x;
  const yDomain = domains.y;
  const xScale = chartScale(xDomain, margin.left, width - margin.right, settings.xLog);
  const yScale = chartScale(yDomain, height - margin.bottom, margin.top, settings.yLog);
  const xTicks = chartTicksForDomain(xDomain, 4, settings.xLog);
  const yTicks = chartTicksForDomain(yDomain, 4, settings.yLog);
  const xLabel = scatterMetricLabel(metricDefinitions, settings.x, settings.xStat);
  const yLabel = scatterMetricLabel(metricDefinitions, settings.y, settings.yStat);
  const sizeLabel = settings.size === "none" ? "fixed point size" : scatterMetricLabel(metricDefinitions, settings.size, settings.sizeStat);
  const series = rdPointSeries(points, xScale, yScale, width - 120);
  const drawPoints = scatterDrawPoints(points, rScale);
  return `
    <div class="rd-chart-wrap">
      <button class="icon-button rd-settings-button" type="button" data-rd-settings aria-label="Rate-distortion figure settings">&#9881;</button>
      <svg class="rd-chart" data-rd-chart data-visualization-id="rate-distortion"
        data-width="${width}" data-height="${height}"
        data-left="${margin.left}" data-right="${margin.right}" data-top="${margin.top}" data-bottom="${margin.bottom}"
        data-x-min="${xDomain[0]}" data-x-max="${xDomain[1]}" data-y-min="${yDomain[0]}" data-y-max="${yDomain[1]}"
        data-x-metric="${escapeAttr(settings.x)}" data-y-metric="${escapeAttr(settings.y)}"
        data-x-stat="${escapeAttr(settings.xStat)}" data-y-stat="${escapeAttr(settings.yStat)}"
        data-x-log="${settings.xLog ? "true" : "false"}" data-y-log="${settings.yLog ? "true" : "false"}"
        viewBox="0 0 ${width} ${height}" preserveAspectRatio="xMidYMid meet" role="img" aria-label="${escapeAttr(presentation.ariaLabel || "Rate distortion plot")}">
        <defs>
          <clipPath id="rd-plot-clip">
            <rect x="${margin.left}" y="${margin.top}" width="${width - margin.left - margin.right}" height="${height - margin.top - margin.bottom}"></rect>
          </clipPath>
        </defs>
        <text class="rd-plot-title" x="${width / 2}" y="12" text-anchor="middle">${escapeHtml(presentation.title || "Rate Distortion")}</text>
        <line class="rd-axis" x1="${margin.left}" y1="${height - margin.bottom}" x2="${width - margin.right}" y2="${height - margin.bottom}"></line>
        <line class="rd-axis" x1="${margin.left}" y1="${margin.top}" x2="${margin.left}" y2="${height - margin.bottom}"></line>
        ${xTicks.map((tick) => `
          <g class="rd-tick">
            <line x1="${xScale(tick)}" y1="${margin.top}" x2="${xScale(tick)}" y2="${height - margin.bottom}"></line>
            <text x="${xScale(tick)}" y="${height - 18}">${escapeHtml(formatRdTick(tick, settings.x))}</text>
          </g>
        `).join("")}
        ${yTicks.map((tick) => `
          <g class="rd-tick y">
            <line x1="${margin.left}" y1="${yScale(tick)}" x2="${width - margin.right}" y2="${yScale(tick)}"></line>
            <text x="${margin.left - 12}" y="${yScale(tick) + 3}">${escapeHtml(formatRdTick(tick, settings.y))}</text>
          </g>
        `).join("")}
        <g clip-path="url(#rd-plot-clip)">
          ${series.map((item) => `
            <polyline class="rd-series-line" points="${escapeAttr(item.points)}" style="--recipe-color: ${escapeAttr(item.color)}"></polyline>
          `).join("")}
          ${series.map((item) => `
            <text class="rd-series-label" x="${item.labelX}" y="${item.labelY}" text-anchor="${escapeAttr(item.anchor)}" style="--recipe-color: ${escapeAttr(item.color)}">${escapeHtml(trim(item.label, 32))}</text>
          `).join("")}
          ${drawPoints.map((point) => `
            <g class="rd-point" data-result-key="${escapeAttr(point.key)}" data-draw-order="${point.drawOrder}" transform="translate(${xScale(point.x).toFixed(1)}, ${yScale(point.y).toFixed(1)})" style="--recipe-color: ${escapeAttr(point.color)}" tabindex="0" role="img" aria-label="${escapeAttr(rdPointTitle(point, xLabel, yLabel, sizeLabel))}" data-result-tooltip="${escapeAttr(rdPointTitle(point, xLabel, yLabel, sizeLabel))}">
              <circle r="${point.drawRadius.toFixed(1)}"></circle>
              <text x="8" y="-7">${escapeHtml(trim(point.label, point.groupSize > 1 ? 16 : 28))}</text>
            </g>
          `).join("")}
        </g>
        <text class="rd-axis-label" x="${width / 2}" y="${height - 5}">${escapeHtml(xLabel)}</text>
        <text class="rd-axis-label y" x="14" y="${height / 2}" transform="rotate(-90 14 ${height / 2})">${escapeHtml(yLabel)}</text>
      </svg>
    </div>
  `;
}

function modelTimeScatterPlot(rows) {
  const labels = recipeDisplayLabels(rows.map((row) => row.recipe));
  const metricDefinitions = scatterMetricDefinitions(rows);
  const settings = normalizedModelTimeSettings(metricDefinitions);
  const points = filterChartPointsForAxisScale(rows
    .flatMap((row) => modelTimeChartPoints(row, labels, settings, metricDefinitions))
    .filter(Boolean), settings);
  if (!points.length) {
    return `
      <div class="rd-chart-wrap model-time-chart-wrap empty">
        <button class="icon-button rd-settings-button" type="button" data-model-time-settings aria-label="Runtime scatter settings">&#9881;</button>
        <div class="result-empty">Run recipes with codec timing and memory metrics to draw the runtime scatter.</div>
      </div>
    `;
  }
  const width = RESULT_FIGURE_WIDTH;
  const height = RESULT_FIGURE_HEIGHT;
  const margin = { left: 68, right: 18, top: 18, bottom: 42 };
  const xs = points.map((point) => point.x);
  const ys = points.map((point) => point.y);
  const sizes = points.map((point) => point.size).filter(Number.isFinite);
  const sizeDomain = sizes.length ? paddedDomain(sizes, 0, sizes.every((value) => value >= 0)) : null;
  const rScale = (value) => {
    if (!Number.isFinite(value) || !sizeDomain) return 6.5;
    if (sizeDomain[0] === sizeDomain[1]) return 8;
    return 5 + ((value - sizeDomain[0]) / (sizeDomain[1] - sizeDomain[0])) * 11;
  };
  const markerExtent = scatterMarkerExtent(points, rScale);
  const baseXDomain = scatterDomainWithMarkerPadding(
    chartDomainForValues(xs, 0.1, xs.every((value) => value >= 0), settings.xLog),
    xs,
    markerExtent,
    width - margin.left - margin.right,
    settings.xLog,
  );
  const baseYDomain = scatterDomainWithMarkerPadding(
    chartDomainForValues(ys, 0.1, ys.every((value) => value >= 0), settings.yLog),
    ys,
    markerExtent,
    height - margin.top - margin.bottom,
    settings.yLog,
  );
  const domains = modelTimeVisibleDomains(baseXDomain, baseYDomain, settings);
  const xDomain = domains.x;
  const yDomain = domains.y;
  const xScale = chartScale(xDomain, margin.left, width - margin.right, settings.xLog);
  const yScale = chartScale(yDomain, height - margin.bottom, margin.top, settings.yLog);
  const xTicks = chartTicksForDomain(xDomain, 4, settings.xLog);
  const yTicks = chartTicksForDomain(yDomain, 4, settings.yLog);
  const title = "Runtime Scatter";
  const xLabel = scatterMetricLabel(metricDefinitions, settings.x, settings.xStat);
  const yLabel = scatterMetricLabel(metricDefinitions, settings.y, settings.yStat);
  const sizeLabel = settings.size === "none" ? "fixed point size" : scatterMetricLabel(metricDefinitions, settings.size, settings.sizeStat);
  const series = rdPointSeries(points, xScale, yScale, width - 120);
  const drawPoints = scatterDrawPoints(points, rScale);
  return `
    <div class="rd-chart-wrap model-time-chart-wrap">
      <button class="icon-button rd-settings-button" type="button" data-model-time-settings aria-label="Runtime scatter settings">&#9881;</button>
      <svg class="rd-chart model-time-chart" data-model-time-chart data-visualization-id="runtime-scatter"
        data-width="${width}" data-height="${height}"
        data-left="${margin.left}" data-right="${margin.right}" data-top="${margin.top}" data-bottom="${margin.bottom}"
        data-x-min="${xDomain[0]}" data-x-max="${xDomain[1]}" data-y-min="${yDomain[0]}" data-y-max="${yDomain[1]}"
        data-x-metric="${escapeAttr(settings.x)}" data-y-metric="${escapeAttr(settings.y)}"
        data-x-stat="${escapeAttr(settings.xStat)}" data-y-stat="${escapeAttr(settings.yStat)}"
        data-x-log="${settings.xLog ? "true" : "false"}" data-y-log="${settings.yLog ? "true" : "false"}"
        viewBox="0 0 ${width} ${height}" preserveAspectRatio="xMidYMid meet" role="img" aria-label="${escapeAttr(title)} scatter plot">
        <defs>
          <clipPath id="model-time-plot-clip">
            <rect x="${margin.left}" y="${margin.top}" width="${width - margin.left - margin.right}" height="${height - margin.top - margin.bottom}"></rect>
          </clipPath>
        </defs>
        <text class="rd-plot-title" x="${width / 2}" y="12" text-anchor="middle">${escapeHtml(title)}</text>
        <line class="rd-axis" x1="${margin.left}" y1="${height - margin.bottom}" x2="${width - margin.right}" y2="${height - margin.bottom}"></line>
        <line class="rd-axis" x1="${margin.left}" y1="${margin.top}" x2="${margin.left}" y2="${height - margin.bottom}"></line>
        ${xTicks.map((tick) => `
          <g class="rd-tick">
            <line x1="${xScale(tick)}" y1="${margin.top}" x2="${xScale(tick)}" y2="${height - margin.bottom}"></line>
            <text x="${xScale(tick)}" y="${height - 18}">${escapeHtml(formatRdTick(tick, settings.x))}</text>
          </g>
        `).join("")}
        ${yTicks.map((tick) => `
          <g class="rd-tick y">
            <line x1="${margin.left}" y1="${yScale(tick)}" x2="${width - margin.right}" y2="${yScale(tick)}"></line>
            <text x="${margin.left - 12}" y="${yScale(tick) + 3}">${escapeHtml(formatRdTick(tick, settings.y))}</text>
          </g>
        `).join("")}
        <g clip-path="url(#model-time-plot-clip)">
          ${series.map((item) => `
            <polyline class="rd-series-line" points="${escapeAttr(item.points)}" style="--recipe-color: ${escapeAttr(item.color)}"></polyline>
          `).join("")}
          ${series.map((item) => `
            <text class="rd-series-label" x="${item.labelX}" y="${item.labelY}" text-anchor="${escapeAttr(item.anchor)}" style="--recipe-color: ${escapeAttr(item.color)}">${escapeHtml(trim(item.label, 24))}</text>
          `).join("")}
          ${drawPoints.map((point) => `
            <g class="rd-point" data-result-key="${escapeAttr(point.key)}" data-draw-order="${point.drawOrder}" transform="translate(${xScale(point.x).toFixed(1)}, ${yScale(point.y).toFixed(1)})" style="--recipe-color: ${escapeAttr(point.color)}" tabindex="0" role="img" aria-label="${escapeAttr(modelTimePointTitle(point, xLabel, yLabel, sizeLabel))}" data-result-tooltip="${escapeAttr(modelTimePointTitle(point, xLabel, yLabel, sizeLabel))}">
              <circle r="${point.drawRadius.toFixed(1)}"></circle>
              <text x="8" y="-7">${escapeHtml(trim(point.label, point.groupSize > 1 ? 16 : 24))}</text>
            </g>
          `).join("")}
        </g>
        <text class="rd-axis-label" x="${width / 2}" y="${height - 5}">${escapeHtml(xLabel)}</text>
        <text class="rd-axis-label y" x="14" y="${height / 2}" transform="rotate(-90 14 ${height / 2})">${escapeHtml(yLabel)}</text>
      </svg>
    </div>
  `;
}

function timeBoxPlot(rows) {
  const labels = recipeDisplayLabels(rows.map((row) => row.recipe));
  const settings = normalizedTimeBoxSettings();
  const boxes = rows
    .map((row) => timeBoxForRow(row, labels, settings))
    .filter(Boolean);
  if (!boxes.length) {
    return `
      <div class="rd-chart-wrap time-box-chart-wrap empty">
        <button class="icon-button rd-settings-button" type="button" data-time-box-settings aria-label="Timing box plot settings">&#9881;</button>
        <div class="result-empty">Run recipes with raw codec timing measurements to draw timing box plots.</div>
      </div>
    `;
  }
  const width = RESULT_FIGURE_WIDTH;
  const height = RESULT_FIGURE_HEIGHT;
  const margin = { left: 68, right: 18, top: 18, bottom: 52 };
  const yDomain = chartDomainForValues(
    boxes.flatMap((box) => [box.min, box.max]),
    0.1,
    true,
    settings.yLog
  );
  const yScale = chartScale(yDomain, height - margin.bottom, margin.top, settings.yLog);
  const xCenter = (index) => margin.left + ((index + 0.5) / boxes.length) * (width - margin.left - margin.right);
  const boxWidth = Math.max(18, Math.min(46, ((width - margin.left - margin.right) / boxes.length) * 0.42));
  const yTicks = chartTicksForDomain(yDomain, 4, settings.yLog);
  const metricLabel = timeBoxMetricLabel(settings.metric);
  return `
    <div class="rd-chart-wrap time-box-chart-wrap">
      <button class="icon-button rd-settings-button" type="button" data-time-box-settings aria-label="Timing box plot settings">&#9881;</button>
      <svg class="rd-chart time-box-chart"
        data-time-box-chart data-visualization-id="timing-distribution"
        viewBox="0 0 ${width} ${height}" preserveAspectRatio="xMidYMid meet" role="img" aria-label="${escapeAttr(metricLabel)} box plot">
        <text class="rd-plot-title" x="${width / 2}" y="12" text-anchor="middle">${escapeHtml(metricLabel)} Distribution</text>
        <line class="rd-axis" x1="${margin.left}" y1="${height - margin.bottom}" x2="${width - margin.right}" y2="${height - margin.bottom}"></line>
        <line class="rd-axis" x1="${margin.left}" y1="${margin.top}" x2="${margin.left}" y2="${height - margin.bottom}"></line>
        ${yTicks.map((tick) => `
          <g class="rd-tick y">
            <line x1="${margin.left}" y1="${yScale(tick)}" x2="${width - margin.right}" y2="${yScale(tick)}"></line>
            <text x="${margin.left - 12}" y="${yScale(tick) + 3}">${escapeHtml(formatTimingTick(tick))}</text>
          </g>
        `).join("")}
        ${boxes.map((box, index) => {
          const cx = xCenter(index);
          const left = cx - boxWidth / 2;
          const q1 = yScale(box.q1);
          const q3 = yScale(box.q3);
          const median = yScale(box.median);
          const min = yScale(box.min);
          const max = yScale(box.max);
          const rectY = Math.min(q1, q3);
          const rectHeight = Math.max(2, Math.abs(q3 - q1));
          return `
            <g class="time-box" data-result-key="${escapeAttr(box.key)}" transform="translate(${cx.toFixed(1)},0)" style="--recipe-color: ${escapeAttr(box.color)}" tabindex="0" role="img" aria-label="${escapeAttr(timeBoxTitle(box, metricLabel))}" data-result-tooltip="${escapeAttr(timeBoxTitle(box, metricLabel))}">
              <g class="time-box-shape">
                <line class="time-box-whisker" x1="0" x2="0" y1="${max.toFixed(1)}" y2="${min.toFixed(1)}"></line>
                <line class="time-box-cap" x1="${(-boxWidth * 0.32).toFixed(1)}" x2="${(boxWidth * 0.32).toFixed(1)}" y1="${max.toFixed(1)}" y2="${max.toFixed(1)}"></line>
                <line class="time-box-cap" x1="${(-boxWidth * 0.32).toFixed(1)}" x2="${(boxWidth * 0.32).toFixed(1)}" y1="${min.toFixed(1)}" y2="${min.toFixed(1)}"></line>
                <rect class="time-box-rect" x="${(left - cx).toFixed(1)}" y="${rectY.toFixed(1)}" width="${boxWidth.toFixed(1)}" height="${rectHeight.toFixed(1)}" rx="3"></rect>
                <line class="time-box-median" x1="${(left - cx).toFixed(1)}" x2="${(left - cx + boxWidth).toFixed(1)}" y1="${median.toFixed(1)}" y2="${median.toFixed(1)}"></line>
              </g>
              <text class="time-box-label" x="0" y="${height - 18}" transform="rotate(-28 0 ${height - 18})">${escapeHtml(trim(box.label, 18))}</text>
            </g>
          `;
        }).join("")}
        <text class="rd-axis-label y" x="14" y="${height / 2}" transform="rotate(-90 14 ${height / 2})">Time</text>
      </svg>
    </div>
  `;
}

function scatterDrawPoints(points, radiusScale) {
  return (points || [])
    .map((point, index) => ({
      ...point,
      sourceIndex: index,
      drawRadius: Number(radiusScale(point.size)),
    }))
    .sort((left, right) => {
      const radiusDelta = Number(right.drawRadius) - Number(left.drawRadius);
      if (Math.abs(radiusDelta) > 1e-9) return radiusDelta;
      return left.sourceIndex - right.sourceIndex;
    })
    .map((point, drawOrder) => ({
      ...point,
      drawOrder,
      drawRadius: Number.isFinite(point.drawRadius) ? point.drawRadius : 6.5,
    }));
}

function normalizedModelTimeSettings(definitions = scatterMetricDefinitions(visibleResultRows(state.resultRows || []))) {
  const next = { ...MODEL_TIME_DEFAULT_SETTINGS, ...(state.modelTimeSettings || {}) };
  normalizeLegacyScatterMetricSettings(next, "x");
  normalizeLegacyScatterMetricSettings(next, "y");
  normalizeLegacyScatterMetricSettings(next, "size");
  normalizeAxisLogSettings(next);
  const ids = new Set(definitions.map((item) => item.id));
  if (!ids.has(next.x)) next.x = ids.has(MODEL_TIME_DEFAULT_SETTINGS.x) ? MODEL_TIME_DEFAULT_SETTINGS.x : (definitions[0] && definitions[0].id) || MODEL_TIME_DEFAULT_SETTINGS.x;
  if (!ids.has(next.y)) next.y = ids.has(MODEL_TIME_DEFAULT_SETTINGS.y) ? MODEL_TIME_DEFAULT_SETTINGS.y : (definitions[0] && definitions[0].id) || MODEL_TIME_DEFAULT_SETTINGS.y;
  if (next.size !== "none" && !ids.has(next.size)) {
    next.size = ids.has(MODEL_TIME_DEFAULT_SETTINGS.size) ? MODEL_TIME_DEFAULT_SETTINGS.size : "none";
  }
  next.xStat = normalizeScatterStat(definitions, next.x, next.xStat, MODEL_TIME_DEFAULT_SETTINGS.xStat);
  next.yStat = normalizeScatterStat(definitions, next.y, next.yStat, MODEL_TIME_DEFAULT_SETTINGS.yStat);
  next.sizeStat = normalizeScatterStat(definitions, next.size, next.sizeStat, MODEL_TIME_DEFAULT_SETTINGS.sizeStat);
  next.colorBy = normalizeFigureColorBy(next.colorBy);
  state.modelTimeSettings = next;
  return next;
}

function normalizedCommunicationSettings() {
  const next = { ...COMMUNICATION_DEFAULT_SETTINGS, ...(state.communicationSettings || {}) };
  normalizeAxisLogSettings(next);
  next.colorBy = normalizeFigureColorBy(next.colorBy);
  state.communicationSettings = next;
  return next;
}

function normalizedChannelResponseSettings() {
  const next = { ...CHANNEL_RESPONSE_DEFAULT_SETTINGS, ...(state.channelResponseSettings || {}) };
  normalizeAxisLogSettings(next);
  next.xLog = false;
  next.colorBy = normalizeFigureColorBy(next.colorBy);
  state.channelResponseSettings = next;
  return next;
}

function normalizedTxPowerSettings() {
  const next = { ...TX_POWER_DEFAULT_SETTINGS, ...(state.txPowerSettings || {}) };
  normalizeAxisLogSettings(next);
  next.xLog = false;
  next.colorBy = normalizeFigureColorBy(next.colorBy);
  state.txPowerSettings = next;
  return next;
}

function normalizedResourcePerformanceSettings() {
  const next = { ...RESOURCE_PERFORMANCE_DEFAULT_SETTINGS, ...(state.resourcePerformanceSettings || {}) };
  normalizeAxisLogSettings(next);
  next.includeZero = coerceBoolean(next.includeZero);
  next.showMarkers = coerceBoolean(next.showMarkers);
  next.showValues = coerceBoolean(next.showValues);
  state.resourcePerformanceSettings = next;
  return next;
}

function normalizedTimeBoxSettings() {
  const next = { ...TIME_BOX_DEFAULT_SETTINGS, ...(state.timeBoxSettings || {}) };
  normalizeAxisLogSettings(next);
  if (!TIME_BOX_METRIC_OPTIONS.some((item) => item.id === next.metric)) {
    next.metric = TIME_BOX_DEFAULT_SETTINGS.metric;
  }
  state.timeBoxSettings = next;
  return next;
}

function normalizeAxisLogSettings(settings) {
  settings.xLog = coerceBoolean(settings.xLog);
  settings.yLog = coerceBoolean(settings.yLog);
}

function normalizeFigureColorBy(value) {
  const options = resultColorOptions(visibleResultRows(state.resultRows || []));
  return options.some((item) => item.id === value) ? value : "recipe";
}

function modelTimeVisibleDomains(baseXDomain, baseYDomain, settings) {
  const view = state.modelTimeView;
  if (
    view &&
    view.xMetric === settings.x &&
    view.yMetric === settings.y &&
    view.xStat === settings.xStat &&
    view.yStat === settings.yStat &&
    coerceBoolean(view.xLog) === coerceBoolean(settings.xLog) &&
    coerceBoolean(view.yLog) === coerceBoolean(settings.yLog) &&
    validDomain(view.xDomain) &&
    validDomain(view.yDomain)
  ) {
    return { x: view.xDomain.slice(), y: view.yDomain.slice() };
  }
  return { x: baseXDomain.slice(), y: baseYDomain.slice() };
}

function domainChartVisibleDomains(viewKey, baseXDomain, baseYDomain, options = {}) {
  const key = String(viewKey || "");
  const view = key && state.domainChartViews ? state.domainChartViews[key] : null;
  const signature = String(options.signature || "");
  const xMetric = String(options.xMetric || "");
  const yMetric = String(options.yMetric || "");
  const y2Metric = String(options.y2Metric || "");
  const hasY2Domain = validDomain(options.y2Domain);
  if (
    view &&
    String(view.signature || "") === signature &&
    String(view.xMetric || "") === xMetric &&
    String(view.yMetric || "") === yMetric &&
    String(view.y2Metric || "") === y2Metric &&
    coerceBoolean(view.xLog) === coerceBoolean(options.xLog) &&
    coerceBoolean(view.yLog) === coerceBoolean(options.yLog) &&
    (!hasY2Domain || coerceBoolean(view.y2Log) === coerceBoolean(options.y2Log)) &&
    validDomain(view.xDomain) &&
    validDomain(view.yDomain) &&
    (!hasY2Domain || validDomain(view.y2Domain))
  ) {
    return {
      x: view.xDomain.slice(),
      y: view.yDomain.slice(),
      ...(hasY2Domain ? { y2: view.y2Domain.slice() } : {}),
    };
  }
  return {
    x: baseXDomain.slice(),
    y: baseYDomain.slice(),
    ...(hasY2Domain ? { y2: options.y2Domain.slice() } : {}),
  };
}

function modelTimeChartPoints(row, labels, settings, definitions) {
  const summaries = resultSummaries(row);
  return summaries.map((summary, index) => {
    const details = collectRunDetails(summary);
    const x = scatterMetricValue(details, settings.x, settings.xStat);
    const y = scatterMetricValue(details, settings.y, settings.yStat);
    if (!Number.isFinite(x) || !Number.isFinite(y)) return null;
    const variant = resultVariantLabel(summary, index);
    const title = recipeDisplayName(row.recipe, labels);
    const xStats = timingStatsForScatterMetric(summary, settings.x);
    const yStats = timingStatsForScatterMetric(summary, settings.y);
    return {
      key: resultRowKey(row),
      groupKey: resultRowKey(row),
      title: summaries.length > 1 ? `${title} - ${variant}` : title,
      label: summaries.length > 1 ? resultVariantValueLabel(summary, index) : title,
      seriesTitle: title,
      groupSize: summaries.length,
      color: resultPointColor(row, summary, settings.colorBy),
      seriesColor: recipeColor(row.recipe),
      x,
      y,
      size: settings.size === "none" ? NaN : scatterMetricValue(details, settings.size, settings.sizeStat),
      xCount: Number(xStats.count),
      yCount: Number(yStats.count),
      xKind: scatterMetricKind(definitions, settings.x),
      yKind: scatterMetricKind(definitions, settings.y),
      sizeKind: scatterMetricKind(definitions, settings.size),
    };
  }).filter(Boolean);
}

function statsForFirstTimingComponent(componentSamples, keys) {
  for (const key of keys) {
    const samples = componentSamples.get(key) || [];
    if (samples.length) return timingStats(samples);
  }
  return {};
}

function timeBoxForRow(row, labels, settings) {
  const values = resultSummaries(row).flatMap((summary) => timingValuesForSummary(summary, settings.metric));
  const stats = boxStats(values);
  if (!stats) return null;
  const title = recipeDisplayName(row.recipe, labels);
  return {
    ...stats,
    key: resultRowKey(row),
    title,
    label: title,
    color: recipeColor(row.recipe),
  };
}

function timingValuesForSummary(summary, metricId) {
  const componentSamples = timingComponentSamplesForSummary(summary);
  if (componentSamples.has(metricId)) return componentSamples.get(metricId);
  return timingStageSamplesForSummary(summary, metricId);
}

function timingStageSamplesForSummary(summary, metricId) {
  const buckets = new Map();
  if (!metricId) return [];
  (summary.steps || []).forEach((step) => {
    codecTimingMeasurements(step).forEach((record, recordIndex) => {
      const stage = String(record.stage || "").trim();
      if (stage !== metricId) return;
      const seconds = Number(record.duration_s);
      if (!Number.isFinite(seconds) || seconds < 0) return;
      const sampleKey = timingRecordSampleKey(record, step, stage, recordIndex);
      buckets.set(sampleKey, (buckets.get(sampleKey) || 0) + seconds);
    });
  });
  return Array.from(buckets.values());
}

function boxStats(values) {
  const sorted = values.map(Number).filter(Number.isFinite).sort((left, right) => left - right);
  if (!sorted.length) return null;
  return {
    min: sorted[0],
    q1: percentile(sorted, 0.25),
    median: percentile(sorted, 0.5),
    q3: percentile(sorted, 0.75),
    max: sorted[sorted.length - 1],
    count: sorted.length,
    mean: sorted.reduce((sum, value) => sum + value, 0) / sorted.length,
  };
}

function timeBoxMetricLabel(metricId) {
  const found = TIME_BOX_METRIC_OPTIONS.find((item) => item.id === metricId);
  return found ? found.label : String(metricId || "Timing");
}

function timeBoxTitle(box, metricLabel) {
  return [
    `${box.title}: ${metricLabel}`,
    `n=${formatValue(box.count)}`,
    `min ${formatTimingDuration(box.min)}`,
    `q1 ${formatTimingDuration(box.q1)}`,
    `median ${formatTimingDuration(box.median)}`,
    `q3 ${formatTimingDuration(box.q3)}`,
    `max ${formatTimingDuration(box.max)}`,
  ].join(", ");
}

function modelTimeMetric(details, keys) {
  const value = numberMetricValue(details, keys);
  return Number.isFinite(value) ? value : NaN;
}

function modelArtifactBytes(details, side) {
  const key = side === "decoder" ? "decoder_bytes" : "encoder_bytes";
  return numberMetricValue(details, [
    `codec_export.model_artifact.${key}`,
    `codec_export.model_artifact.total_bytes`,
    `sender.model_artifact.${key}`,
    `receiver.model_artifact.${key}`,
  ]);
}

function modelTimePointTitle(point, xLabel, yLabel, sizeLabel) {
  const parts = [
    `${point.title}: ${xLabel} ${formatScatterValue(point.x, point.xKind)}`,
    `${yLabel} ${formatScatterValue(point.y, point.yKind)}`,
  ];
  if (Number.isFinite(point.size)) parts.push(`${sizeLabel} ${formatScatterValue(point.size, point.sizeKind)}`);
  if (Number.isFinite(point.xCount)) parts.push(`x n=${formatValue(point.xCount)}`);
  if (Number.isFinite(point.yCount)) parts.push(`y n=${formatValue(point.yCount)}`);
  return parts.join(", ");
}

function formatTimingTick(value) {
  const number = Number(value);
  if (!Number.isFinite(number)) return "";
  return formatTimingDuration(number);
}

function rdVisibleDomains(baseXDomain, baseYDomain, settings) {
  const view = state.rdView;
  if (
    view &&
    view.xMetric === settings.x &&
    view.yMetric === settings.y &&
    view.xStat === settings.xStat &&
    view.yStat === settings.yStat &&
    coerceBoolean(view.xLog) === coerceBoolean(settings.xLog) &&
    coerceBoolean(view.yLog) === coerceBoolean(settings.yLog) &&
    validDomain(view.xDomain) &&
    validDomain(view.yDomain)
  ) {
    return { x: view.xDomain.slice(), y: view.yDomain.slice() };
  }
  return { x: baseXDomain.slice(), y: baseYDomain.slice() };
}

function validDomain(domain) {
  return (
    Array.isArray(domain) &&
    domain.length === 2 &&
    Number.isFinite(domain[0]) &&
    Number.isFinite(domain[1]) &&
    domain[1] > domain[0]
  );
}

function bindRdChartInteractions() {
  const chart = els.resultsComparison.querySelector("[data-rd-chart]");
  if (chart && chart.dataset.domainViewportBound !== "true") {
    chart.dataset.domainViewportBound = "true";
    configureVisualizationViewportAccessibility(chart);
    chart.addEventListener("wheel", onRdChartWheel, { passive: false });
    chart.addEventListener("pointerdown", startRdChartPan);
    chart.addEventListener("dblclick", resetRdChartView);
    chart.addEventListener("keydown", onRdChartKeydown);
  }
  const modelTimeChart = els.resultsComparison.querySelector("[data-model-time-chart]");
  if (modelTimeChart && modelTimeChart.dataset.domainViewportBound !== "true") {
    modelTimeChart.dataset.domainViewportBound = "true";
    configureVisualizationViewportAccessibility(modelTimeChart);
    modelTimeChart.addEventListener("wheel", onModelTimeChartWheel, { passive: false });
    modelTimeChart.addEventListener("pointerdown", startModelTimeChartPan);
    modelTimeChart.addEventListener("dblclick", resetModelTimeChartView);
    modelTimeChart.addEventListener("keydown", onModelTimeChartKeydown);
  }
}

function bindDomainChartInteractions() {
  if (!els.resultsComparison) return;
  els.resultsComparison.querySelectorAll("[data-domain-chart]").forEach((chart) => {
    if (chart.dataset.domainViewportBound === "true") return;
    chart.dataset.domainViewportBound = "true";
    configureVisualizationViewportAccessibility(chart);
    chart.addEventListener("wheel", onDomainChartWheel, { passive: false });
    chart.addEventListener("pointerdown", startDomainChartPan);
    chart.addEventListener("dblclick", resetDomainChartView);
    chart.addEventListener("keydown", onDomainChartKeydown);
  });
}

function domainChartViewKey(chart) {
  return String(chart && chart.dataset ? chart.dataset.domainViewKey || chart.dataset.visualizationId || "" : "");
}

function setDomainChartView(chart, spec, xDomain, yDomain, y2Domain = null) {
  const key = domainChartViewKey(chart);
  if (!key) return;
  state.domainChartViews = {
    ...(state.domainChartViews || {}),
    [key]: {
      signature: String(chart.dataset.domainSignature || ""),
      xMetric: spec.xMetric,
      yMetric: spec.yMetric,
      y2Metric: spec.y2Metric,
      xLog: spec.xLog,
      yLog: spec.yLog,
      y2Log: spec.y2Log,
      xDomain: xDomain.slice(),
      yDomain: yDomain.slice(),
      ...(validDomain(y2Domain) ? { y2Domain: y2Domain.slice() } : {}),
    },
  };
}

function clearDomainChartView(chart) {
  const key = domainChartViewKey(chart);
  if (!key || !state.domainChartViews || !Object.prototype.hasOwnProperty.call(state.domainChartViews, key)) return;
  const next = { ...state.domainChartViews };
  delete next[key];
  state.domainChartViews = next;
}

function onDomainChartWheel(event) {
  const chart = event.currentTarget;
  if (!chart || !visualizationWheelZoomRequested(event)) return;
  event.preventDefault();
  const spec = rdChartSpec(chart);
  const point = rdChartPointer(chart, event, spec);
  const factor = Math.max(0.4, Math.min(2.5, Math.exp(event.deltaY * 0.0012)));
  setDomainChartView(
    chart,
    spec,
    zoomDomain(spec.xDomain, point.x, factor, spec.xLog),
    zoomDomain(spec.yDomain, point.y, factor, spec.yLog),
    validDomain(spec.y2Domain) ? zoomDomain(spec.y2Domain, point.y2, factor, spec.y2Log) : null,
  );
  renderResultsDashboard(state.resultRows || []);
}

function startDomainChartPan(event) {
  if (event.button !== 0 || !event.currentTarget) return;
  event.preventDefault();
  const chart = event.currentTarget;
  const spec = rdChartSpec(chart);
  const rect = chart.getBoundingClientRect();
  chart.classList.add("panning");
  state.drag = {
    kind: "domain-chart-pan",
    chart,
    viewKey: domainChartViewKey(chart),
    spec,
    screenWidth: rect.width,
    screenHeight: rect.height,
    startX: event.clientX,
    startY: event.clientY,
  };
}

function resetDomainChartView(event) {
  if (event && typeof event.preventDefault === "function") event.preventDefault();
  clearDomainChartView(event && event.currentTarget);
  renderResultsDashboard(state.resultRows || []);
}

function onDomainChartKeydown(event) {
  const chart = event.currentTarget;
  if (!chart) return;
  if (event.key === "0") {
    event.preventDefault();
    clearDomainChartView(chart);
    renderResultsDashboard(state.resultRows || []);
    return;
  }
  const spec = rdChartSpec(chart);
  const centerX = axisValueAtRatio(spec.xDomain, 0.5, spec.xLog);
  const centerY = axisValueAtRatio(spec.yDomain, 0.5, spec.yLog);
  let xDomain = spec.xDomain;
  let yDomain = spec.yDomain;
  let y2Domain = spec.y2Domain;
  if (event.key === "+" || event.key === "=") {
    xDomain = zoomDomain(spec.xDomain, centerX, 0.82, spec.xLog);
    yDomain = zoomDomain(spec.yDomain, centerY, 0.82, spec.yLog);
    if (validDomain(spec.y2Domain)) {
      const centerY2 = axisValueAtRatio(spec.y2Domain, 0.5, spec.y2Log);
      y2Domain = zoomDomain(spec.y2Domain, centerY2, 0.82, spec.y2Log);
    }
  } else if (event.key === "-" || event.key === "_") {
    xDomain = zoomDomain(spec.xDomain, centerX, 1.22, spec.xLog);
    yDomain = zoomDomain(spec.yDomain, centerY, 1.22, spec.yLog);
    if (validDomain(spec.y2Domain)) {
      const centerY2 = axisValueAtRatio(spec.y2Domain, 0.5, spec.y2Log);
      y2Domain = zoomDomain(spec.y2Domain, centerY2, 1.22, spec.y2Log);
    }
  } else if (event.key === "ArrowLeft") {
    xDomain = panDomain(spec.xDomain, -0.08, spec.xLog);
  } else if (event.key === "ArrowRight") {
    xDomain = panDomain(spec.xDomain, 0.08, spec.xLog);
  } else if (event.key === "ArrowUp") {
    yDomain = panDomain(spec.yDomain, 0.08, spec.yLog);
    if (validDomain(spec.y2Domain)) y2Domain = panDomain(spec.y2Domain, 0.08, spec.y2Log);
  } else if (event.key === "ArrowDown") {
    yDomain = panDomain(spec.yDomain, -0.08, spec.yLog);
    if (validDomain(spec.y2Domain)) y2Domain = panDomain(spec.y2Domain, -0.08, spec.y2Log);
  } else {
    return;
  }
  event.preventDefault();
  setDomainChartView(chart, spec, xDomain, yDomain, y2Domain);
  renderResultsDashboard(state.resultRows || []);
}

function onRdChartWheel(event) {
  const chart = event.currentTarget;
  if (!chart || !visualizationWheelZoomRequested(event)) return;
  event.preventDefault();
  const spec = rdChartSpec(chart);
  const point = rdChartPointer(chart, event, spec);
  const factor = Math.max(0.4, Math.min(2.5, Math.exp(event.deltaY * 0.0012)));
  const xDomain = zoomDomain(spec.xDomain, point.x, factor, spec.xLog);
  const yDomain = zoomDomain(spec.yDomain, point.y, factor, spec.yLog);
  state.rdView = {
    xMetric: spec.xMetric,
    yMetric: spec.yMetric,
    xStat: spec.xStat,
    yStat: spec.yStat,
    xLog: spec.xLog,
    yLog: spec.yLog,
    xDomain,
    yDomain,
  };
  renderResultsDashboard(state.resultRows || []);
}

function startRdChartPan(event) {
  if (event.button !== 0 || !event.currentTarget) return;
  event.preventDefault();
  const chart = event.currentTarget;
  const spec = rdChartSpec(chart);
  const rect = chart.getBoundingClientRect();
  chart.classList.add("panning");
  state.drag = {
    kind: "rd-pan",
    chart,
    spec,
    screenWidth: rect.width,
    screenHeight: rect.height,
    startX: event.clientX,
    startY: event.clientY,
  };
}

function resetRdChartView(event) {
  if (event && typeof event.preventDefault === "function") event.preventDefault();
  state.rdView = null;
  renderResultsDashboard(state.resultRows || []);
}

function onRdChartKeydown(event) {
  const chart = event.currentTarget;
  if (!chart) return;
  const spec = rdChartSpec(chart);
  if (applyDomainChartKeyboardNavigation(event, spec, "rdView")) {
    renderResultsDashboard(state.resultRows || []);
  }
}

function onModelTimeChartWheel(event) {
  const chart = event.currentTarget;
  if (!chart || !visualizationWheelZoomRequested(event)) return;
  event.preventDefault();
  const spec = rdChartSpec(chart);
  const point = rdChartPointer(chart, event, spec);
  const factor = Math.max(0.4, Math.min(2.5, Math.exp(event.deltaY * 0.0012)));
  state.modelTimeView = {
    xMetric: spec.xMetric,
    yMetric: spec.yMetric,
    xStat: spec.xStat,
    yStat: spec.yStat,
    xLog: spec.xLog,
    yLog: spec.yLog,
    xDomain: zoomDomain(spec.xDomain, point.x, factor, spec.xLog),
    yDomain: zoomDomain(spec.yDomain, point.y, factor, spec.yLog),
  };
  renderResultsDashboard(state.resultRows || []);
}

function startModelTimeChartPan(event) {
  if (event.button !== 0 || !event.currentTarget) return;
  event.preventDefault();
  const chart = event.currentTarget;
  const spec = rdChartSpec(chart);
  const rect = chart.getBoundingClientRect();
  chart.classList.add("panning");
  state.drag = {
    kind: "model-time-pan",
    chart,
    spec,
    screenWidth: rect.width,
    screenHeight: rect.height,
    startX: event.clientX,
    startY: event.clientY,
  };
}

function resetModelTimeChartView(event) {
  if (event && typeof event.preventDefault === "function") event.preventDefault();
  state.modelTimeView = null;
  renderResultsDashboard(state.resultRows || []);
}

function onModelTimeChartKeydown(event) {
  const chart = event.currentTarget;
  if (!chart) return;
  const spec = rdChartSpec(chart);
  if (applyDomainChartKeyboardNavigation(event, spec, "modelTimeView")) {
    renderResultsDashboard(state.resultRows || []);
  }
}

function applyDomainChartKeyboardNavigation(event, spec, viewKey) {
  if (!event || !spec || !viewKey) return false;
  if (event.key === "0") {
    event.preventDefault();
    state[viewKey] = null;
    return true;
  }
  const centerX = axisValueAtRatio(spec.xDomain, 0.5, spec.xLog);
  const centerY = axisValueAtRatio(spec.yDomain, 0.5, spec.yLog);
  let xDomain = spec.xDomain;
  let yDomain = spec.yDomain;
  if (event.key === "+" || event.key === "=") {
    xDomain = zoomDomain(spec.xDomain, centerX, 0.82, spec.xLog);
    yDomain = zoomDomain(spec.yDomain, centerY, 0.82, spec.yLog);
  } else if (event.key === "-" || event.key === "_") {
    xDomain = zoomDomain(spec.xDomain, centerX, 1.22, spec.xLog);
    yDomain = zoomDomain(spec.yDomain, centerY, 1.22, spec.yLog);
  } else if (event.key === "ArrowLeft") {
    xDomain = panDomain(spec.xDomain, -0.08, spec.xLog);
  } else if (event.key === "ArrowRight") {
    xDomain = panDomain(spec.xDomain, 0.08, spec.xLog);
  } else if (event.key === "ArrowUp") {
    yDomain = panDomain(spec.yDomain, 0.08, spec.yLog);
  } else if (event.key === "ArrowDown") {
    yDomain = panDomain(spec.yDomain, -0.08, spec.yLog);
  } else {
    return false;
  }
  event.preventDefault();
  state[viewKey] = {
    xMetric: spec.xMetric,
    yMetric: spec.yMetric,
    xStat: spec.xStat,
    yStat: spec.yStat,
    xLog: spec.xLog,
    yLog: spec.yLog,
    xDomain,
    yDomain,
  };
  return true;
}

function rdChartSpec(chart) {
  const width = Number(chart.dataset.width) || 760;
  const height = Number(chart.dataset.height) || 292;
  const left = Number(chart.dataset.left) || 68;
  const right = Number(chart.dataset.right) || 18;
  const top = Number(chart.dataset.top) || 10;
  const bottom = Number(chart.dataset.bottom) || 38;
  return {
    width,
    height,
    left,
    right,
    top,
    bottom,
    plotWidth: Math.max(1, width - left - right),
    plotHeight: Math.max(1, height - top - bottom),
    xDomain: [Number(chart.dataset.xMin), Number(chart.dataset.xMax)],
    yDomain: [Number(chart.dataset.yMin), Number(chart.dataset.yMax)],
    y2Domain: [Number(chart.dataset.y2Min), Number(chart.dataset.y2Max)],
    xMetric: chart.dataset.xMetric || "",
    yMetric: chart.dataset.yMetric || "",
    y2Metric: chart.dataset.y2Metric || "",
    xStat: chart.dataset.xStat || "",
    yStat: chart.dataset.yStat || "",
    xLog: chart.dataset.xLog === "true",
    yLog: chart.dataset.yLog === "true",
    y2Log: chart.dataset.y2Log === "true",
  };
}

function rdChartPointer(chart, event, spec) {
  const rect = chart.getBoundingClientRect();
  const svgX = rect.width ? ((event.clientX - rect.left) / rect.width) * spec.width : spec.left + spec.plotWidth / 2;
  const svgY = rect.height ? ((event.clientY - rect.top) / rect.height) * spec.height : spec.top + spec.plotHeight / 2;
  const xRatio = Math.max(0, Math.min(1, (svgX - spec.left) / spec.plotWidth));
  const yRatio = Math.max(0, Math.min(1, (svgY - spec.top) / spec.plotHeight));
  const yRatioFromBottom = 1 - yRatio;
  return {
    x: axisValueAtRatio(spec.xDomain, xRatio, spec.xLog),
    y: axisValueAtRatio(spec.yDomain, yRatioFromBottom, spec.yLog),
    y2: validDomain(spec.y2Domain)
      ? axisValueAtRatio(spec.y2Domain, yRatioFromBottom, spec.y2Log)
      : NaN,
  };
}

function axisValueAtRatio(domain, ratio, logScale = false) {
  const safeRatio = Math.max(0, Math.min(1, Number(ratio)));
  if (logScale && domain[0] > 0 && domain[1] > domain[0]) {
    const min = Math.log10(domain[0]);
    const max = Math.log10(domain[1]);
    return 10 ** (min + safeRatio * (max - min));
  }
  return domain[0] + safeRatio * (domain[1] - domain[0]);
}

function zoomDomain(domain, anchor, factor, logScale = false) {
  const min = Number(domain[0]);
  const max = Number(domain[1]);
  if (!Number.isFinite(min) || !Number.isFinite(max) || max <= min) return domain;
  if (logScale && min > 0 && max > min) {
    const logMin = Math.log10(min);
    const logMax = Math.log10(max);
    const logAnchor = Number(anchor) > 0 ? Math.log10(Number(anchor)) : (logMin + logMax) / 2;
    const nextMin = logAnchor - (logAnchor - logMin) * factor;
    const nextMax = logAnchor + (logMax - logAnchor) * factor;
    if (!Number.isFinite(nextMin) || !Number.isFinite(nextMax) || nextMax <= nextMin) return domain;
    return [10 ** nextMin, 10 ** nextMax];
  }
  const safeAnchor = Number.isFinite(anchor) ? anchor : (min + max) / 2;
  const nextMin = safeAnchor - (safeAnchor - min) * factor;
  const nextMax = safeAnchor + (max - safeAnchor) * factor;
  if (!Number.isFinite(nextMin) || !Number.isFinite(nextMax) || nextMax <= nextMin) return domain;
  return [nextMin, nextMax];
}

function panDomain(domain, ratio, logScale = false, sign = 1) {
  const min = Number(domain[0]);
  const max = Number(domain[1]);
  if (!Number.isFinite(min) || !Number.isFinite(max) || max <= min) return domain;
  const shiftRatio = Number(ratio) * Number(sign || 1);
  if (logScale && min > 0 && max > min) {
    const logMin = Math.log10(min);
    const logMax = Math.log10(max);
    const shift = shiftRatio * (logMax - logMin);
    return [10 ** (logMin + shift), 10 ** (logMax + shift)];
  }
  const shift = shiftRatio * (max - min);
  return [min + shift, max + shift];
}

function rdChartPoints(row, labels, settings, definitions) {
  const summaries = resultSummaries(row);
  return summaries.map((summary, index) => {
    const details = collectRunDetails(summary);
    const x = scatterMetricValue(details, settings.x, settings.xStat, summary, definitions);
    const y = scatterMetricValue(details, settings.y, settings.yStat, summary, definitions);
    if (!Number.isFinite(x) || !Number.isFinite(y)) return null;
    const channelUses = transmittedSymbolCount(details);
    const sourcePixels = sourcePixelCount(details);
    const bandwidthRatio = channelUsesPerSourcePixel(details);
    const transmittedBits = transmittedBitCount(details);
    const transmittedBpp = transmittedBitsPerSourcePixel(details);
    const variant = resultVariantLabel(summary, index);
    const title = recipeDisplayName(row.recipe, labels);
    return {
      key: resultRowKey(row),
      groupKey: resultRowKey(row),
      title: summaries.length > 1 ? `${title} - ${variant}` : title,
      label: summaries.length > 1 ? resultVariantValueLabel(summary, index) : title,
      seriesTitle: title,
      groupSize: summaries.length,
      color: resultPointColor(row, summary, settings.colorBy),
      seriesColor: recipeColor(row.recipe),
      x,
      y,
      size: settings.size === "none" ? NaN : scatterMetricValue(details, settings.size, settings.sizeStat, summary, definitions),
      xKind: scatterMetricKind(definitions, settings.x),
      yKind: scatterMetricKind(definitions, settings.y),
      sizeKind: scatterMetricKind(definitions, settings.size),
      channelUses,
      sourcePixels,
      bandwidthRatio,
      transmittedBits,
      transmittedBpp,
      variant,
    };
  }).filter(Boolean);
}

function rdPointSeries(points, xScale, yScale, labelSwitchX = 620) {
  const groups = new Map();
  points.forEach((point) => {
    const group = groups.get(point.groupKey) || [];
    group.push(point);
    groups.set(point.groupKey, group);
  });
  return Array.from(groups.values())
    // A line represents a rate sweep. Repeated SNR evaluations of a
    // fixed-bottleneck codec have the same bandwidth ratio and should remain
    // separate operating points rather than masquerading as an RD curve.
    .filter((group) => (
      group.length > 1
      && new Set(group.map((point) => Number(point.x).toPrecision(12))).size > 1
    ))
    .map((group) => {
      const sorted = group.slice().sort((left, right) => left.x - right.x);
      const end = sorted[sorted.length - 1];
      const endX = xScale(end.x);
      const endY = yScale(end.y);
      const labelOnLeft = endX > labelSwitchX;
      return {
        groupKey: sorted[0].groupKey,
        color: sorted[0].seriesColor || sorted[0].color,
        label: sorted[0].seriesTitle || sorted[0].title,
        labelX: (labelOnLeft ? endX - 12 : endX + 12).toFixed(1),
        labelY: (endY + 4).toFixed(1),
        anchor: labelOnLeft ? "end" : "start",
        points: sorted.map((point) => `${xScale(point.x).toFixed(1)},${yScale(point.y).toFixed(1)}`).join(" "),
      };
    });
}

function rdPointTitle(point, xLabel, yLabel, sizeLabel) {
  const parts = [
    `${point.title}: ${xLabel} ${formatScatterValue(point.x, point.xKind)}`,
    `${yLabel} ${formatScatterValue(point.y, point.yKind)}`,
  ];
  if (Number.isFinite(point.size)) parts.push(`${sizeLabel} ${formatScatterValue(point.size, point.sizeKind)}`);
  if (Number.isFinite(point.bandwidthRatio)) {
    parts.push(`Bandwidth ratio ${formatMetricNumber(point.bandwidthRatio, 5)} complex channel uses/pixel`);
  }
  if (Number.isFinite(point.channelUses)) parts.push(`Transmitted complex channel uses ${formatValue(point.channelUses)}`);
  if (Number.isFinite(point.sourcePixels)) parts.push(`Source pixels ${formatValue(point.sourcePixels)}`);
  if (Number.isFinite(point.transmittedBpp)) {
    parts.push(`Transmitted digital bpp ${formatMetricNumber(point.transmittedBpp, 5)}`);
  }
  if (Number.isFinite(point.transmittedBits)) parts.push(`Transmitted digital bits ${formatValue(point.transmittedBits)}`);
  return parts.join(", ");
}

function rdChartSummary(rows) {
  const definitions = scatterMetricDefinitions(rows);
  const presentation = rateDistortionPresentation(rows);
  const settings = normalizedRdSettings(definitions, presentation.settings, presentation.context);
  const sizeLabel = settings.size === "none" ? "fixed point size" : scatterMetricLabel(definitions, settings.size, settings.sizeStat);
  return `${scatterMetricLabel(definitions, settings.x, settings.xStat)} vs ${scatterMetricLabel(definitions, settings.y, settings.yStat)} - size: ${sizeLabel}`;
}

function scatterMetricDefinitions(rows) {
  const definitions = new Map();
  addScatterMetricDefinition(definitions, "rate_bpp", "Transmit rate (bits/pixel)", "scalar");
  addScatterMetricDefinition(definitions, "tx_bits", "Tx bits", "bits");
  addScatterMetricDefinition(definitions, "channel_uses_per_pixel", "Bandwidth ratio (complex channel uses/pixel)", "scalar");
  addScatterMetricDefinition(definitions, "channel_use_count", "Transmitted complex channel uses", "scalar");
  addScatterMetricDefinition(definitions, "reference_snr_db", "Reference SNR (dB)", "scalar");
  addScatterMetricDefinition(definitions, "source_pixels", "Source pixels", "scalar");
  addScatterMetricDefinition(definitions, RD_DEFAULT_SETTINGS.y, rdMetricHumanLabel("", RD_DEFAULT_SETTINGS.y), "scalar");
  addScatterMetricDefinition(definitions, MODEL_TIME_DEFAULT_SETTINGS.x, rdMetricHumanLabel("", MODEL_TIME_DEFAULT_SETTINGS.x), "timing");
  addScatterMetricDefinition(definitions, MODEL_TIME_DEFAULT_SETTINGS.y, rdMetricHumanLabel("", MODEL_TIME_DEFAULT_SETTINGS.y), "timing");
  addScatterMetricDefinition(definitions, MODEL_TIME_DEFAULT_SETTINGS.size, rdMetricHumanLabel("", MODEL_TIME_DEFAULT_SETTINGS.size), "bytes");
  rows.forEach((row) => {
    resultSummaries(row).forEach((summary) => {
      const details = collectRunDetails(summary);
      details.metrics.forEach((item) => {
        const key = `${item.step}.${item.metric}`;
        const number = Number(item.value);
        if (!Number.isFinite(number)) return;
        const timingBase = splitTimingMetricId(key);
        if (timingBase) {
          addScatterMetricDefinition(definitions, timingBase.metric, rdMetricHumanLabel("", timingBase.metric), "timing");
        } else {
          const kind = key.includes("_bytes")
            ? "bytes"
            : key.includes("bit_count") || key.endsWith(".tx_bits")
              ? "bits"
              : "scalar";
          addScatterMetricDefinition(definitions, key, rdMetricHumanLabel(item.step, item.metric), kind);
        }
      });
    });
  });
  return Array.from(definitions.values());
}

function addPaperClaimMetricAliases(definitions) {
  const hasDecoderSymbolDecode = definitions.has("codec.codec_timing.decoder.symbol_decode");
  const hasDecoderTotal = definitions.has("codec.codec_timing.decoder.total");
  const hasPayloadDecodeStage =
    definitions.has("payload_decoder.codec_timing.decoder.total") ||
    definitions.has("payload_unpacker.codec_timing.decoder.total") ||
    definitions.has("receiver.codec_timing.decoder.payload_decode") ||
    definitions.has("receiver.codec_timing.decoder.bitstream_decode") ||
    hasDecoderSymbolDecode ||
    definitions.has("codec.codec_timing.decoder.payload_model_inference");
  [
    ["paper_claim.decoding_bottleneck.decoder_symbol_decode", "codec.codec_timing.decoder.symbol_decode", "Decoder raw symbol decode"],
    ["paper_claim.decoding_bottleneck.decoder_total", "codec.codec_timing.decoder.total", "Decoder total"],
    ["paper_claim.eflic.decoder_total", "codec.codec_timing.decoder.total", "Decoder total"],
    ["paper_claim.eflic.encoder_total", "codec.codec_timing.encoder.total", "Encoder total"],
    ["paper_claim.eflic.index_pack_symbol_encode", "codec.codec_timing.encoder.symbol_encode", "Index pack / symbol encode"],
    ["paper_claim.eflic.index_unpack_symbol_decode", "codec.codec_timing.decoder.symbol_decode", "Index unpack / symbol decode"],
    ["paper_claim.eflic.neural_decoder_inference", "receiver.codec_timing.decoder.inference", "Neural decoder inference"],
    ["paper_claim.eflic.neural_encoder_inference", "sender.codec_timing.encoder.inference", "Neural encoder inference"],
  ].forEach(([id, sourceId, label]) => {
    if (definitions.has(sourceId)) addScatterMetricDefinition(definitions, id, label, "timing", sourceId);
  });
  if (hasPayloadDecodeStage) {
    addScatterMetricDefinition(
      definitions,
      "paper_claim.decoding_bottleneck.decoder_payload_stage",
      "Decoder payload stage",
      "timing"
    );
  }
  if (hasPayloadDecodeStage && hasDecoderTotal) {
    addScatterMetricDefinition(
      definitions,
      "paper_claim.decoding_bottleneck.decoder_payload_stage_share",
      "Decoder payload stage share",
      "timing_share"
    );
  }
  if (hasDecoderSymbolDecode && hasDecoderTotal) {
    addScatterMetricDefinition(
      definitions,
      "paper_claim.decoding_bottleneck.decoder_symbol_decode_share",
      "Decoder raw symbol decode share",
      "timing_share"
    );
  }
}

function addScatterMetricDefinition(definitions, id, label, kind = "scalar", sourceId = null) {
  if (!definitions.has(id)) definitions.set(id, { id, label, kind, sourceId });
}

function normalizedRdSettings(
  definitions,
  preferredSettings = RD_DEFAULT_SETTINGS,
  context = "generic-rate-distortion",
) {
  const ids = new Set(definitions.map((item) => item.id));
  const firstMetric = definitions[0] && definitions[0].id;
  const contextChanged = state.rdSettingsContext !== context;
  const next = {
    ...preferredSettings,
    ...(contextChanged ? {} : state.rdSettings || {}),
  };
  normalizeLegacyScatterMetricSettings(next, "x");
  normalizeLegacyScatterMetricSettings(next, "y");
  normalizeLegacyScatterMetricSettings(next, "size");
  normalizeAxisLogSettings(next);
  if (!ids.has(next.x)) next.x = ids.has(preferredSettings.x) ? preferredSettings.x : firstMetric || preferredSettings.x;
  if (!ids.has(next.y)) next.y = ids.has(preferredSettings.y) ? preferredSettings.y : firstMetric || preferredSettings.y;
  if (next.size !== "none" && !ids.has(next.size)) {
    next.size = ids.has(preferredSettings.size) ? preferredSettings.size : "none";
  }
  next.xStat = normalizeScatterStat(definitions, next.x, next.xStat, preferredSettings.xStat);
  next.yStat = normalizeScatterStat(definitions, next.y, next.yStat, preferredSettings.yStat);
  next.sizeStat = normalizeScatterStat(definitions, next.size, next.sizeStat, preferredSettings.sizeStat);
  next.colorBy = normalizeFigureColorBy(next.colorBy);
  state.rdSettings = next;
  state.rdSettingsContext = context;
  if (contextChanged) state.rdView = null;
  return next;
}

function scatterMetricValue(details, metricId, stat = "value", summary = null, definitions = null) {
  if (metricId === "paper_claim.decoding_bottleneck.decoder_payload_stage") {
    const safeStat = TIME_STAT_OPTIONS.some((item) => item.id === stat) ? stat : "p50";
    return decoderPayloadStageMetricValue(details, safeStat);
  }
  if (metricId === "paper_claim.decoding_bottleneck.decoder_payload_stage_share") {
    const safeStat = TIME_STAT_OPTIONS.some((item) => item.id === stat) ? stat : "p50";
    const payloadStage = decoderPayloadStageMetricValue(details, safeStat);
    const decoderTotal = numberMetricValue(details, [`codec.codec_timing.decoder.total.${safeStat}_s`]);
    return Number.isFinite(payloadStage) && Number.isFinite(decoderTotal) && decoderTotal > 0
      ? (payloadStage / decoderTotal) * 100
      : NaN;
  }
  if (metricId === "paper_claim.decoding_bottleneck.decoder_symbol_decode_share") {
    const safeStat = TIME_STAT_OPTIONS.some((item) => item.id === stat) ? stat : "p50";
    const symbolDecode = numberMetricValue(details, [`codec.codec_timing.decoder.symbol_decode.${safeStat}_s`]);
    const decoderTotal = numberMetricValue(details, [`codec.codec_timing.decoder.total.${safeStat}_s`]);
    return Number.isFinite(symbolDecode) && Number.isFinite(decoderTotal) && decoderTotal > 0
      ? (symbolDecode / decoderTotal) * 100
      : NaN;
  }
  metricId = scatterMetricSourceId(definitions || scatterMetricDefinitions(visibleResultRows(state.resultRows || [])), metricId);
  if (metricId === "rate_bpp") {
    const bits = transmittedBitCount(details);
    const pixels = sourcePixelCount(details);
    return Number.isFinite(bits) && Number.isFinite(pixels) && pixels > 0 ? bits / pixels : NaN;
  }
  if (metricId === "tx_bits") return transmittedBitCount(details);
  if (metricId === "channel_uses_per_pixel") return channelUsesPerSourcePixel(details);
  if (metricId === "channel_use_count") return transmittedSymbolCount(details);
  if (metricId === "reference_snr_db") return summarySnrDb(summary, details);
  if (metricId === "source_pixels") return sourcePixelCount(details);
  if (isTimingMetricBaseId(metricId)) {
    const safeStat = TIME_STAT_OPTIONS.some((item) => item.id === stat) ? stat : "p50";
    return numberMetricValue(details, [`${metricId}.${safeStat}_s`]);
  }
  return numberMetricValue(details, [metricId]);
}

function decoderPayloadStageMetricValue(details, stat) {
  const suffix = `${stat}_s`;
  const direct = numberMetricValue(details, [
    `payload_decoder.codec_timing.decoder.total.${suffix}`,
    `payload_unpacker.codec_timing.decoder.total.${suffix}`,
    `receiver.codec_timing.decoder.payload_decode.${suffix}`,
    `receiver.codec_timing.decoder.bitstream_decode.${suffix}`,
    `receiver.codec_timing.decoder.entropy_decode.${suffix}`,
  ]);
  if (Number.isFinite(direct)) return direct;
  const pieces = [
    numberMetricValue(details, [`codec.codec_timing.decoder.symbol_decode.${suffix}`]),
    numberMetricValue(details, [`codec.codec_timing.decoder.payload_model_inference.${suffix}`]),
    numberMetricValue(details, [`codec.codec_timing.decoder.payload_decode.${suffix}`]),
  ].filter(Number.isFinite);
  return pieces.length ? pieces.reduce((sum, value) => sum + value, 0) : NaN;
}

function scatterMetricLabel(definitions, id, stat = "value") {
  const match = definitions.find((item) => item.id === id);
  const label = match ? match.label : rdMetricHumanLabel("", id);
  return metricKindUsesTimingStats(scatterMetricKind(definitions, id)) ? `${label} ${timeStatLabel(stat)}` : label;
}

function scatterMetricKind(definitions, id) {
  if (id === "none") return "scalar";
  const match = definitions.find((item) => item.id === id);
  if (match && match.kind) return match.kind;
  id = scatterMetricSourceId(definitions, id);
  if (isTimingMetricBaseId(id)) return "timing";
  if (String(id || "").includes("_bytes")) return "bytes";
  return "scalar";
}

function normalizeScatterStat(definitions, metricId, stat, fallback = "value") {
  if (!metricKindUsesTimingStats(scatterMetricKind(definitions, metricId))) return "value";
  const requested = String(stat || fallback || "p50");
  return TIME_STAT_OPTIONS.some((item) => item.id === requested) ? requested : "p50";
}

function metricKindUsesTimingStats(kind) {
  return kind === "timing" || kind === "timing_share";
}

function normalizeLegacyScatterMetricSettings(settings, field) {
  const metric = settings[field];
  const split = splitTimingMetricId(metric);
  if (!split) return;
  settings[field] = split.metric;
  if (!settings[`${field}Stat`] || settings[`${field}Stat`] === "value") {
    settings[`${field}Stat`] = split.stat;
  }
}

function splitTimingMetricId(metricId) {
  const text = String(metricId || "");
  const match = text.match(/^(.+\.codec_timing\..+)\.(sum|mean|p50|p90|p95|p99|std)_s$/);
  return match ? { metric: match[1], stat: match[2] } : null;
}

function isTimingMetricBaseId(metricId) {
  const text = String(metricId || "");
  return text.includes(".codec_timing.") && !splitTimingMetricId(text);
}

function timingStatsForScatterMetric(summary, metricId) {
  if (metricId === "paper_claim.decoding_bottleneck.decoder_payload_stage" || metricId === "paper_claim.decoding_bottleneck.decoder_payload_stage_share") {
    return decoderPayloadStageTimingStats(summary);
  }
  if (metricId === "paper_claim.decoding_bottleneck.decoder_symbol_decode_share") {
    return timingStats(timingValuesForSummary(summary, "decoder.symbol_decode"));
  }
  metricId = scatterMetricSourceId(scatterMetricDefinitions(visibleResultRows(state.resultRows || [])), metricId);
  if (!isTimingMetricBaseId(metricId)) return {};
  const componentKey = String(metricId).split(".codec_timing.")[1] || "";
  const samples = timingValuesForSummary(summary, componentKey);
  return timingStats(samples);
}

function scatterMetricSourceId(definitions, id) {
  const match = (definitions || []).find((item) => item.id === id);
  return match && match.sourceId ? match.sourceId : id;
}

function decoderPayloadStageTimingStats(summary) {
  const componentSamples = timingComponentSamplesForSummary(summary);
  return statsForFirstTimingComponent(componentSamples, [
    "decoder.symbol_decode",
    "decoder.payload_model_inference",
    "decoder.payload_decode",
  ]);
}

